<template>
  <section class="workbook" :class="{ 'ops-workbook': isOpsPage }">
    <template v-if="isOpsPage">
      <div class="ops-ms-page" :data-opstone="opsTabTone">
        <div class="ops-ms-head">
          <div class="ops-ms-tabs ops-ms-terms">
            <button
              v-for="t in opsTypeTabs"
              :key="t.key"
              type="button"
              class="ops-ms-tab"
              :class="{ active: t.key === activeType }"
              :data-opstype="t.key"
              @click="selectType(t.key)"
            >
              {{ t.label }}
            </button>
          </div>
          <div class="ops-ms-country">
            <div class="country-dd">
              <button class="country-btn" type="button" :class="{ fixed: !canSwitchCountry }" :disabled="!canSwitchCountry" @click="toggleCountryMenu">
                <img :src="flagUrl(currentCountry?.flag)" alt="" />
                <span>{{ currentCountry?.name || 'Vietnam' }}</span>
                <svg v-if="canSwitchCountry" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="m6 9 6 6 6-6" /></svg>
              </button>
              <div v-if="canSwitchCountry && countryOpen" class="country-menu">
                <button
                  v-for="country in countries"
                  :key="country.id"
                  type="button"
                  :class="{ active: country.id === currentCountry?.id }"
                  @click="selectCountry(country.id)"
                >
                  <img :src="flagUrl(country.flag)" alt="" />
                  <span>{{ country.name }}</span>
                </button>
              </div>
            </div>
          </div>
        </div>

        <div class="ops-ms-tabs ops-ms-modes">
          <button
            v-for="mode in opsModeTabs"
            :key="mode"
            type="button"
            class="ops-ms-tab"
            :class="{ active: mode === activeMode }"
            :data-opsmode="mode"
            @click="selectMode(mode)"
          >
            {{ mode }}
          </button>
        </div>

        <div class="ops-ms-tabs ops-ms-depts">
          <button
            v-for="d in deptTabs"
            :key="d"
            type="button"
            class="ops-ms-tab"
            :class="{ active: d === activeDept }"
            :data-opsdept="d"
            @click="selectDept(d)"
          >
            <span class="ops-dot"></span>
            <span>{{ d }}</span>
          </button>
        </div>

        <div class="ops-ms-toolbar">
          <button v-if="canAddOpsRow()" class="ops-btn primary" type="button" @click="addRow">
            <svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
            Add Row
          </button>
          <button class="ops-btn edit" type="button" :disabled="!canEditSelectedOpsRow" @click="editSelectedOpsRow">
            <svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg>
            Edit
          </button>
          <button class="ops-btn danger" type="button" :disabled="!canDeleteSelectedOpsRows" @click="deleteOpsRows">
            <svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>
            Remove
          </button>
          <div class="ops-export-wrap">
            <button class="ops-btn" type="button" @click.stop="toggleOpsExportMenu">
              <svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12M7 10l5 5 5-5M4 21h16"/></svg>
              Export
            </button>
            <div v-if="opsExportOpen" class="ops-export-menu">
              <button type="button" :disabled="!opsSelectedRows.size" @click="exportOpsScope('selected')">Export selected rows{{ opsSelectedRows.size ? ` (${opsSelectedRows.size})` : '' }}</button>
              <button type="button" :disabled="!opsFilteringActive" @click="exportOpsScope('filtered')">Export filtered rows{{ opsFilteringActive ? ` (${opsBodyRows.length})` : '' }}</button>
              <button type="button" @click="exportOpsScope('all')">Export all rows ({{ Math.max(0, rows.length - 1) }})</button>
            </div>
          </div>
          <div class="ops-spacer"></div>
          <div class="ops-search-group">
            <select class="ops-filter-select" v-model="opsFilterField">
              <option value="all">All</option>
              <option v-for="column in visibleColumns" :key="column" :value="String(column)">{{ headerLabel(column) || columnLetter(column) }}</option>
            </select>
            <span class="ops-search-div"></span>
            <input v-model.trim="query" class="ops-search" type="text" placeholder="Search&hellip;" @keydown.esc.prevent="query = ''" />
            <button class="ops-btn search" type="button">Search</button>
            <button class="ops-btn ghost" type="button" :disabled="!opsFilteringActive" @click="cancelOpsSearch">Cancel Search</button>
            <button class="ops-btn ghost" type="button" @click="toggleOpsAdvancedFilter">+ Filter</button>
          </div>
          <span class="ops-status-lbl">Status</span>
          <select class="ops-status-select" :value="activeStatus" @change="selectOpsStatusEvent">
            <option value="active">ACTIVE</option>
            <option value="pending">PENDING</option>
            <option value="done">COMPLETED</option>
            <option value="cancel">CANCEL</option>
          </select>
        </div>

        <div v-if="opsFilterOpen" class="ops-adv-filter">
          <div class="ops-adv-rows">
            <template v-if="opsAdvancedFilters.length">
              <div v-for="(filter, index) in opsAdvancedFilters" :key="index" class="ops-adv-row">
                <select v-model="filter.field" @change="resetOpsFilter(index)">
                  <option value="all">All</option>
                  <option v-for="column in visibleColumns" :key="column" :value="String(column)">{{ headerLabel(column) || columnLetter(column) }}</option>
                </select>
                <select v-model="filter.op">
                  <option value="contains">Contains</option>
                  <option value="empty">Is Empty</option>
                  <option value="notempty">Is Not Empty</option>
                </select>
                <input v-if="filter.op === 'contains'" v-model.trim="filter.value" type="text" placeholder="Value..." />
                <button class="ops-adv-remove" type="button" @click="removeOpsFilter(index)">x</button>
              </div>
            </template>
            <span v-else class="ops-adv-empty">No conditions yet - click "+ Add condition".</span>
          </div>
          <div class="ops-adv-actions">
            <button class="ops-btn ghost" type="button" @click="addOpsFilter">+ Add condition</button>
            <button class="ops-btn search" type="button" @click="applyOpsAdvancedFilter">Apply</button>
            <button class="ops-btn ghost" type="button" @click="clearOpsAdvancedFilter">Clear all</button>
          </div>
        </div>

        <div class="ops-tablewrap">
          <table class="ops-ms-table">
            <colgroup>
              <col style="width:34px" />
              <col v-for="column in visibleColumns" :key="column" :style="{ width: `${opsColumnWidth(column)}px` }" />
            </colgroup>
            <thead>
              <tr>
                <th class="ops-sel">
                  <input type="checkbox" :checked="opsAllVisibleSelected" @change="toggleAllOpsRows" />
                </th>
                <th
                  v-for="column in visibleColumns"
                  :key="column"
                  @contextmenu.prevent="openOpsHeaderMenu(column, $event)"
                >
                  {{ headerLabel(column).toUpperCase() }}
                  <span
                    class="ops-rsz"
                    title="Resize column"
                    @mousedown.stop.prevent="startColResize($event, column)"
                    @dblclick.stop.prevent="autoFitColumn(column)"
                  ></span>
                </th>
              </tr>
            </thead>
            <tbody>
              <tr v-if="loading">
                <td :colspan="visibleColumns.length + 1" class="ops-empty">Loading worksheet...</td>
              </tr>
              <tr v-else-if="!opsBodyRows.length">
                <td :colspan="visibleColumns.length + 1" class="ops-empty">
                  <b>No {{ activeType?.toLowerCase() || 'ops' }} / {{ activeMode?.toLowerCase() || 'mode' }} / {{ activeDept?.toLowerCase() || 'dept' }} yet.</b>
                  <span v-if="canAddOpsRow()">Click <b style="display:inline">Add Row</b> to create the first record.</span>
                </td>
              </tr>
              <template v-else>
              <tr v-for="rowIndex in opsBodyRows" :key="rowIndex" :class="{ selected: opsSelectedRows.has(rowIndex), editing: isOpsEditingRow(rowIndex) }">
                <td class="ops-sel">
                  <input type="checkbox" :disabled="isOpsEditingRow(rowIndex)" :checked="opsSelectedRows.has(rowIndex)" @change="toggleOpsRow(rowIndex)" />
                </td>
                <td
                  v-for="columnIndex in visibleColumns"
                  :key="columnIndex"
                  :class="opsCellClass(rowIndex, columnIndex)"
                  @dblclick="handleOpsCellDblClick(rowIndex, columnIndex, $event)"
                >
                  <div v-if="isStampedOpsCheckboxColumn(columnIndex)" class="ops-sent-cell">
                    <span class="sent-check-row"><input
                        class="ops-check"
                        type="checkbox"
                        :checked="isChecked(rows[rowIndex]?.[columnIndex])"
                        :disabled="(isExwFclGsdSentEcdColumn(columnIndex) && isSentEcdLocked(rows[rowIndex]?.[columnIndex])) || ((isExwFclEcdBcSentColumn(columnIndex) || isManifestSubmitColumn(columnIndex)) && isBcSentLocked(rows[rowIndex]?.[columnIndex]))"
                        @change="toggleCheckbox(rowIndex, columnIndex, $event)"
                      /><button v-if="isStampedOpsCheckboxColumn(columnIndex) && isChecked(rows[rowIndex]?.[columnIndex])" class="bc-sent-edit" type="button" title="Edit" @click="unlockBcSent(rowIndex, columnIndex)">&#9998;</button></span>
                    <span v-if="sentCheckboxTimestamp(rows[rowIndex]?.[columnIndex], columnIndex)" class="ops-sent-at">{{ sentCheckboxTimestamp(rows[rowIndex]?.[columnIndex], columnIndex) }}</span>
                  </div>
                  <input
                    v-else-if="isCheckboxCell(rowIndex, columnIndex)"
                    class="ops-check"
                    type="checkbox"
                    :checked="isChecked(rows[rowIndex]?.[columnIndex])"
                    :disabled="isSentEcdRowLocked(rowIndex)"
                    @change="toggleCheckbox(rowIndex, columnIndex, $event)"
                  />
                  <button
                    v-else-if="isActionInfoCell(rowIndex, columnIndex)"
                    v-show="!hideLockedGsdAddAction(rowIndex, !infoActionIsDetail(rowIndex, columnIndex))"
                    class="ops-pill"
                    type="button"
                    :class="{ has: hasInfoRecords(rowIndex, columnIndex), 'detail-alert': infoDetailNeedsAttention(rowIndex, columnIndex) }"
                    @click="openInfoModal(rowIndex, columnIndex)"
                  >
                    <span v-if="infoDetailNeedsAttention(rowIndex, columnIndex)" class="detail-alert-icon">!</span>{{ infoActionIsDetail(rowIndex, columnIndex) ? 'DETAIL' : 'ADD+' }}
                  </button>
                  <button
                    v-else-if="isTruckInfoCell(rowIndex, columnIndex)"
                    v-show="!hideLockedGsdAddAction(rowIndex, !truckActionIsDetail(rowIndex, columnIndex))"
                    class="ops-pill"
                    type="button"
                    :class="{ has: hasTruckRecords(rowIndex, columnIndex), 'detail-alert': truckDetailNeedsAttention(rowIndex, columnIndex) }"
                    @click="openTruckModal(rowIndex, columnIndex)"
                  >
                    <span v-if="truckDetailNeedsAttention(rowIndex, columnIndex)" class="detail-alert-icon">!</span>{{ truckActionIsDetail(rowIndex, columnIndex) ? 'DETAIL' : 'ADD+' }}
                  </button>
                  <button
                    v-else-if="isClientLinkCell(rowIndex, columnIndex) && canEditClientLinkCell(rowIndex, columnIndex) && !clientCellText(rows[rowIndex]?.[columnIndex])"
                    v-show="!hideLockedGsdAddAction(rowIndex, true)"
                    class="ops-pill"
                    type="button"
                    @click="canEditClientLinkCell(rowIndex, columnIndex) && openGsdModal(rowIndex, columnIndex)"
                  >
                    ADD+
                  </button>
                  <button
                    v-else-if="isClientLinkCell(rowIndex, columnIndex) && clientCellText(rows[rowIndex]?.[columnIndex])"
                    class="ops-client"
                    type="button"
                    :title="clientCellTitle(rows[rowIndex]?.[columnIndex])"
                    @click="openGsdModal(rowIndex, columnIndex)"
                  >
                    <b>{{ clientCellText(rows[rowIndex]?.[columnIndex]) }}</b>
                  </button>
                  <span v-else-if="isClientLinkCell(rowIndex, columnIndex)" class="ops-textcell"></span>
                  <button
                    v-else-if="isDoInfoCell(rowIndex, columnIndex)"
                    v-show="!hideLockedGsdAddAction(rowIndex, !doInfoDate(rows[rowIndex]?.[columnIndex]))"
                    class="ops-pill"
                    type="button"
                    :class="{ has: !!doInfoDate(rows[rowIndex]?.[columnIndex]), 'document-value': !!doInfoDate(rows[rowIndex]?.[columnIndex]) }"
                    @click="openDoInfoModal(rowIndex, columnIndex)"
                  >{{ doInfoDate(rows[rowIndex]?.[columnIndex]) || 'ADD+' }}</button>
                  <button
                    v-else-if="isGsdActionButtonCell(rowIndex, columnIndex)"
                    v-show="!hideLockedGsdAddAction(rowIndex, gsdActionButtonText(rowIndex, columnIndex) === 'ADD+')"
                    class="ops-pill"
                    type="button"
                    :class="{ view: normalizedHeaderLabel(columnIndex) === 'REMINDER', has: !!String(rows[rowIndex]?.[columnIndex] || '').trim() && !['REMINDER', 'NOTICE'].includes(normalizedHeaderLabel(columnIndex)), 'linked-value': showActionEditIcon(rowIndex, columnIndex), 'document-value': isPlainDocumentValue(rowIndex, columnIndex), 'do-release-warn': isDoReleaseWarnCell(rowIndex, columnIndex), 'detail-alert': detailActionNeedsAttention(rowIndex, columnIndex), 'volume-summary-btn': normalizedHeaderLabel(columnIndex) === 'VOLUME' && !!volumeSummaryText(rows[rowIndex]?.[columnIndex]) }"
                    @click="handleGsdActionButton(rowIndex, columnIndex)"
                  >
                    <span v-if="isDoReleaseWarnCell(rowIndex, columnIndex)" class="do-release-warn-icon">!</span><span v-else-if="detailActionNeedsAttention(rowIndex, columnIndex)" class="detail-alert-icon">!</span>{{ gsdActionButtonText(rowIndex, columnIndex) }}
                    <span v-if="noticeBadgeCount(rowIndex, columnIndex)" class="ops-nbadge">{{ noticeBadgeCount(rowIndex, columnIndex) }}</span>
                  </button>
                  <select
                    v-else-if="isActionSelectCell(rowIndex, columnIndex)"
                    class="ops-action-select"
                    :class="actionSelectClass(rows[rowIndex]?.[columnIndex])"
                    :value="actionCellValue(rows[rowIndex]?.[columnIndex])"
                    :disabled="isActionSelectLocked(rowIndex)"
                    @change="changeActionCell(rowIndex, columnIndex, $event)"
                  >
                    <option value="ACTIVE">ACTIVE</option>
                    <option value="PENDING">PENDING</option>
                    <option value="DONE">DONE</option>
                    <option value="CANCEL">CANCEL</option>
                  </select>
                  <span v-else-if="isLockedAfterBcSentDate(rowIndex, columnIndex)" class="ops-textcell ops-locked-date-text">{{ displayCell(rows[rowIndex]?.[columnIndex], rowIndex, columnIndex) }}</span>
                  <button
                    v-else-if="isAtaDateCell(rowIndex, columnIndex)"
                    class="ops-ata-btn"
                    :class="{ has: !!String(rows[rowIndex]?.[columnIndex] || '').trim() }"
                    type="button"
                    :title="String(rows[rowIndex]?.[columnIndex] || 'Choose ATA date')"
                    @click="openAtaDatePopup(rowIndex, columnIndex, $event)"
                  >
                    <span v-if="String(rows[rowIndex]?.[columnIndex] || '').trim()">{{ displayCell(rows[rowIndex]?.[columnIndex], rowIndex, columnIndex) }}</span>
                    <svg v-else viewBox="0 0 24 24" aria-hidden="true">
                      <rect x="3" y="4" width="18" height="17" rx="2" />
                      <path d="M8 2v4M16 2v4M3 10h18" />
                    </svg>
                  </button>
                  <select
                    v-else-if="isDropdownCell(rowIndex, columnIndex) && !isLockedOpsCell(rowIndex, columnIndex)"
                    class="ops-efa-select"
                    :value="opsNativeDropdownValue(rowIndex, columnIndex)"
                    :disabled="isLockedOpsCell(rowIndex, columnIndex) || isSentEcdRowLocked(rowIndex)"
                    @change="setDropdownValue(rowIndex, columnIndex, $event)"
                  >
                    <option
                      v-for="option in opsNativeDropdownOptions(rowIndex, columnIndex)"
                      :key="`ops-dd-${columnIndex}-${String(option)}`"
                      :value="option"
                    >
                      {{ option || '—' }}
                    </option>
                  </select>
                  <input
                    v-else-if="isOpsEditingRow(rowIndex) && !isLockedOpsCell(rowIndex, columnIndex) && !isSentEcdRowLocked(rowIndex)"
                    class="ops-edit-input"
                    :class="{ time: isOpsTimeColumn(columnIndex), date: isOpsRowDateColumn(columnIndex) }"
                    :type="isOpsTimeColumn(columnIndex) ? 'datetime-local' : isOpsRowDateColumn(columnIndex) ? 'date' : 'text'"
                    :value="opsEditInputValue(rows[rowIndex]?.[columnIndex], columnIndex)"
                    @input="updateOpsEditCell(rowIndex, columnIndex, $event)"
                    @keydown.enter.prevent="blurEventTarget"
                  />
                  <input
                    v-else-if="isOpsTimeColumn(columnIndex) && !isLockedOpsCell(rowIndex, columnIndex) && !isLclSheet()"
                    class="ops-time-input"
                    type="datetime-local"
                    :value="toDatetimeLocalValue(rows[rowIndex]?.[columnIndex])"
                    :disabled="isSentEcdRowLocked(rowIndex)"
                    @input="updateOpsTimeCell(rowIndex, columnIndex, $event)"
                    @keydown.enter.prevent="blurEventTarget"
                  />
                  <span
                    v-else
                    class="ops-textcell"
                    :class="{ 'inline-editing': isEditingCell(rowIndex, columnIndex) }"
                    :contenteditable="isEditingCell(rowIndex, columnIndex) ? 'true' : 'false'"
                    :title="isOpsConfirmableFreeTextCell(rowIndex, columnIndex) ? 'Double-click to edit' : ''"
                    spellcheck="false"
                    @blur="finishOpsCellEdit(rowIndex, columnIndex, $event)"
                    @keydown.enter.prevent="blurEventTarget"
                  >{{ displayCell(rows[rowIndex]?.[columnIndex], rowIndex, columnIndex) }}</span>
                  <div v-if="isOpsEditingRow(rowIndex) && columnIndex === visibleColumns[0]" class="ops-edit-ledge">
                    <button type="button" class="save" @click="saveOpsEdit">Save</button>
                    <button type="button" class="cancel" @click="cancelOpsEdit">Cancel</button>
                  </div>
                </td>
              </tr>
              </template>
            </tbody>
          </table>
        </div>
        <div class="ops-ms-foot">
          {{ opsBodyRows.length }} {{ activeType?.toLowerCase() || 'ops' }} / {{ activeMode?.toLowerCase() || 'mode' }} / {{ activeDept?.toLowerCase() || 'dept' }}
        </div>
        <div
          v-if="opsHeaderMenu.open"
          class="ops-head-menu"
          :style="{ left: `${opsHeaderMenu.left}px`, top: `${opsHeaderMenu.top}px` }"
        >
          <button type="button" @click="addOpsColumnFromMenu">+ Add Column</button>
          <button type="button" :disabled="!canRemoveOpsHeaderColumn" :title="canRemoveOpsHeaderColumn ? '' : 'Cannot remove a built-in column'" @click="removeOpsColumnFromMenu">✕ Remove Column</button>
        </div>
        <div v-if="opsColumnModal.open" class="ops-col-modal-overlay" @mousedown.self="closeOpsColumnModal">
          <div class="ops-col-modal" role="dialog" aria-modal="true">
            <template v-if="opsColumnModal.mode === 'add'">
              <h3>Add column</h3>
              <p>Enter a name for the new column.</p>
              <input
                ref="opsColumnNameInput"
                v-model.trim="opsColumnModal.name"
                type="text"
                placeholder="E.G. CONTRACT NO#"
                @keydown.enter.prevent="confirmAddOpsColumn"
              />
              <div class="ops-col-actions">
                <button type="button" class="ghost" @click="closeOpsColumnModal">Cancel</button>
                <button type="button" class="primary" @click="confirmAddOpsColumn">Add</button>
              </div>
            </template>
            <template v-else>
              <h3>Remove column: {{ opsColumnTitle(opsColumnModal.column) }}</h3>
              <p>This will permanently delete this column and its data in every row. This cannot be undone.</p>
              <div class="ops-col-actions">
                <button type="button" class="ghost" @click="closeOpsColumnModal">Cancel</button>
                <button type="button" class="primary" @click="confirmRemoveOpsColumn">Confirm</button>
              </div>
            </template>
          </div>
        </div>
      </div>
    </template>
    <template v-else>
    <div class="main-head">
      <div class="head-line">
        <button class="side-toggle" type="button" title="Toggle sidebar" @click="$emit('toggle-sidebar')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
            <path d="M3 6h18M3 12h18M3 18h18" />
          </svg>
        </button>
        <span class="sheet-name">{{ activeLabel }}</span>
        <div class="head-tail">
          <div class="country-dd">
            <button class="country-btn" type="button" :class="{ fixed: !canSwitchCountry }" :disabled="!canSwitchCountry" @click="toggleCountryMenu">
              <img :src="flagUrl(currentCountry?.flag)" alt="" />
              <span>{{ currentCountry?.name || 'Vietnam' }}</span>
              <svg v-if="canSwitchCountry" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="m6 9 6 6 6-6" /></svg>
            </button>
            <div v-if="canSwitchCountry && countryOpen" class="country-menu">
              <button
                v-for="country in countries"
                :key="country.id"
                type="button"
                :class="{ active: country.id === currentCountry?.id }"
                @click="selectCountry(country.id)"
              >
                <img :src="flagUrl(country.flag)" alt="" />
                <span>{{ country.name }}</span>
              </button>
            </div>
          </div>
          <button type="button" class="wb-export" @click="exportCsv">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="M7 10l5 5 5-5"/><path d="M12 15V3"/></svg>
            Export CSV
          </button>
        </div>
    </div>
    <div class="wb-toolbar">
        <label class="wb-search">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" /></svg>
          <input v-model.trim="query" placeholder="Search this sheet..." />
        </label>
        <span class="selection-count">{{ selectionInfo }}</span>
        <button type="button" title="Duplicate selected row(s) below" :disabled="!hasSelection" @click="duplicateRows">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" /></svg>
          Copy
        </button>
        <button type="button" class="danger" :disabled="!hasSelection" @click="deleteSelection">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4h8v2m-9 0 1 15h8l1-15M10 10v7m4-7v7" /></svg>
          Delete
        </button>
        <span class="divider"></span>
        <button type="button" class="primary" @click="addRow">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14" /></svg>
          Add row
        </button>
        <button type="button" @click="addColumn">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14" /></svg>
          Add column
        </button>
        <span class="divider"></span>
        <button type="button" class="icon-btn" title="Freeze rows down to the selected row" :disabled="!hasSelection" @click="freezeRows">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="1" /><path d="M3 9h18" /></svg>
        </button>
        <button type="button" class="icon-btn" title="Freeze columns up to the selected column" :disabled="!hasSelection" @click="freezeCols">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="1" /><path d="M9 3v18" /></svg>
        </button>
        <button type="button" class="icon-btn" title="Unfreeze rows / columns" @click="freezeClear">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="1" /><path d="M7 7l10 10M17 7L7 17" /></svg>
        </button>
        <span class="divider"></span>
        <button type="button" class="icon-btn" :class="{ active: selectedAlign === 'left' }" title="Align left" :disabled="!hasSelection" @click="setAlign('left')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M3 12h12M3 18h15" /></svg>
        </button>
        <button type="button" class="icon-btn" :class="{ active: selectedAlign === 'center' }" title="Align center" :disabled="!hasSelection" @click="setAlign('center')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M6 12h12M4 18h16" /></svg>
        </button>
        <button type="button" class="icon-btn" :class="{ active: selectedAlign === 'right' }" title="Align right" :disabled="!hasSelection" @click="setAlign('right')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M9 12h12M6 18h15" /></svg>
        </button>
        <span class="divider"></span>
        <button type="button" :class="{ active: selectedType === 'text' }" :disabled="!hasSelection" @click="setType('text')">Abc</button>
        <button type="button" :class="{ active: selectedType === 'number' }" :disabled="!hasSelection" @click="setType('number')">123</button>
        <button type="button" :class="{ active: selectedType === 'time' }" :disabled="!hasSelection" @click="setType('time')">24h</button>
        <button type="button" :class="{ active: selectedType === 'date' }" :disabled="!hasSelection" @click="setType('date')">Date</button>
        <span class="divider"></span>
        <button type="button" :class="{ active: hasFormat('dropdown') }" title="Make the selected column a dropdown" :disabled="!hasSelection" @click="toggleFormat('dropdown')">▾ List</button>
        <button type="button" :class="{ active: hasFormat('checkbox') }" title="Make the selected column a checkbox" :disabled="!hasSelection" @click="toggleFormat('checkbox')">☑ Check</button>
        <button type="button" :class="{ active: hasFormat('xfer') }" title="Send the row to the next department tab when ticked" :disabled="!hasSelection" @click="toggleFormat('xfer')">→ Next</button>
        <button type="button" :class="{ active: hasFormat('lock') }" title="Lock the selected columns (toggle)" :disabled="!hasSelection" @click="toggleFormat('lock')">🔒 Lock</button>
        <span class="divider"></span>
        <button type="button" class="icon-btn" title="Text color" :disabled="!hasSelection" @click="openColorPalette('color', $event)">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M7 18 12 6l5 12M9.2 13h5.6" /></svg>
        </button>
        <button type="button" class="icon-btn" title="Cell background" :disabled="!hasSelection" @click="openColorPalette('background', $event)">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="4" y="4" width="16" height="16" rx="2" /><path d="M4 9.5h16" /></svg>
        </button>
        <span class="divider"></span>
        <button type="button" class="icon-btn" title="Merge selected cells" :disabled="!hasMergeableCellRange" @click="mergeCells">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="1" /><path d="M9 9l3 3-3 3M15 9l-3 3 3 3" /></svg>
        </button>
        <button type="button" class="icon-btn" title="Unmerge selected cells" :disabled="!hasSelection" @click="unmergeCells">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="1" /><path d="M12 9V5M12 19v-4M8.5 12H4M20 12h-4.5" /></svg>
        </button>
      </div>
    </div>

    <div v-if="opsTypeTabs.length > 1" class="ops-row ops-row-type">
      <span class="ops-lbl">Type</span>
      <button
        v-for="t in opsTypeTabs"
        :key="t.key"
        type="button"
        class="cl-tab"
        :data-opstype="t.key"
        :class="{ on: t.key === activeType }"
        @click="selectType(t.key)"
      >{{ t.label }}</button>
    </div>
    <div v-if="deptTabs.length" class="ops-row ops-row-dept">
      <span class="ops-lbl">Dept</span>
      <button v-for="d in deptTabs" :key="d" type="button" class="cl-tab dept-tab" :data-opsdept="d" :class="{ on: d === activeDept, custom: canDeleteDept(d) }" @click="selectDept(d)">
        <span class="dept-lbl">{{ d }}</span>
        <span v-if="deptCounts[d]" class="ops-badge">{{ deptCounts[d] }}</span>
        <span v-if="canDeleteDept(d)" class="dept-x" title="Delete department" @click.stop="deleteDept(d)">×</span>
      </button>
      <button v-if="canAddDept" class="cl-tab dept-add" type="button" title="Add department" @click="addDeptPrompt">+</button>
    </div>
    <div v-if="deptTabs.length" class="ops-row ops-row-status">
      <span class="ops-lbl">Status</span>
      <button v-for="s in statusTabs" :key="s.key" type="button" class="cl-tab" :data-opsstatus="s.key" :class="{ on: s.key === activeStatus }" @click="selectStatus(s.key)">{{ s.label }}</button>
      <div class="ops-sort">
        <span class="ops-sort-lbl">Sort</span>
        <select class="opssort-sel" :value="sortBy" @change="selectSort($event)">
          <option value="default">—</option>
          <option value="new">Newest</option>
          <option value="etd">By ETD</option>
          <option value="eta">By ETA</option>
        </select>
      </div>
    </div>
    <div v-if="sheetTabs.length > 1 || showAddTab" class="sheet-tabs">
      <span v-if="showSheetTabLabel" class="sheet-tabs-label">{{ title }}</span>
      <button
        v-for="tab in sheetTabs"
        :key="tab.key"
        type="button"
        :class="{ active: tab.key === activeKey }"
        @click="selectSheetTab(tab.key)"
      >
        <span>{{ tab.label }}</span>
        <span
          v-if="canDeleteTab(tab.key)"
          class="sheet-tab-delete"
          title="Delete tab"
          @click.stop="$emit('delete-tab', tab)"
        >×</span>
      </button>
      <button v-if="showAddTab" class="sheet-tab-add" type="button" @click="$emit('add-tab')">+ Add tab</button>
    </div>

    <div class="sheet-shell">
      <div v-if="loading" class="sheet-empty">Loading worksheet...</div>
      <div v-else-if="!rows.length" class="sheet-empty">No worksheet data.</div>
      <div v-else class="sheet-grid">
        <button class="corner" type="button" title="Select all rows" @mousedown.prevent="startSel('all', 0, 0)"></button>
        <div ref="columnBar" class="column-bar">
          <table :style="{ width: `${sheetWidth}px` }">
            <colgroup>
              <col v-for="column in visibleColumns" :key="column" :style="{ width: `${columnWidth(column)}px` }" />
            </colgroup>
            <thead>
              <tr>
                <th
                  v-for="column in visibleColumns"
                  :key="column"
                  :class="{ sel: colIsSelected(column) }"
                  :data-col="column"
                  @mousedown.prevent="startSel('col', 0, column)"
                >
                  {{ columnLetter(column) }}
                  <span class="rsz" :data-rsz="column" @mousedown.stop.prevent="startColResize($event, column)" @dblclick.stop.prevent="autoFitColumn(column)"></span>
                </th>
              </tr>
            </thead>
          </table>
        </div>
        <div ref="rowBar" class="row-bar">
          <table>
            <tbody>
              <tr v-for="rowIndex in visibleRowIndexes" :key="rowIndex" :class="{ hdr: rowIndex === 0 }" :style="rowStyle(rowIndex)">
                <th 
                  class="row-number" 
                  :class="{ hdrn: rowIndex === 0 }" 
                  :data-row="rowIndex"
                  @mousedown.prevent="startSel('row', rowIndex, 0)"
                >
                  {{ rowIndex + 1 }}
                  <span class="rrz" :data-rrz="rowIndex" @mousedown.stop.prevent="startRowResize($event, rowIndex)" @dblclick.stop.prevent="resetRowHeight(rowIndex)" title="Resize row"></span>
                </th>
              </tr>
            </tbody>
          </table>
        </div>
        <div ref="sheetBody" class="sheet-body" @scroll="syncSheetScroll">
          <table ref="sheetTable" :style="{ width: `${sheetWidth}px` }">
            <colgroup>
              <col v-for="column in visibleColumns" :key="column" :style="{ width: `${columnWidth(column)}px` }" />
            </colgroup>
            <tbody>
              <tr v-if="loading">
                <td :colspan="visibleColumns.length" class="ops-empty">Loading worksheet...</td>
              </tr>
              <tr v-for="rowIndex in visibleRowIndexes" :key="rowIndex" :class="{ hdr: rowIndex === 0 }" :style="rowStyle(rowIndex)">
                <template v-for="columnIndex in visibleColumns" :key="columnIndex">
                  <td
                    v-if="!isMergedCovered(rowIndex, columnIndex)"
                    :colspan="mergeSpan(rowIndex, columnIndex).columns"
                    :rowspan="mergeSpan(rowIndex, columnIndex).rows"
                    class="cell"
                    :class="cellClass(rowIndex, columnIndex)"
                    :style="cellStyle(rowIndex, columnIndex)"
                    :contenteditable="canEditCell(rowIndex, columnIndex) ? 'true' : 'false'"
                    spellcheck="false"
                    :data-r="rowIndex"
                    :data-c="columnIndex"
                    @mousedown="handleCellMouseDown(rowIndex, columnIndex, $event)"
                    @dblclick.prevent="beginEditCell(rowIndex, columnIndex)"
                    @blur="finishEditCell(rowIndex, columnIndex, $event)"
                    @keydown.enter.prevent="handleEnterEdit(rowIndex, columnIndex, $event)"
                    @keydown.tab.prevent="handleTabEdit(rowIndex, columnIndex, $event)"
                    @keydown.esc.prevent="cancelEditCell(rowIndex, columnIndex, $event)"
                    @contextmenu.prevent="openContextMenu(rowIndex, columnIndex, $event)"
                  >
                    <div v-if="isStampedOpsCheckboxColumn(columnIndex)" class="cell-sent-wrap">
                      <span class="sent-check-row"><input
                          class="cell-check"
                          type="checkbox"
                          :checked="isChecked(rows[rowIndex]?.[columnIndex])"
                          :disabled="(isExwFclGsdSentEcdColumn(columnIndex) && isSentEcdLocked(rows[rowIndex]?.[columnIndex])) || ((isExwFclEcdBcSentColumn(columnIndex) || isManifestSubmitColumn(columnIndex)) && isBcSentLocked(rows[rowIndex]?.[columnIndex]))"
                          @mousedown.stop
                          @click.stop
                          @change="toggleCheckbox(rowIndex, columnIndex, $event)"
                        /><button v-if="isStampedOpsCheckboxColumn(columnIndex) && isChecked(rows[rowIndex]?.[columnIndex])" class="bc-sent-edit" type="button" title="Edit" @mousedown.stop @click.stop="unlockBcSent(rowIndex, columnIndex)">&#9998;</button></span>
                      <span v-if="sentCheckboxTimestamp(rows[rowIndex]?.[columnIndex], columnIndex)" class="cell-sent-at">{{ sentCheckboxTimestamp(rows[rowIndex]?.[columnIndex], columnIndex) }}</span>
                    </div>
                    <input
                      v-else-if="isCheckboxCell(rowIndex, columnIndex)"
                      class="cell-check"
                      type="checkbox"
                      :checked="isChecked(rows[rowIndex]?.[columnIndex])"
                      :disabled="isSentEcdRowLocked(rowIndex)"
                      @mousedown.stop
                      @click.stop
                      @change="toggleCheckbox(rowIndex, columnIndex, $event)"
                    />
                    <button
                      v-else-if="isActionInfoCell(rowIndex, columnIndex)"
                      class="ad-btn"
                      :class="{ has: hasInfoRecords(rowIndex, columnIndex), 'detail-alert': infoDetailNeedsAttention(rowIndex, columnIndex) }"
                      type="button"
                      @mousedown.stop
                      @click.stop="openInfoModal(rowIndex, columnIndex)"
                    >
                      <span v-if="infoDetailNeedsAttention(rowIndex, columnIndex)" class="detail-alert-icon">!</span>{{ infoActionIsDetail(rowIndex, columnIndex) ? 'DETAIL' : 'ADD+' }}
                    </button>
                    <button
                      v-else-if="isTruckInfoCell(rowIndex, columnIndex)"
                      class="ad-btn"
                      :class="{ has: hasTruckRecords(rowIndex, columnIndex), 'detail-alert': truckDetailNeedsAttention(rowIndex, columnIndex) }"
                      type="button"
                      @mousedown.stop
                      @click.stop="openTruckModal(rowIndex, columnIndex)"
                    >
                      <span v-if="truckDetailNeedsAttention(rowIndex, columnIndex)" class="detail-alert-icon">!</span>{{ truckActionIsDetail(rowIndex, columnIndex) ? 'DETAIL' : 'ADD+' }}
                    </button>
                    <button
                    v-else-if="isClientLinkCell(rowIndex, columnIndex) && canEditClientLinkCell(rowIndex, columnIndex) && !clientCellText(rows[rowIndex]?.[columnIndex])"
                      class="addcli"
                      type="button"
                      @mousedown.stop
                      @click.stop="canEditClientLinkCell(rowIndex, columnIndex) && openGsdModal(rowIndex, columnIndex)"
                    >
                      ADD+
                    </button>
                    <button
                      v-else-if="isClientLinkCell(rowIndex, columnIndex)"
                      class="clival-btn"
                      type="button"
                      :title="clientCellTitle(rows[rowIndex]?.[columnIndex])"
                      @mousedown.stop
                      @click.stop="openGsdModal(rowIndex, columnIndex)"
                    >
                      <b>{{ clientCellText(rows[rowIndex]?.[columnIndex]) }}</b>
                    </button>
                    <button
                      v-else-if="isDoInfoCell(rowIndex, columnIndex)"
                      class="gsd-btn"
                      :class="{ 'document-value': !!doInfoDate(rows[rowIndex]?.[columnIndex]) }"
                      type="button"
                      @mousedown.stop
                      @click.stop="openDoInfoModal(rowIndex, columnIndex)"
                    >{{ doInfoDate(rows[rowIndex]?.[columnIndex]) || 'ADD+' }}</button>
                    <button
                      v-else-if="isGsdActionButtonCell(rowIndex, columnIndex)"
                      class="gsd-btn"
                      :class="[gsdActionButtonClass(columnIndex), { 'linked-value': showActionEditIcon(rowIndex, columnIndex), 'document-value': isPlainDocumentValue(rowIndex, columnIndex), 'do-release-warn': isDoReleaseWarnCell(rowIndex, columnIndex), 'detail-alert': detailActionNeedsAttention(rowIndex, columnIndex), 'volume-summary-btn': normalizedHeaderLabel(columnIndex) === 'VOLUME' && !!volumeSummaryText(rows[rowIndex]?.[columnIndex]) }]"
                      type="button"
                      @mousedown.stop
                      @click.stop="handleGsdActionButton(rowIndex, columnIndex)"
                    >
                      <span v-if="isDoReleaseWarnCell(rowIndex, columnIndex)" class="do-release-warn-icon">!</span><span v-else-if="detailActionNeedsAttention(rowIndex, columnIndex)" class="detail-alert-icon">!</span>{{ gsdActionButtonText(rowIndex, columnIndex) }}
                    </button>
                    <select
                      v-else-if="isActionSelectCell(rowIndex, columnIndex)"
                      class="actsel"
                      :class="actionSelectClass(rows[rowIndex]?.[columnIndex])"
                      :value="actionCellValue(rows[rowIndex]?.[columnIndex])"
                      :disabled="isActionSelectLocked(rowIndex)"
                      @mousedown.stop
                      @click.stop
                      @change="changeActionCell(rowIndex, columnIndex, $event)"
                    >
                      <option value="ACTIVE">ACTIVE</option>
                      <option value="PENDING">PENDING</option>
                      <option value="DONE">DONE</option>
                      <option value="CANCEL">CANCEL</option>
                    </select>
                    <span v-else-if="isLockedAfterBcSentDate(rowIndex, columnIndex)" class="ops-locked-date-text">{{ displayCell(rows[rowIndex]?.[columnIndex], rowIndex, columnIndex) }}</span>
                    <button
                      v-else-if="isAtaDateCell(rowIndex, columnIndex)"
                      class="ops-ata-btn"
                      :class="{ has: !!String(rows[rowIndex]?.[columnIndex] || '').trim() }"
                      type="button"
                      :disabled="isSentEcdRowLocked(rowIndex)"
                      @mousedown.stop
                      @click.stop="openAtaDatePopup(rowIndex, columnIndex, $event)"
                    >
                      <span v-if="String(rows[rowIndex]?.[columnIndex] || '').trim()">{{ displayCell(rows[rowIndex]?.[columnIndex], rowIndex, columnIndex) }}</span>
                      <svg v-else viewBox="0 0 24 24" aria-hidden="true">
                        <rect x="3" y="4" width="18" height="17" rx="2" />
                        <path d="M8 2v4M16 2v4M3 10h18" />
                      </svg>
                    </button>
                    <button
                      v-else-if="isDropdownCell(rowIndex, columnIndex) && !isLockedOpsCell(rowIndex, columnIndex)"
                      class="cell-select cell-dd-button"
                      type="button"
                      :disabled="isSentEcdRowLocked(rowIndex)"
                      @mousedown.stop
                      @click.stop="openDropdownPopup(rowIndex, columnIndex, $event)"
                    >
                      <span>{{ displayCell(rows[rowIndex]?.[columnIndex], rowIndex, columnIndex) }}</span>
                    </button>
                    <span v-else>{{ displayCell(rows[rowIndex]?.[columnIndex], rowIndex, columnIndex) }}</span>
                  </td>
                </template>
              </tr>
              <tr v-if="!loading && visibleRowIndexes.length <= 1">
                <td :colspan="visibleColumns.length" class="ops-empty"><b>No matching data</b><span v-if="saveError">{{ saveError }}</span><button v-if="saveError" class="ops-empty-retry" type="button" @click="loadSheet">Retry</button><span v-else>Try another Status or clear the search filters.</span></td>
              </tr>
            </tbody>
          </table>
        </div>
        <!-- Scrollbar corners with helpers -->
        <div class="scrollbar-corner-left">

        </div>
        <div class="scrollbar-corner-top">

        </div>
      </div>
    </div>
    </template>
    <div v-if="colorPalette.open" class="color-palette" :style="{ left: `${colorPalette.left}px`, top: `${colorPalette.top}px` }">
      <button v-for="color in palette" :key="color" type="button" class="color-swatch" :style="{ background: color }" :title="color" @click="setSelectedColor(color)"></button>
      <button type="button" class="clear-color" @click="setSelectedColor('')">Clear color</button>
    </div>
    <div v-if="dropdownPopup.open" class="ddpop on" :class="{ 'ops-simple': isOpsStaffColumn(dropdownPopup.column) }" :style="{ left: `${dropdownPopup.left}px`, top: `${dropdownPopup.top}px`, width: `${dropdownPopup.width}px` }">
      <div class="ddsearchwrap">
        <input v-model="dropdownPopup.filter" class="ddsearch" type="text" @keydown.enter.prevent="chooseFirstDropdownOption" @keydown.esc.prevent="closeDropdownPopup" />
      </div>
      <div class="ddlist">
        <div
          v-for="option in filteredDropdownPopupOptions"
          :key="`dd-${String(option)}-${dropdownPopup.column}`"
          class="ddopt"
          role="button"
          tabindex="0"
          @click="selectDropdownOption(option)"
          @keydown.enter.prevent="selectDropdownOption(option)"
        >
          <span>{{ option || '—' }}</span>
          <button v-if="dropdownPopup.mode === 'edit'" class="ddx" type="button" title="Remove" @click.stop="removeDropdownPopupOption(option)">x</button>
        </div>
        <div v-if="!filteredDropdownPopupOptions.length" class="ddempty">No options</div>
      </div>
      <div v-if="dropdownPopup.error" class="dderr">{{ dropdownPopup.error }}</div>
      <template v-if="dropdownPopup.mode === 'edit'">
        <div class="ddaddwrap">
          <input v-model.trim="dropdownPopup.newItem" class="ddadd" type="text" placeholder="New item" @keydown.enter.prevent="addDropdownPopupOption" />
          <button class="ddaddbtn" type="button" title="Add" @click="addDropdownPopupOption">✓</button>
        </div>
        <button class="ddfoot" type="button" @click="dropdownPopup.mode = 'pick'">Done</button>
      </template>
      <button v-else class="ddfoot ddedit" type="button" @click="dropdownPopup.mode = 'edit'">Edit</button>
    </div>
    <div v-if="datePopup.open" class="datepop on" :class="{ 'modal-datepop': !!datePopup.cutoffField || !!nativePickerInput }" :style="{ left: `${datePopup.left}px`, top: `${datePopup.top}px` }">
      <div class="dp-head">
        <button type="button" @click="shiftDateMonth(-1)">‹</button>
        <strong>{{ datePopupMonthLabel }}</strong>
        <button type="button" @click="shiftDateMonth(1)">›</button>
      </div>
      <div class="dp-grid dp-dow">
        <span v-for="day in ['Mo','Tu','We','Th','Fr','Sa','Su']" :key="day">{{ day }}</span>
      </div>
      <div class="dp-grid">
        <button
          v-for="day in datePopupDays"
          :key="day.key"
          type="button"
          :class="{ muted: !day.inMonth, today: day.today, selected: day.selected }"
          :disabled="isDatePopupDayDisabled(day.date)"
          @click="selectDatePopup(day.date)"
        >
          {{ day.date.getDate() }}
        </button>
      </div>
      <div class="dp-actions">
        <button type="button" @click="clearDatePopup">Clear</button>
        <button type="button" @click="selectDatePopup(new Date())">Today</button>
      </div>
    </div>
    <div v-if="dropdownModal.open" class="wb-modal-overlay wsmodal-overlay" @mousedown.self="closeDropdownModal">
      <div class="wsmodal" role="dialog" aria-modal="true">
        <div class="wsmodal-head">Dropdown options</div>
        <div class="wsmodal-body">Separate options with commas or new lines.</div>
        <textarea
          ref="dropdownOptionsInput"
          v-model="dropdownModal.text"
          class="wsmodal-input"
          rows="5"
          placeholder="Option A, Option B, Option C"
          @keydown.ctrl.enter.prevent="applyDropdownModal"
        ></textarea>
        <div class="wsmodal-foot">
          <button type="button" class="wsmodal-btn" @click="closeDropdownModal">Cancel</button>
          <button type="button" class="wsmodal-btn primary" @click="applyDropdownModal">Add</button>
        </div>
      </div>
    </div>
    <div v-if="confirmModal.open" class="wb-modal-overlay wb-confirm-overlay wsmodal-overlay" @mousedown.self="resolveConfirm(false)">
      <div v-if="confirmModal.tone === 'question'" class="wb-confirm-modal tone-question" role="dialog" aria-modal="true">
        <div class="question-confirm-title">{{ confirmModal.message }}</div>
        <div class="question-confirm-actions">
          <button type="button" class="question-confirm-btn no" @click="resolveConfirm(false)">{{ confirmModal.cancelText }}</button>
          <button type="button" class="question-confirm-btn yes" @click="resolveConfirm(true)">{{ confirmModal.okText }}</button>
        </div>
      </div>
      <div v-else class="wsmodal" :class="{ 'no-title': !confirmModal.title }" role="dialog" aria-modal="true">
        <div v-if="confirmModal.title" class="wsmodal-head">{{ confirmModal.title }}</div>
        <div class="wsmodal-body">{{ confirmModal.message }}</div>
        <div class="wsmodal-foot">
          <button type="button" class="wsmodal-btn" :class="{ 'solid-grey': !confirmModal.title }" @click="resolveConfirm(false)">{{ confirmModal.cancelText }}</button>
          <button type="button" class="wsmodal-btn" :class="!confirmModal.title ? 'solid-danger' : (confirmModal.tone === 'danger' || confirmModal.tone === 'remove' ? 'danger' : 'primary')" @click="resolveConfirm(true)">{{ confirmModal.okText }}</button>
        </div>
      </div>
    </div>
    <div v-if="cutoffTimePopup.open" class="cutoff-timepop" :style="{ left: `${cutoffTimePopup.left}px`, top: `${cutoffTimePopup.top}px` }" role="dialog" aria-label="Select cutoff time">
      <div class="ctp-head"><strong>Select time</strong><span>24-hour</span></div>
      <div class="ctp-labels"><span>Hour</span><span>Minute</span></div>
      <div class="ctp-columns">
        <div class="ctp-list"><button v-for="hour in cutoffHours" :key="`ctp-h-${hour}`" type="button" :class="{ selected: cutoffTimePopup.hour === hour }" @click="cutoffTimePopup.hour = hour">{{ hour }}</button></div>
        <div class="ctp-list"><button v-for="minute in cutoffMinutes" :key="`ctp-m-${minute}`" type="button" :class="{ selected: cutoffTimePopup.minute === minute }" @click="cutoffTimePopup.minute = minute">{{ minute }}</button></div>
      </div>
      <div class="ctp-actions"><button type="button" @click="clearCutoffTime">Clear</button><button type="button" @click="setCutoffTimeNow">Now</button><button class="primary" type="button" @click="applyNativeOrCutoffTime">Done</button></div>
    </div>
    <div v-if="pickerFieldProxy.open" class="ops-picker-field-proxy" :class="pickerFieldProxy.type" :style="{ left: `${pickerFieldProxy.left}px`, top: `${pickerFieldProxy.top}px`, width: `${pickerFieldProxy.width}px`, height: `${pickerFieldProxy.height}px` }">
      <span>{{ pickerFieldProxy.label }}</span>
      <svg v-if="pickerFieldProxy.type === 'date'" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M8 2v4M16 2v4M3 10h18"/></svg>
      <svg v-else viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>
    </div>
    <div v-if="dispatchLoading" class="dispatch-loading-overlay" role="dialog" aria-modal="true" aria-live="polite">
      <div class="dispatch-loading-modal">
        <span class="dispatch-loading-spinner" aria-hidden="true"></span>
        <span>Processing</span>
      </div>
    </div>
    <div v-if="rowConfirmModal.open" class="wb-modal-overlay row-confirm-overlay" @mousedown.self="resolveRowConfirm(false)">
      <div class="row-confirm-modal" role="dialog" aria-modal="true">
        <button class="row-confirm-x" type="button" aria-label="Close" @click="resolveRowConfirm(false)">x</button>
        <div class="row-confirm-title">{{ rowConfirmModal.message || `Please type "CONFIRM" to ${rowConfirmModal.action} row:` }}</div>
        <input ref="rowConfirmInput" v-model.trim="rowConfirmModal.value" type="text" :placeholder="rowConfirmModal.expected" autocomplete="off" @keydown.enter.prevent="resolveRowConfirm(true)" />
        <div class="row-confirm-actions">
          <button class="ignore" type="button" @click="resolveRowConfirm(false)">Ignore</button>
          <button class="ok" type="button" :disabled="rowConfirmModal.value.toUpperCase() !== rowConfirmModal.expected.toUpperCase()" @click="resolveRowConfirm(true)">OK</button>
        </div>
      </div>
    </div>
    <div v-if="deptModal.open" class="wb-modal-overlay wsmodal-overlay" @mousedown.self="closeDeptModal">
      <div class="wsmodal" role="dialog" aria-modal="true">
        <div class="wsmodal-head">Add department</div>
        <div class="wsmodal-body">Enter a code for the new department.</div>
        <input ref="deptInput" v-model.trim="deptModal.name" class="wsmodal-input" type="text" placeholder="QCD" autocomplete="off" @keydown.enter.prevent="applyDeptModal" />
        <div class="wsmodal-foot">
          <button type="button" class="wsmodal-btn" @click="closeDeptModal">Cancel</button>
          <button type="button" class="wsmodal-btn primary" @click="applyDeptModal">Add</button>
        </div>
      </div>
    </div>
    <div v-if="doInfoModal.open" class="wb-modal-overlay do-info-overlay" @mousedown.self="closeDoInfoModal">
      <div class="do-info-modal" role="dialog" aria-modal="true" aria-label="DO information">
        <button class="do-info-x" type="button" aria-label="Close" @click="closeDoInfoModal">×</button>
        <div class="do-info-row">
          <label>Upload<br>MBL DO:</label>
          <input v-model="doInfoModal.mblNo" type="text" :disabled="!doInfoModal.editing" />
          <input v-model="doInfoModal.date" type="date" :disabled="!doInfoModal.editing" />
          <button class="gsd-pre-icon upload do-info-upload" :class="{ has: !!doInfoModal.mblFile.name }" type="button" :disabled="!doInfoModal.editing" :title="doInfoModal.mblFile.name || 'Upload MBL DO'" @click="chooseDoInfoFile('mbl')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15V5M8 9l4-4 4 4"/><path d="M5 14v4h14v-4"/></svg></button>
          <button v-if="doInfoModal.mblFile.dataUrl" class="gsd-pre-icon eye on do-info-view" type="button" title="View MBL DO" @click="viewDoInfoFile('mbl')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button>
        </div>
        <div class="do-info-row">
          <label>HBL DO:</label>
          <input v-model="doInfoModal.hblNo" type="text" :disabled="!doInfoModal.editing" />
          <input v-model="doInfoModal.date" type="date" :disabled="!doInfoModal.editing" />
          <button class="gsd-pre-icon upload do-info-upload" :class="{ has: !!doInfoModal.hblFile.name }" type="button" :disabled="!doInfoModal.editing" :title="doInfoModal.hblFile.name || 'Upload HBL DO'" @click="chooseDoInfoFile('hbl')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15V5M8 9l4-4 4 4"/><path d="M5 14v4h14v-4"/></svg></button>
          <button v-if="doInfoModal.hblFile.dataUrl" class="gsd-pre-icon eye on do-info-view" type="button" title="View HBL DO" @click="viewDoInfoFile('hbl')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button>
        </div>
        <div class="do-info-actions">
          <button v-if="!doInfoModal.editing" class="edit" type="button" @click="doInfoModal.editing = true">Edit</button>
          <button class="save" type="button" :disabled="!doInfoModal.editing || !doInfoModal.date" @click="saveDoInfoModal">Save</button>
          <button class="close" type="button" @click="closeDoInfoModal">Close</button>
        </div>
      </div>
    </div>
    <div v-if="gsdModal.open" class="wb-modal-overlay gsd-modal-overlay" @mousedown.self="closeGsdModal">
      <div
        class="wb-modal gsd-modal"
        :style="gsdModalShellStyle()"
        :class="{
          'gsd-reminder-modal': gsdModal.kind === 'reminder',
          'gsd-client-modal': gsdModal.kind === 'client',
          'gsd-extra-modal': gsdModal.kind === 'extra',
          'gsd-dealt-modal': gsdModal.kind === 'dealt',
          'gsd-hbl-modal': gsdModal.kind === 'hbl',
          'gsd-cutoff-modal': isCutoffModal(),
          'gsd-volume-modal': isVolumeModal(),
          'gsd-air-fca-ecd-volume-modal': isVolumeModal() && isAirSheet() && isFcaEcdSheet(),
          'gsd-dap-tcd-volume-modal': isDapTcdVolumeDetailModal(),
          'gsd-ccd-record-modal': isCcdCutoffModal() || isCcdVolumeModal(),
          'gsd-freetime-modal': isFreetimeModal(),
          'gsd-route-modal': isRouteModal(),
          'gsd-vessel-modal': isVesselModal() && !isAirDcdVesselHistoryModal(),
          'gsd-vessel-ecd-modal': isExwEcdVesselDelayModal(),
          'gsd-vhist-modal': isAirDcdVesselHistoryModal(),
          'gsd-pickup-modal': isPickupModal(),
          'gsd-air-exw-fcd-pickup-modal': isPickupModal() && isAirSheet() && isExwFcdSheet(),
          'gsd-delivery-details-modal': isDeliveryDetailsModal(),
          'gsd-mock-pk-modal': isDeliveryDetailsModal() || isExwFcaPickupModal(),
          'gsd-delivery-edit-modal': isDeliveryDetailsModal() && !isReadonlyDeliveryDetailsModal(),
          'gsd-dap-tcd-delivery-modal': isDeliveryDetailsModal() && isAirSheet() && isDapTcdSheet(),
          'gsd-do-cont-modal': isDoContSealModal(),
          'gsd-air-do-icd-cont-modal': isAirDoIcdContSealModal() || isAirDupIcdContSealModal(),
          'gsd-air-dup-icd-cont-modal': isAirDupIcdContSealModal(),
          'gsd-air-dup-ccd-cont-modal': isAirDupCcdContSealModal(),
          'gsd-truck-cont-modal': isTruckContModal(),
          'gsd-fcl-dup-tcd-truck-modal': isTruckContModal() && (isFclDduTcdSheet() || (isDapTcdSheet() && opsParts?.mode === 'FCL')),
          'gsd-fcl-dap-tcd-truck-modal': isTruckContModal() && isDapTcdSheet() && opsParts?.mode === 'FCL',
          'gsd-dap-fcd-trucking-detail-modal': isTruckContModal() && isAirSheet() && isDapFcdSheet() && isLclTruckingDetailModal(),
          'gsd-prs-modal': isPickupReturnStatusModal(),
          'gsd-prs-editing': isPickupReturnStatusModal() && gsdModal.editing,
          'gsd-air-dup-icd-prs-modal': isAirDupIcdTruckingStatusModal(),
          'gsd-air-dup-tcd-trucking-status-modal': isAirDupTcdTruckingStatusModal() || isAirDupFcdTruckingStatusModal(),
          'gsd-air-dup-fcd-trucking-status-modal': isAirDupFcdTruckingStatusModal(),
          'gsd-air-pickup-status-modal': isAirSheet() && isLclPickupStatusModal(),
          'gsd-bill-modal': isBillApprovalModal() || isBillReleaseModal() || isDoReleaseModal(),
          'gsd-bill-detail-modal': isBillApprovalModal(),
          'gsd-ecd-bill-detail-readonly': isReadonlyExwFclEcdBillDetail(),
          'gsd-do-release-modal': isDoReleaseModal(),
          'gsd-si-modal': isSiSubmitModal(),
          'gsd-ecd-bill-release-modal': isEcdBillReleaseModal(),
          'gsd-pc-modal': isPreAlertConfirmationModal(),
          'gsd-arrival-detail-modal': isArrivalNoticeModal(),
          'gsd-air-do-icd-pc-modal': isAirDoIcdPreAlertConfirmationModal(),
          'gsd-air-dup-icd-pc-modal': isAirDupCompactPreAlertConfirmationModal(),
          'gsd-prealert-modal': isPreAlertModal(),
          'gsd-cda-modal': isClearanceDocsModal(),
          'gsd-clr-modal': isClearanceDetailsModal(),
          'gsd-simple-clr-modal': isSimpleCcdClearanceDetailsModal(),
          'gsd-dup-tcd-clr-modal': isDupTcdClearanceDetailsModal(),
          'gsd-form-modal': gsdModal.kind === 'form',
          'gsd-air-modal': isAirSheet(),
          'gsd-wide-form-modal': gsdModal.kind === 'form' && isWideGsdForm(gsdModal.title) && !hasSpecializedGsdModalLayout(),
          'gsd-payment-modal': isPaymentRequestModal(),
          'gsd-edit-payment-modal': usesFullPaymentRequestLayout(),
          'gsd-air-payment-modal': isPaymentRequestModal() && isAirSheet(),
          'gsd-air-fca-tcd-payment-modal': isPaymentRequestModal() && isAirSheet() && isFcaTcdSheet(),
          'gsd-expcol-modal': isExpenseCollectModal(),
        }"
        role="dialog"
        aria-modal="true"
      >
        <button class="gsd-modal-x" type="button" title="Close" @click="closeGsdModal">&times;</button>
        <div v-if="gsdModal.loading && (isPaymentRequestModal() || isExpenseCollectModal())" class="payment-loading-screen" role="status" aria-live="polite">
          <div class="payment-loading-mark"><span></span><span></span><span></span></div>
          <strong>Loading payment data</strong>
          <small>Please wait a moment…</small>
        </div>

        <template v-if="gsdModal.kind === 'extra'">
          <div class="gsd-extra-head">
            <div class="gsd-extra-title">Select extra services:</div>
            <div class="gsd-extra-actions">
              <button class="wb-modal-btn primary" type="button" :disabled="!gsdModal.editing" @click="addExtraOther">Add+</button>
              <button class="wb-modal-btn edit" type="button" :disabled="gsdModal.editing" @click="enableGsdModalEdit">Edit</button>
            </div>
          </div>
          <div class="gsd-extra-body">
            <label class="gsd-extra-option"><input v-model="gsdModal.extra.insurance" type="checkbox" :disabled="!gsdModal.editing" /> <span>Buy cargo insurance</span></label>
            <label class="gsd-extra-option"><input v-model="gsdModal.extra.payNominated" type="checkbox" :disabled="!gsdModal.editing" /> <span>Pay charges as nominated</span></label>
            <label class="gsd-extra-option"><input v-model="gsdModal.extra.collectNominated" type="checkbox" :disabled="!gsdModal.editing" /> <span>Collect charges as nominated</span></label>
            <div v-for="(item, index) in gsdModal.extra.others" :key="index" class="gsd-extra-other">
              <label><input v-model="item.checked" type="checkbox" :disabled="!gsdModal.editing" @change="changeExtraOtherCheck(index)" /> <span>Others</span></label>
              <input v-model.trim="item.text" :disabled="!gsdModal.editing || !item.checked || item.confirmed" type="text" />
              <button class="gsd-extra-ok" :class="{ on: item.confirmed, ready: item.checked && !!item.text.trim() && !item.confirmed }" type="button" :disabled="!gsdModal.editing" title="Confirm" @click="confirmExtraOther(index)">✓</button>
            </div>
            <label class="gsd-extra-remarks">
              <span>Remarks</span>
              <textarea v-model="gsdModal.extra.remarks" :disabled="!gsdModal.editing"></textarea>
            </label>
          </div>
        </template>

        <template v-else>
          <template v-if="gsdModal.kind === 'reminder'">
            <div class="gsd-reminder-head">Tab: <b>{{ activeDept || 'GSD' }}</b></div>
            <div v-if="gsdModal.reminderMode === 'compose'" class="gsd-reminder-add">
              <span>Add Note to Dept:</span>
              <div class="gsd-reminder-depts">
                <button v-for="dept in reminderDeptTargets()" :key="dept" type="button" :class="{ on: gsdModal.reminderDept === dept }" @click="selectReminderDept(dept)">{{ dept }}</button>
              </div>
            </div>
            <div v-else class="gsd-reminder-add">
              <span>Note(s) from Dept:</span>
              <div class="gsd-reminder-depts">
                <button v-for="dept in reminderDeptTargets()" :key="dept" type="button" :class="{ on: gsdModal.reminderViewDept === dept, has: reminderDeptCount(dept) }" @click="selectReminderViewDept(dept)">
                  {{ dept }}<span v-if="reminderDeptCount(dept)" class="gsd-reminder-badge">{{ reminderDeptCount(dept) }}</span>
                </button>
              </div>
            </div>
            <div class="gsd-reminder-section-title">Share Notes</div>
            <table class="gsd-reminder-table">
              <colgroup>
                <col style="width:7%" />
                <col :style="{ width: gsdModal.reminderMode === 'compose' ? '13%' : '16%' }" />
                <col :style="{ width: gsdModal.reminderMode === 'compose' ? '11%' : '13%' }" />
                <col :style="{ width: gsdModal.reminderMode === 'compose' ? '25%' : '22%' }" />
                <col style="width:30%" />
                <col :style="{ width: gsdModal.reminderMode === 'compose' ? '14%' : '12%' }" />
              </colgroup>
              <thead>
                <tr>
                  <th>Order</th>
                  <th>Date</th>
                  <th>{{ gsdModal.reminderMode === 'compose' ? 'To Dept.' : 'From Dept.' }}</th>
                  <th>Title</th>
                  <th>Details</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody v-if="gsdModal.reminderMode === 'compose'">
                <tr v-for="(note, index) in gsdModal.reminderNotes" :key="note.id || index">
                  <td>{{ index + 1 }}.</td>
                  <td>{{ note.date }}</td>
                  <td>{{ note.dept }}</td>
                  <td>
                    <input v-if="gsdModal.reminderEditId === note.id" v-model.trim="note.title" class="gsd-reminder-title-input" type="text" placeholder="Title" />
                    <span v-else>{{ note.title }}</span>
                  </td>
                  <td>
                    <input v-if="gsdModal.reminderEditId === note.id" v-model.trim="note.details" type="text" placeholder="Details" />
                    <span v-else>{{ note.details }}</span>
                  </td>
                  <td>
                    <button v-if="gsdModal.reminderEditId === note.id" type="button" class="gsd-reminder-icon ok" title="Save" @click="saveReminderEdit"><svg viewBox="0 0 24 24"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z" /><polyline points="17 21 17 13 7 13 7 21" /><polyline points="7 3 7 8 15 8" /></svg></button>
                    <span v-else class="gsd-reminder-icon ok done" title="Saved"><svg viewBox="0 0 24 24"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z" /><polyline points="17 21 17 13 7 13 7 21" /><polyline points="7 3 7 8 15 8" /></svg></span>
                    <span v-if="gsdModal.reminderEditId === note.id" class="gsd-reminder-icon edit off" title="Editing"><svg viewBox="0 0 24 24"><path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" /></svg></span>
                    <button v-else type="button" class="gsd-reminder-icon edit" title="Edit" @click="editReminderNote(note.id)"><svg viewBox="0 0 24 24"><path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" /></svg></button>
                    <button type="button" class="gsd-reminder-icon del" title="Remove" @click="removeReminderNote(index)"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6" /><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" /><line x1="10" y1="11" x2="10" y2="17" /><line x1="14" y1="11" x2="14" y2="17" /></svg></button>
                  </td>
                </tr>
                <tr v-if="gsdModal.reminderDept && !gsdModal.reminderEditId" class="gsd-reminder-editing-row">
                  <td>{{ gsdModal.reminderNotes.length + 1 }}.</td>
                  <td>{{ reminderToday() }}</td>
                  <td>{{ gsdModal.reminderDept }}</td>
                  <td><input v-model.trim="gsdModal.reminderDraft.title" class="gsd-reminder-title-input" type="text" placeholder="Title" @keydown.enter.prevent="saveReminderDraft" /></td>
                  <td><input v-model.trim="gsdModal.reminderDraft.details" type="text" placeholder="Details" @keydown.enter.prevent="saveReminderDraft" /></td>
                  <td>
                    <button type="button" class="gsd-reminder-icon ok" title="Save" @click="saveReminderDraft"><svg viewBox="0 0 24 24"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z" /><polyline points="17 21 17 13 7 13 7 21" /><polyline points="7 3 7 8 15 8" /></svg></button>
                    <span class="gsd-reminder-icon edit off" title="Edit"><svg viewBox="0 0 24 24"><path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" /></svg></span>
                    <button type="button" class="gsd-reminder-icon del" title="Cancel" @click="cancelReminderDraft"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6" /><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" /><line x1="10" y1="11" x2="10" y2="17" /><line x1="14" y1="11" x2="14" y2="17" /></svg></button>
                  </td>
                </tr>
                <tr v-if="!gsdModal.reminderNotes.length && !gsdModal.reminderDept">
                  <td colspan="6" class="gsd-reminder-empty">No notes yet — pick a Dept above to add one.</td>
                </tr>
              </tbody>
              <tbody v-else>
                <tr v-for="(note, index) in reminderViewNotes()" :key="note.id || index" :class="{ 'notice-new-row': reminderJustViewedType(note) === 'new', 'notice-updated-row': reminderJustViewedType(note) === 'updated' }">
                  <td>{{ index + 1 }}.</td>
                  <td>{{ note.date }}</td>
                  <td>{{ note.dept }}</td>
                  <td>
                    <span v-if="reminderJustViewedType(note)" class="notice-change-chip" :class="reminderJustViewedType(note)">{{ reminderJustViewedType(note) === 'updated' ? 'UPDATED' : 'NEW' }}</span>
                    <span>{{ note.title }}</span>
                  </td>
                  <td>{{ note.details }}</td>
                  <td>
                    <button type="button" class="gsd-reminder-icon unread" :class="{ off: note.read !== true }" :disabled="note.read !== true" :title="note.read === true ? 'Mark as unread' : 'Unread'" @click="markReminderUnread(note.id)">
                      <svg viewBox="0 0 24 24"><path d="M3 5h18v14H3z" /><path d="m3 7 9 6 9-6" /></svg>
                    </button>
                  </td>
                </tr>
                <tr v-if="!reminderViewNotes().length">
                  <td colspan="6" class="gsd-reminder-empty">No notes from {{ gsdModal.reminderViewDept }}.</td>
                </tr>
              </tbody>
            </table>
            <template v-if="gsdModal.reminderMode === 'compose'">
              <div class="gsd-reminder-section-title">Notifications</div>
              <div class="gsd-reminder-notify">
              <div v-for="dept in reminderDeptTargets()" :key="dept">
                <b>{{ dept }}:</b>
                <button type="button" class="gsd-reminder-detail" @click="filterReminderDept(dept)">DETAIL</button>
                <span class="gsd-reminder-bell">🔔<span v-if="reminderDeptCount(dept)" class="gsd-reminder-bell-badge">{{ reminderDeptCount(dept) }}</span></span>
              </div>
              </div>
            </template>
            <div v-else class="gsd-reminder-foot">
              <button class="wb-modal-btn slate gsd-reminder-back" type="button" @click="backToReminderCompose">
                <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 6-6 6 6 6" /></svg>
                <span>Back</span>
              </button>
            </div>
          </template>
          <template v-else-if="gsdModal.kind === 'client'">
            <div class="gsd-client-head">
              <div class="gsd-simple-title">{{ gsdModal.title }}</div>
            </div>
            <div class="gsd-client-body">
              <template v-if="gsdModal.clientView === 'search'">
                <div class="gsd-client-search">
                  <select v-model="gsdModal.clientMode" :disabled="!gsdModal.editing" @change="clearGsdClientDetail">
                    <option value="id">By ID</option>
                    <option value="namecode">By NameCode</option>
                  </select>
                  <input
                    ref="gsdClientSearchInput"
                    v-model.trim="gsdModal.text"
                    :disabled="!gsdModal.editing"
                    type="text"
                    placeholder="Type ID or NameCode..."
                    @input="uppercaseClientSearch"
                    @keydown.enter.prevent="showFirstGsdClientDetail"
                  />
                </div>
                <div v-if="gsdModal.text.trim()" class="gsd-client-results">
                  <button
                    v-for="client in gsdClientResults"
                    :key="client.entityId || client.id || client.namecode"
                    class="gsd-client-row"
                    :class="{ on: isSelectedGsdClient(client) }"
                    type="button"
                    @click="showGsdClientDetail(client)"
                  >
                    <span class="nc">{{ client.namecode || '-' }}</span>
                    <span class="id">{{ client.id || '(no id)' }}</span>
                    <span class="co">{{ client.companyName || '' }}</span>
                  </button>
                  <div v-if="!gsdClientResults.length" class="gsd-client-empty">No client found. Use "Add New" to create one.</div>
                </div>
                <div class="gsd-client-actions">
                  <button class="wb-modal-btn primary" type="button" :disabled="!gsdModal.editing" @click="openNewClientForm">Add New</button>
                </div>
              </template>

              <template v-else-if="gsdModal.clientView === 'detail'">
                <div class="gsd-client-detail">
                  <div v-for="item in clientDetailRows(gsdModal.selectedClient)" :key="item.label" class="gsd-client-detail-row">
                    <div class="key">{{ item.label }}</div>
                    <div class="value" :class="{ empty: !item.value }">{{ item.value || '-' }}</div>
                  </div>
                </div>
                <div class="gsd-client-usebar">
                  <button v-if="canEditClientLinkCell(gsdModal.row, gsdModal.column)" class="wb-modal-btn slate" type="button" @click="backToClientSearch">Back</button>
                  <button v-if="canEditClientLinkCell(gsdModal.row, gsdModal.column)" class="wb-modal-btn edit" type="button" @click="openEditClientForm">Edit</button>
                  <button v-if="canEditClientLinkCell(gsdModal.row, gsdModal.column)" class="wb-modal-btn primary" type="button" :disabled="!gsdModal.editing" @click="useSelectedGsdClient">Use this {{ gsdModal.clientRole }}</button>
                </div>
              </template>

              <template v-else>
                <div class="gsd-new-client-title">{{ gsdModal.clientView === 'edit' ? 'Edit Client' : 'New Client' }}</div>
                <datalist id="gsd-city-options">
                  <option v-for="option in cityOptions" :key="option" :value="option" />
                </datalist>
                <datalist id="gsd-country-options">
                  <option v-for="option in countryOptions" :key="option" :value="option" />
                </datalist>
                <div class="gsd-new-client-form">
                  <label class="full">
                    <span>ID</span>
                    <div class="gsd-client-id-preview" :class="{ empty: clientIdPreview === 'auto' }">{{ clientIdPreview }}</div>
                  </label>
                  <label><span>NameCode</span><input v-model.trim="gsdModal.clientForm.namecode" :disabled="!gsdModal.editing" @input="uppercaseClientField('namecode')" /></label>
                  <label><span>Company Name</span><input v-model.trim="gsdModal.clientForm.companyName" :disabled="!gsdModal.editing" @input="uppercaseClientField('companyName')" /></label>
                  <label class="full"><span>Address</span><input v-model.trim="gsdModal.clientForm.address" :disabled="!gsdModal.editing" @input="uppercaseClientField('address')" /></label>
                  <label class="with-plus"><span>City / Province</span><input v-model.trim="gsdModal.clientForm.city" list="gsd-city-options" :disabled="!gsdModal.editing" placeholder="Type to select" @input="uppercaseClientField('city')" /><button type="button" :disabled="!gsdModal.editing" @click="openEntityOptionModal('city')">+</button></label>
                  <label class="with-plus"><span>Country</span><input v-model.trim="gsdModal.clientForm.country" list="gsd-country-options" :disabled="!gsdModal.editing" placeholder="Type to select" @input="uppercaseClientField('country')" /><button type="button" :disabled="!gsdModal.editing" @click="openEntityOptionModal('country')">+</button></label>
                  <label><span>PIC Name</span><input v-model.trim="gsdModal.clientForm.picName" :disabled="!gsdModal.editing" @input="uppercaseClientField('picName')" /></label>
                  <label><span>Phone</span><input v-model.trim="gsdModal.clientForm.phone" :disabled="!gsdModal.editing" /></label>
                  <label class="full"><span>Email</span><input v-model.trim="gsdModal.clientForm.email" autocomplete="off" :class="{ invalid: !!gsdModal.clientForm.email && !emailOk(gsdModal.clientForm.email) }" :disabled="!gsdModal.editing" @input="uppercaseClientField('email')" /></label>
                  <label><span>Status</span><select v-model="gsdModal.clientForm.status" :disabled="!gsdModal.editing"><option>ACTIVE</option><option>INACTIVE</option></select></label>
                </div>
                <div class="gsd-client-form-actions">
                  <button type="button" class="wb-modal-btn slate" @click="backFromClientForm">Back</button>
                  <button type="button" class="wb-modal-btn cancel" @click="resetClientForm">Cancel</button>
                  <button type="button" class="wb-modal-btn primary" :disabled="!gsdModal.editing || clientSavePending" @click="saveGsdModal">{{ gsdModal.clientView === 'edit' ? 'Save Changes' : 'Save Client' }}</button>
                </div>
              </template>
            </div>
          </template>
          <template v-else-if="gsdModal.kind === 'dealt'">
            <div class="gsd-dealt-body">
              <div class="gsd-dealt-section">
                <div class="gsd-dealt-label">Inquiry information</div>
                <textarea ref="dealtInquiryInput" v-model="gsdModal.dealt.inquiry" class="gsd-dealt-textarea sm" :readonly="!gsdModal.editing"></textarea>
              </div>
              <div class="gsd-dealt-columns">
                <div class="gsd-dealt-section">
                  <div class="gsd-dealt-label">Cost</div>
                  <textarea v-model="gsdModal.dealt.cost" class="gsd-dealt-textarea lg" :readonly="!gsdModal.editing"></textarea>
                </div>
                <div class="gsd-dealt-section">
                  <div class="gsd-dealt-label">Quotation</div>
                  <textarea v-model="gsdModal.dealt.quote" class="gsd-dealt-textarea lg" :readonly="!gsdModal.editing"></textarea>
                </div>
              </div>
              <div class="gsd-dealt-section">
                <div class="gsd-dealt-label">Remarks</div>
                <textarea v-model="gsdModal.dealt.remarks" class="gsd-dealt-textarea sm" :readonly="!gsdModal.editing"></textarea>
              </div>
              <div class="gsd-dealt-section gsd-dealt-attach">
                <button class="gsd-dealt-attach-btn" type="button" :disabled="!gsdModal.editing" @click="triggerDealtFiles">📎 ATTACH FILES</button>
                <input ref="dealtFileInput" type="file" multiple hidden accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.xls,.xlsx,.csv,.txt,.zip,.rar,.7z" @change="addDealtFiles" />
                <div class="gsd-dealt-files">
                  <div v-for="(file, index) in gsdModal.dealt.files" :key="`${file.name}-${index}`" class="gsd-dealt-file">
                    <span class="file-icon">📄</span>
                    <button type="button" class="gsd-dealt-file-link" :title="`View ${file.name}`" @click="viewDealtFile(file)">{{ file.name }}</button>
                    <button v-if="gsdModal.editing" type="button" title="Remove" @click="removeDealtFile(index)">×</button>
                  </div>
                </div>
              </div>
            </div>
          </template>
          <template v-else-if="gsdModal.kind === 'hbl'">
            <div class="gsd-hbl-title">Is HBL required for this batch?</div>
            <div class="gsd-hbl-buttons">
              <button class="wb-modal-btn" :class="{ primary: gsdModal.form.required === 'YES' }" type="button" :disabled="!gsdModal.editing" @click="setHblRequired('YES')">YES</button>
              <button class="wb-modal-btn" :class="{ primary: gsdModal.form.required === 'NO' }" type="button" :disabled="!gsdModal.editing" @click="setHblRequired('NO')">NO</button>
            </div>
            <input
              v-model.trim="gsdModal.form.hblNo"
              class="gsd-hbl-input"
              type="text"
              placeholder="Enter HBL NO#"
              autocomplete="off"
              :disabled="!gsdModal.editing || gsdModal.form.required !== 'YES'"
              @input="uppercaseHblInput"
              @keydown.enter.prevent="saveGsdModal"
            />
            <div class="gsd-hbl-hint">{{ gsdModal.form.hint || '' }}</div>
          </template>
          <template v-else-if="isCutoffModal()">
            <div v-if="!isCcdCutoffModal()" class="gsd-cutoff-form">
              <div class="gsd-cutoff-block">
                <div class="gsd-cutoff-label">SI CUTOFF</div>
                <div class="gsd-cutoff-inputs">
                  <button class="gsd-cutoff-date" type="button" @click="openCutoffDatePopup('siDate', $event)"><span :class="{ placeholder: !gsdModal.form.siDate }">{{ cutoffDateLabel(gsdModal.form.siDate) }}</span><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M8 2v4M16 2v4M3 10h18"/></svg></button>
                  <button class="gsd-cutoff-time" type="button" @click="openCutoffTimePopup('siTime', $event)"><span :class="{ placeholder: !gsdModal.form.siTime }">{{ gsdModal.form.siTime || '-- : --' }}</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></button>
                </div>
              </div>
              <div class="gsd-cutoff-block">
                <div class="gsd-cutoff-label">{{ isLclSheet() ? 'CFS CUTOFF' : 'CY CUTOFF' }}</div>
                <div class="gsd-cutoff-inputs">
                  <button class="gsd-cutoff-date" type="button" @click="openCutoffDatePopup('cyDate', $event)"><span :class="{ placeholder: !gsdModal.form.cyDate }">{{ cutoffDateLabel(gsdModal.form.cyDate) }}</span><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M8 2v4M16 2v4M3 10h18"/></svg></button>
                  <button class="gsd-cutoff-time" type="button" @click="openCutoffTimePopup('cyTime', $event)"><span :class="{ placeholder: !gsdModal.form.cyTime }">{{ gsdModal.form.cyTime || '-- : --' }}</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></button>
                </div>
              </div>
            </div>
            <div v-if="!isCcdCutoffModal()" class="gsd-cutoff-savebar">
              <button class="wb-modal-btn primary" type="button" :disabled="!cutoffHasInput()" @click="saveCutoffRecord">Save</button>
            </div>
            <div v-if="!isCcdCutoffModal()" class="gsd-cutoff-hint">{{ gsdModal.form.hint || '' }}</div>
            <div class="gsd-cutoff-history">
              <table class="gsd-cutoff-table">
                <thead>
                  <tr>
                    <th colspan="3">SI CUTOFF</th>
                    <th colspan="2">{{ isLclSheet() ? 'CFS CUTOFF' : 'CY CUTOFF' }}</th>
                    <th>STATUS</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(item, index) in cutoffRecords()" :key="item.id" :class="{ selected: gsdModal.form.selectedId === item.id }" @click="selectCutoffRecord(item.id)">
                    <td>{{ index + 1 }}</td>
                    <td>{{ formatCutoffDate(item.siDate) || '-' }}</td>
                    <td>{{ item.siTime || '-' }}</td>
                    <td>{{ formatCutoffDate(item.cyDate) || '-' }}</td>
                    <td>{{ item.cyTime || '-' }}</td>
                    <td :class="index === 0 ? 'applied' : 'expired'">{{ index === 0 ? 'Applied' : 'Expired' }}</td>
                  </tr>
                  <tr v-if="!cutoffRecords().length">
                    <td colspan="6" class="empty">No cutoff saved yet</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <div class="gsd-cutoff-footer">
              <button class="wb-modal-btn slate" type="button" @click="closeGsdModal">Close</button>
              <button v-if="!isCcdCutoffModal()" class="wb-modal-btn edit" type="button" :disabled="!gsdModal.form.selectedId" @click="editCutoffRecord">Edit</button>
              <button v-if="!isCcdCutoffModal()" class="wb-modal-btn cancel" type="button" :disabled="!gsdModal.form.selectedId" @click="removeCutoffRecord">Remove</button>
            </div>
          </template>
          <template v-else-if="isVolumeModal()">
            <div v-if="!isCcdVolumeModal()" class="gsd-volume-form" :class="{ lcl: isLclSheet() }">
              <div class="gsd-volume-block">
                <div class="gsd-volume-label">VOLUME</div>
                <input v-model.trim="gsdModal.form.volume" type="number" min="1" step="1" placeholder="Qty" @input="clearRecordHint" />
              </div>
              <div class="gsd-volume-block">
                <div class="gsd-volume-label">{{ isLclSheet() ? 'UNIT' : 'TYPE' }} <button class="gsd-plusmini" type="button" @click="startVolumeOption('type')">+</button></div>
                <select v-model="gsdModal.form.type" @change="clearRecordHint">
                  <option value="">-- select --</option>
                  <option v-for="option in gsdModal.form.typeOptions" :key="option" :value="option">{{ option }}</option>
                </select>
                <div v-if="gsdModal.form.addOption === 'type'" class="gsd-option-add">
                  <input v-model.trim="gsdModal.form.newOption" type="text" :placeholder="isLclSheet() ? 'New UNIT' : 'New TYPE'" @input="uppercaseVolumeOption" @keydown.enter.prevent="saveVolumeOption" />
                  <button type="button" @click="saveVolumeOption">Add</button>
                  <button type="button" class="cancel" @click="cancelVolumeOption">Cancel</button>
                </div>
              </div>
              <template v-if="isLclSheet()">
                <div class="gsd-volume-block">
                  <div class="gsd-volume-label">G.W</div>
                  <input v-model.trim="gsdModal.form.gw" type="number" min="0" step="any" placeholder="Weight" @input="clearRecordHint" />
                </div>
                <div class="gsd-volume-block">
                  <div class="gsd-volume-label">UNIT</div>
                  <select v-model="gsdModal.form.gwUnit" @change="clearRecordHint">
                    <option>KGS</option>
                    <option>LBS</option>
                  </select>
                </div>
                <div class="gsd-volume-block">
                  <div class="gsd-volume-label">MEA.(CBM)</div>
                  <input v-model.trim="gsdModal.form.mea" type="number" min="0" step="any" placeholder="CBM" @input="clearRecordHint" />
                </div>
              </template>
              <div v-else class="gsd-volume-block">
                <div class="gsd-volume-label">PURPOSE <button class="gsd-plusmini" type="button" @click="startVolumeOption('purpose')">+</button></div>
                <select v-model="gsdModal.form.purpose" @change="clearRecordHint">
                  <option value="">-- select --</option>
                  <option v-for="option in gsdModal.form.purposeOptions" :key="option" :value="option">{{ option }}</option>
                </select>
                <div v-if="gsdModal.form.addOption === 'purpose'" class="gsd-option-add">
                  <input v-model.trim="gsdModal.form.newOption" type="text" placeholder="New PURPOSE" @input="uppercaseVolumeOption" @keydown.enter.prevent="saveVolumeOption" />
                  <button type="button" @click="saveVolumeOption">Add</button>
                  <button type="button" class="cancel" @click="cancelVolumeOption">Cancel</button>
                </div>
              </div>
            </div>
            <div v-if="!isCcdVolumeModal()" class="gsd-record-savebar">
              <button class="wb-modal-btn primary" type="button" :disabled="!volumeHasInput()" @click="saveVolumeRecord">Save</button>
            </div>
            <div v-if="!isCcdVolumeModal()" class="gsd-record-hint" :class="{ editing: !!gsdModal.form.editId }">{{ gsdModal.form.hint || '' }}</div>
            <div class="gsd-record-history">
              <table class="gsd-record-table volume">
                <thead>
                  <tr v-if="isLclSheet() && isCcdVolumeModal()"><th>ORDER</th><th>VOLUME</th><th>G.WEIGHT</th><th>MEA</th></tr>
                  <tr v-else-if="isLclSheet()"><th>ORDER</th><th>VOLUME</th><th>G.W</th><th>MEA.(CBM)</th></tr>
                  <tr v-else><th>ORDER</th><th>VOLUME</th><th>TYPE</th><th>PURPOSE</th></tr>
                </thead>
                <tbody>
                  <tr v-for="(item, index) in volumeRecords()" :key="item.id" :class="{ selected: !isReadonlyTcdVolumeModal() && gsdModal.form.selectedId === item.id }" @click="!isReadonlyTcdVolumeModal() && selectRecord(item.id)">
                    <td>{{ index + 1 }}</td>
                    <template v-if="isLclSheet()">
                      <td>{{ `${item.volume || ''} ${item.type || ''}`.trim() }}</td>
                      <td>{{ item.gw ? `${item.gw} ${item.gwUnit || ''}`.trim() : '—' }}</td>
                      <td>{{ item.mea ? `${item.mea} CBM` : '—' }}</td>
                    </template>
                    <template v-else>
                      <td>{{ item.volume }}</td>
                      <td>{{ item.type }}</td>
                      <td>{{ item.purpose }}</td>
                    </template>
                  </tr>
                  <tr v-if="!volumeRecords().length"><td colspan="4" class="empty">No volume saved yet</td></tr>
                </tbody>
              </table>
            </div>
            <div class="gsd-record-footer">
              <button class="wb-modal-btn slate" type="button" @click="closeGsdModal">Close</button>
              <button v-if="!isCcdVolumeModal()" class="wb-modal-btn edit" type="button" :disabled="!gsdModal.form.selectedId" @click="editVolumeRecord">{{ gsdModal.form.editId ? 'Editing...' : 'Edit' }}</button>
              <button v-if="!isCcdVolumeModal()" class="wb-modal-btn cancel" type="button" :disabled="!gsdModal.form.selectedId" @click="removeVolumeRecord">Remove</button>
            </div>
          </template>
          <template v-else-if="isFreetimeModal()">
            <div class="gsd-free-title">FREETIME CONFIRMATION</div>
