                <input v-model.trim="gsdModal.form.dem" type="number" min="0" step="1" placeholder="0" @input="clearRecordHint" />
              </div>
              <div class="gsd-volume-block">
                <div class="gsd-volume-label">DET</div>
                <input v-model.trim="gsdModal.form.det" type="number" min="0" step="1" placeholder="0" @input="clearRecordHint" />
              </div>
            </div>
