            <div class="gsd-record-history">
              <table class="gsd-record-table free">
                <thead><tr><th>DEM</th><th>DET</th><th>STATUS</th></tr></thead>
                <tbody>
                  <tr v-for="(item, index) in freetimeRecords()" :key="item.id" :class="{ selected: gsdModal.form.selectedId === item.id }" @click="selectRecord(item.id)">
                    <td>{{ item.dem }}</td>
                    <td>{{ item.det }}</td>
                    <td :class="index === 0 ? 'applied' : 'expired'">{{ index === 0 ? 'Applied' : 'Expired' }}</td>
                  </tr>
                  <tr v-if="!freetimeRecords().length"><td colspan="3" class="empty">No freetime saved yet</td></tr>
                </tbody>
              </table>
            </div>
