          <template v-else-if="isRouteModal()">
            <div v-if="gsdModal.form.view !== 'add'" class="gsd-route-search">
              <div class="gsd-route-head">ROUTE <button v-if="gsdModal.editing" class="gsd-plusmini" type="button" title="Add new route" @click="showRouteAdd">+</button></div>
              <label class="gsd-route-field">
                <span>Route</span>
                <input
                  v-model.trim="gsdModal.form.route"
                  class="gsd-route-input"
                  list="gsd-route-options"
                  type="text"
                  placeholder="Type route code e.g. CNSHA-VNHCM"
                  autocomplete="off"
                  :disabled="!gsdModal.editing"
                  @input="updateRouteSearch"
                  @keydown.enter.prevent="saveRouteSelection"
                />
              </label>
              <datalist id="gsd-route-options">
                <option v-for="route in routeDirectory" :key="routeLabel(route)" :value="routeLabel(route)">{{ route.pol }} → {{ route.pod }}</option>
              </datalist>
              <div class="gsd-route-hint" :class="{ ok: gsdModal.form.routeOk }">{{ gsdModal.form.hint || '' }}</div>
              <div class="gsd-route-actions">
                <button v-if="gsdModal.editing" class="wb-modal-btn primary" type="button" :disabled="!gsdModal.form.routeOk" @click="saveRouteSelection">Save</button>
              </div>
            </div>
            <div v-else class="gsd-route-add">
              <div class="gsd-route-grid">
                <label><span>POL</span><input v-model.trim="gsdModal.form.pol" type="text" @input="uppercaseRouteAdd('pol')" /></label>
                <label><span>COUNTRY/AREA</span><select v-model="gsdModal.form.polC" @change="uppercaseRouteAdd('polC')"><option value="">Select country/area</option><option v-for="country in routeCountryOptions" :key="`route-pol-${country}`" :value="country">{{ country }}</option></select></label>
                <label><span>CODE</span><input v-model.trim="gsdModal.form.polCode" type="text" @input="uppercaseRouteAdd('polCode')" /></label>
                <label><span>POD</span><input v-model.trim="gsdModal.form.pod" type="text" @input="uppercaseRouteAdd('pod')" /></label>
                <label><span>COUNTRY/AREA</span><select v-model="gsdModal.form.podC" @change="uppercaseRouteAdd('podC')"><option value="">Select country/area</option><option v-for="country in routeCountryOptions" :key="`route-pod-${country}`" :value="country">{{ country }}</option></select></label>
                <label><span>CODE</span><input v-model.trim="gsdModal.form.podCode" type="text" @input="uppercaseRouteAdd('podCode')" /></label>
              </div>
              <div class="gsd-route-hint" :class="{ ok: gsdModal.form.routeSaved }">{{ gsdModal.form.hint || '' }}</div>
              <div class="gsd-route-actions add">
                <button class="wb-modal-btn slate" type="button" @click="showRouteSearch">Cancel</button>
                <button class="wb-modal-btn primary" type="button" :disabled="gsdModal.form.routeSaved" @click="saveRoutePending">Save</button>
                <button class="wb-modal-btn primary" type="button" :disabled="!gsdModal.form.routeSaved" @click="addPendingRouteToCell">Add route</button>
              </div>
            </div>
          </template>
          <template v-else-if="isAirDcdVesselHistoryModal()">
            <div class="gsd-vhist-head">VESSEL / VOYAGE</div>
            <div class="gsd-vhist-wrap">
              <table class="gsd-vhist-table">
                <thead>
                  <tr><th>Order</th><th>Time</th><th>VesselName</th><th>VoyageNo</th><th>ETD</th><th>ETA</th><th>Reason</th><th>Type</th><th>Status</th></tr>
                </thead>
                <tbody>
                  <template v-if="airDcdVesselHistory().length">
                    <tr v-for="(item, index) in airDcdVesselHistory()" :key="`${item.order}-${index}`">
                      <td>{{ item.order }}</td>
                      <td>{{ item.time || '—' }}</td>
                      <td>{{ item.name || '—' }}</td>
                      <td>{{ item.voyage || '—' }}</td>
                      <td>{{ formatVesselHistoryDate(item.etd) || '—' }}</td>
                      <td>{{ formatVesselHistoryDate(item.eta) || '—' }}</td>
                      <td>{{ item.reason || '—' }}</td>
                      <td><span class="gsd-vty" :class="item.type === 'DELAY' ? 'dly' : 'sel'">{{ item.type }}</span></td>
                      <td :class="item.status === 'Applied' ? 'applied' : 'expired'">{{ item.status }}</td>
                    </tr>
                  </template>
                  <tr v-else><td colspan="9" class="empty">No information yet.</td></tr>
                </tbody>
              </table>
            </div>
