    <div v-if="bookingDetailModal.open" class="wb-modal-overlay booking-detail-overlay" @mousedown.self="closeBookingDetail">
      <div class="booking-detail-modal" role="dialog" aria-modal="true">
        <button class="booking-detail-x" type="button" @click="closeBookingDetail">&times;</button>
        <div class="booking-detail-title">BOOKING DETAIL</div>
        <div class="booking-detail-row">
          <label>Booking No#:</label>
          <input v-model.trim="bookingDetailModal.number" :disabled="bookingDetailModal.locked || isReadonlyTcdBookingDetail()" placeholder="Booking No#" />
          <button class="booking-icon" :class="{ attached: !!bookingDetailModal.url, uploading: bookingDetailModal.uploading }" type="button" :title="bookingDetailModal.uploading ? 'Uploading file...' : bookingDetailModal.url ? 'Replace attached file' : 'Attach file'" :disabled="bookingDetailModal.uploading || bookingDetailModal.locked || isReadonlyTcdBookingDetail()" @click="uploadBookingNumber">
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m0 0L7.5 8.5M12 4l4.5 4.5M5 14v5h14v-5" /></svg>
          </button>
          <button class="booking-eye" :class="{ attached: !!bookingDetailModal.url }" type="button" :title="bookingDetailModal.url ? 'View attached file' : 'No file attached'" :disabled="!bookingDetailModal.url" @click="viewBookingDetailFile">
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z" /><circle cx="12" cy="12" r="2.5" /></svg>
          </button>
        </div>
        <div class="booking-doc-wrap">
          <button class="booking-add-doc" type="button" :disabled="bookingDetailModal.locked || isReadonlyTcdBookingDetail()" @click="addBookingDocument">Add Doc+</button>
          <div class="booking-doc-list">
            <div v-for="(document, index) in bookingDetailModal.documents" :key="document.id" class="booking-detail-row booking-doc-row" :class="{ 'has-remove': bookingDetailModal.documents.length > 1 && !bookingDetailModal.locked && !isReadonlyTcdBookingDetail() }">
              <input v-model.trim="document.name" :disabled="bookingDetailModal.locked || isReadonlyTcdBookingDetail()" placeholder="Document Name" />
              <button class="booking-icon" :class="{ attached: !!document.url, uploading: bookingDetailModal.uploading && bookingUploadIndex === index }" type="button" :title="bookingDetailModal.uploading && bookingUploadIndex === index ? 'Uploading file...' : document.url ? 'Replace attached file' : 'Attach file'" :disabled="bookingDetailModal.uploading || bookingDetailModal.locked || isReadonlyTcdBookingDetail()" @click="uploadBookingDocument(index)">
                <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m0 0L7.5 8.5M12 4l4.5 4.5M5 14v5h14v-5" /></svg>
              </button>
              <button class="booking-eye" :class="{ attached: !!document.url }" type="button" :title="document.url ? 'View attached file' : 'No file attached'" :disabled="!document.url" @click="viewBookingDocument(index)">
                <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z" /><circle cx="12" cy="12" r="2.5" /></svg>
              </button>
              <button v-if="!bookingDetailModal.locked && !isReadonlyTcdBookingDetail() && bookingDetailModal.documents.length > 1" class="booking-remove" type="button" title="Remove" @click="removeBookingDocument(index)">&times;</button>
            </div>
          </div>
        </div>
        <input ref="bookingDetailInput" class="booking-file-input" type="file" @change="onBookingDetailFile" />
        <div v-if="!isReadonlyTcdBookingDetail()" class="booking-detail-actions">
          <button class="wb-modal-btn slate" type="button" :disabled="bookingDetailModal.locked" @click="clearBookingDetail">Clear</button>
          <button class="wb-modal-btn edit" type="button" :disabled="!bookingDetailModal.locked" @click="bookingDetailModal.locked = false">Edit</button>
          <button class="wb-modal-btn primary" type="button" :disabled="bookingDetailModal.locked" @click="saveBookingDetail">Save</button>
        </div>
      </div>
    </div>
