    <div v-if="preDocsModal.open" class="wb-modal-overlay wsmodal-overlay pre-docs-overlay" @mousedown.self="closePreDocsModal">
      <div class="wsmodal pdc-modal" :class="{ 'gsd-air-aux-modal': isAirSheet() }" role="dialog" aria-modal="true">
        <button class="pdc-close" type="button" title="Close" @click="closePreDocsModal">&times;</button>
        <div class="pdc-title">ATTACH DEST. CLEARANCE DOCS</div>
        <div class="pdc-mock-toolbar"><button class="wb-modal-btn primary" type="button" :disabled="!preDocsModal.editing" @click="addPreDocsOther">Add+</button></div>
        <div class="pdc-mock-body">
          <div class="pdc-mock-row">
            <span>COMMERCIAL INVOICE (CI)</span>
            <input :checked="preDocsData().ci.on" type="checkbox" :disabled="!preDocsModal.editing" @change="setPreDocsChecked('ci', ($event.target as HTMLInputElement).checked)" />
            <button class="pdc-mock-icon upload" :class="{ has: preDocsData().ci.files.length }" type="button" :disabled="!preDocsModal.editing || !preDocsData().ci.on" title="Upload" @click="choosePreDocsFile('ci')"><svg viewBox="0 0 24 24"><path d="M12 15V5M8 9l4-4 4 4"/><path d="M5 14v4h14v-4"/></svg><b v-if="preDocsData().ci.files.length">({{ preDocsData().ci.files.length }})</b></button>
            <button class="pdc-mock-icon eye" :class="{ on: preDocsData().ci.files.length }" type="button" :disabled="!preDocsData().ci.files.length" title="View" @click="viewPreDocsFiles(preDocsData().ci.files)"><svg viewBox="0 0 24 24"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button>
          </div>
          <div class="pdc-mock-row">
            <span>PACKING LIST (PL)</span>
            <input :checked="preDocsData().pl.on" type="checkbox" :disabled="!preDocsModal.editing" @change="setPreDocsChecked('pl', ($event.target as HTMLInputElement).checked)" />
            <button class="pdc-mock-icon upload" :class="{ has: preDocsData().pl.files.length }" type="button" :disabled="!preDocsModal.editing || !preDocsData().pl.on" title="Upload" @click="choosePreDocsFile('pl')"><svg viewBox="0 0 24 24"><path d="M12 15V5M8 9l4-4 4 4"/><path d="M5 14v4h14v-4"/></svg><b v-if="preDocsData().pl.files.length">({{ preDocsData().pl.files.length }})</b></button>
            <button class="pdc-mock-icon eye" :class="{ on: preDocsData().pl.files.length }" type="button" :disabled="!preDocsData().pl.files.length" title="View" @click="viewPreDocsFiles(preDocsData().pl.files)"><svg viewBox="0 0 24 24"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button>
          </div>
