                <button v-if="preDocsModal.editing" class="pdc-del" type="button" title="Remove" @click="removePreDocsFile('ci', fi)">×</button>
              </div>
              <button class="pdc-up" type="button" :disabled="!preDocsModal.editing" title="Upload" @click="choosePreDocsFile('ci')">+</button>
            </div>
          </div>
          <div class="pdc-sec">
            <label class="pdc-label"><input v-model="preDocsData().pl.on" type="checkbox" :disabled="!preDocsModal.editing" /> <span>PACKING LIST (PL)</span></label>
            <div class="pdc-files">
              <div v-for="(f, fi) in preDocsData().pl.files" :key="fi" class="pdc-file">
