                <button v-if="preDocsModal.editing" class="pdc-del" type="button" title="Remove" @click="removePreDocsFile('pl', fi)">×</button>
              </div>
              <button class="pdc-up" type="button" :disabled="!preDocsModal.editing" title="Upload" @click="choosePreDocsFile('pl')">+</button>
            </div>
          </div>
          <div v-for="(o, oi) in preDocsData().others" :key="oi" class="pdc-sec">
