            <div class="pdc-files">
              <div v-for="(f, fi) in o.files" :key="fi" class="pdc-file">
                <button class="pdc-view" type="button" :title="f.name" @click="viewPreDocsFile(f)">{{ f.name }}</button>
                <button v-if="preDocsModal.editing" class="pdc-del" type="button" title="Remove" @click="removePreDocsFile('other', fi, oi)">×</button>
              </div>
              <button class="pdc-up" type="button" :disabled="!preDocsModal.editing" title="Upload" @click="choosePreDocsFile('other', oi)">+</button>
