    <div v-if="paymentHistoryPicker.open" class="wb-modal-overlay payment-history-overlay" @mousedown.self="closePaymentHistoryPicker">
      <div class="wb-modal payment-history-modal" role="dialog" aria-modal="true">
        <button class="gsd-modal-x" type="button" @click="closePaymentHistoryPicker">×</button>
        <div class="payment-history-head"><b>REF LAST BUSINESS</b></div>
        <div v-if="paymentHistoryPicker.row >= 0" class="payment-history-selected">Selected JOB NO#: <b>{{ paymentHistoryPicker.jobNo || '—' }}</b> &nbsp; REF NO#: <b>{{ paymentHistoryPicker.refNo || '—' }}</b></div>
        <div v-if="paymentHistoryPicker.row >= 0" class="payment-history-scroll"><table><thead><tr><th><input type="checkbox" :checked="paymentHistoryAllSelected()" @change="toggleAllPaymentHistory" /></th><th>CHARGE NAME</th><th>PAY TO</th><th>PAY AT</th><th>CUR.</th><th>TOTAL PAY</th><th>COLLECT FROM</th><th>COLLECT AT</th><th>CUR.</th><th>TOTAL COLLECT</th></tr></thead><tbody><tr v-for="line in paymentHistoryPicker.lines" :key="line.id"><td><input v-model="line.selected" type="checkbox" /></td><td>{{ line.chargeName }}</td><td :class="{ warning: !paymentPartyKnown(line.payTo) }">{{ line.payTo }}</td><td>{{ line.payAt }}</td><td :class="{ warning: !paymentCurrencyKnown(line.curPay) }">{{ line.curPay }}</td><td>{{ line.totalPay }}</td><td :class="{ warning: !paymentCollectKnown(line.collectFrom) }">{{ line.collectFrom }}</td><td>{{ line.collectAt }}</td><td :class="{ warning: !paymentCurrencyKnown(line.curCollect) }">{{ line.curCollect }}</td><td>{{ line.totalCollect }}</td></tr></tbody></table></div>
        <div class="payment-history-actions"><button class="cancel" type="button" @click="closePaymentHistoryPicker">Cancel</button><button class="select" type="button" :disabled="!paymentHistoryPicker.lines.some((line:any) => line.selected)" @click="selectPaymentHistoryLines">Use selected data</button></div>
      </div>
