      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>
      <span>{{ toastMessage }}</span>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, onUpdated, reactive, ref, watch } from 'vue'
import { OPS_TERMS, opsBaseForType, opsDeptsFor, opsHeaderFor, opsLeafKey, opsStatusKey, parseOpsKey } from '~/composables/useOpsSheet'

type SheetTab = { key: string; label: string }
type CellPosition = { row: number; column: number }
type SelectionKind = 'cell' | 'row' | 'col' | 'all' | 'cellctrl' | null
type ResizeState = {
  type: 'col' | 'row'
  index: number
  startX: number
  startY: number
  startW: number
  startH: number
}
type ColumnFormatKind = 'dropdown' | 'checkbox' | ''
type ColumnFormat = { kind?: ColumnFormatKind; options?: string[] }

const props = defineProps<{
  title: string
  description?: string
  groupLabel: string
  sheetKey: string
  tabs?: SheetTab[]
  controlledTabs?: boolean
  protectedTabKeys?: string[]
  showAddTab?: boolean
  request: (url: string, options?: Record<string, any>) => Promise<any>
  countries?: any[]
  currentCountry?: any
  canSwitchCountry?: boolean
  currentUser?: { id?: string; username?: string; displayName?: string; country?: string | null } | null
}>()
const emit = defineEmits<{
  (event: 'toggle-sidebar'): void
  (event: 'select-country', country: string): void
  (event: 'select-tab', key: string): void
  (event: 'add-tab'): void
  (event: 'delete-tab', tab: SheetTab): void
  (event: 'select-ops-leaf', key: string): void
}>()

const loading = ref(false)
const dispatchLoading = ref('')
const clientSavePending = ref(false)
const rows = ref<any[][]>([])
const columnWidths = ref<number[]>([])
const rowHeights = ref<Record<string, number>>({})
const formatting = ref<Record<string, any>>({})
const merges = ref<number[][]>([])
const settings = ref<Record<string, any>>({})
const query = ref('')
const activeKey = ref(props.sheetKey)
const saveState = ref('Database ready')
const saveError = ref('')
const opsStaffNames = ref<string[]>([])
const opsStaffByDepartment = ref<Record<string, string[]>>({})
const opsStaffCountry = ref('')
let opsStaffLoading: Promise<void> | null = null

// Ops tab state follows the mockup leaf key format.
const opsParts = computed(() => parseOpsKey(activeKey.value || ''))
const orderedOpsDepts = (base: any, type: any, mode?: string) => {
  if (base === 'EFA' && type === 'EXW' && mode === 'FCL') {
    return ['GSD', 'ECD', 'TCD', 'CCD', 'DCD', 'FCD']
  }
  return opsDeptsFor(base, type)
}
const opsTypeTabs = computed<{ key: string; label: string }[]>(() => {
  if (!opsParts.value) return []
  return OPS_TERMS.map((t) => ({ key: t, label: t }))
})
const activeType = ref<string>('EXW')
const flushPendingSave = async (): Promise<boolean> => {
  if (!saveTimer) return true
  const requestedKey = saveTimerKey || activeKey.value
  const requestedCountry = saveTimerCountry || loadedCountryId.value
  if (activeKey.value !== requestedKey || loadedCountryId.value !== requestedCountry) {
    cancelOwnedSaveTimer(requestedKey, requestedCountry)
    return false
  }
  const payload = sheetPayload(requestedKey, false, requestedCountry)
  if (!cancelOwnedSaveTimer(requestedKey, requestedCountry)) return false
  return saveSheet(requestedKey, payload, requestedCountry)
}
const goOpsLeaf = (key: string) => {
  flushPendingSave()
  activeKey.value = key
  emit('select-ops-leaf', key)
}
const selectType = (key: string) => {
  const p = opsParts.value
  if (!p) return
  const base = opsBaseForType(key as any)
  const depts = orderedOpsDepts(base, key as any, p.mode)
  const dept = depts.includes(p.dept as any) ? p.dept : (depts[0] || p.dept)
  goOpsLeaf(opsLeafKey(base, p.mode, key as any, dept as any))
}
watch(opsParts, (p) => {
  if (p) {
    activeType.value = p.type || ''
  }
}, { immediate: true })

const deptTabs = computed<string[]>(() => {
  if (!opsParts.value) return []
  const defaults = orderedOpsDepts(opsParts.value.base, opsParts.value.type, opsParts.value.mode)
    .filter((dept) => !hiddenDeptTabs.value.includes(dept))
  const custom = customDeptTabs.value.filter((dept) => !defaults.includes(dept as any))
  return [...defaults, ...custom]
})
const activeDept = ref<string>('ECD')
const activeStatus = ref<string>('active')
const customDeptTabs = ref<string[]>([])
const hiddenDeptTabs = ref<string[]>([])
const deptScopeKey = (p = opsParts.value) => p ? `${p.base}::${p.type || ''}` : ''
const opsModes = ['FCL', 'LCL', 'AIR'] as const
const opsStatuses = ['active', 'pending', 'done'] as const
const opsModeTabs = computed(() => opsParts.value ? [...opsModes] : [])
const activeMode = computed(() => opsParts.value?.mode || 'FCL')
const selectMode = (mode: string) => {
  const p = opsParts.value
  if (!p) return
  const dept = orderedOpsDepts(p.base, p.type, mode).includes(p.dept as any)
    ? p.dept
    : (orderedOpsDepts(p.base, p.type, mode)[0] || p.dept)
  goOpsLeaf(opsLeafKey(p.base, mode as any, p.type, dept as any))
}
const selectDept = (key: string) => {
  const p = opsParts.value
  if (!p) return
  goOpsLeaf(opsLeafKey(p.base, p.mode, p.type, key as any))
}
watch(opsParts, (p) => {
  if (p) {
    activeDept.value = p.dept
    activeStatus.value = p.status
  }
}, { immediate: true })
const canAddDept = computed(() => !!opsParts.value)
const canDeleteDept = (dept: string) => {
  return !!opsParts.value && deptTabs.value.includes(dept)
}
const addDeptPrompt = async () => {
  deptModal.name = ''
  deptModal.open = true
  await nextTick()
  deptInput.value?.focus()
}
const closeDeptModal = () => {
  deptModal.open = false
  deptModal.name = ''
}
const applyDeptModal = async () => {
  const p = opsParts.value
  if (!p) return
  const name = deptModal.name.trim().toUpperCase()
  if (!name) return
  if (!/^[A-Z0-9]{2,8}$/.test(name)) {
    showToast('Department code must be 2-8 letters/numbers')
    return
  }
  const defaults = opsDeptsFor(p.base, p.type)
  if (!customDeptTabs.value.includes(name) && !defaults.includes(name as any)) {
    customDeptTabs.value = [...customDeptTabs.value, name]
    rememberCustomDept(p, name)
  }
  closeDeptModal()
  await createDeptSheets(p, name)
  goOpsLeaf(opsLeafKey(p.base, p.mode, p.type, name as any))
  showToast(`Department ${name} added`)
}
const deleteDept = async (dept: string) => {
  const p = opsParts.value
  if (!p || !canDeleteDept(dept)) return
  if (!(await askConfirm(`Move department ${dept} and all its sheets to Dustbin?`, 'Delete department'))) return
  await deleteDeptSheets(p, dept)
  customDeptTabs.value = customDeptTabs.value.filter((item) => item !== dept)
  if (opsDeptsFor(p.base, p.type).includes(dept as any)) {
    hiddenDeptTabs.value = Array.from(new Set([...hiddenDeptTabs.value, dept]))
  }
  forgetCustomDept(p, dept)
  const fallback = deptTabs.value.find((item) => item !== dept)
  if (p.dept === dept && fallback) goOpsLeaf(opsLeafKey(p.base, p.mode, p.type, fallback as any))
  showToast(`Department ${dept} moved to Dustbin`)
}
