const opsAppliedFilters = ref<{ field: string; op: string; value: string }[]>([])
const rowMatchesOpsAdvancedFilters = (rowIndex: number) => {
  const row = rows.value[rowIndex] || []
  return opsAppliedFilters.value.every((filter) => {
    const values = filter.field === 'all'
      ? visibleColumns.value.map((column) => row[column])
      : [row[Number(filter.field)]]
    const normalizedValues = values.map((value) => String(value ?? '').trim().toLowerCase())
    if (filter.op === 'empty') return normalizedValues.every((value) => !value)
    if (filter.op === 'notempty') return normalizedValues.some((value) => !!value)
    const needle = String(filter.value || '').trim().toLowerCase()
    if (!needle) return true
    return normalizedValues.some((value) => value.includes(needle))
  })
}
const opsFilteringActive = computed(() => Boolean(query.value || opsAppliedFilters.value.length))
const addOpsFilter = () => opsAdvancedFilters.value.push({ field: 'all', op: 'contains', value: '' })
const resetOpsFilter = (index: number) => {
  const filter = opsAdvancedFilters.value[index]
  if (filter) {
    filter.op = 'contains'
    filter.value = ''
  }
}
const removeOpsFilter = (index: number) => {
  opsAdvancedFilters.value.splice(index, 1)
  if (!opsAdvancedFilters.value.length) opsAppliedFilters.value = []
}
const toggleOpsAdvancedFilter = () => {
  opsFilterOpen.value = !opsFilterOpen.value
  if (opsFilterOpen.value && !opsAdvancedFilters.value.length) addOpsFilter()
}
const applyOpsAdvancedFilter = () => {
  opsAppliedFilters.value = opsAdvancedFilters.value
    .filter((filter) => filter.op === 'empty' || filter.op === 'notempty' || String(filter.value || '').trim())
    .map((filter) => ({ ...filter }))
}
const clearOpsAdvancedFilter = () => {
  opsAdvancedFilters.value = []
  opsAppliedFilters.value = []
}
