let saveTimer: ReturnType<typeof setTimeout> | null = null
let saveTimerKey = ''
let saveTimerCountry = ''
const sheetUpdatedAtByStorageKey = new Map<string, string>()
const pendingLinkedWrites = new Set<Promise<unknown>>()
const linkedWriteChains = new Map<string, Promise<void>>()
const trackLinkedWrite = <T,>(write: Promise<T>) => {
  pendingLinkedWrites.add(write)
  void write.then(
    () => pendingLinkedWrites.delete(write),
    () => pendingLinkedWrites.delete(write),
  )
  return write
}
const resetSaveTimer = () => {
  saveTimer = null
  saveTimerKey = ''
  saveTimerCountry = ''
}
const cancelOwnedSaveTimer = (key: string, country: string) => {
  if (!saveTimer || saveTimerKey !== key || saveTimerCountry !== country) return false
  clearTimeout(saveTimer)
  resetSaveTimer()
  return true
}
const armSaveTimer = (key: string, country: string, delay: number) => {
  if (saveTimer) clearTimeout(saveTimer)
  const timer = setTimeout(() => {
    if (saveTimer !== timer || saveTimerKey !== key || saveTimerCountry !== country) return
    resetSaveTimer()
    if (activeKey.value === key && loadedCountryId.value === country && countryViewId() === country) {
      void saveSheet(key, undefined, country)
    }
  }, delay)
  saveTimer = timer
  saveTimerKey = key
  saveTimerCountry = country
}
const queueLinkedWrite = <T,>(key: string, operation: () => Promise<T>) => {
  const previous = linkedWriteChains.get(key) || Promise.resolve()
  const write = previous.catch(() => undefined).then(operation)
  const tracked = write.then(() => undefined)
  linkedWriteChains.set(key, tracked)
  const clearTrackedWrite = () => {
    if (linkedWriteChains.get(key) === tracked) linkedWriteChains.delete(key)
  }
  void tracked.then(clearTrackedWrite, clearTrackedWrite)
  trackLinkedWrite(tracked)
  return write
}
