const normalizeClientRecord = (record: any): GsdClientRecord => {
  // Client payloads may come from the workbook as upper-case JSON keys while
  // API records use camelCase. Read both forms before rendering or linking.
  const field = (...names: string[]) => names.map((name) => record?.[name]).find((value) => value != null)
  const rolesValue = field('roles', 'ROLES')
  const driversValue = field('drivers', 'DRIVERS')
  return {
    entityId: String(field('entityId', 'ENTITYID') || '').trim(),
    sourcePage: String(field('sourcePage') || '').trim(),
    sourceKind: String(field('sourceKind') || '').trim(),
    sourceCountry: String(field('sourceCountry') || '').trim(),
    sourceSortOrder: Number(field('sourceSortOrder') || 0),
    sourceData: field('sourceData') && typeof field('sourceData') === 'object' ? field('sourceData') : undefined,
    id: String(field('id', 'ID') || '').trim(),
    namecode: String(field('namecode', 'NAMECODE') || field('id', 'ID') || field('companyName', 'COMPANYNAME') || '').trim(),
    companyName: String(field('companyName', 'COMPANYNAME', 'company', 'COMPANY') || '').trim(),
    address: String(field('address', 'ADDRESS') || '').trim(),
    city: String(field('city', 'CITY') || '').trim(),
    country: String(field('country', 'COUNTRY') || '').trim(),
    picName: String(field('picName', 'PICNAME', 'pic', 'PIC') || '').trim(),
    phone: String(field('phone', 'PHONE') || '').trim(),
    email: String(field('email', 'EMAIL') || '').trim(),
    status: String(field('status', 'STATUS') || 'ACTIVE').trim(),
    roles: Array.isArray(rolesValue)
      ? rolesValue.map((role: any) => String(role || '').trim()).filter(Boolean)
      : String(field('role', 'ROLE') || '').split(',').map((role) => role.trim()).filter(Boolean),
    drivers: Array.isArray(driversValue) ? driversValue.map(normalizeTruckDriverRecord) : [],
  }
}
