const upperText = (value: any) => String(value ?? '').trim().toUpperCase()
const emailOk = (value: any) => {
  const text = String(value || '').trim()
  if (!text) return true
  return text.split(',').every((part) => /^[^\s@,]+@[^\s@,]+\.[^\s@,]+$/.test(part.trim()))
}
const optionMatch = (options: string[], value: any) => {
  const target = upperText(value)
  return options.find((option) => upperText(option) === target) || ''
}
const paymentOptionLabel = (kind: PaymentOptionKind) => {
  if (kind === 'charge') return 'Charge name'
  if (kind === 'party') return 'Pay to'
  if (kind === 'collect') return 'Collect from'
  return 'Currency'
}
const paymentOptionValues = (kind: PaymentOptionKind) => {
  if (kind === 'charge') return paymentChargeOptions.value
  if (kind === 'party') return paymentPartyOptions.value
  if (kind === 'collect') return paymentCollectOptions.value
  return paymentCurrencies.value
}
const setPaymentOptionValues = (kind: PaymentOptionKind, values: string[]) => {
  const clean = Array.from(new Set(values.map((item) => upperText(item)).filter(Boolean))).sort((a, b) => a.localeCompare(b))
  if (kind === 'charge') paymentChargeOptions.value = clean
  else if (kind === 'party') paymentPartyOptions.value = clean
  else if (kind === 'collect') paymentCollectOptions.value = clean
  else paymentCurrencies.value = clean
}
const loadPaymentChargeOptions = async () => {
  if (paymentChargesLoading.value) return
  paymentChargesLoading.value = true
  try {
    const response = await props.request('/records?country=GLOBAL&page=ref_charges&search=&limit=1000&skip=0')
    const items = Array.isArray(response?.items) ? response.items : Array.isArray(response) ? response : []
    const names = items
      .filter((record: any) => {
        const data = record?.data && typeof record.data === 'object' ? record.data : record
        const status = upperText(data?.status)
        return !status || status === 'ACTIVE'
      })
      .map((record: any) => {
        const data = record?.data && typeof record.data === 'object' ? record.data : record
        return String(data?.cname || data?.chargeName || '').trim()
      })
      .filter(Boolean)
    setPaymentOptionValues('charge', names)
  } catch (error: any) {
    paymentChargeOptions.value = []
    console.warn('Could not load Reference Data charges', error)
  } finally {
    paymentChargesLoading.value = false
  }
}
const loadPaymentPartyOptions = async () => {
  if (paymentPartiesLoading.value) return
  paymentPartiesLoading.value = true
  try {
    const pages = [
      'traders_ocean_carriers',
      'traders_ocean_agent',
      'traders_airlines',
      'traders_air_agent',
      'traders_customs_broker',
      'traders_hauliers',
      'traders_dest_agent',
    ]
    const responses = await Promise.all(pages.map((page) => props.request(
      `/records?country=${encodeURIComponent(countryViewId())}&page=${encodeURIComponent(page)}&search=&limit=1000&skip=0`,
    )))
    const allParties: string[] = []
    const collectParties: string[] = []
    responses.forEach((response: any, pageIndex) => {
      const items = Array.isArray(response?.items) ? response.items : Array.isArray(response) ? response : []
      items.forEach((record: any) => {
        const data = record?.data && typeof record.data === 'object' ? record.data : record
        if (upperText(data?.status) && upperText(data?.status) !== 'ACTIVE') return
        const value = upperText(data?.namecode || data?.company || data?.companyName || data?.id)
        if (!value) return
        allParties.push(value)
        const roles = (Array.isArray(data?.roles) ? data.roles : [data?.role]).map(upperText).filter(Boolean)
        const page = pages[pageIndex]
        const excludedPage = page === 'traders_ocean_carriers' || page === 'traders_airlines'
        const hasAllowedRole = roles.some((role: string) => !['OCEAN CARRIER', 'OCEAN CARRIERS', 'AIRLINE', 'AIRLINES'].includes(role))
        if (!excludedPage && (!roles.length || hasAllowedRole)) collectParties.push(value)
      })
    })
    setPaymentOptionValues('party', allParties)
    setPaymentOptionValues('collect', collectParties)
  } catch (error) {
    paymentPartyOptions.value = []
    paymentCollectOptions.value = []
    console.warn('Could not load Traders & Suppliers for Payment Request', error)
  } finally {
    paymentPartiesLoading.value = false
  }
}
const loadPaymentReferenceOptions = async () => {
  await Promise.all([
    loadPaymentChargeOptions(),
    loadPaymentPartyOptions(),
    (async () => {
      try {
        const [countriesResponse, currenciesResponse, banksResponse] = await Promise.all([
          props.request('/records?country=GLOBAL&page=ref_countries&search=&limit=1000&skip=0'),
          props.request('/records?country=GLOBAL&page=ref_currencies&search=&limit=1000&skip=0'),
          props.request('/records?country=GLOBAL&page=internal_banks&search=&limit=1000&skip=0'),
        ])
        const activeData = (response: any) => {
          const items = Array.isArray(response?.items) ? response.items : Array.isArray(response) ? response : []
          return items.map((record: any) => record?.data && typeof record.data === 'object' ? record.data : record)
            .filter((data: any) => !upperText(data?.status) || upperText(data?.status) === 'ACTIVE')
        }
        paymentCountries.value = Array.from(new Set(activeData(countriesResponse)
          .map((data: any) => String(data?.countryname || data?.countryName || '').trim())
          .filter(Boolean))).sort((a, b) => a.localeCompare(b))
        paymentCurrencies.value = Array.from(new Set(activeData(currenciesResponse)
          .map((data: any) => upperText(data?.curcode || data?.code))
          .filter(Boolean))).sort((a, b) => a.localeCompare(b))
        const bankDetails: Record<string, { bankName: string; currency: string; accountName: string; accountNumber: string; swift: string }> = {}
        activeData(banksResponse).forEach((data: any) => {
          const bankName = upperText(data?.bankname || data?.bankName)
          const currency = upperText(data?.currency)
          if (!bankName || !currency) return
          const label = `${bankName} (${currency})`
          bankDetails[label] = {
            bankName,
            currency,
            accountName: String(data?.accname || data?.accountName || '').trim(),
            accountNumber: String(data?.accnumber || data?.accountNumber || '').trim(),
            swift: upperText(data?.swift || data?.swiftCode),
          }
        })
        paymentBankDetails.value = bankDetails
        paymentBankOptions.value = Object.keys(bankDetails).sort((a, b) => a.localeCompare(b))
      } catch (error) {
        paymentCountries.value = []
        paymentCurrencies.value = []
        paymentBankOptions.value = []
        paymentBankDetails.value = {}
        console.warn('Could not load Payment Request reference data', error)
      }
    })(),
  ])
}
