const traderRoleForClientRole = (role: string) => {
  const normalized = upperText(role)
  if (['ORIGIN AGENT', 'DESTINATION AGENT', 'DEST. AGENT', 'AGENT', 'AGENTS'].includes(normalized)) return 'DEST. AGENT'
  if (['LINER', 'OCEAN AGENT', 'OCEAN AGENTS'].includes(normalized)) return 'OCEAN AGENT'
  if (['OCEAN CARRIER', 'OCEAN CARRIERS'].includes(normalized)) return 'OCEAN CARRIER'
  if (['AIRLINE', 'AIRLINES'].includes(normalized)) return 'AIRLINE'
  if (['AIR AGENT', 'AIR AGENTS'].includes(normalized)) return 'AIR AGENT'
  if (['CUSTOMS BROKER', 'CUSTOMS BROKERS'].includes(normalized)) return 'CUSTOMS BROKER'
  if (['HAULIER', 'HAULIERS'].includes(normalized)) return 'HAULIER'
  return normalized
}
const traderPageForRole = (role: string) => {
  const normalized = traderRoleForClientRole(role)
  if (normalized === 'DEST. AGENT') return 'traders_dest_agent'
  if (normalized === 'OCEAN CARRIER') return 'traders_ocean_carriers'
  if (normalized === 'OCEAN AGENT') return 'traders_ocean_agent'
  if (normalized === 'AIRLINE') return 'traders_airlines'
  if (normalized === 'AIR AGENT') return 'traders_air_agent'
  if (normalized === 'CUSTOMS BROKER') return 'traders_customs_broker'
  if (normalized === 'HAULIER') return 'traders_hauliers'
  return 'traders_traders'
}
const currentTraderCreator = () => String(props.currentUser?.displayName || props.currentUser?.username || '').trim()
const linkPaymentPartyToTraders = async (client: GsdClientRecord, role: string) => {
  const country = countryViewId()
  const traderRole = traderRoleForClientRole(role)
  const page = traderPageForRole(traderRole)
  const search = upperText(client.namecode || client.id || client.companyName)
  const response = await props.request('/records?country=' + encodeURIComponent(country) + '&page=' + page + '&search=' + encodeURIComponent(search) + '&limit=1000')
  const exists = (Array.isArray(response?.items) ? response.items : []).some((record: any) => {
    const data = record?.data || {}
    return upperText(data.namecode) === upperText(client.namecode) && (Array.isArray(data.roles) ? data.roles : [data.role]).map(upperText).includes(traderRole)
  })
  if (exists) return
  await props.request('/records', {
    method: 'POST',
    body: {
      country, page, kind: 'traders-suppliers', sortOrder: 0,
      data: {
        recdate: new Date().toISOString().slice(0, 10),
        id: client.id, namecode: client.namecode, role: traderRole, roles: [traderRole],
        gsd: currentTraderCreator(),
        company: client.companyName, address: client.address, city: client.city, country: client.country,
        pic: client.picName, phone: client.phone, email: client.email, status: client.status || 'ACTIVE',
      },
    },
  })
}
const savePaymentParty = async () => {
  const payload = clientFormFromRecord(paymentPartyModal.form)
  // The mockup permits direct City/Province and Country input; the datalists are
  // suggestions only and must not discard an otherwise valid entered value.
  payload.city = upperText(paymentPartyModal.form.city)
  payload.country = upperText(paymentPartyModal.form.country)
  if (!validateClientForm(payload)) return
  const role = upperText(paymentPartyModal.form.role)
  if (!role || !paymentPartyRoleOptions.value.map(upperText).includes(role)) {
    showToast('Please select a valid role')
    return
  }
  paymentPartyModal.saving = true
  try {
    const saved = await props.request('/entities/clients', {
      method: 'POST',
      body: { ...payload, roles: [role] },
    })
    const clean = normalizeClientRecord(saved?.data || saved)
    await linkPaymentPartyToTraders(clean, role)
    await loadPaymentPartyOptions()
    closePaymentPartyModal()
  } catch (error: any) {
    console.error('Could not save payment party', error)
    showToast(error?.data?.message || error?.message || 'Could not save party')
  } finally {
    paymentPartyModal.saving = false
  }
}
const closePaymentOptionModal = () => {
  paymentOptionModal.open = false
  paymentOptionModal.value = ''
  paymentOptionModal.error = ''
  paymentOptionModal.saving = false
}
const uppercasePaymentOptionField = (field: 'code' | 'value') => {
  paymentOptionModal[field] = upperText(paymentOptionModal[field])
  paymentOptionModal.error = ''
}
const savePaymentOption = async () => {
  const code = upperText(paymentOptionModal.code)
  const value = upperText(paymentOptionModal.value)
  if (!code || !value) {
    paymentOptionModal.error = 'Code and name are required'
    return
  }
  const values = paymentOptionValues(paymentOptionModal.kind)
  const optionKey = paymentOptionModal.kind === 'currency' ? code : value
  if (values.some((item) => upperText(item) === optionKey)) {
    paymentOptionModal.error = 'Already exists'
    return
  }
  paymentOptionModal.saving = true
  paymentOptionModal.error = ''
  try {
    await loadPaymentReferenceOptions()
    const currentValues = paymentOptionValues(paymentOptionModal.kind)
    if (currentValues.some((item) => upperText(item) === optionKey)) {
      paymentOptionModal.error = `${paymentOptionLabel(paymentOptionModal.kind)} already exists in Reference Data`
      return
    }
    const isCurrency = paymentOptionModal.kind === 'currency'
    await props.request('/records', {
      method: 'POST',
      body: {
        country: 'GLOBAL',
        page: isCurrency ? 'ref_currencies' : 'ref_charges',
        kind: 'reference-data',
        data: isCurrency
          ? { curcode: code, curname: value, symbol: '', status: 'ACTIVE', notes: '' }
          : { cname: value, ccode: code, status: 'ACTIVE', notes: '' },
        sortOrder: currentValues.length + 1,
      },
    })
    await loadPaymentReferenceOptions()
    closePaymentOptionModal()
  } catch (error: any) {
    paymentOptionModal.error = error?.data?.message || error?.message || `Could not add ${paymentOptionLabel(paymentOptionModal.kind)}`
  } finally {
    paymentOptionModal.saving = false
  }
}
const sharedOptionPage = (type: 'city' | 'country') => `sm_option_${type}`
const normalizeSharedOption = (value: any) => upperText(value)
const entityCountryCode = (value: any) => {
  const key = upperText(value)
  return entityCountryCodes[key] || key.replace(/[^A-Z]/g, '').slice(0, 2) || 'XX'
}
const ddmmyy = (date = new Date()) => {
  const part = (value: number) => String(value).padStart(2, '0')
  return `${part(date.getDate())}${part(date.getMonth() + 1)}${String(date.getFullYear()).slice(-2)}`
}
const clientIdPreview = computed(() => {
  if (gsdModal.clientView === 'edit' && gsdModal.selectedClient?.id) return gsdModal.selectedClient.id
  const form = gsdModal.clientForm
  const city = optionMatch(cityOptions.value, form.city)
  const country = optionMatch(countryOptions.value, form.country)
  const complete = requiredClientFields.every((field) => String((form as any)[field] || '').trim()) && city && country && emailOk(form.email)
  return complete ? `${entityCountryCode(country)}${ddmmyy()}01` : 'auto'
})
const loadEntityOptions = async (type: 'city' | 'country') => {
  try {
    const requests = [props.request(`/records?country=GLOBAL&page=${encodeURIComponent(sharedOptionPage(type))}&limit=1000`)]
    if (type === 'country') requests.push(props.request('/records?country=GLOBAL&page=ref_countries&limit=1000'))
    const responses = await Promise.all(requests)
    const items = responses.flatMap((res: any) => Array.isArray(res?.items) ? res.items : [])
    const fromDb = items
      .map((item: any) => normalizeSharedOption(item?.data?.countryname || item?.data?.value || item?.data?.label || item?.data?.name))
      .filter(Boolean)
    const defaults = type === 'country' ? defaultClientCountries : []
    const values = Array.from(new Set([...defaults, ...fromDb].filter(Boolean))).sort((a, b) => a.localeCompare(b))
    if (type === 'city') cityOptions.value = values
    else countryOptions.value = values
  } catch (error) {
    console.error(`Could not load ${type} options`, error)
  }
}
const loadClientOptionLists = () => {
  void loadEntityOptions('city')
  void loadEntityOptions('country')
}
