    const routes = (Array.isArray(res?.items) ? res.items : [])
      .map((item: any) => normalizeRouteRecord({ id: item?.id, ...(item?.data || {}) }))
      .filter((route: RouteRecord) => route.polCode && route.podCode)
    routeDirectory.value = routes
  } catch (error) {
    console.error('Could not load route reference data', error)
  }
}
