const loadPickupReferenceData = async () => {
  if (pickupReferencesLoaded) return
  try {
    const [countriesResponse, portsResponse, legacyPostalResponse] = await Promise.all([
      props.request('/records?country=GLOBAL&page=ref_countries&limit=1000'),
      props.request('/records?country=GLOBAL&page=ref_ports&limit=1000'),
      props.request('/records?country=GLOBAL&page=ref_postalcode&limit=1000'),
    ])
    const itemsOf = (response: any) => Array.isArray(response?.items) ? response.items : Array.isArray(response?.data?.items) ? response.data.items : []
    const countries = itemsOf(countriesResponse)
      .filter((item: any) => upperText(item?.data?.status || 'ACTIVE') !== 'INACTIVE')
      .map((item: any) => upperText(item?.data?.iso2))
      .filter(Boolean)
    const countryPostalResponses = await Promise.all(countries.map((iso: string) =>
      props.request(`/records?country=${encodeURIComponent(iso)}&page=admin&limit=1000`).catch(() => ({ items: [] })),
    ))
    const postalItems = [...itemsOf(legacyPostalResponse), ...countryPostalResponses.flatMap(itemsOf)]
    const postalSeen = new Set<string>()
    pickupPostalOptions.value = postalItems.map((item: any) => {
      const data = item?.data || {}
      const value = String(data.zip || data.postalcode || data.postalCode || '').trim()
      const city = upperText(data.dist || data.district || data.city || data.prov || data.province || '')
      const ward = upperText(data.ward || data.placeName || '')
      const location = [ward, city, upperText(data.prov || data.province || '')].filter((part, index, list) => part && list.indexOf(part) === index).join(', ')
      return { value, city, ward, label: location ? `${value} — ${location}` : value }
    }).filter((item: PickupReferenceOption) => item.value && !postalSeen.has(item.value) && !!postalSeen.add(item.value))
      .sort((a: PickupReferenceOption, b: PickupReferenceOption) => a.value.localeCompare(b.value, undefined, { numeric: true }))
    const portSeen = new Set<string>()
    pickupPortOptions.value = itemsOf(portsResponse).map((item: any) => {
      const data = item?.data || {}
      const code = upperText(data.portcode || data.code || '')
      const name = upperText(data.portname || data.name || '')
      const label = name && code ? `${name} (${code})` : name || code
      return { value: label, label }
    }).filter((item: PickupReferenceOption) => item.value && !portSeen.has(item.value) && !!portSeen.add(item.value))
      .sort((a: PickupReferenceOption, b: PickupReferenceOption) => a.label.localeCompare(b.label))
    pickupReferencesLoaded = true
  } catch (error) {
    console.error('Could not load Pickup reference data', error)
  }
}
const openTruckDriverPicker = async (record: TruckContRecord, targetIndex: number) => {
  const companyName = upperText(record.truck || '')
  if (!companyName) return
  try {
    const res = await props.request('/entities/clients?limit=1000')
    const source = Array.isArray(res?.items)
      ? res.items
      : Array.isArray(res?.data?.items)
        ? res.data.items
        : Array.isArray(res?.data?.data?.items) ? res.data.data.items : []
    const company = source.map(normalizeClientRecord).find((item: GsdClientRecord) =>
      item.roles?.map(upperText).includes('TRUCK COMP')
      && [item.namecode, item.companyName, item.id].some((value) => upperText(value) === companyName),
