const datePopupDays = computed(() => {
  const first = new Date(datePopup.viewYear, datePopup.viewMonth, 1)
  const mondayOffset = (first.getDay() + 6) % 7
  const start = new Date(first)
  start.setDate(first.getDate() - mondayOffset)
  const current = parseOpsDate(datePopup.cutoffField ? gsdModal.form[datePopup.cutoffField] : nativePickerInput ? nativePickerInput.value : rows.value[datePopup.row]?.[datePopup.column])
  const today = new Date()
  return Array.from({ length: 42 }, (_, index) => {
    const date = new Date(start)
    date.setDate(start.getDate() + index)
    return {
      key: date.toISOString(),
      date,
      inMonth: date.getMonth() === datePopup.viewMonth,
      today: sameDate(date, today),
      selected: current ? sameDate(date, current) : false,
    }
  })
})

const sheetTabs = computed<SheetTab[]>(() => props.tabs?.length ? props.tabs : [{ key: props.sheetKey, label: props.title }])
const showSheetTabLabel = computed(() => props.title === 'ENTITIES' && sheetTabs.value.length > 1)
