const hasSelection = computed(() => !!selectedCell.value || !!selectedRect.value)
const selectedAlign = computed(() => {
  if (!selectedCell.value) return ''
  const format = cellFormatOf(selectedCell.value.row, selectedCell.value.column)
  return format.align || defaultCellAlign()
})
const selectedType = computed(() => {
  if (!selectedCell.value) return ''
  return cellFormatOf(selectedCell.value.row, selectedCell.value.column).type || 'text'
})

const selectedRect = computed(() => {
  if (!selectionAnchor.value || !selectionFocus.value || !selectionKind.value) return null
  let r1 = Math.min(selectionAnchor.value.row, selectionFocus.value.row)
  let r2 = Math.max(selectionAnchor.value.row, selectionFocus.value.row)
  let c1 = Math.min(selectionAnchor.value.column, selectionFocus.value.column)
  let c2 = Math.max(selectionAnchor.value.column, selectionFocus.value.column)

  if (selectionKind.value === 'all') {
    r1 = 0; r2 = Math.max(0, rows.value.length - 1);
    c1 = 0; c2 = Math.max(0, columnCount.value - 1);
  } else if (selectionKind.value === 'row') {
    c1 = 0; c2 = Math.max(0, columnCount.value - 1);
  } else if (selectionKind.value === 'col') {
    r1 = 0; r2 = Math.max(0, rows.value.length - 1);
  }
  return { r1, r2, c1, c2 }
})

const hasCellRange = computed(() => {
  const rect = selectedRect.value
  return Boolean(rect && (rect.r1 !== rect.r2 || rect.c1 !== rect.c2))
})
const hasMergeableCellRange = computed(() => {
  const rect = selectedRect.value
  return Boolean(rect && selectionKind.value === 'cell' && (rect.r1 !== rect.r2 || rect.c1 !== rect.c2))
})

const selectionInfo = computed(() => {
  const rect = selectedRect.value
  if (!rect) return ''
  const rowCount = rect.r2 - rect.r1 + 1
  const columnCount = rect.c2 - rect.c1 + 1
  return rowCount * columnCount > 1 ? `${rowCount}×${columnCount}` : ''
})
