const opsTabTone = computed(() => ['EXW', 'FCA', 'FCF'].includes(activeType.value) ? 'forwarding' : 'delivery')
const columnCount = computed(() => rows.value.reduce((max, row) => Math.max(max, row?.length || 0), 1))
