const isDefaultTemplateColumn = (column: number) => !!defaultTemplateColumnCount.value && column >= 0 && column < defaultTemplateColumnCount.value && !customColumnIndexes().has(column)
const opsHeaderMenu = reactive({ open: false, left: 0, top: 0, column: -1 })
