})
const sheetWidth = computed(() => visibleColumns.value.reduce((total, column) => total + columnWidth(column), 0))
const doneColumnIndex = computed(() => {
  const header = (rows.value[0] || []).map((cell: any) => String(cell ?? '').trim().toUpperCase())
  return header.findIndex((label) => ['DONE', 'HOÀN THÀNH', 'HOAN THANH', 'COMPLETED'].includes(label))
})
const rowMatchesStatus = (index: number) => {
  if (!isOpsPage.value || index === 0) return true
  const actionColumn = headerIndexOf(['ACTION'])
  if (actionColumn >= 0) {
    const action = actionCellValue(rows.value[index]?.[actionColumn])
    if (activeStatus.value === 'done') return action === 'DONE'
    if (activeStatus.value === 'cancel') return action === 'CANCEL'
    return action === (activeStatus.value === 'pending' ? 'PENDING' : 'ACTIVE')
  }
  const doneColumn = doneColumnIndex.value
  if (doneColumn < 0) return true
  const done = isChecked(rows.value[index]?.[doneColumn])
  if (activeStatus.value === 'done') return done
  if (activeStatus.value === 'pending') return !done && rows.value[index]?.some((cell) => String(cell ?? '').trim())
  if (activeStatus.value === 'cancel') return false
  return !done
}
const headerIndexOf = (labels: string[]) => {
  const header = (rows.value[0] || []).map((cell: any) => String(cell ?? '').trim().toUpperCase())
  return header.findIndex((label) => labels.includes(label))
}
const sortedIndexes = (indexes: number[]) => {
  if (!isOpsPage.value || sortBy.value === 'default') return indexes
  const header = indexes.filter((index) => index === 0)
  const body = indexes.filter((index) => index > 0)
  const sortColumn = sortBy.value === 'new'
    ? 0
    : headerIndexOf(sortBy.value === 'etd'
      ? ['ETD', 'ETD DỰ KIẾN', 'ETD DU KIEN']
      : ['ETA', 'ETA DỰ KIẾN', 'ETA DU KIEN'])
  if (sortColumn < 0) return indexes
  const parseValue = (value: any) => {
    const raw = String(value ?? '').trim()
    if (!raw) return sortBy.value === 'new' ? -Infinity : Infinity
    const numeric = Number(raw)
    if (Number.isFinite(numeric) && sortBy.value === 'new') return numeric
    const date = new Date(raw)
    return Number.isNaN(date.getTime()) ? raw.toLowerCase() : date.getTime()
  }
  body.sort((a, b) => {
    const av = parseValue(rows.value[a]?.[sortColumn])
    const bv = parseValue(rows.value[b]?.[sortColumn])
    if (typeof av === 'number' && typeof bv === 'number') {
      const compared = sortBy.value === 'new' ? bv - av : av - bv
      return compared || (sortBy.value === 'new' ? b - a : a - b)
    }
    const compared = String(av).localeCompare(String(bv))
    return (sortBy.value === 'new' ? -compared : compared) || (sortBy.value === 'new' ? b - a : a - b)
  })
  return [...header, ...body]
}
const filteredRowIndexes = computed(() => {
  const needle = query.value.toLowerCase()
  const indexes = rows.value.map((_, index) => index).filter(rowMatchesStatus)
  const filtered = needle
    ? indexes.filter((index) => {
        if (index === 0) return true
        if (isOpsPage.value && opsFilterField.value !== 'all') {
          const column = Number(opsFilterField.value)
          return String(rows.value[index]?.[column] ?? '').toLowerCase().includes(needle)
        }
        return rows.value[index].some((cell) => String(cell ?? '').toLowerCase().includes(needle))
      })
    : indexes
  const advanced = opsAppliedFilters.value.length
    ? filtered.filter((index) => index === 0 || rowMatchesOpsAdvancedFilters(index))
    : filtered
  return sortedIndexes(advanced)
})
const visibleRowsLimit = ref(250)
const visibleRowIndexes = computed(() => filteredRowIndexes.value.slice(0, visibleRowsLimit.value))
const selectableVisibleRows = computed(() => visibleRowIndexes.value.filter((index) => index > 0))
const opsBodyRows = computed(() => filteredRowIndexes.value.filter((index) => index > 0))
const opsAllVisibleSelected = computed(() => opsBodyRows.value.length > 0 && opsBodyRows.value.every((index) => opsSelectedRows.value.has(index)))
const recalibrateStatusCounts = () => {
  statusCounts.active = 0
  statusCounts.pending = 0
  statusCounts.done = 0
  statusCounts.cancel = 0
  if (!isOpsPage.value) return
  const actionColumn = headerIndexOf(['ACTION'])
  const doneColumn = doneColumnIndex.value
  for (let index = 1; index < rows.value.length; index++) {
    const hasData = rows.value[index]?.some((cell) => String(cell ?? '').trim())
    if (!hasData) continue
    if (actionColumn >= 0) {
      const action = actionCellValue(rows.value[index]?.[actionColumn])
      if (action === 'PENDING') statusCounts.pending++
      else if (action === 'DONE') statusCounts.done++
      else if (action === 'CANCEL') statusCounts.cancel++
      else statusCounts.active++
      continue
    }
    const done = doneColumn >= 0 && isChecked(rows.value[index]?.[doneColumn])
    if (done) statusCounts.done++
    else statusCounts.active++
  }
}

