const buildHeaderColumnMap = (existing: string[], target: string[]) => {
  const aliases: Record<string, string[]> = {
      NOTICE: ['NOTICE', 'REMINDER'],
      'EXW+': ['EXW+', 'EFA+'],
      'FCF+': ['FCF+', 'EFA+'],
      'ORIGIN AGENT': ['ORIGIN AGENT', 'ORIGINAL AGENT'],
      'CUT OFF DETAIL': ['CUT OFF DETAIL', 'CUT OFF DETAILS'],
      'BILL DETAIL': ['BILL DETAIL', 'BILL APPROVAL'],
  }
  const available = new Map<string, number[]>()
  existing.forEach((label, index) => {
    const key = String(label || '').trim().toUpperCase()
    available.set(key, [...(available.get(key) || []), index])
  })
  const used = new Set<number>()
  return target.map((label) => {
    const compatibleLabels = aliases[label] || [label]
    for (const compatibleLabel of compatibleLabels) {
      const indexes = available.get(compatibleLabel) || []
      const index = indexes.find((candidate) => !used.has(candidate))
      if (index !== undefined) {
        used.add(index)
        return index
      }
    }
    return null
  })
}

const retiredOpsHeaderExtras = new Set([
  'FREETIME TYPE',
  'MBL RELEASE',
  'HBL RELEASE',
  'DAYS AFTER ATA',
  'PICKUP DATE',
  'RETURN DATE',
  'DONE',
])
const alignRowsToHeader = (loadedRows: any[][], target: string[]) => {
  const existing = (loadedRows[0] || []).map((c) => String(c ?? '').trim())
  const colMap = buildHeaderColumnMap(existing, target)
  const finalMap = colMap
  const finalHeader = target.slice()
  const oldToNew = new Map<number, number>()
  finalMap.forEach((oldIndex, newIndex) => {
    if (oldIndex !== null && !oldToNew.has(oldIndex)) oldToNew.set(oldIndex, newIndex)
  })
  const nextRows = loadedRows.length ? loadedRows : [finalHeader.slice()]
  nextRows[0] = finalHeader.slice()
  for (let i = 1; i < nextRows.length; i++) {
    const row = nextRows[i] || []
    nextRows[i] = finalMap.map((oldIndex) => (oldIndex === null ? '' : row[oldIndex] ?? ''))
  }
  return { rows: nextRows, colMap: finalMap, oldToNew, defaultCount: target.length }
}

