  settings.value = {}
}

const sanitizeOpsStructuralSettings = () => {
  if (!opsParts.value) return
  const defaults = defaultTemplateColumnCount.value
  if (!defaults) return
  const hidden = (settings.value.hiddenColumns || []).map((value: any) => Number(value)).filter((value: number) => Number.isFinite(value) && value >= defaults)
  if (hidden.length !== (settings.value.hiddenColumns || []).length) {
    settings.value = { ...settings.value, hiddenColumns: hidden }
  }
}

const sheetGroupFor = (key = activeKey.value) => parseOpsKey(key) ? 'Operations' : String(props.title || 'Workbook')
const workbookMetaMarker = '__SHOPTRANS_WORKBOOK_META__'
const normalizeWorkbookCell = (value: any): any => {
  if (value === undefined) return ''
  if (Array.isArray(value)) return value.map(normalizeWorkbookCell)
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalizeWorkbookCell(item)]))
  return value
}
const normalizeWorkbookRow = (row: any[] = []) => Array.from({ length: row.length }, (_, index) => normalizeWorkbookCell(row[index]))
const snapshotSheetState = () => ({
  rows: rows.value.map(normalizeWorkbookRow),
  columnWidths: [...columnWidths.value],
  rowHeights: normalizeWorkbookCell(rowHeights.value),
  formatting: normalizeWorkbookCell(formatting.value),
  merges: normalizeWorkbookCell(merges.value),
  settings: normalizeWorkbookCell(settings.value),
})
const encodeWorkbookRows = (snapshot = snapshotSheetState()) => {
  const dataRows = snapshot.rows.filter((row) => String(row?.[0] ?? '') !== workbookMetaMarker)
  const meta = {
    version: 1,
    columnWidths: snapshot.columnWidths,
    rowHeights: snapshot.rowHeights,
    formatting: snapshot.formatting,
    merges: snapshot.merges,
    settings: snapshot.settings,
  }
  return [...dataRows.map(normalizeWorkbookRow), [workbookMetaMarker, JSON.stringify(meta)]]
}
const extractWorkbookRows = (loadedRows: any[][], sheet: any) => {
  const rowsOnly: any[][] = []
  let meta: any = null
  for (const row of loadedRows || []) {
    if (String(row?.[0] ?? '') === workbookMetaMarker) {
      try {
        meta = JSON.parse(String(row?.[1] || '{}'))
      } catch (error) {
        console.warn('Invalid workbook metadata row', error)
      }
      continue
    }
    rowsOnly.push(row)
  }
  return {
    rows: rowsOnly,
    columnWidths: Array.isArray(meta?.columnWidths) ? meta.columnWidths : Array.isArray(sheet.columnWidths) ? [...sheet.columnWidths] : [],
    rowHeights: meta?.rowHeights && typeof meta.rowHeights === 'object' ? meta.rowHeights : sheet.rowHeights || {},
    formatting: meta?.formatting && typeof meta.formatting === 'object' ? meta.formatting : sheet.formatting || {},
    merges: Array.isArray(meta?.merges) ? meta.merges : Array.isArray(sheet.merges) ? sheet.merges : [],
    settings: meta?.settings && typeof meta.settings === 'object' ? meta.settings : sheet.settings || {},
  }
}
const countryViewId = () => String(props.currentCountry?.id || 'VN').trim().toUpperCase() || 'VN'
const loadedCountryId = ref(countryViewId())
const sheetStorageKey = (key: string, country = loadedCountryId.value) => country === 'VN' ? key : `${key}::COUNTRY:${country}`
const responseUpdatedAt = (response: any) => String(response?.updatedAt || response?.data?.updatedAt || response?.data?.data?.updatedAt || '').trim()
const rememberSheetUpdatedAt = (storageKey: string, updatedAt: any) => {
  const value = String(updatedAt || '').trim()
  if (value) sheetUpdatedAtByStorageKey.set(storageKey, value)
}
const isVisibleSheet = (key: string, country: string) =>
  activeKey.value === key && loadedCountryId.value === country && countryViewId() === country
const versionedSheetPayload = <T extends Record<string, any>>(storageKey: string, payload: T) => {
  const expectedUpdatedAt = sheetUpdatedAtByStorageKey.get(storageKey)
  return expectedUpdatedAt ? { ...payload, expectedUpdatedAt } : payload
}
const patchLoadedWorkbookSheet = async (storageKey: string, loadedSheet: any, payload: Record<string, any>) => {
  const expectedUpdatedAt = responseUpdatedAt(loadedSheet)
  if (!expectedUpdatedAt) throw new Error(`Workbook version is missing for ${storageKey}`)
  const saved = await props.request(`/workbook/sheets/${encodeURIComponent(storageKey)}`, {
    method: 'PATCH',
    body: { ...payload, expectedUpdatedAt },
  })
  rememberSheetUpdatedAt(storageKey, responseUpdatedAt(saved))
  return saved
}
const sheetPayload = (key = activeKey.value, includeKey = false, country = loadedCountryId.value, snapshot = snapshotSheetState()) => ({
  ...(includeKey ? { key: sheetStorageKey(key, country), label: key } : {}),
  ...(includeKey ? { group: sheetGroupFor(key) } : {}),
  rows: encodeWorkbookRows(snapshot),
  columnWidths: snapshot.columnWidths,
  rowHeights: snapshot.rowHeights,
  formatting: snapshot.formatting,
  merges: snapshot.merges,
  settings: snapshot.settings,
})

const createSheet = (key = activeKey.value, country = loadedCountryId.value, payloadOverride?: ReturnType<typeof sheetPayload>) => props.request('/workbook/sheets', {
  method: 'POST',
  body: payloadOverride
    ? { ...payloadOverride, key: sheetStorageKey(key, country), label: key, group: sheetGroupFor(key) }
    : sheetPayload(key, true, country),
})
const customDeptStoreKey = (scope = deptScopeKey()) => `ST_OPS_CUSTOM_DEPTS::${scope}`
const readRememberedCustomDepts = (scope = deptScopeKey()) => {
  if (!scope || !process.client) return []
  try {
    const parsed = JSON.parse(localStorage.getItem(customDeptStoreKey(scope)) || '[]')
    return Array.isArray(parsed) ? parsed.map((item) => String(item || '').toUpperCase()).filter(Boolean) : []
  } catch {
    return []
  }
}
const rememberCustomDept = (p: any, dept: string) => {
  const scope = deptScopeKey(p)
  if (!scope || !process.client) return
  const defaults = opsDeptsFor(p.base, p.type)
  const next = Array.from(new Set([...readRememberedCustomDepts(scope), dept]))
    .filter((item) => !defaults.includes(item as any))
  localStorage.setItem(customDeptStoreKey(scope), JSON.stringify(next))
}
const forgetCustomDept = (p: any, dept: string) => {
  const scope = deptScopeKey(p)
  if (!scope || !process.client) return
  const next = readRememberedCustomDepts(scope).filter((item) => item !== dept)
  if (next.length) localStorage.setItem(customDeptStoreKey(scope), JSON.stringify(next))
  else localStorage.removeItem(customDeptStoreKey(scope))
}
let workbookSheetIndexCache: any[] = []
let workbookSheetIndexLoadedAt = 0
let workbookSheetIndexPromise: Promise<any[]> | null = null
const loadWorkbookSheetIndex = (force = false) => {
  const fresh = workbookSheetIndexCache.length && Date.now() - workbookSheetIndexLoadedAt < 60_000
  if (!force && fresh) return Promise.resolve(workbookSheetIndexCache)
  if (!force && workbookSheetIndexPromise) return workbookSheetIndexPromise
  workbookSheetIndexPromise = props.request('/workbook/sheets')
    .then((data: any) => {
      workbookSheetIndexCache = Array.isArray(data?.items) ? data.items : []
      workbookSheetIndexLoadedAt = Date.now()
      return workbookSheetIndexCache
    })
    .finally(() => { workbookSheetIndexPromise = null })
  return workbookSheetIndexPromise
}
const invalidateWorkbookSheetIndex = () => {
  workbookSheetIndexCache = []
  workbookSheetIndexLoadedAt = 0
}
const refreshCustomDeptTabs = async (p = opsParts.value) => {
  if (!p) {
    customDeptTabs.value = []
    hiddenDeptTabs.value = []
    return
  }
  const defaults = opsDeptsFor(p.base, p.type)
  const next = new Set(readRememberedCustomDepts(deptScopeKey(p)))
  const activeDepts = new Set<string>()
  try {
    const items = await loadWorkbookSheetIndex()
    for (const item of items) {
      const parsed = parseOpsKey(item.key)
      if (!parsed || parsed.base !== p.base || parsed.type !== p.type) continue
      activeDepts.add(parsed.dept)
      if (!defaults.includes(parsed.dept as any)) next.add(parsed.dept)
    }
  } catch (error) {
    console.error('Could not load custom departments', error)
    defaults.forEach((dept) => activeDepts.add(dept))
  }
  hiddenDeptTabs.value = defaults.filter((dept) => !activeDepts.has(dept))
  customDeptTabs.value = Array.from(next).filter((dept) => !defaults.includes(dept as any)).sort()
}
const createDeptSheets = async (p: any, dept: string) => {
  for (const mode of opsModes) {
    for (const status of opsStatuses) {
      const leaf = opsLeafKey(p.base, mode, p.type, dept as any)
      const key = opsStatusKey(leaf, status as any)
      const header = opsHeaderFor(p.base, mode, dept as any, p.type)
      try {
        await props.request('/workbook/sheets', {
          method: 'POST',
          body: {
            key,
            label: key,
            group: 'Operations',
            rows: [header],
            columnWidths: header.map(() => 132),
            rowHeights: {},
            formatting: {},
            merges: [],
            settings: {},
          },
        })
      } catch (error: any) {
        if (requestStatus(error) !== 409) throw error
      }
    }
  }
  invalidateWorkbookSheetIndex()
}
const deleteDeptSheets = async (p: any, dept: string) => {
  for (const mode of opsModes) {
    for (const status of opsStatuses) {
      const leaf = opsLeafKey(p.base, mode, p.type, dept as any)
      const key = opsStatusKey(leaf, status as any)
      try {
        await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(key))}`, { method: 'DELETE' })
      } catch (error: any) {
        if (requestStatus(error) !== 404) throw error
      }
    }
  }
  invalidateWorkbookSheetIndex()
}
watch(opsParts, (p) => {
  refreshCustomDeptTabs(p)
}, { immediate: true })

let sheetLoadRun = 0
const loadSheet = async () => {
  const run = ++sheetLoadRun
  const requestedKey = activeKey.value
  const requestedCountry = countryViewId()
  const requestedStorageKey = sheetStorageKey(requestedKey, requestedCountry)
  loading.value = true
  saveError.value = ''
  selectedCell.value = null
  selectionAnchor.value = null
  selectionFocus.value = null
  selectionKind.value = null
  visibleRowsLimit.value = 250
  editingCell.value = null

  // Staff options are only needed when an assignment editor is opened. Load them
  // beside the worksheet request so a small sheet is never held up by lookups.
  if (isOpsPage.value) void loadOpsStaff()
  
  try {
    // Wait for source-tab mirrors before hydrating the destination tab.
    if (pendingLinkedWrites.size) await Promise.allSettled([...pendingLinkedWrites])
    if (run !== sheetLoadRun || activeKey.value !== requestedKey || countryViewId() !== requestedCountry) return
    let sheet: any
    try {
      sheet = await props.request(`/workbook/sheets/${encodeURIComponent(requestedStorageKey)}`)
    } catch (firstError: any) {
      const status = requestStatus(firstError)
      if (status === 404 || (status >= 400 && status < 500)) throw firstError
      await new Promise<void>((resolve) => window.setTimeout(resolve, 250))
      if (run !== sheetLoadRun || activeKey.value !== requestedKey || countryViewId() !== requestedCountry) return
      sheet = await props.request(`/workbook/sheets/${encodeURIComponent(requestedStorageKey)}`)
    }
    if (run !== sheetLoadRun || activeKey.value !== requestedKey || countryViewId() !== requestedCountry) return
    loadedCountryId.value = requestedCountry
    rememberSheetUpdatedAt(requestedStorageKey, responseUpdatedAt(sheet))
    const extracted = extractWorkbookRows(Array.isArray(sheet.rows) ? sheet.rows.map((row: any[]) => [...row]) : [], sheet)
    let rowsLoaded: any[][] = extracted.rows
    let widthsLoaded: number[] = extracted.columnWidths
    let formattingLoaded: Record<string, any> = extracted.formatting
    let mergesLoaded: number[][] = extracted.merges
    let rowHeightsLoaded: Record<string, number> = extracted.rowHeights
    let settingsLoaded: Record<string, any> = extracted.settings

    // For ops leaves, align row 0 with the per-(base,mode,dept) header from
    // the mockup so column counts match when the user switches Dept tabs.
    const parsed = parseOpsKey(requestedKey)
    if (parsed) {
      const target = opsHeaderFor(parsed.base, parsed.mode, parsed.dept, parsed.type)
      if (!rowsLoaded.length) rowsLoaded = [target.slice()]
      // EXW/FCL/GSD renamed this column from REMINDER to NOTICE. Rename the
      // persisted header before alignment so the existing notes stay intact.
      if (isExwFclGsdSheet() && rowsLoaded[0]) {
        const legacyGsdOpsIndex = rowsLoaded[0].findIndex((cell) => String(cell ?? '').trim().toUpperCase() === 'GSD OPS')
        if (legacyGsdOpsIndex >= 0) rowsLoaded[0][legacyGsdOpsIndex] = 'GSD'
        const legacyReminderIndex = rowsLoaded[0].findIndex((cell) => String(cell ?? '').trim().toUpperCase() === 'REMINDER')
        if (legacyReminderIndex >= 0) {
          rowsLoaded[0][legacyReminderIndex] = 'NOTICE'
        }
        if (parsed.mode === 'FCL' && parsed.type === 'FCF') {
          const legacySentIndex = rowsLoaded[0].findIndex((cell) => String(cell ?? '').trim().toUpperCase() === 'SENT ICD')
          if (legacySentIndex >= 0) {
            rowsLoaded[0][legacySentIndex] = 'SENT ECD'
          }
        }
      }
      // Preserve values created under the former column name while migrating
      // ICD/TCD worksheets to the DO INFO document popup.
      if (['ICD', 'TCD'].includes(String(parsed.dept || '').toUpperCase()) && rowsLoaded[0]) {
        const legacyDoValidityIndex = rowsLoaded[0].findIndex((cell) => upperText(cell) === 'DO VALIDITY')
        if (legacyDoValidityIndex >= 0 && target.includes('DO INFO')) rowsLoaded[0][legacyDoValidityIndex] = 'DO INFO'
      }
      const existing = (rowsLoaded[0] || []).map((c) => String(c ?? '').trim())
      const same = existing.length === target.length && existing.every((c, i) => c === target[i])
      const needsStructuralAlign = !same || rowsLoaded.some((row) => (row?.length || 0) !== target.length)
      if (needsStructuralAlign) {
        const aligned = alignRowsToHeader(rowsLoaded, target)
        rowsLoaded = aligned.rows
        const width = rowsLoaded[0]?.length || target.length
        widthsLoaded = aligned.colMap.map((oldIndex) => (oldIndex === null ? 132 : widthsLoaded[oldIndex] || 132))
        const remappedFormatting: Record<string, any> = {}
        Object.entries(formattingLoaded).forEach(([key, value]) => {
          const [r, c] = key.split(':').map(Number)
          const nextCol = aligned.oldToNew.get(c)
          if (Number.isFinite(r) && nextCol !== undefined && nextCol < width) {
            remappedFormatting[`${r}:${nextCol}`] = value
          }
        })
        formattingLoaded = remappedFormatting
        mergesLoaded = mergesLoaded
          .map((m) => [m[0], aligned.oldToNew.get(m[1]), m[2], aligned.oldToNew.get(m[3])])
          .filter((m): m is number[] => m[1] !== undefined && m[3] !== undefined && m[1] < width && m[3] < width)
      }

      // Populate the GSD overview from ECD records that already existed before
      // the reverse-link feature was introduced. Prefer the stable shipment
      // link and fall back to JOB NO# for legacy rows without link metadata.
      if (
        parsed.dept === 'GSD' &&
        ['EXW', 'FCA', 'FCF'].includes(upperText(parsed.type)) &&
        target.includes('ECD OPS')
      ) {
        try {
          const ecdKey = opsLeafKey(parsed.base, parsed.mode, parsed.type, 'ECD')
          const ecdStorageKey = sheetStorageKey(ecdKey, requestedCountry)
          const ecdSheet = await props.request(`/workbook/sheets/${encodeURIComponent(ecdStorageKey)}`)
          const ecdTargetHeader = opsHeaderFor(parsed.base, parsed.mode, 'ECD', parsed.type)
          const ecdExtracted = extractWorkbookRows(Array.isArray(ecdSheet?.rows) ? ecdSheet.rows.map((row: any[]) => [...row]) : [], ecdSheet)
          const ecdRows = alignRowsToHeader(ecdExtracted.rows, ecdTargetHeader).rows
          const sourceLinks = settingsLoaded?.opsRowLinks || {}
          const ecdLinks = ecdExtracted.settings?.opsRowLinks || ecdSheet?.settings?.opsRowLinks || {}
          const sourceJobColumn = target.findIndex((label) => upperText(label) === 'JOB NO#')
          const sourceEcdOpsColumn = target.findIndex((label) => upperText(label) === 'ECD OPS')
          const ecdJobColumn = ecdTargetHeader.findIndex((label) => upperText(label) === 'JOB NO#')
          const ecdOpsColumn = ecdTargetHeader.findIndex((label) => upperText(label) === 'ECD OPS')
          rowsLoaded.forEach((sourceRow, sourceRowIndex) => {
            if (sourceRowIndex === 0 || String(sourceRow?.[sourceEcdOpsColumn] || '').trim()) return
            const shipmentLink = String(sourceLinks[String(sourceRowIndex)] || '').trim()
            const jobNo = sourceJobColumn >= 0 ? upperText(sourceRow?.[sourceJobColumn]) : ''
            const ecdRowIndex = ecdRows.findIndex((ecdRow, index) => index > 0 && (
              (shipmentLink && String(ecdLinks[String(index)] || '').trim() === shipmentLink) ||
              (jobNo && ecdJobColumn >= 0 && upperText(ecdRow?.[ecdJobColumn]) === jobNo)
            ))
            const ecdOwner = ecdRowIndex > 0 && ecdOpsColumn >= 0 ? String(ecdRows[ecdRowIndex]?.[ecdOpsColumn] || '').trim() : ''
            if (ecdOwner) sourceRow[sourceEcdOpsColumn] = ecdOwner
          })
        } catch (error: any) {
          if (requestStatus(error) !== 404) console.warn('Could not hydrate ECD OPS on GSD', error)
        }
      }
    }

    backfillGeneratedJobNumbers(rowsLoaded)

    if (parsed && ['TCD', 'CCD', 'DCD'].includes(String(parsed.dept || '').toUpperCase())) {
      const modeColumn = (rowsLoaded[0] || []).findIndex((cell) => String(cell ?? '').trim().toUpperCase() === 'MODE')
      const manualRows = new Set<number>((settingsLoaded.manualOpsRows || []).map(Number))
      if (modeColumn >= 0) rowsLoaded.forEach((row, index) => {
        if (index <= 0) return
        const currentMode = upperText(row?.[modeColumn])
        if (!currentMode) row[modeColumn] = manualRows.has(index) ? 'MANU' : 'AUTO'
        else if (currentMode === 'MANUAL') row[modeColumn] = 'MANU'
      })
    }

    rows.value = rowsLoaded
    columnWidths.value = widthsLoaded
    rowHeights.value = rowHeightsLoaded
    formatting.value = formattingLoaded
    merges.value = mergesLoaded
    settings.value = settingsLoaded
    sanitizeOpsStructuralSettings()
    recalibrateStatusCounts()
    const loadedUpdatedAt = responseUpdatedAt(sheet)
    saveState.value = loadedUpdatedAt ? `Saved ${new Date(loadedUpdatedAt).toLocaleTimeString('en-GB')}` : 'Database ready'
    // Loading or remapping a worksheet is read-only. Persisting a structural
    // normalization here used to let a page refresh overwrite linked business
    // data before the user had changed anything.
  } catch (error: any) {
    if (run !== sheetLoadRun || activeKey.value !== requestedKey || countryViewId() !== requestedCountry) return
    const parsed = parseOpsKey(requestedKey)
    if (parsed && requestStatus(error) === 404) {
      const target = opsHeaderFor(parsed.base, parsed.mode, parsed.dept, parsed.type)
      setLocalOpsSheet(target)
      saveState.value = 'New worksheet'
      saveError.value = ''
      try {
        loadedCountryId.value = requestedCountry
        const created = await createSheet(requestedKey, requestedCountry)
        rememberSheetUpdatedAt(requestedStorageKey, responseUpdatedAt(created))
      } catch (createError: any) {
        if (activeKey.value !== requestedKey || countryViewId() !== requestedCountry) return true
        if (requestStatus(createError) === 409) {
          await loadSheet()
          return true
        }
        saveState.value = 'Local worksheet'
        saveError.value = createError?.data?.message || createError?.message || 'Could not create worksheet.'
        console.error('Could not create worksheet', createError)
      }
    } else {
      saveError.value = error?.data?.message || error?.message || 'Could not load worksheet.'
      console.error('Could not load worksheet', error)
    }
  } finally {
    if (run === sheetLoadRun && activeKey.value === requestedKey && countryViewId() === requestedCountry) loading.value = false
  }
}
const loadVesselReferenceData = async () => {
  try {
    const res = await props.request('/records?country=GLOBAL&page=ref_vessels&limit=1000')
    vesselDirectory.value = (Array.isArray(res?.items) ? res.items : [])
      .map((item: any) => normalizeVesselRecord({ id: item?.id, ...(item?.data || {}) }))
      .filter((vessel: VesselRecord) => vessel.name && vessel.imo)
      .sort((a: VesselRecord, b: VesselRecord) => a.name.localeCompare(b.name))
  } catch (error) {
    console.error('Could not load vessel reference data', error)
  }
}
const loadRouteCountryOptions = async () => {
  try {
    const res = await props.request('/records?country=GLOBAL&page=ref_countries&limit=1000')
    routeCountryOptions.value = Array.from(new Set(
      (Array.isArray(res?.items) ? res.items : [])
        .filter((item: any) => upperText(item?.data?.status || 'ACTIVE') !== 'INACTIVE')
        .map((item: any) => upperText(item?.data?.countryname || '').trim())
        .filter(Boolean),
    )).sort((left, right) => left.localeCompare(right))
  } catch (error) {
    routeCountryOptions.value = []
    console.error('Could not load Route countries from Reference Data', error)
  }
}

const saveSheet = async (
  requestedKey = activeKey.value,
  payloadOverride?: ReturnType<typeof sheetPayload>,
  requestedCountry = loadedCountryId.value,
  forceLatest = false,
): Promise<boolean> => {
  const requestedStorageKey = sheetStorageKey(requestedKey, requestedCountry)
  // Do not serialize the visible rows under a key belonging to an earlier tab.
  // Delayed autosaves previously overwrote linked ECD data after tab switches.
  if (!payloadOverride && !isVisibleSheet(requestedKey, requestedCountry)) return false
  const payloadSnapshot = payloadOverride || sheetPayload(requestedKey, false, requestedCountry)
  if (loading.value && !payloadOverride) {
    armSaveTimer(requestedKey, requestedCountry, 350)
    return false
  }
  cancelOwnedSaveTimer(requestedKey, requestedCountry)
  if (isVisibleSheet(requestedKey, requestedCountry)) {
    saveState.value = 'Saving...'
    saveError.value = ''
  }
  try {
    const ownLinkedWrite = payloadOverride ? null : linkedWriteChains.get(requestedStorageKey)
    if (ownLinkedWrite) await ownLinkedWrite.catch(() => undefined)
    if (!payloadOverride && !isVisibleSheet(requestedKey, requestedCountry)) return false
    // A linked write can advance the worksheet version while we are waiting.
    // Build the versioned body only after that write has settled; otherwise a
    // manual CCD/TCD row save receives 409 and the old conflict handler reloads
    // the sheet, dropping the unsaved row from the screen.
    // Explicit MANUAL-row saves are serialized by the backend transaction and
    // intentionally omit optimistic versioning. CCD/TCD receive background
    // linked writes frequently enough that a GET-version/PATCH retry can race
    // repeatedly and make a user-created row impossible to save.
    const requestPayload = forceLatest ? payloadSnapshot : versionedSheetPayload(requestedStorageKey, payloadSnapshot)
    const saved = await props.request(`/workbook/sheets/${encodeURIComponent(requestedStorageKey)}`, {
      method: 'PATCH',
      body: requestPayload,
    })
    const savedUpdatedAt = responseUpdatedAt(saved)
    rememberSheetUpdatedAt(requestedStorageKey, savedUpdatedAt)
    if (!isVisibleSheet(requestedKey, requestedCountry)) return true
    saveState.value = `Saved ${new Date(savedUpdatedAt || Date.now()).toLocaleTimeString('en-GB')}`
    return true
  } catch (error: any) {
    if (requestStatus(error) === 409 && !forceLatest) {
      // Preserve the user's local row and retry once against the newest server
      // version. Never resolve a save conflict by reloading and discarding the
      // CCD/TCD MANUAL row that the user has just entered.
      try {
        const latest = await props.request(`/workbook/sheets/${encodeURIComponent(requestedStorageKey)}`)
        const latestUpdatedAt = responseUpdatedAt(latest)
        if (!latestUpdatedAt) throw error
        rememberSheetUpdatedAt(requestedStorageKey, latestUpdatedAt)
        const retried = await props.request(`/workbook/sheets/${encodeURIComponent(requestedStorageKey)}`, {
          method: 'PATCH',
          body: { ...payloadSnapshot, expectedUpdatedAt: latestUpdatedAt },
        })
        const retriedUpdatedAt = responseUpdatedAt(retried)
        rememberSheetUpdatedAt(requestedStorageKey, retriedUpdatedAt)
        if (isVisibleSheet(requestedKey, requestedCountry)) {
          saveState.value = `Saved ${new Date(retriedUpdatedAt || Date.now()).toLocaleTimeString('en-GB')}`
          saveError.value = ''
        }
        return true
      } catch (retryError: any) {
        if (isVisibleSheet(requestedKey, requestedCountry)) {
          saveState.value = 'Not saved'
          saveError.value = retryError?.data?.message || retryError?.message || 'Worksheet changed. Please save again.'
        }
        console.error('Could not save worksheet after conflict', retryError)
      }
      return false
    }
    if (requestStatus(error) === 404 && parseOpsKey(requestedKey)) {
      try {
        const created = await createSheet(requestedKey, requestedCountry, payloadSnapshot)
        const createdUpdatedAt = responseUpdatedAt(created)
        rememberSheetUpdatedAt(requestedStorageKey, createdUpdatedAt)
        if (!isVisibleSheet(requestedKey, requestedCountry)) return true
        saveState.value = `Saved ${new Date(createdUpdatedAt || Date.now()).toLocaleTimeString('en-GB')}`
        return true
      } catch (createError: any) {
        if (!isVisibleSheet(requestedKey, requestedCountry)) return false
        if (requestStatus(createError) === 409) {
          await loadSheet()
          return false
        }
        saveError.value = createError?.data?.message || createError?.message || 'Could not create worksheet.'
        console.error('Could not create worksheet', createError)
        return false
      }
    }
    if (!isVisibleSheet(requestedKey, requestedCountry)) return false
    saveError.value = error?.data?.message || error?.message || 'Could not save worksheet.'
    console.error('Could not save worksheet', error)
    return false
  }
}

const scheduleSave = () => {
  saveState.value = 'Saving...'
  const requestedKey = activeKey.value
  const requestedCountry = loadedCountryId.value
  armSaveTimer(requestedKey, requestedCountry, 700)
}

const normalizeRows = () => {
  const count = columnCount.value
  rows.value.forEach((row) => {
    while (row.length < count) row.push('')
  })
}

const formatLocalDateTime = (date = new Date()) => {
  const pad = (value: number) => String(value).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`
}

const isExwFclGsdSheet = () => {
  const parts = opsParts.value
  const type = String(parts?.type || '').toUpperCase()
  const mode = String(parts?.mode || '').toUpperCase()
  return parts?.dept === 'GSD' && (
    ['EXW', 'FCA', 'FCF', 'DO', 'DAP', 'DDU', 'DDP'].includes(type) && ['FCL', 'LCL', 'AIR'].includes(mode)
  )
}
const staffDepartments = (data: Record<string, any>) =>
  [data.department, data.departments]
    .flatMap((value: any) => Array.isArray(value) ? value : String(value || '').split(','))
    .map((value: any) => String(value || '').trim().toUpperCase())
    .filter(Boolean)
const staffMatchesCurrentCountry = (data: Record<string, any>) => {
  const country = String(data.country || '').trim().toUpperCase()
  if (!country) return true
  const id = String(props.currentCountry?.id || '').trim().toUpperCase()
  const name = String(props.currentCountry?.name || '').trim().toUpperCase()
  return country === id || country === name
}
const staffDisplayName = (data: Record<string, any>) =>
  String(data.fullname || data.fullName || data.name || data.nickname || data.namecode || data.staffid || data.code || '').trim()
const addOpsStaffToDepartment = (target: Map<string, Set<string>>, data: Record<string, any>) => {
  if (String(data.status || '').trim().toUpperCase() === 'INACTIVE' || !staffMatchesCurrentCountry(data)) return
  const name = staffDisplayName(data)
  if (!name) return
  staffDepartments(data).forEach((department) => {
    if (!target.has(department)) target.set(department, new Set())
    target.get(department)?.add(name)
  })
}
const addOpsStaffFromRows = (target: Map<string, Set<string>>, sourceRows: any[][]) => {
  const header = (sourceRows[0] || []).map((label: any) => String(label || '').trim().toUpperCase())
  sourceRows.slice(1).forEach((row) => {
    const data = header.reduce<Record<string, any>>((result, label, index) => ({ ...result, [label.toLowerCase().replace(/[^a-z0-9]+/g, '')]: row?.[index] }), {})
    const normalized = {
      ...data,
      fullname: data.fullname,
      fullName: data.fullname,
      position: data.position,
      country: data.country,
      status: data.status,
      code: data.code,
    }
    addOpsStaffToDepartment(target, normalized)
  })
}
const loadOpsStaff = async () => {
  const country = String(props.currentCountry?.id || 'VN').trim().toUpperCase() || 'VN'
  if (opsStaffCountry.value === country) return
  if (opsStaffLoading) return opsStaffLoading
  opsStaffLoading = (async () => {
    const namesByDepartment = new Map<string, Set<string>>()
    const [staffRecordsResult, staffSheetResult] = await Promise.allSettled([
      props.request('/records?country=GLOBAL&page=internal_staff&limit=1000'),
      props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey('STAFF', country))}`),
    ])
    if (staffRecordsResult.status === 'fulfilled') {
      ;(staffRecordsResult.value?.items || []).forEach((record: any) => {
        const data = record?.data || {}
        addOpsStaffToDepartment(namesByDepartment, data)
      })
    } else {
      console.warn('Could not load OPS staff directory', staffRecordsResult.reason)
    }
    if (staffSheetResult.status === 'fulfilled') {
      const sheet = staffSheetResult.value
      addOpsStaffFromRows(namesByDepartment, Array.isArray(sheet?.rows) ? sheet.rows : [])
    } else if (requestStatus(staffSheetResult.reason) !== 404) {
      console.warn('Could not load STAFF workbook', staffSheetResult.reason)
    }
    opsStaffByDepartment.value = Object.fromEntries([...namesByDepartment.entries()].map(([department, names]) => [department, [...names].sort((left, right) => left.localeCompare(right))]))
    opsStaffNames.value = Array.from(new Set(Object.values(opsStaffByDepartment.value).flat())).sort((left, right) => left.localeCompare(right))
    opsStaffCountry.value = country
  })()
  try {
    await opsStaffLoading
  } finally {
    opsStaffLoading = null
  }
}
const leastLoadedOpsStaff = () => {
  const candidates = opsStaffNames.value
  if (!candidates.length) return ''
  const header = rows.value[0] || []
  const opsColumn = header.findIndex((label: any) => String(label || '').trim().toUpperCase() === 'OPS')
  const actionColumn = header.findIndex((label: any) => String(label || '').trim().toUpperCase() === 'ACTION')
  const loads = new Map(candidates.map((name) => [name, 0]))
  rows.value.slice(1).forEach((sourceRow) => {
    const assignee = String(sourceRow?.[opsColumn] || '').trim()
    const action = String(actionColumn >= 0 ? sourceRow?.[actionColumn] || 'ACTIVE' : 'ACTIVE').trim().toUpperCase()
    if (loads.has(assignee) && !['DONE', 'CANCEL'].includes(action)) loads.set(assignee, (loads.get(assignee) || 0) + 1)
  })
  return candidates.slice().sort((left, right) => (loads.get(left)! - loads.get(right)!) || left.localeCompare(right))[0] || ''
}
const jobDateCode = (value: any, fallback = new Date()) => {
  const match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (match) return `${match[3]}${match[2]}${match[1]}`
  const pad = (part: number) => String(part).padStart(2, '0')
  return `${pad(fallback.getDate())}${pad(fallback.getMonth() + 1)}${fallback.getFullYear()}`
}
const generatedJobCountryCode = () => String(props.currentCountry?.id || 'VN').trim().toUpperCase() || 'VN'
const nextGeneratedJobNo = (timeValue: any, sourceRows = rows.value) => {
  const dateCode = jobDateCode(timeValue)
  const prefix = `${generatedJobCountryCode()}${dateCode}`
  const jobColumn = (sourceRows[0] || []).findIndex((label: any) => String(label || '').trim().toUpperCase() === 'JOB NO#')
  const highest = jobColumn < 0 ? 0 : sourceRows.slice(1).reduce((max, sourceRow) => {
    const match = String(sourceRow?.[jobColumn] || '').trim().toUpperCase().match(new RegExp(`^${prefix}(\\d+)$`))
    return match ? Math.max(max, Number(match[1]) || 0) : max
  }, 0)
  return `${prefix}${String(highest + 1).padStart(2, '0')}`
}
const backfillGeneratedJobNumbers = (sourceRows: any[][]) => {
  if (!isExwFclGsdSheet() || sourceRows.length < 2) return false
  const header = sourceRows[0] || []
  const timeColumn = header.findIndex((label: any) => String(label || '').trim().toUpperCase() === 'TIME')
  const jobColumn = header.findIndex((label: any) => String(label || '').trim().toUpperCase() === 'JOB NO#')
  if (jobColumn < 0) return false
  let changed = false
  sourceRows.slice(1).forEach((sourceRow) => {
    if (String(sourceRow?.[jobColumn] || '').trim()) return
    sourceRow[jobColumn] = nextGeneratedJobNo(timeColumn >= 0 ? sourceRow?.[timeColumn] : '', sourceRows)
    changed = true
  })
  return changed
}

const makeBlankWorkbookRow = () => {
  const row = Array.from({ length: columnCount.value }, () => '')
  const header = rows.value[0] || []
  header.forEach((label, index) => {
    const normalized = String(label ?? '').trim().toUpperCase()
    if (index === 0 && normalized === 'TIME') row[index] = formatLocalDateTime()
    else if (isOpsPage.value && normalized === 'BU') row[index] = generatedJobCountryCode()
    else if (isOpsPage.value && normalized === 'SALES') row[index] = String(props.currentUser?.displayName || props.currentUser?.username || '').trim()
    else if (isOpsPage.value && normalized === 'JOB NO#') row[index] = nextGeneratedJobNo(row[0])
    else if (isExwFclGsdSheet() && normalized === 'GSD') {
      row[index] = leastLoadedDepartmentStaff(opsDeptUpper(), header.map((item) => String(item ?? '')), rows.value)
    }
    else if (normalized === 'ACTION') row[index] = 'ACTIVE'
    else if (normalized === 'DONE' || normalized === 'HOAN THANH') row[index] = ''
  })
  if (isOpsPage.value) {
    const jobColumn = header.findIndex((label) => String(label ?? '').trim().toUpperCase() === 'JOB NO#')
    const refColumn = header.findIndex((label) => String(label ?? '').trim().toUpperCase() === 'REF#')
    if (jobColumn >= 0 && refColumn >= 0 && String(row[jobColumn] || '').trim()) row[refColumn] = row[jobColumn]
  }
  return row
}

const isOpsEditingRow = (row: number) => opsEditingRow.value?.row === row
const isOpsMoneyColumn = (column: number) => /^(?:TOTAL(?:\s+(?:PAY(?:MENT)?|COLLECT(?:ION)?|PRICE|COST))?|(?:DEDUCTED\s+)?AMOUNT|(?:UNIT\s+|SELLING\s+|BUYING\s+)?(?:PRICE|COST))$/.test(normalizedHeaderLabel(column))
const normalizeOpsMoneyRow = (row: number) => {
  ;(rows.value[0] || []).forEach((_, column) => {
    if (isOpsMoneyColumn(column) && String(rows.value[row]?.[column] ?? '').trim()) {
      rows.value[row][column] = formatMoneyValue(rows.value[row][column])
    }
  })
}
const leastLoadedDepartmentStaff = (department: string, header: string[], dataRows: any[][]) => {
  const dept = String(department || '').trim().toUpperCase()
  const candidates = opsStaffByDepartment.value[dept] || []
  if (!candidates.length) return ''
  const opsColumn = header.findIndex((label) => {
    const normalized = String(label || '').trim().toUpperCase()
    return normalized === `${dept} OPS` || (dept === 'GSD' && normalized === 'GSD')
  })
  if (opsColumn < 0) return ''
  const actionColumn = header.findIndex((label) => String(label || '').trim().toUpperCase() === 'ACTION')
  const loads = new Map(candidates.map((name) => [name, 0]))
  dataRows.slice(1).forEach((row) => {
    const assignee = String(row?.[opsColumn] || '').trim()
    const action = String(actionColumn >= 0 ? row?.[actionColumn] || 'ACTIVE' : 'ACTIVE').trim().toUpperCase()
    if (loads.has(assignee) && !['DONE', 'CANCEL'].includes(action)) loads.set(assignee, (loads.get(assignee) || 0) + 1)
  })
  return [...candidates].sort((left, right) => (loads.get(left) || 0) - (loads.get(right) || 0) || left.localeCompare(right))[0] || ''
}
const saveOpsEdit = async () => {
  if (!opsEditingRow.value) return
  dispatchLoading.value = 'Saving manual row...'
  try {
  const edit = opsEditingRow.value
  normalizeOpsMoneyRow(edit.row)
  const actionColumn = headerIndexOf(['ACTION'])
  if (actionColumn >= 0 && !String(rows.value[edit.row]?.[actionColumn] || '').trim()) rows.value[edit.row][actionColumn] = 'ACTIVE'
  const mblColumn = (rows.value[0] || []).findIndex((_, column) => normalizedHeaderLabel(column) === 'MBL NO#')
  if (
    mblColumn >= 0 &&
    isExwFclFreeTextMblColumn(mblColumn) &&
    ['ECD', 'DCD'].includes(opsDeptUpper()) &&
    String(rows.value[edit.row]?.[mblColumn] ?? '') !== String(edit.snapshot[mblColumn] ?? '')
  ) {
    void mirrorExwFclDocumentNumber('MBL NO#', rows.value[edit.row]?.[mblColumn] ?? '', edit.row)
  }
  // Manual-row Save is an explicit user action. Let all older linked writes
  // finish first; otherwise one of them can complete after this PATCH and
  // restore the older row list while leaving manualOpsRows in settings.
  const manualSheetKey = activeKey.value
  const manualCountry = loadedCountryId.value
  cancelOwnedSaveTimer(manualSheetKey, manualCountry)
  if (pendingLinkedWrites.size) await Promise.allSettled([...pendingLinkedWrites])
  const ownLinkedWrite = linkedWriteChains.get(sheetStorageKey(manualSheetKey, manualCountry))
  if (ownLinkedWrite) await ownLinkedWrite.catch(() => undefined)
  const manualPayload = sheetPayload(manualSheetKey, false, manualCountry)
  const storageKey = sheetStorageKey(manualSheetKey, manualCountry)
  const saveNewManualRow = async () => {
    const result = await props.request(`/workbook/sheets/${encodeURIComponent(storageKey)}/manual-rows`, {
      method: 'POST',
      body: {
        row: normalizeWorkbookRow(rows.value[edit.row] || []),
        creator: String(props.currentUser?.displayName || props.currentUser?.username || '').trim(),
      },
    })
    rememberSheetUpdatedAt(storageKey, responseUpdatedAt(result))
    return true
  }
  let saved = false
  try {
    saved = edit.isNew
      ? await saveNewManualRow()
      : await saveSheet(manualSheetKey, manualPayload, manualCountry, true)
  } catch (error: any) {
    saveError.value = error?.data?.message || error?.message || 'Could not save the manual row.'
  }
  if (saved) {
    // Do not announce success until GET confirms that the exact manual row is
    // present in persistent storage. Retry once if an overlapping write won
    // the race immediately after PATCH.
    const expectedTime = String(rows.value[edit.row]?.[0] || '').trim()
    const verifyStoredRow = async () => {
      const latest = await props.request(`/workbook/sheets/${encodeURIComponent(storageKey)}`)
      rememberSheetUpdatedAt(storageKey, responseUpdatedAt(latest))
      const extracted = extractWorkbookRows(Array.isArray(latest.rows) ? latest.rows.map((row: any[]) => [...row]) : [], latest)
      return extracted.rows.some((row, index) => index > 0 && String(row?.[0] || '').trim() === expectedTime)
    }
    try {
      if (!(await verifyStoredRow())) {
        saved = edit.isNew
          ? await saveNewManualRow()
          : await saveSheet(manualSheetKey, manualPayload, manualCountry, true)
        if (saved) saved = await verifyStoredRow()
      }
    } catch (error: any) {
      saved = false
      saveError.value = error?.data?.message || error?.message || 'Could not verify the saved manual row.'
    }
  }
  if (saved) {
    opsEditingRow.value = null
    opsSelectedRows.value = new Set()
  } else {
    showToast(saveError.value || 'Could not save the manual row. Please try Save again.')
  }
  } finally {
    dispatchLoading.value = ''
  }
}
const cancelOpsEdit = () => {
  const edit = opsEditingRow.value
  if (!edit) return
  if (edit.isNew) {
    rows.value.splice(edit.row, 1)
    remapOpsRowSettings((row) => row === edit.row ? null : row > edit.row ? row - 1 : row)
    setManualOpsRows([...manualOpsRows()].filter((row) => row !== edit.row).map((row) => row > edit.row ? row - 1 : row))
  }
  else rows.value[edit.row] = edit.snapshot.slice()
  opsSelectedRows.value = new Set()
  opsEditingRow.value = null
  showToast(edit.isNew ? 'Cancelled' : 'Changes discarded')
}
const isBlankOpsDataRow = (row: any[] = []) => {
  return visibleColumns.value.every((column) => {
    const label = normalizedHeaderLabel(column)
    const value = String(row[column] ?? '').trim()
    if (!value) return true
    if (label === 'ACTION' && value.toUpperCase() === 'ACTIVE') return true
    return false
  })
}

const confirmRowDepts = new Set(['TCD', 'CCD', 'DCD'])
const requiresRowConfirmation = () => confirmRowDepts.has(String(opsParts.value?.dept || '').toUpperCase())
const canAddOpsRow = () => ['GSD', 'CCD', 'TCD', 'DCD'].includes(String(opsParts.value?.dept || '').toUpperCase())
const canManageManualOpsRows = () => canAddOpsRow()
const manualOpsRows = () => new Set<number>((settings.value.manualOpsRows || []).map(Number).filter((row: number) => Number.isInteger(row) && row > 0))
const setManualOpsRows = (indexes: Iterable<number>) => {
  settings.value = { ...settings.value, manualOpsRows: [...new Set(indexes)].sort((a, b) => a - b) }
}
const newOpsShipmentLink = () => `OPS:${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
const remapOpsRowSettings = (mapRow: (row: number) => number | null, clonedRows: Array<{ source: number; target: number; newLink?: boolean }> = []) => {
  const remapIndexedObject = (value: any, regenerateLink = false) => {
    if (!value || typeof value !== 'object') return value
    const next: Record<string, any> = {}
    Object.entries(value).forEach(([key, item]) => {
      const row = Number(key)
      const mapped = Number.isInteger(row) ? mapRow(row) : null
      if (mapped !== null) next[String(mapped)] = item
    })
    if (regenerateLink) clonedRows.forEach(({ source, target, newLink }) => {
      if (!(String(source) in value)) return
      next[String(target)] = regenerateLink && newLink ? newOpsShipmentLink() : value[String(source)]
    })
    return next
  }
  settings.value = {
    ...settings.value,
    opsRowLinks: remapIndexedObject(settings.value.opsRowLinks, true),
    opsRowCreators: remapIndexedObject(settings.value.opsRowCreators),
    crossServiceLinks: remapIndexedObject(settings.value.crossServiceLinks),
    linkedDateChanges: remapIndexedObject(settings.value.linkedDateChanges),
  }
}
const markManualOpsRow = (row: number) => setManualOpsRows([...manualOpsRows(), row])
const isManualOpsRow = (row: number) => manualOpsRows().has(row)
const isStandaloneManualOpsRow = (row: number) =>
  ['CCD', 'TCD', 'DCD'].includes(String(opsParts.value?.dept || '').toUpperCase()) && isManualOpsRow(row)
const canEditSelectedOpsRow = computed(() => {
  if (!isOpsPage.value || !canManageManualOpsRows() || opsEditingRow.value || opsSelectedRows.value.size !== 1) return false
  const row = [...opsSelectedRows.value][0]
  return isManualOpsRow(row) && !isSentEcdRowLocked(row)
})
const canDeleteSelectedOpsRows = computed(() => {
  if (!isOpsPage.value || !canManageManualOpsRows() || opsEditingRow.value || !opsSelectedRows.value.size) return false
  return [...opsSelectedRows.value].every((row) => isManualOpsRow(row))
})
const editSelectedOpsRow = () => {
  if (!canEditSelectedOpsRow.value) return
  const row = [...opsSelectedRows.value][0]
  opsEditingRow.value = { row, isNew: false, snapshot: rows.value[row].slice() }
}

const addRow = async () => {
  if (isOpsPage.value && opsEditingRow.value) {
    showToast('Save or cancel the current row first')
    return
  }
  if (isOpsPage.value) {
    if (!canAddOpsRow()) return
    await loadOpsStaff()
    if (requiresRowConfirmation() && !(await askRowConfirm('add'))) return
    sortBy.value = 'new'
    activeStatus.value = 'active'
    query.value = ''
    opsFilterField.value = 'all'
    opsAdvancedFilters.value = []
    opsAppliedFilters.value = []
    const blankRow = rows.value.findIndex((row, index) => index > 0 && isBlankOpsDataRow(row))
    if (blankRow > 0) {
      rows.value[blankRow] = makeBlankWorkbookRow()
      const modeColumn = headerIndexOf(['MODE'])
      if (modeColumn >= 0) rows.value[blankRow][modeColumn] = 'MANU'
      const links = { ...(settings.value.opsRowLinks || {}) }
      if (String(opsParts.value?.dept || '').toUpperCase() === 'GSD') links[String(blankRow)] = newOpsShipmentLink()
      else delete links[String(blankRow)]
      const creators = { ...(settings.value.opsRowCreators || {}), [String(blankRow)]: String(props.currentUser?.displayName || props.currentUser?.username || '').trim() }
      settings.value = { ...settings.value, opsRowLinks: links, opsRowCreators: creators }
      markManualOpsRow(blankRow)
      opsEditingRow.value = { row: blankRow, isNew: true, snapshot: rows.value[blankRow].slice() }
      opsSelectedRows.value = new Set()
      return
    }
  }
  rows.value.push(makeBlankWorkbookRow())
  if (isOpsPage.value) {
    const row = rows.value.length - 1
    const modeColumn = headerIndexOf(['MODE'])
    if (modeColumn >= 0) rows.value[row][modeColumn] = 'MANU'
    const links = { ...(settings.value.opsRowLinks || {}) }
    if (String(opsParts.value?.dept || '').toUpperCase() === 'GSD') links[String(row)] = newOpsShipmentLink()
    else delete links[String(row)]
    const creators = { ...(settings.value.opsRowCreators || {}), [String(row)]: String(props.currentUser?.displayName || props.currentUser?.username || '').trim() }
    settings.value = { ...settings.value, opsRowLinks: links, opsRowCreators: creators }
    markManualOpsRow(row)
    opsEditingRow.value = { row, isNew: true, snapshot: rows.value[row].slice() }
    opsSelectedRows.value = new Set()
    return
  }
  scheduleSave()
}

const toggleOpsRow = (row: number) => {
  const next = new Set(opsSelectedRows.value)
  if (next.has(row)) next.delete(row)
  else next.add(row)
  opsSelectedRows.value = next
}

const toggleAllOpsRows = () => {
  if (opsAllVisibleSelected.value) {
    opsSelectedRows.value = new Set()
    return
  }
  opsSelectedRows.value = new Set(opsBodyRows.value)
}

const deleteOpsRows = async () => {
  if (opsEditingRow.value) {
    showToast('Save or cancel the current row first')
    return
  }
  const selected = [...opsSelectedRows.value].filter((row) => row > 0 && row < rows.value.length).sort((a, b) => b - a)
  if (!selected.length) return
  if (!canManageManualOpsRows()) {
    showToast('Rows can only be removed manually in GSD, CCD or TCD')
    return
  }
  const nonManual = selected.filter((row) => !isManualOpsRow(row))
  if (nonManual.length) {
    showToast('Only rows created with Add Row can be removed')
    return
  }
  if (String(opsParts.value?.dept || '').toUpperCase() === 'GSD') {
    for (const row of selected) {
      if (await hasDownstreamOpsActivity(row)) {
        showToast('This shipment is already being processed by the next department')
        return
      }
    }
  }
  if (requiresRowConfirmation()) {
    if (!(await askRowConfirm('remove'))) return
  } else if (!(await askConfirm(`Remove ${selected.length} selected record${selected.length > 1 ? 's' : ''}?`, 'Remove'))) return
  const removed = new Set(selected)
  for (const row of selected) rows.value.splice(row, 1)
  remapOpsRowSettings((row) => removed.has(row) ? null : row - selected.filter((removedRow) => removedRow < row).length)
  setManualOpsRows([...manualOpsRows()].filter((row) => !removed.has(row)).map((row) => row - selected.filter((removedRow) => removedRow < row).length))
  opsSelectedRows.value = new Set()
  scheduleSave()
  showToast(`Removed ${selected.length} row${selected.length > 1 ? 's' : ''}`)
}

const addColumn = () => {
  const next = columnCount.value
  rows.value.forEach((row, index) => row.push(index === 0 ? `Column ${next + 1}` : ''))
  columnWidths.value.push(120)
  scheduleSave()
}

const remapColumnArray = <T,>(source: T[], oldToNew: Map<number, number>) => {
  const next: T[] = []
  oldToNew.forEach((newIndex, oldIndex) => {
    if (oldIndex in source) next[newIndex] = source[oldIndex]
  })
  return next
}

const shiftOpsColumnStateForInsert = (insertAt: number) => {
  const nextFormatting: Record<string, any> = {}
  Object.entries(formatting.value).forEach(([key, value]) => {
    const [row, column] = key.split(':').map(Number)
    if (!Number.isFinite(row) || !Number.isFinite(column)) return
    nextFormatting[`${row}:${column >= insertAt ? column + 1 : column}`] = value
  })
  formatting.value = nextFormatting

  merges.value = merges.value.map((merge) => [
    merge[0],
    merge[1] >= insertAt ? merge[1] + 1 : merge[1],
    merge[2],
    merge[3] >= insertAt ? merge[3] + 1 : merge[3],
  ])

  const nextColumnFormats: Record<string, any> = {}
  Object.entries(settings.value.columnFormats || {}).forEach(([key, value]) => {
    const column = Number(key)
    if (Number.isFinite(column)) nextColumnFormats[String(column >= insertAt ? column + 1 : column)] = value
  })
  const shiftList = (values: any[]) => values.map((value) => {
    const column = Number(value)
    return Number.isFinite(column) && column >= insertAt ? column + 1 : column
  })
  const nextDropdownOptions: Record<string, any> = {}
  Object.entries(settings.value.dropdownOptions || {}).forEach(([key, value]) => {
    const scopedPrefix = `${activeKey.value}:`
    if (key.startsWith(scopedPrefix)) {
      const column = Number(key.slice(scopedPrefix.length))
      nextDropdownOptions[`${scopedPrefix}${Number.isFinite(column) && column >= insertAt ? column + 1 : column}`] = value
      return
    }
    const column = Number(key)
    if (Number.isFinite(column)) nextDropdownOptions[String(column >= insertAt ? column + 1 : column)] = value
  })
  const currentXfer = Number(settings.value.xferColumn)
  settings.value = {
    ...settings.value,
    columnFormats: nextColumnFormats,
    hiddenColumns: shiftList(settings.value.hiddenColumns || []),
    lockedColumns: shiftList(settings.value.lockedColumns || []),
    customColumns: [...shiftList(settings.value.customColumns || []), insertAt].sort((a, b) => a - b),
    dropdownOptions: nextDropdownOptions,
    xferColumn: Number.isFinite(currentXfer) && currentXfer >= insertAt ? currentXfer + 1 : settings.value.xferColumn,
  }
}

const deleteCustomColumns = (columns: number[]) => {
  const toDelete = new Set(columns.filter((column) => !isDefaultTemplateColumn(column)))
  if (!toDelete.size) {
    showToast('Default template columns cannot be deleted')
    return false
  }
  const oldToNew = new Map<number, number>()
  let nextIndex = 0
  for (let oldIndex = 0; oldIndex < columnCount.value; oldIndex++) {
    if (!toDelete.has(oldIndex)) oldToNew.set(oldIndex, nextIndex++)
  }
  rows.value = rows.value.map((row) => row.filter((_, index) => !toDelete.has(index)))
  columnWidths.value = remapColumnArray(columnWidths.value, oldToNew)
  const nextFormatting: Record<string, any> = {}
  Object.entries(formatting.value).forEach(([key, value]) => {
    const [r, c] = key.split(':').map(Number)
    const nextCol = oldToNew.get(c)
    if (Number.isFinite(r) && nextCol !== undefined) nextFormatting[`${r}:${nextCol}`] = value
  })
  formatting.value = nextFormatting
  merges.value = merges.value
    .map((merge) => [merge[0], oldToNew.get(merge[1]), merge[2], oldToNew.get(merge[3])])
    .filter((merge): merge is number[] => merge[1] !== undefined && merge[3] !== undefined)

  const nextColumnFormats: Record<string, any> = {}
  Object.entries(settings.value.columnFormats || {}).forEach(([key, value]) => {
    const nextCol = oldToNew.get(Number(key))
    if (nextCol !== undefined) nextColumnFormats[String(nextCol)] = value
  })
  const nextHidden = (settings.value.hiddenColumns || [])
    .map((value: any) => oldToNew.get(Number(value)))
    .filter((value: any) => value !== undefined)
  const nextLocked = (settings.value.lockedColumns || [])
    .map((value: any) => oldToNew.get(Number(value)))
    .filter((value: any) => value !== undefined)
  const nextCustomColumns = (settings.value.customColumns || [])
    .map((value: any) => oldToNew.get(Number(value)))
    .filter((value: any) => value !== undefined)
  const nextDropdownOptions: Record<string, any> = {}
  Object.entries(settings.value.dropdownOptions || {}).forEach(([key, value]) => {
    const scopedPrefix = `${activeKey.value}:`
    if (key.startsWith(scopedPrefix)) {
      const nextCol = oldToNew.get(Number(key.slice(scopedPrefix.length)))
      if (nextCol !== undefined) nextDropdownOptions[`${scopedPrefix}${nextCol}`] = value
      return
    }
    const nextCol = oldToNew.get(Number(key))
    if (nextCol !== undefined) nextDropdownOptions[String(nextCol)] = value
  })
  const currentXfer = Number(settings.value.xferColumn)
  settings.value = {
    ...settings.value,
    columnFormats: nextColumnFormats,
    hiddenColumns: nextHidden,
    lockedColumns: nextLocked,
    customColumns: nextCustomColumns,
    dropdownOptions: nextDropdownOptions,
    xferColumn: Number.isFinite(currentXfer) ? oldToNew.get(currentXfer) ?? null : settings.value.xferColumn,
  }
  scheduleSave()
  showToast(`Deleted ${toDelete.size} custom column(s)`)
  return true
}

const closeOpsHeaderMenu = () => {
  opsHeaderMenu.open = false
  opsHeaderMenu.column = -1
}

const openOpsHeaderMenu = (column: number, event: MouseEvent) => {
  console.log('[opsmenu] fired', column, event.clientX, event.clientY)
  closeContextSurfaces()
  opsHeaderMenu.column = column
  opsHeaderMenu.left = Math.min(event.clientX, window.innerWidth - 180)
  opsHeaderMenu.top = Math.min(event.clientY, window.innerHeight - 90)
  opsHeaderMenu.open = true
  nextTick(() => {
    const el = document.querySelector('.ops-head-menu')
    console.log('[opsmenu] open=', opsHeaderMenu.open, 'el=', el ? JSON.stringify(el.getBoundingClientRect()) : 'NOT RENDERED', el ? getComputedStyle(el).cssText.slice(0, 0) : '')
    if (el) {
      const cs = getComputedStyle(el)
      console.log('[opsmenu] style display=', cs.display, 'visibility=', cs.visibility, 'opacity=', cs.opacity, 'z-index=', cs.zIndex, 'position=', cs.position)
    }
  })
}

const onGlobalScrollClose = () => {
  if (opsHeaderMenu.open) closeOpsHeaderMenu()
}

const closeOpsColumnModal = () => {
  opsColumnModal.open = false
  opsColumnModal.name = ''
  opsColumnModal.column = -1
}

const opsColumnTitle = (column: number) => {
  const label = headerLabel(column).trim()
  return label || columnLetter(column)
}

const addOpsColumnFromMenu = () => {
  const column = opsHeaderMenu.column
  closeOpsHeaderMenu()
  opsColumnModal.mode = 'add'
  opsColumnModal.column = column
  opsColumnModal.name = ''
  opsColumnModal.open = true
  nextTick(() => opsColumnNameInput.value?.focus())
}

const removeOpsColumnFromMenu = () => {
  const column = opsHeaderMenu.column
  if (column < 0) return
  if (isDefaultTemplateColumn(column)) {
    closeOpsHeaderMenu()
    showToast('Default template columns cannot be deleted')
    return
  }
  closeOpsHeaderMenu()
  opsColumnModal.mode = 'remove'
  opsColumnModal.column = column
  opsColumnModal.name = ''
  opsColumnModal.open = true
}

const confirmAddOpsColumn = () => {
  const columnName = opsColumnModal.name.trim()
  if (!columnName) {
    showToast('Enter column name')
    opsColumnNameInput.value?.focus()
    return
  }
  const insertAt = Math.min(Math.max(opsColumnModal.column + 1, 0), columnCount.value)
  rows.value.forEach((row, index) => row.splice(insertAt, 0, index === 0 ? columnName : ''))
  columnWidths.value.splice(insertAt, 0, 120)
  shiftOpsColumnStateForInsert(insertAt)
  closeOpsColumnModal()
  scheduleSave()
  showToast('Column added')
}

const confirmRemoveOpsColumn = () => {
  const column = opsColumnModal.column
  if (column < 0) return
  if (deleteCustomColumns([column])) closeOpsColumnModal()
}

const duplicateRows = () => {
  const rect = selectedRect.value
  if (!rect) {
    showToast('Select a row first')
    return
  }
  const from = Math.max(1, rect.r1)
  const to = Math.max(from, rect.r2)
  if (to < 1 || from >= rows.value.length) {
    showToast('Select a row first')
    return
  }
  const clones = rows.value.slice(from, to + 1).map((row) => [...row])
  if (!clones.length) return
  const insertAt = Math.min(rows.value.length, to + 1)
  const shiftedFormatting: Record<string, any> = {}
  Object.entries(formatting.value).forEach(([key, value]) => {
    const [row, column] = key.split(':').map(Number)
    const nextRow = Number.isFinite(row) && row >= insertAt ? row + clones.length : row
    shiftedFormatting[`${nextRow}:${column}`] = value
  })
  formatting.value = shiftedFormatting
  const shiftedHeights: Record<string, any> = {}
  Object.entries(rowHeights.value || {}).forEach(([key, value]) => {
    const row = Number(key)
    shiftedHeights[String(Number.isFinite(row) && row >= insertAt ? row + clones.length : row)] = value
  })
  clones.forEach((_, index) => {
    const sourceHeight = rowHeights.value[String(from + index)]
    if (sourceHeight) shiftedHeights[String(insertAt + index)] = sourceHeight
  })
  rowHeights.value = shiftedHeights
  rows.value.splice(insertAt, 0, ...clones)
  remapOpsRowSettings(
    (row) => row >= insertAt ? row + clones.length : row,
    clones.map((_, index) => ({ source: from + index, target: insertAt + index, newLink: true })),
  )
  selectionKind.value = null
  selectedCell.value = null
  selectionAnchor.value = null
  selectionFocus.value = null
  scheduleSave()
  showToast(clones.length > 1 ? `${clones.length} rows duplicated` : 'Row duplicated')
}

const copySelection = async () => {
  const rect = selectedRect.value
  if (!rect) return
  const textLines = []
  for (let r = rect.r1; r <= rect.r2; r++) {
    const line = []
    for (let c = rect.c1; c <= rect.c2; c++) {
      line.push(rows.value[r]?.[c] ?? '')
    }
    textLines.push(line.join('\t'))
  }
  await navigator.clipboard.writeText(textLines.join('\n'))
  showToast('Copied to clipboard')
}

const selectionToTsv = () => {
  const rect = selectedRect.value
  if (!rect) return ''
  const textLines = []
  for (let r = rect.r1; r <= rect.r2; r++) {
    const line = []
    for (let c = rect.c1; c <= rect.c2; c++) line.push(rows.value[r]?.[c] ?? '')
    textLines.push(line.join('\t'))
  }
  return textLines.join('\n')
}

const copyText = async (text: string, message = 'Copied to clipboard') => {
  if (!text) return
  await navigator.clipboard.writeText(text)
  showToast(message)
}

const closeContextSurfaces = () => {
  contextMenu.open = false
  notePopover.open = false
}

const openContextMenu = (row: number, column: number, event: MouseEvent) => {
  if (!cellInRange(row, column)) startSel('cell', row, column)
  contextMenu.row = row
  contextMenu.column = column
  contextMenu.left = Math.min(event.clientX, window.innerWidth - 180)
  contextMenu.top = Math.min(event.clientY, window.innerHeight - 210)
  contextMenu.open = true
  notePopover.open = false
}

const contextCopy = async () => {
  contextMenu.open = false
  await copyText(selectionToTsv())
}

const contextCut = async () => {
  contextMenu.open = false
  const text = selectionToTsv()
  if (!text) return
  await copyText(text, 'Cut')
  clearSelection()
}

const contextPaste = async () => {
  contextMenu.open = false
  try {
    const text = await navigator.clipboard.readText()
    if (!text) {
      showToast('Press Ctrl+V to paste')
      return
    }
    await pasteTextAtSelection(text)
  } catch {
    showToast('Press Ctrl+V to paste')
  }
}

const contextClear = () => {
  contextMenu.open = false
  clearSelection()
}

const notes = () => ({ ...(settings.value.notes || {}) }) as Record<string, string>
const noteKey = (row: number, column: number) => `${row}:${column}`
const noteText = (row: number, column: number) => notes()[noteKey(row, column)] || ''
const openNotePopover = () => {
  const row = contextMenu.row
  const column = contextMenu.column
  contextMenu.open = false
  notePopover.row = row
  notePopover.column = column
  notePopover.text = noteText(row, column)
  const cell = sheetBody.value?.querySelector<HTMLElement>(`td[data-r="${row}"][data-c="${column}"]`)
  const rect = cell?.getBoundingClientRect()
  notePopover.left = Math.max(8, Math.min(rect?.left ?? contextMenu.left, window.innerWidth - 280))
  notePopover.top = Math.max(8, Math.min((rect?.bottom ?? contextMenu.top) + 4, window.innerHeight - 190))
  notePopover.open = true
}

const saveNote = () => {
  const next = notes()
  const key = noteKey(notePopover.row, notePopover.column)
  if (notePopover.text.trim()) next[key] = notePopover.text.trim()
  else delete next[key]
  settings.value = { ...settings.value, notes: next }
  notePopover.open = false
  scheduleSave()
}

const deleteNote = () => {
  const next = notes()
  delete next[noteKey(notePopover.row, notePopover.column)]
  settings.value = { ...settings.value, notes: next }
  notePopover.open = false
  scheduleSave()
  showToast('Note removed')
}

const askConfirm = (message: string, title = 'Confirm', options: Partial<{ okText: string; cancelText: string; tone: 'primary' | 'danger' | 'remove' | 'question' }> = {}) => new Promise<boolean>((resolve) => {
  confirmModal.title = title
  confirmModal.message = message
  confirmModal.okText = options.okText || 'OK'
  confirmModal.cancelText = options.cancelText || 'Cancel'
  confirmModal.tone = options.tone || 'primary'
  confirmModal.resolve = resolve
  confirmModal.open = true
})

const resolveConfirm = (value: boolean) => {
  const resolve = confirmModal.resolve
  confirmModal.open = false
  confirmModal.resolve = null
  resolve?.(value)
}

const askRowConfirm = (action: 'add' | 'remove') => new Promise<boolean>((resolve) => {
  rowConfirmModal.action = action
  rowConfirmModal.expected = 'CONFIRM'
  rowConfirmModal.message = ''
  rowConfirmModal.value = ''
  rowConfirmModal.resolve = resolve
  rowConfirmModal.open = true
  nextTick(() => rowConfirmInput.value?.focus())
})

const askTypedRowConfirm = (expected: string, message: string) => new Promise<boolean>((resolve) => {
  rowConfirmModal.expected = expected
  rowConfirmModal.message = message
  rowConfirmModal.value = ''
  rowConfirmModal.resolve = resolve
  rowConfirmModal.open = true
  nextTick(() => rowConfirmInput.value?.focus())
})

const resolveRowConfirm = (accepted: boolean) => {
  if (accepted && rowConfirmModal.value.toUpperCase() !== rowConfirmModal.expected.toUpperCase()) return
  const resolve = rowConfirmModal.resolve
  rowConfirmModal.open = false
  rowConfirmModal.resolve = null
  resolve?.(accepted)
}

const deleteSelection = async () => {
  const rect = selectedRect.value
  if (!rect) return
  
  if (selectionKind.value === 'col') {
    const selectedColumns = Array.from({ length: rect.c2 - rect.c1 + 1 }, (_, index) => rect.c1 + index)
    const customColumns = selectedColumns.filter((column) => !isDefaultTemplateColumn(column))
    if (!customColumns.length) {
      showToast('Default template columns cannot be deleted')
      return
    }
    const blocked = selectedColumns.length - customColumns.length
    const message = blocked
      ? `${blocked} default template column(s) will be kept. Delete ${customColumns.length} custom column(s)?`
      : `Delete ${customColumns.length} custom column(s)?`
    if (await askConfirm(message, 'Delete columns')) {
      deleteCustomColumns(customColumns)
      selectionKind.value = null
    }
  } else if (selectionKind.value === 'row') {
    const count = rect.r2 - rect.r1 + 1
    if (await askConfirm(`Delete ${count} row(s)?`, 'Delete rows')) {
      for (let r = rect.r2; r >= rect.r1; r--) {
        if (r === 0) continue
        rows.value.splice(r, 1)
        delete rowHeights.value[String(r)]
      }
      const removedRows = new Set(Array.from({ length: count }, (_, index) => rect.r1 + index).filter((row) => row > 0))
      remapOpsRowSettings((row) => removedRows.has(row) ? null : row - [...removedRows].filter((removedRow) => removedRow < row).length)
      selectionKind.value = null
      scheduleSave()
      showToast(`Deleted ${count} row(s)`)
    }
  } else {
    if (await askConfirm('Clear contents of the selected cells?', 'Clear selection')) clearSelection()
  }
}

const clearSelection = () => {
  const rect = selectedRect.value
  if (!rect) return
  for (let r = rect.r1; r <= rect.r2; r++) {
    for (let c = rect.c1; c <= rect.c2; c++) {
      if (r === 0 && isDefaultTemplateColumn(c)) continue
      if (isLockedOpsCell(r, c)) continue
      if (rows.value[r]) rows.value[r][c] = ''
    }
  }
  scheduleSave()
  showToast('Selection cleared')
}

// Drag, Select, Editing Interactions

const startSel = (kind: SelectionKind, row: number, col: number) => {
  if (editingCell.value) {
    const el = document.querySelector(`td[data-r="${editingCell.value.row}"][data-c="${editingCell.value.column}"]`) as HTMLElement
    if (el) el.blur()
    editingCell.value = null
  }

  selectionKind.value = kind
  selectionAnchor.value = { row, column: col }
  selectionFocus.value = { row, column: col }
  selectedCell.value = { row, column: col }
  dragging.value = true
  colorPalette.open = false
}

const handleCellMouseDown = (row: number, col: number, event: MouseEvent) => {
  if (isEditingCell(row, col)) return
  if (editingCell.value) {
    const el = document.querySelector(`td[data-r="${editingCell.value.row}"][data-c="${editingCell.value.column}"]`) as HTMLElement
    if (el) el.blur()
  }
  event.preventDefault() // prevent text selection native
  if (event.shiftKey && selectionAnchor.value) {
    selectionFocus.value = { row, column: col }
    selectionKind.value = 'cell'
    dragging.value = true
  } else if (event.ctrlKey || event.metaKey) {
    startSel('cellctrl', row, col)
  } else {
    startSel('cell', row, col)
  }
}

const isEditingCell = (row: number, col: number) => editingCell.value?.row === row && editingCell.value?.column === col

const beginEditCell = async (row: number, col: number) => {
  if (row === 0 && isDefaultTemplateColumn(col)) {
    showToast('Default template columns are locked')
    return
  }
  if (isLockedOpsCell(row, col)) {
    showToast('Column locked')
    return
  }
  if (isSentEcdRowLocked(row)) {
    showToast('Row locked after SENT ECD. Use the Edit icon at SENT ECD to unlock it.')
    return
  }
  if (isCheckboxCell(row, col)) return
  if (isActionSelectCell(row, col)) return
  if (isDropdownCell(row, col)) {
    const cell = sheetBody.value?.querySelector<HTMLElement>(`td[data-r="${row}"][data-c="${col}"]`)
    if (cell) openDropdownPopup(row, col, undefined, cell)
    return
  }
  if (isActionInfoCell(row, col)) {
    openInfoModal(row, col)
    return
  }
  if (isTruckInfoCell(row, col)) {
    openTruckModal(row, col)
    return
  }
  if (isDatePopupCell(row, col)) {
    const cell = sheetBody.value?.querySelector<HTMLElement>(`td[data-r="${row}"][data-c="${col}"]`)
    if (cell) openDatePopup(row, col, cell)
    return
  }
  editingCell.value = { row, column: col }
  await nextTick()
  const el = sheetBody.value?.querySelector(`td[data-r="${row}"][data-c="${col}"]`) as HTMLElement
  if (el) {
    el.focus()
    const range = document.createRange()
    range.selectNodeContents(el)
    range.collapse(false) // collapse to end
    const sel = window.getSelection()
    sel?.removeAllRanges()
    sel?.addRange(range)
  }
}

const finishEditCell = (row: number, col: number, event: Event) => {
  if (editingCell.value?.row !== row || editingCell.value?.column !== col) return
  editingCell.value = null
  if (row === 0 && isDefaultTemplateColumn(col)) return
  if (isLockedOpsCell(row, col) || isSentEcdRowLocked(row)) return
  normalizeRows()
  const rawValue = (event.target as HTMLElement)?.innerText ?? ''
  const value = row > 0 && isOpsMoneyColumn(col) && rawValue.trim() ? formatMoneyValue(rawValue) : rawValue
  if (rows.value[row][col] === value) return
  rows.value[row][col] = value
  mirrorFclLinkedCell(row, col)
  scheduleSave()
}

const pasteTextAtSelection = async (text: string) => {
  if (!text || !selectionAnchor.value) return
  const lines = text.split(/\r?\n/).filter((line, i, arr) => i < arr.length - 1 || line !== '')
  if (!lines.length) return

  const startRow = Math.min(selectionAnchor.value.row, selectionFocus.value?.row ?? selectionAnchor.value.row)
  const startCol = Math.min(selectionAnchor.value.column, selectionFocus.value?.column ?? selectionAnchor.value.column)

  for (let r = 0; r < lines.length; r++) {
    const cols = lines[r].split('\t')
    const targetRow = startRow + r
    while (targetRow >= rows.value.length) rows.value.push(Array.from({ length: columnCount.value }, () => ''))
    for (let c = 0; c < cols.length; c++) {
      const targetCol = startCol + c
      if (targetCol < columnCount.value) {
        if (targetRow === 0 && isDefaultTemplateColumn(targetCol)) continue
        if (isLockedOpsCell(targetRow, targetCol)) continue
        if (!rows.value[targetRow]) rows.value[targetRow] = Array(columnCount.value).fill('')
        rows.value[targetRow][targetCol] = cols[c]
      }
    }
  }
  scheduleSave()
  showToast('Pasted')
}

const cancelEditCell = (row: number, col: number, event: Event) => {
  const el = event.target as HTMLElement
  el.innerText = displayCell(rows.value[row]?.[col], row, col) || ''
  el.blur()
  editingCell.value = null
}

const handleEnterEdit = (row: number, col: number, event: KeyboardEvent) => {
  if (event.shiftKey) return // allow multiline with shift+enter
  const el = event.target as HTMLElement
  el.blur()
  const nextRow = Math.min(row + 1, rows.value.length - 1)
  startSel('cell', nextRow, col)
}

const handleTabEdit = (row: number, col: number, event: KeyboardEvent) => {
  const el = event.target as HTMLElement
  el.blur()
  const nextCol = Math.max(0, Math.min(col + (event.shiftKey ? -1 : 1), columnCount.value - 1))
  startSel('cell', row, nextCol)
}

const rowIsSelected = (row: number) => {
  const rect = selectedRect.value
  return Boolean(rect && row >= rect.r1 && row <= rect.r2)
}

const colIsSelected = (col: number) => {
  const rect = selectedRect.value
  return Boolean(rect && col >= rect.c1 && col <= rect.c2)
}

// Resizing
const startColResize = (event: MouseEvent, column: number) => {
  resizing.value = {
    type: 'col', index: column,
    startX: event.clientX, startY: event.clientY,
    startW: columnWidth(column), startH: 0
  }
  document.body.style.cursor = 'col-resize'
}

const startRowResize = (event: MouseEvent, row: number) => {
  resizing.value = {
    type: 'row', index: row,
    startX: event.clientX, startY: event.clientY,
    startW: 0, startH: Number(rowHeights.value[String(row)]) || 26
  }
  document.body.style.cursor = 'row-resize'
}

const handleResizeMove = (event: MouseEvent) => {
  if (!resizing.value) return
  if (resizing.value.type === 'col') {
    const w = Math.max(56, resizing.value.startW + (event.clientX - resizing.value.startX))
    columnWidths.value[resizing.value.index] = w
  } else {
    const h = Math.max(22, resizing.value.startH + (event.clientY - resizing.value.startY))
    rowHeights.value[String(resizing.value.index)] = h
  }
}

const handleResizeEnd = () => {
  resizing.value = null
  document.body.style.cursor = ''
  syncRenderedRowHeights()
  scheduleSave()
}

const autoFitColumn = (column: number) => {
  let maxLen = 0
  for (const row of rows.value.slice(0, 200)) {
    const val = row[column]
    if (val) maxLen = Math.max(maxLen, String(val).length)
  }
  const fitWidth = Math.max(56, maxLen * 8 + 20)
  columnWidths.value[column] = fitWidth
  scheduleSave()
}

const resetRowHeight = (row: number) => {
  delete rowHeights.value[String(row)]
  syncRenderedRowHeights()
  scheduleSave()
}

// Global window events
const onGlobalMouseMove = (event: MouseEvent) => {
  if (resizing.value) {
    handleResizeMove(event)
    return
  }
  if (!dragging.value || !selectionKind.value || selectionKind.value === 'all') return

  const el = document.elementFromPoint(event.clientX, event.clientY)
  if (!el || !el.closest) return

  if (selectionKind.value === 'col') {
    const th = el.closest('th[data-col]') as HTMLElement
    if (th) {
      const c = Number(th.dataset.col)
      if (c !== selectionFocus.value?.column) selectionFocus.value = { row: 0, column: c }
    }
  } else if (selectionKind.value === 'row') {
    const th = el.closest('th[data-row]') as HTMLElement
    if (th) {
      const r = Number(th.dataset.row)
      if (r !== selectionFocus.value?.row) selectionFocus.value = { row: r, column: 0 }
    }
  } else if (selectionKind.value === 'cellctrl' || selectionKind.value === 'cell') {
    const td = el.closest('td.cell') as HTMLElement
    if (td) {
      const r = Number(td.dataset.r)
      const c = Number(td.dataset.c)
      if (r !== selectionFocus.value?.row || c !== selectionFocus.value?.column) {
        selectionFocus.value = { row: r, column: c }
        if (selectionKind.value === 'cellctrl') {
           const anchor = selectionAnchor.value!
           selectionKind.value = Math.abs(r - anchor.row) >= Math.abs(c - anchor.column) ? 'row' : 'col'
        }
      }
    }
  }
}

const onGlobalMouseUp = () => {
  dragging.value = false
  if (resizing.value) {
    handleResizeEnd()
  }
}

const onGlobalMouseDown = (event: MouseEvent) => {
  const target = event.target as HTMLElement | null
  if (isOpsPage.value && target instanceof HTMLInputElement && (['date', 'time', 'datetime-local'].includes(target.type) || target === nativePickerInput) && !target.disabled && !target.readOnly) {
    event.preventDefault()
    if (nativePickerInput && target !== nativePickerInput) cancelNativeOperationsPicker()
    const pickerType = target === nativePickerInput ? nativePickerType : target.type as 'date' | 'time' | 'datetime-local'
    const computed = window.getComputedStyle(target)
    const rect = target.getBoundingClientRect()
    if (!nativePickerOriginalStyle.has(target)) nativePickerOriginalStyle.set(target, target.style.cssText)
    target.type = 'text'
    target.classList.add('ops-picker-proxy')
    Object.assign(target.style, {
      width: `${rect.width}px`, height: `${rect.height}px`, minWidth: `${rect.width}px`, boxSizing: 'border-box',
      borderTopWidth: computed.borderTopWidth, borderTopStyle: computed.borderTopStyle, borderTopColor: computed.borderTopColor,
      borderRightWidth: computed.borderRightWidth, borderRightStyle: computed.borderRightStyle, borderRightColor: computed.borderRightColor,
      borderBottomWidth: computed.borderBottomWidth, borderBottomStyle: computed.borderBottomStyle, borderBottomColor: computed.borderBottomColor,
      borderLeftWidth: computed.borderLeftWidth, borderLeftStyle: computed.borderLeftStyle, borderLeftColor: computed.borderLeftColor,
      borderRadius: computed.borderRadius, backgroundColor: computed.backgroundColor, backgroundImage: computed.backgroundImage,
      backgroundRepeat: computed.backgroundRepeat, backgroundPosition: computed.backgroundPosition, backgroundSize: computed.backgroundSize,
      paddingTop: computed.paddingTop, paddingRight: computed.paddingRight, paddingBottom: computed.paddingBottom, paddingLeft: computed.paddingLeft,
      color: computed.color, fontFamily: computed.fontFamily, fontSize: computed.fontSize, fontWeight: computed.fontWeight,
      lineHeight: computed.lineHeight, textAlign: computed.textAlign,
    })
    target.style.visibility = 'hidden'
    const rawValue = target.value
    const dateValue = rawValue ? cutoffDateLabel(rawValue.slice(0, 10)) : 'dd/mm/yyyy'
    const timeValue = rawValue.match(/(?:T)?(\d{2}:\d{2})/)?.[1] || '-- : --'
    Object.assign(pickerFieldProxy, { open: true, left: rect.left, top: rect.top, width: rect.width, height: rect.height, type: pickerType === 'time' ? 'time' : 'date', label: pickerType === 'time' ? timeValue : dateValue })
    openNativeOperationsPicker(target, pickerType)
    return
  }
  if (!target?.closest('.country-dd')) countryOpen.value = false
  if (!target?.closest('.ops-head-menu')) closeOpsHeaderMenu()
  if (!target?.closest('.ctxmenu')) contextMenu.open = false
  if (!target?.closest('.notepop')) notePopover.open = false
  if (!target?.closest('.ddpop') && !target?.closest('.ddcell')) closeDropdownPopup()
  if (!target?.closest('.datepop')) {
    closeDatePopup()
    if (nativePickerInput && !cutoffTimePopup.open) cancelNativeOperationsPicker()
  }
  if (!target?.closest('.cutoff-timepop') && !target?.closest('.gsd-cutoff-time')) {
    closeCutoffTimePopup()
    if (nativePickerInput && !datePopup.open) cancelNativeOperationsPicker()
  }
}
const preventNativeOperationsPicker = (event: MouseEvent) => {
  const target = event.target
  if (isOpsPage.value && target instanceof HTMLInputElement && (['date', 'time', 'datetime-local'].includes(target.type) || target === nativePickerInput) && !target.disabled) event.preventDefault()
}

const onGlobalKeyDown = (event: KeyboardEvent) => {
  if (editingCell.value) return 
  if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return

  if (!selectionFocus.value) return
  const row = selectionFocus.value.row
  const col = selectionFocus.value.column

  if (event.key === 'F2' || event.key === 'Enter') {
    event.preventDefault()
    beginEditCell(row, col)
    return
  }

  if (event.key === 'Delete' || event.key === 'Backspace') {
    event.preventDefault()
    deleteSelection()
    return
  }

  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'c') {
    event.preventDefault()
    copySelection()
    return
  }

  const nav = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }[event.key]
  if (nav) {
    event.preventDefault()
    const nextRow = Math.max(0, Math.min(rows.value.length - 1, row + nav[0]))
    const nextCol = Math.max(0, Math.min(columnCount.value - 1, col + nav[1]))
    if (event.shiftKey) {
      selectionFocus.value = { row: nextRow, column: nextCol }
    } else {
      startSel('cell', nextRow, nextCol)
    }
    nextTick(() => {
      const el = sheetBody.value?.querySelector(`td[data-r="${nextRow}"][data-c="${nextCol}"]`)
      if (el) el.scrollIntoView({ block: 'nearest', inline: 'nearest' })
    })
    return
  }

  if (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey) {
    event.preventDefault()
    beginEditCell(row, col).then(() => {
      const el = sheetBody.value?.querySelector(`td[data-r="${row}"][data-c="${col}"]`) as HTMLElement
      if (el) {
        el.innerText = event.key
        const range = document.createRange()
        range.selectNodeContents(el)
        range.collapse(false)
        const sel = window.getSelection()
        sel?.removeAllRanges()
        sel?.addRange(range)
      }
    })
  }
}

const onGlobalPaste = async (event: ClipboardEvent) => {
  if (editingCell.value) return // allow native paste inside cell
  if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return
  
  const text = event.clipboardData?.getData('text/plain')
  if (!text || !selectionAnchor.value) return
  
  event.preventDefault()
  await pasteTextAtSelection(text)
}

const syncSheetScroll = () => {
  if (!sheetBody.value) return
  if (columnBar.value) columnBar.value.scrollLeft = sheetBody.value.scrollLeft
  if (rowBar.value) rowBar.value.scrollTop = sheetBody.value.scrollTop
}
const syncRenderedRowHeights = async () => {
  await nextTick()
  const bodyRows = sheetBody.value?.querySelectorAll<HTMLTableRowElement>('tbody tr')
  const gutterRows = rowBar.value?.querySelectorAll<HTMLTableRowElement>('tbody tr')
  if (!bodyRows || !gutterRows) return
  bodyRows.forEach((row, index) => {
    const gutterRow = gutterRows[index]
    if (gutterRow) gutterRow.style.height = `${row.offsetHeight}px`
  })
  syncSheetScroll()
}
const formatKey = (row: number, column: number) => `${row}:${column}`
const selectedCells = () => {
  const rect = selectedRect.value
  if (!rect) return selectedCell.value ? [selectedCell.value] : []
  const cells: CellPosition[] = []
  for (let row = rect.r1; row <= rect.r2; row++) {
    for (let column = rect.c1; column <= rect.c2; column++) cells.push({ row, column })
  }
  return cells
}
const selectedColumns = () => {
  const rect = selectedRect.value
  if (!rect) return selectedCell.value ? [selectedCell.value.column] : []
  const columns = []
  for (let column = rect.c1; column <= rect.c2; column++) columns.push(column)
  return columns
}
