const isFclStructureLockedColumn = (column: number) => {
  if (String(opsParts.value?.mode || '').toUpperCase() !== 'FCL') return false
  const type = String(opsParts.value?.type || '').toUpperCase()
  const dept = String(opsParts.value?.dept || '').toUpperCase()
  const label = normalizedHeaderLabel(column)
  if (label === `${dept} OPS`) return false
  const flow = `${type}+`
  if (dept === 'GSD') return ['TIME', 'JOB NO#'].includes(label)
  if (dept === 'ECD') return ['TIME', 'BU', 'DEALT INFO', 'SALES', 'JOB NO#', 'ECD OPS', flow, type === 'EXW' ? 'EFA+' : flow, 'CLIENT', 'PICKUP DETAIL', 'TRUCK & CONT/SEAL INFO', 'TRUCKING INFO', 'BILL DETAIL', 'BILL RELEASE'].includes(label)
  if (dept === 'ICD') {
    const locked = ['TIME', 'BU', 'DEALT INFO', 'SALES', 'JOB NO#', 'ICD OPS', flow, 'CLIENT']
    if (type === 'DAP') locked.push('DELIVERY DETAIL', 'CONT/SEAL INFO')
    if (['DDU', 'DDP'].includes(type)) locked.push('DELIVERY DETAIL', 'PICKUP/RETURN STATUS', 'PICKUP STATUS')
    return locked.includes(label)
  }
  if (dept === 'TCD') {
    const locked = ['TIME', 'BU', 'DEALT INFO', 'SALES', 'JOB NO#', type === 'EXW' || type === 'FCA' ? 'ECD OPS' : 'ICD OPS', 'CLIENT', 'SHIPPER', 'CNEE', 'DESTINATION AGENT', 'DEST. AGENT', 'LINER', 'BC NO#', 'REF#', 'HBL NO#', 'MBL NO#', 'ETD', 'ETA', 'CUTOFF DETAIL', 'CUT OFF DETAIL', 'CUT OFF DETAILS', 'VOLUME', 'ROUTE', 'VESSEL/VOYAGE', 'ATD', 'ATA', 'DO VALIDITY']
    if (['DDU', 'DDP'].includes(type)) locked.push('CLEARANCE DETAIL')
