const updateSelectedFormatting = (property: string, value: string) => {
  const next = { ...formatting.value }
  selectedCells().forEach(({ row, column }) => {
    const key = formatKey(row, column)
    const format = { ...(next[key] || {}) }
    if (value === '') delete format[property]
    else format[property] = value
    next[key] = format
  })
  formatting.value = next
  scheduleSave()
}
const setAlign = (align: string) => {
  updateSelectedFormatting('align', align)
