const hasFormat = (key: string) => {
  const columns = selectedColumns()
  if (!columns.length) return false
  if (key === 'lock') return columns.every((column) => isLockedColumn(column))
  if (key === 'xfer') return columns.some((column) => xferColumn() === column)
  return columns.every((column) => columnFormatOf(column).kind === key)
}
const toggleFormat = (key: string) => {
  const columns = selectedColumns()
  if (!columns.length) return
  if (key === 'lock') {
    const next = lockedColumns()
    const shouldUnlock = columns.every((column) => next.has(column))
    columns.forEach((column) => shouldUnlock ? next.delete(column) : next.add(column))
    settings.value = { ...settings.value, lockedColumns: [...next].sort((a, b) => a - b) }
    scheduleSave()
    showToast(shouldUnlock ? 'Columns unlocked' : 'Columns locked')
    return
  }
  if (key === 'xfer') {
    const current = xferColumn()
    const nextColumn = columns[0]
    const nextFormats = columnFormats()
    if (current !== nextColumn) nextFormats[String(nextColumn)] = { kind: 'checkbox' }
    settings.value = { ...settings.value, columnFormats: nextFormats, xferColumn: current === nextColumn ? null : nextColumn }
    scheduleSave()
    showToast(current === nextColumn ? 'Next transfer removed' : `Next transfer set on ${columnLetter(nextColumn)}`)
    return
  }
  const nextFormats = columnFormats()
  const shouldClear = columns.every((column) => nextFormats[String(column)]?.kind === key)
  if (!shouldClear && key === 'dropdown') {
    openDropdownModal(columns)
    return
  }
  columns.forEach((column) => {
    if (shouldClear) delete nextFormats[String(column)]
    else nextFormats[String(column)] = {
      kind: key as ColumnFormatKind,
    }
  })
  settings.value = { ...settings.value, columnFormats: nextFormats }
  scheduleSave()
  showToast(shouldClear ? 'Column format removed' : `${key === 'checkbox' ? 'Checkbox' : 'Dropdown'} format applied`)
}
const openDropdownModal = async (columns: number[]) => {
