const applyDropdownModal = () => {
  const columns = dropdownModal.columns
  if (!columns.length) {
    closeDropdownModal()
    return
  }
  const options = dropdownModal.text.split(/[\n,]/).map((item) => item.trim()).filter(Boolean)
  const nextFormats = columnFormats()
  columns.forEach((column) => {
    nextFormats[String(column)] = { kind: 'dropdown', options }
  })
  settings.value = { ...settings.value, columnFormats: nextFormats }
  closeDropdownModal()
  scheduleSave()
