const cellInRange = (row: number, column: number) => {
  const rect = selectedRect.value
  return Boolean(rect && row >= rect.r1 && row <= rect.r2 && column >= rect.c1 && column <= rect.c2)
}
const mergeAt = (row: number, column: number) => merges.value.find((merge) => row >= merge[0] && row <= merge[2] && column >= merge[1] && column <= merge[3])
const isMergedCovered = (row: number, column: number) => {
  const merge = mergeAt(row, column)
  return Boolean(merge && (row !== merge[0] || column !== merge[1]))
}
const mergeSpan = (row: number, column: number) => {
  const merge = mergeAt(row, column)
  if (!merge || row !== merge[0] || column !== merge[1]) return { rows: 1, columns: 1 }
  return { rows: merge[2] - merge[0] + 1, columns: merge[3] - merge[1] + 1 }
}
const openColorPalette = (target: string, event: MouseEvent) => {
  const rect = (event.currentTarget as HTMLElement).getBoundingClientRect()
  colorPalette.target = target
  colorPalette.left = Math.max(8, Math.min(rect.left, window.innerWidth - 200))
  colorPalette.top = rect.bottom + 6
  colorPalette.open = true
}
const setSelectedColor = (color: string) => {
  updateSelectedFormatting(colorPalette.target, color)
  colorPalette.open = false
}
const mergeCells = () => {
  const rect = selectedRect.value
  if (!rect || !hasMergeableCellRange.value) return
  merges.value = merges.value.filter((merge) => !(merge[0] <= rect.r2 && merge[2] >= rect.r1 && merge[1] <= rect.c2 && merge[3] >= rect.c1))
  merges.value.push([rect.r1, rect.c1, rect.r2, rect.c2])
  scheduleSave()
  showToast('Cells merged')
}

const unmergeCells = () => {
  const rect = selectedRect.value
  if (!rect) return
  let changed = false
  merges.value = merges.value.filter(m => {
    if (m[0] <= rect.r2 && m[2] >= rect.r1 && m[1] <= rect.c2 && m[3] >= rect.c1) {
      changed = true
      return false
    }
    return true
  })
  if (changed) {
    scheduleSave()
    showToast('Cells unmerged')
  }
}
const formatHeaderLabel = (value: any) => {
  const label = String(value ?? '').replace(/\s+/g, ' ').trim()
  if (!label || label !== label.toUpperCase()) return label
  const keepUpper = new Set(['ID', 'ICD', 'ECD', 'TCD', 'CCD', 'DCD', 'FCD', 'OPS', 'HBL', 'MBL', 'BL', 'GP', 'HC'])
  return label
    .split(/(\s+|\/|-)/)
    .map((part) => {
      if (/^\s+$|^\/$|^-$/.test(part)) return part
      const suffix = part.match(/[#()+]+$/)?.[0] || ''
      const core = suffix ? part.slice(0, -suffix.length) : part
      if (!core) return part
      if (keepUpper.has(core)) return `${core}${suffix}`
      return `${core.charAt(0).toUpperCase()}${core.slice(1).toLowerCase()}${suffix}`
    })
    .join('')
}
const headerLabel = (column: number) => {
  const label = formatHeaderLabel(rows.value[0]?.[column])
  return label.toUpperCase() === 'BILL APPROVAL' ? 'BILL DETAIL' : label
}
