const isAirWorkflowPlainTextColumn = (column: number) => {
  if (!isLclSheet()) return false
  const type = String(opsParts.value?.type || '').toUpperCase()
  const dept = String(opsParts.value?.dept || '').toUpperCase()
  const label = normalizedHeaderLabel(column)
  if (['FCD'].includes(dept) && ['DO', 'DAP', 'DDU', 'DDP', 'DUP'].includes(type)) {
    return ['HBL NO#', 'ROUTE', 'VESSEL/VOYAGE'].includes(label)
  }
  if (dept === 'TCD' && ['DAP', 'DDU', 'DDP', 'DUP'].includes(type)) {
    return ['HBL NO#', 'ROUTE', 'VESSEL/VOYAGE'].includes(label)
  }
  if (dept === 'CCD' && ['DDU', 'DDP', 'DUP'].includes(type)) {
    return ['HBL NO#', 'ROUTE', 'VESSEL/VOYAGE'].includes(label)
  }
  if (type === 'FCF' && dept === 'DCD') {
    // Mockup `3. FCF DCD.html`: HBL NO# is an interactive chip, not plain text
    return ['ROUTE', 'VESSEL/VOYAGE'].includes(label)
  }
  if (type === 'FCF' && dept === 'FCD') {
    return ['HBL NO#', 'ROUTE', 'VESSEL/VOYAGE'].includes(label)
  }
  return false
}
// Mockups `4. FCA DCD.html` / `3. FCF DCD.html` (AIR): party cells + HBL NO# are interactive chips, not plain text
const airDcdInteractiveLabels = new Set(['HBL NO#', 'SHIPPER', 'CNEE', 'ORIGINAL AGENT', 'DESTINATION AGENT', 'LINER'])
const isExwCcdPlainTextColumn = (column: number) => {
  const label = normalizedHeaderLabel(column)
  if (opsParts.value?.type === 'EXW' && opsParts.value?.mode === 'FCL' && opsDeptUpper() === 'DCD' && ['HBL NO#', 'MBL NO#'].includes(label)) return false
  // AIR DO ICD mockup renders PICKUP STATUS as an ADD+/DETAIL action cell.
  if (isAirSheet() && isDoIcdSheet() && label === 'PICKUP STATUS') return false
  // AIR/LCL mockups: HBL NO# is an interactive chip everywhere except the read-only
  // DAP/DUP TCD & DUP CCD views handled by isAirWorkflowPlainTextColumn
  if (isLclSheet() && label === 'HBL NO#') return isAirWorkflowPlainTextColumn(column)
  // AIR/LCL mockups: party cells are interactive chips on every sheet except EXW/FCA TCD
  if (isLclSheet() && ['SHIPPER', 'CNEE', 'ORIGINAL AGENT', 'DESTINATION AGENT', 'LINER'].includes(label)) {
    return (isExwTcdSheet() || isFcaTcdSheet()) && ['SHIPPER', 'CNEE', 'LINER'].includes(label)
  }
  // Downstream FCD volume cells use the read-only Volume modal instead of a plain text cell.
  if (isLclSheet() && (isExwFcdSheet() || isFcfFcdSheet()) && label === 'VOLUME') return false
  return (
  isAirWorkflowPlainTextColumn(column) ||
  (isExwCcdSheet() && exwCcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  (isExwTcdSheet() && exwTcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  (isExwDcdSheet() && exwDcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  (isExwFcdSheet() && exwFcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  (isFcaTcdSheet() && fcaTcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  (isFcaDcdSheet() && fcaDcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  (isFcaFcdSheet() && fcaFcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  (isFcfEcdSheet() && fcfWorkDeptPlainTextLabels.has(normalizedHeaderLabel(column))) ||
  ((isFcfDcdSheet() || isFcfFcdSheet()) && fcfDcdFcdPlainTextLabels.has(normalizedHeaderLabel(column))) ||
