const defaultDropdownOptionsFor = (column: number) => {
  const label = normalizedHeaderLabel(column)
  if (isExwCcdPlainTextColumn(column)) return []
  if ((isExwEcdSheet() || isFcaEcdSheet() || isFcfEcdSheet()) && ['BU', 'SALES', 'OPS'].includes(label)) return []
  const staffDepartment = label.match(/^(GSD|ECD|ICD|CCD|TCD|DCD|FCD) OPS$/)?.[1]
    || (label === 'GSD' && opsDeptUpper() === 'GSD' ? 'GSD' : '')
    || (['OPS', 'OPS1', 'OPS2'].includes(label) ? opsDeptUpper() : '')
  const departmentStaff = staffDepartment ? (opsStaffByDepartment.value[staffDepartment] || []) : []
  if (isOpsStaffColumn(column)) return ['', ...departmentStaff]
  if (['BU', 'BRANCH'].includes(label)) return ['HCM', 'HPH', 'HAN', 'DAD']
  if (label === 'SALES') return ['', ...opsStaffNames.value]
  if (['OPS', 'OPS1', 'OPS2'].includes(label) || /^(GSD|ECD|ICD|TCD|CCD|DCD|FCD) OPS$/.test(label)) return ['', ...departmentStaff]
  if (label === 'TERM') return ['FCL', 'LCL', 'AIR']
  if (['EFA+', 'EXW+', 'FCA+', 'FCF+'].includes(label)) return ['', 'DO', 'DAP', 'DDU', 'DDP']
  if (isLclSheet() && ['DO+', 'DUP+'].includes(label)) return ['', 'DAP', 'DDU']
  if (['DO+', 'DAP+', 'DDU+', 'DDP+', 'DUP+'].includes(label)) return ['', 'EXW', 'FCA', 'FCF']
  if (label === 'TYPE') return ['EXW', 'FCA', 'FOB', 'CIF', 'D/O', 'DUP', 'DAP', 'DDP']
  if (label.includes('FREETIME TYPE')) return ['COMBINED', 'DETENTION', 'DEMURRAGE']
  if (label.includes('CONFIRMATION') || label.includes('APPROVAL') || label.includes('READINESS') || label.includes('RELEASE') || label === 'DONE') return ['PENDING', 'DONE', 'N/A']
  if (label.includes('LINER') || label.includes('CARRIER')) return ['MAERSK', 'ONE', 'HMM', 'CMA CGM', 'MSC']
  if (label.includes('AGENT')) return ['DIRECT', 'OVERSEAS AGENT', 'LOCAL AGENT']
  return []
}
