    ? columnFormatOf(column).kind === 'dropdown' || isOpsStaffColumn(column) || defaultDropdownOptionsFor(column).length > 0
    : !isExwCcdPlainTextColumn(column) && (columnFormatOf(column).kind === 'dropdown' || isOpsDropdownColumn(column))
)
const normalizeDropdownOption = (value: any) => {
  const option = String(value ?? '').trim()
  return !option || /^[-–—]+$/.test(option) ? '' : option
}
const uniqueDropdownOptions = (values: any[], includeBlank = false) => {
  const result: string[] = []
  const seen = new Set<string>()
  let hasBlank = includeBlank
  for (const value of values) {
    const option = normalizeDropdownOption(value)
    if (!option) {
      hasBlank = true
      continue
    }
    const key = option.toLocaleUpperCase()
    if (seen.has(key)) continue
    seen.add(key)
    result.push(option)
  }
  return hasBlank ? ['', ...result] : result
}
const dropdownOptions = (column: number) => {
  const formatOptions = Array.isArray(columnFormatOf(column).options) ? columnFormatOf(column).options as string[] : []
  const stored = settings.value.dropdownOptions || {}
  const storedOptions = stored[opsColumnOptionKey(column)] || stored[String(column)]
  const options = Array.isArray(storedOptions)
    ? storedOptions
    : formatOptions.length ? formatOptions : defaultDropdownOptionsFor(column)
  return uniqueDropdownOptions(options, isOpsStaffColumn(column))
}
const opsNativeDropdownValue = (row: number, column: number) => normalizeDropdownOption(rows.value[row]?.[column])
const opsNativeDropdownOptions = (row: number, column: number) => {
  const options = dropdownOptions(column)
  const current = opsNativeDropdownValue(row, column)
  return uniqueDropdownOptions(
    options.some((option) => option.toLocaleUpperCase() === current.toLocaleUpperCase()) ? options : [current, ...options],
    !current,
  )
}
