  if (['SHIPPER', 'CNEE', 'ORIGIN AGENT', 'ORIGINAL AGENT', 'DESTINATION AGENT', 'DEST. AGENT', 'LINER'].includes(label)) return true
  if (isExwCcdPlainTextColumn(column)) return false
