const recoverLinkedNoticeInbox = async (row: number, column: number) => {
  const current = opsParts.value
  if (!current || current.dept === 'GSD' || row < 1) return [] as ReminderNote[]
  const currentHeader = (rows.value[0] || []).map((value) => String(value ?? '').trim())
  const currentRow = rows.value[row] || []
  const shipmentLink = opsShipmentLink(currentHeader, currentRow, row, settings.value)
  if (!shipmentLink) return [] as ReminderNote[]
  try {
    const sourceKey = opsLeafKey(current.base, current.mode, current.type, 'GSD')
    const sourceSheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(sourceKey))}`)
