    const sourceSettings = extracted.settings || sourceSheet?.settings || {}
    const sourceLinks = sourceSettings.opsRowLinks && typeof sourceSettings.opsRowLinks === 'object' ? sourceSettings.opsRowLinks : {}
    const sourceRowIndex = sourceRows.findIndex((_item, index) => index > 0 && String(sourceLinks[String(index)] || '').trim() === shipmentLink)
    if (sourceRowIndex < 1) return [] as ReminderNote[]
    const noticeColumn = sourceHeader.findIndex((label) => ['NOTICE', 'REMINDER'].includes(upperText(label)))
    const sourceNotice = noticeColumn >= 0 ? parseJsonCell(sourceRows[sourceRowIndex]?.[noticeColumn], null as any) : null
    const targetDept = upperText(current.dept)
    const notes = sourceNotice && Array.isArray(sourceNotice.notes) ? sourceNotice.notes.filter((note: any) => {
      const dept = upperText(note?.dept)
      return dept === targetDept || dept === `O${targetDept}` || dept === `D${targetDept}`
    }) : []
    if (!notes.length) return [] as ReminderNote[]
    const recovered = notes.map((note: any) => ({
      ...note,
      dept: 'GSD',
      sourceType: upperText(current.type),
      read: false,
      changeType: 'new' as const,
    }))
    const local = parseJsonCell(rows.value[row]?.[column], null as any)
    const localNotes = local && Array.isArray(local.notes) ? local.notes : []
    const localInbox = local && Array.isArray(local.inbox) ? local.inbox : []
    const merged = [...localInbox]
    recovered.forEach((note: ReminderNote) => {
      const index = merged.findIndex((item: any) => String(item?.id || '') === note.id)
      if (index >= 0) merged[index] = note
      else merged.push(note)
    })
    rows.value[row][column] = JSON.stringify({ notes: localNotes, inbox: merged })
    await saveSheet()
    return recovered
  } catch (error) {
    console.warn('Could not recover linked NOTICE from GSD', error)
    return [] as ReminderNote[]
  }
}
