const paymentStamp = () => {
  const date = new Date()
  const part = (value: number) => String(value).padStart(2, '0')
  return `${date.getFullYear()}-${part(date.getMonth() + 1)}-${part(date.getDate())} ${part(date.getHours())}:${part(date.getMinutes())}:${part(date.getSeconds())}`
}
const normalizePaymentDocuments = (value: any): PaymentDocument[] => {
  const first = Array.isArray(value) ? value[0] : value
  if (!first) return []
  if (typeof first === 'string') return [{ name: first, url: '' }]
  const name = String(first?.name || first?.file || '').trim()
  const url = String(first?.url || first?.dataUrl || '').trim()
  return name || url ? [{ name: name || 'Attachment', url, type: String(first?.type || '') }] : []
}
const normalizePaymentLine = (line: any): PaymentLine => ({
  ...newPaymentLine(),
  id: String(line?.id || `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`),
  selected: !!line?.selected,
