  ednNo: String(line?.ednNo || line?.eDnNo || line?.edn || ''),
  ednDate: String(line?.ednDate || line?.eDnDate || ''),
  idnNo: String(line?.idnNo || line?.iDnNo || line?.idn || ''),
  idnDate: String(line?.idnDate || line?.iDnDate || ''),
  einvNo: String(line?.einvNo || line?.eInvoiceNo || line?.einv || ''),
  einvDate: String(line?.einvDate || line?.eInvoiceDate || ''),
  iinvNo: String(line?.iinvNo || line?.iInvoiceNo || line?.iinv || ''),
  iinvDate: String(line?.iinvDate || line?.iInvoiceDate || ''),
