const paymentLineHasData = (line: PaymentLine) =>
  ['chargeName', 'payTo', 'payAt', 'curPay', 'totalPay', 'collectFrom', 'collectAt', 'curCollect', 'totalCollect', 'noteToFcd', 'sentAt', 'approvedAt', 'status', 'reason', 'lastFeedback', 'statusDetails', 'ednNo', 'ednDate', 'idnNo', 'idnDate', 'einvNo', 'einvDate', 'iinvNo', 'iinvDate'].some((key) => String((line as any)[key] || '').trim()) ||
  line.ready || line.docsPay.length > 0 || line.docsCollect.length > 0 || line.docsInvoice.length > 0
const paymentRequestFromCell = (value: any): PaymentRequestState => {
  const parsed = parseJsonCell(value, null as any)
  if (parsed && typeof parsed === 'object' && 'payment' in parsed) {
    const payment = (parsed as any).payment || {}
    return {
      jobNo: String(payment.jobNo || payment.job || ''),
      refNo: String(payment.refNo || payment.ref || ''),
      refLastBiz: String(payment.refLastBiz || ''),
      issueFrom: String(payment.issueFrom || ''),
      issueBank: String(payment.issueBank || ''),
      lines: Array.isArray(payment.lines) ? payment.lines.map(normalizePaymentLine) : [],
    }
  }
  if (parsed && typeof parsed === 'object' && 'form' in parsed) {
    const form = (parsed as any).form || {}
    if (Array.isArray(form.lines)) {
      return {
        jobNo: String(form.jobNo || form.job || ''),
        refNo: String(form.refNo || form.ref || ''),
        refLastBiz: String(form.refLastBiz || ''),
        issueFrom: String(form.issueFrom || ''),
        issueBank: String(form.issueBank || ''),
        lines: form.lines.map(normalizePaymentLine),
      }
    }
    const line = normalizePaymentLine({
      chargeName: form.chargeName || form.item,
      payTo: form.payTo,
      payAt: form.payAt,
      curPay: form.curPay || form.currency,
      totalPay: form.totalPay || form.amount,
      collectFrom: form.collectFrom,
      collectAt: form.collectAt,
      curCollect: form.curCollect,
      totalCollect: form.totalCollect,
      noteToFcd: form.noteToFcd || form.remarks,
      ready: form.debitReady,
    })
    return {
      jobNo: String(form.jobNo || ''),
      refNo: String(form.refNo || ''),
      refLastBiz: String(form.refLastBiz || ''),
      issueFrom: String(form.issueFrom || ''),
      issueBank: String(form.issueBank || ''),
      lines: paymentLineHasData(line) ? [line] : [],
    }
  }
  return emptyPaymentRequest()
}
const recoverLinkedPaymentRequestForFcd = async (row: number, currentValue: any) => {
  const current = opsParts.value
  if (!current || opsDeptUpper() !== 'FCD' || row < 1) return currentValue
  const local = paymentRequestFromCell(currentValue)
  const currentHeader = (rows.value[0] || []).map((value: any) => String(value ?? '').trim())
  const currentRow = rows.value[row] || []
  const shipmentLink = opsShipmentLink(currentHeader, currentRow, row, settings.value)
  const identity = rowIdentity(currentHeader, currentRow)
  const recovered: PaymentRequestState[] = []
  for (const dept of fclStructureSyncPeers('PAYMENT REQUEST')) {
    try {
      const key = opsLeafKey(current.base, current.mode, current.type, dept)
      const sheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(key))}`)
      const header = opsHeaderFor(current.base, current.mode, dept, current.type)
      const extracted = extractWorkbookRows(Array.isArray(sheet?.rows) ? sheet.rows.map((item: any[]) => [...item]) : [], sheet)
      const alignedRows = alignRowsToHeader(extracted.rows, header).rows
      const sourceSettings = extracted.settings || sheet?.settings || {}
      let sourceRowIndex = shipmentLink
        ? alignedRows.findIndex((item, index) => index > 0 && opsShipmentLink(header, item, index, sourceSettings) === shipmentLink)
        : -1
      if (sourceRowIndex < 1 && identity) sourceRowIndex = alignedRows.findIndex((item, index) => index > 0 && rowIdentity(header, item) === identity)
      // Compatibility with old generated rows that predate opsRowLinks.
      if (sourceRowIndex < 1 && row < alignedRows.length) sourceRowIndex = row
      const paymentColumn = header.findIndex((label) => ['PAYMENT REQUEST', 'PAYMENT REQUEST APPLICATION'].includes(upperText(label)))
      if (sourceRowIndex < 1 || paymentColumn < 0) continue
      const payment = paymentRequestFromCell(alignedRows[sourceRowIndex]?.[paymentColumn])
      if (payment.lines.length || payment.jobNo || payment.refNo || payment.issueFrom || payment.issueBank) recovered.push(payment)
    } catch (error: any) {
      if (requestStatus(error) !== 404) console.warn(`Could not recover Payment Request from ${dept}`, error)
    }
  }
  if (!recovered.length) return currentValue
  const sources = [...recovered, local]
  const mergedLines = new Map<string, PaymentLine>()
  sources.forEach((payment) => payment.lines.forEach((line, index) => {
    const key = String(line.id || `${line.chargeName}:${line.payTo}:${line.collectFrom}:${index}`)
    const incoming = normalizePaymentLine(line)
    const existing = mergedLines.get(key)
    // The same request line can exist in several departments. Always retain
    // the copy with the newest Send Request timestamp instead of allowing a
    // stale local FCD copy to overwrite the newly-sent values merely because
    // it was processed last.
    const incomingStamp = String(incoming.sentAt || incoming.reqDate || '')
    const existingStamp = String(existing?.sentAt || existing?.reqDate || '')
    if (!existing || incomingStamp > existingStamp || (incomingStamp === existingStamp && !existing.statusDetails && !!incoming.statusDetails)) {
      mergedLines.set(key, incoming)
    }
  }))
  const latest = (field: keyof PaymentRequestState) => {
    for (let index = sources.length - 1; index >= 0; index -= 1) {
      const value = sources[index]?.[field]
      if (typeof value === 'string' && value.trim()) return value
    }
    return ''
  }
  return JSON.stringify({ payment: {
    jobNo: latest('jobNo') || rowValueByHeader('JOB NO#'),
    refNo: latest('refNo') || rowValueByHeader('REF NO#') || rowValueByHeader('REF#'),
    refLastBiz: latest('refLastBiz'),
    issueFrom: latest('issueFrom'),
    issueBank: latest('issueBank'),
    lines: Array.from(mergedLines.values()).map((line) => ({ ...line, selected: false })),
  } })
}
const paymentPayload = () => ({
  jobNo: gsdModal.payment.jobNo,
  refNo: gsdModal.payment.refNo,
  refLastBiz: gsdModal.payment.refLastBiz,
  issueFrom: gsdModal.payment.issueFrom,
  issueBank: gsdModal.payment.issueBank,
  lines: gsdModal.payment.lines.map((line) => ({
    ...line,
    selected: false,
  })),
})
type FclStructureDept = 'GSD' | 'ECD' | 'ICD' | 'TCD' | 'CCD' | 'DCD' | 'FCD'
const fclStructureSyncPeers = (label: string): FclStructureDept[] => {
  if (!['FCL', 'LCL', 'AIR'].includes(String(opsParts.value?.mode || '').toUpperCase())) return []
  const type = String(opsParts.value?.type || '').toUpperCase()
  const dept = opsDeptUpper()
  const groups: Record<string, string[]> = {
    'EXW:PAYMENT REQUEST': ['ECD', 'CCD', 'TCD', 'DCD', 'FCD'],
    'FCA:PAYMENT REQUEST': ['ECD', 'TCD', 'DCD', 'FCD'],
    'FCF:PAYMENT REQUEST': ['ECD', 'DCD', 'FCD'],
    'DO:PAYMENT REQUEST': ['ICD', 'FCD'],
    'DAP:PAYMENT REQUEST': ['ICD', 'TCD', 'FCD'],
    'DDU:PAYMENT REQUEST': ['ICD', 'CCD', 'TCD', 'FCD'],
    'DDP:PAYMENT REQUEST': ['ICD', 'CCD', 'TCD', 'FCD'],
    'EXW:EXTRA SERVICE': ['GSD', 'ECD'],
    'FCA:EXTRA SERVICE': ['GSD', 'ECD'],
    'FCF:EXTRA SERVICE': ['GSD', 'ECD'],
    'DO:EXTRA SERVICE': ['GSD', 'ICD'],
    'DAP:EXTRA SERVICE': ['GSD', 'ICD'],
    'DDU:EXTRA SERVICE': ['GSD', 'ICD'],
    'DDP:EXTRA SERVICE': ['GSD', 'ICD'],
    'DDU:PRE-ALERT CONFIRMATION': ['ICD', 'CCD'],
    'DDP:PRE-ALERT CONFIRMATION': ['ICD', 'CCD'],
    'EXW:BILL DETAIL': ['ECD', 'DCD'],
    'FCA:BILL DETAIL': ['ECD', 'DCD'],
    'FCF:BILL DETAIL': ['ECD', 'DCD'],
    'EXW:AWB DETAIL': ['ECD', 'DCD'],
    'FCA:AWB DETAIL': ['ECD', 'DCD'],
    'FCF:AWB DETAIL': ['ECD', 'DCD'],
    'EXW:DEALT INFO': ['ECD', 'TCD', 'CCD', 'DCD', 'FCD'],
    'FCA:DEALT INFO': ['ECD'],
    'FCF:DEALT INFO': ['ECD'],
    'DO:DEALT INFO': ['ICD'],
    'DAP:DEALT INFO': ['ICD'],
    'DDU:DEALT INFO': ['ICD'],
    'DDP:DEALT INFO': ['ICD'],
  }
  const peers = groups[`${type}:${label}`] || []
  if (String(opsParts.value?.mode || '').toUpperCase() === 'AIR' && type === 'FCA' && label === 'PAYMENT REQUEST') {
    return peers.filter((peer) => peer !== dept && ['ECD', 'TCD', 'DCD', 'FCD'].includes(peer)) as FclStructureDept[]
  }
  if (String(opsParts.value?.mode || '').toUpperCase() === 'AIR' && type === 'FCF' && label === 'PAYMENT REQUEST') {
    return peers.filter((peer) => peer !== dept && ['ECD', 'DCD', 'FCD'].includes(peer)) as FclStructureDept[]
  }
  if (String(opsParts.value?.mode || '').toUpperCase() === 'AIR' && ['DDU', 'DDP'].includes(type) && label === 'PAYMENT REQUEST') {
    return peers.filter((peer) => peer !== dept && ['ICD', 'CCD', 'TCD', 'FCD'].includes(peer)) as FclStructureDept[]
  }
  return peers.filter((peer) => peer !== dept) as FclStructureDept[]
}
const persistPaymentRequest = async (immediate = false) => {
  if (!rows.value[gsdModal.row]) return
  const payload = paymentPayload()
  const hasData = String(payload.jobNo || payload.refNo || payload.issueFrom || payload.issueBank || '').trim() || payload.lines.some((line) => paymentLineHasData(line as PaymentLine))
  rows.value[gsdModal.row][gsdModal.column] = hasData ? JSON.stringify({ payment: payload }) : ''
  scheduleSave()
  if (immediate) {
    await saveSheet()
    await Promise.all(fclStructureSyncPeers('PAYMENT REQUEST').map((dept) => mirrorExwFclWorkflowCell(dept, 'PAYMENT REQUEST', rows.value[gsdModal.row][gsdModal.column])))
  }
}
const paymentInvalidKey = (line: PaymentLine, field: keyof PaymentLine) => `${line.id}:${String(field)}`
const paymentFieldInvalid = (line: PaymentLine, field: keyof PaymentLine) => paymentInvalidFields.value.has(paymentInvalidKey(line, field))
const clearPaymentInvalid = (line: PaymentLine, field: keyof PaymentLine) => {
  const next = new Set(paymentInvalidFields.value)
  next.delete(paymentInvalidKey(line, field))
  paymentInvalidFields.value = next
}
const handlePaymentTextInput = (line: PaymentLine, field: keyof PaymentLine) => {
  clearPaymentInvalid(line, field)
  persistPaymentRequest()
}
const validatePaymentCharge = (line: PaymentLine) => {
  const matched = optionMatch(paymentChargeOptions.value, line.chargeName)
  if (!matched) {
    line.chargeName = ''
    paymentInvalidFields.value = new Set([...paymentInvalidFields.value, paymentInvalidKey(line, 'chargeName')])
    persistPaymentRequest()
    showToast('Select Charge name from Reference Data / Charges')
    return
  }
  line.chargeName = matched
  clearPaymentInvalid(line, 'chargeName')
  persistPaymentRequest()
}
const validatePaymentReference = (line: PaymentLine, field: keyof PaymentLine, options: string[], label: string) => {
  const matched = optionMatch(options, line[field])
  if (!matched) {
    ;(line as any)[field] = ''
    paymentInvalidFields.value = new Set([...paymentInvalidFields.value, paymentInvalidKey(line, field)])
    persistPaymentRequest()
    showToast(`Select ${label} from Reference Data`)
    return
  }
  ;(line as any)[field] = matched
  clearPaymentInvalid(line, field)
  persistPaymentRequest()
}
