const issuePaymentNote = (kind: 'DEBIT' | 'CREDIT') => {
  const selected = selectedPaymentLines()
  if (!selected.length) {
    showToast('Select row(s) first')
    return
  }
  if (!selected.every((line) => upperText(line.status) === 'APPROVED')) {
    showToast('Only Approved row(s) can be exported')
    return
  }
  const sameParty = paymentLinesShareField(selected, kind === 'DEBIT' ? 'collectFrom' : 'payTo')
  const sameCurrency = paymentLinesShareField(selected, kind === 'DEBIT' ? 'curCollect' : 'curPay')
  if (!sameParty || !sameCurrency) {
    showToast(kind === 'DEBIT'
      ? 'Selected lines must share the same Collect from and the same currency.'
      : 'Selected lines must share the same Pay to and the same currency.')
    return
  }
  openPaymentNoteModal(kind, selected.map((line) => ({
    charge: line.chargeName,
    party: kind === 'DEBIT' ? line.collectFrom : line.payTo,
    currency: kind === 'DEBIT' ? line.curCollect : line.curPay,
    amount: kind === 'DEBIT' ? line.totalCollect : line.totalPay,
  })), gsdModal.payment.issueFrom, gsdModal.payment.issueBank)
}
