const sanitizeMoneyInput = (value: any) => {
  const source = String(value ?? '').trim()
  if (!source) return ''
  const negative = source.startsWith('-')
  const cleaned = source.replace(/[^0-9.,]/g, '')
  const separator = Math.max(cleaned.lastIndexOf('.'), cleaned.lastIndexOf(','))
  const whole = (separator >= 0 ? cleaned.slice(0, separator) : cleaned).replace(/[.,]/g, '') || '0'
  const decimals = separator >= 0 ? cleaned.slice(separator + 1).replace(/[^0-9]/g, '').slice(0, 2) : ''
  const hasSeparator = separator >= 0
  return `${negative ? '-' : ''}${whole}${hasSeparator ? `.${decimals}` : ''}`
}
const formatMoneyValue = (value: any) => {
  const clean = sanitizeMoneyInput(value)
  if (!clean || clean === '-') return ''
  const number = Number(clean)
  return Number.isFinite(number) ? number.toFixed(2) : ''
}
const sanitizePaymentAmount = (line: PaymentLine, key: 'totalPay' | 'totalCollect') => {
  clearPaymentInvalid(line, key)
  line[key] = sanitizeMoneyInput(line[key])
  persistPaymentRequest()
}
const formatPaymentAmount = (line: PaymentLine, key: 'totalPay' | 'totalCollect') => {
  line[key] = formatMoneyValue(line[key])
  persistPaymentRequest()
}
const upperPaymentField = (line: PaymentLine, key: 'curPay' | 'curCollect' | 'ednNo' | 'idnNo' | 'einvNo' | 'iinvNo') => {
  clearPaymentInvalid(line, key)
  line[key] = String(line[key] || '').toUpperCase()
  persistPaymentRequest()
}
// Debit/Invoice references are completed by FCD in Payment Approval and are
// mirrored back here as feedback. Requesting departments only view them.
const paymentDnFieldLocked = (line: PaymentLine, _key: 'ednNo' | 'ednDate' | 'idnNo' | 'idnDate' | 'einvNo' | 'einvDate' | 'iinvNo' | 'iinvDate') => paymentLineLocked(line)
