const paymentDoc = (line: PaymentLine, side: PaymentDocSide) => {
  const attachment = (side === 'pay' ? line.docsPay : side === 'collect' ? line.docsCollect : line.docsInvoice)[0]
  return attachment?.url ? attachment : null
}
const viewPaymentDoc = (line: PaymentLine, side: PaymentDocSide) => {
  const attachment = paymentDoc(line, side)
  if (!attachment?.url) {
    showToast('This legacy attachment has no saved file content. Please upload it again.')
    return
  }
  if (attachment.url.startsWith('/attachments/')) {
    void viewAdminAttachment(attachment.url)
    return
  }
  try {
    let viewUrl = attachment.url
    let shouldRevoke = false
    if (viewUrl.startsWith('data:')) {
      const separator = viewUrl.indexOf(',')
      if (separator < 0) throw new Error('Invalid attachment data')
      const header = viewUrl.slice(5, separator)
      const encoded = viewUrl.slice(separator + 1)
      const isBase64 = header.includes(';base64')
      const mimeType = header.split(';')[0] || attachment.type || 'application/octet-stream'
      const binary = isBase64 ? atob(encoded) : decodeURIComponent(encoded)
      const bytes = new Uint8Array(binary.length)
      for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index)
      viewUrl = URL.createObjectURL(new Blob([bytes], { type: mimeType }))
      shouldRevoke = true
    }
    const opened = window.open(viewUrl, '_blank')
    if (!opened) {
      if (shouldRevoke) URL.revokeObjectURL(viewUrl)
      showToast('Browser blocked the file viewer. Please allow pop-ups and try again.')
      return
    }
    if (shouldRevoke) window.setTimeout(() => URL.revokeObjectURL(viewUrl), 60_000)
  } catch {
    showToast('Could not open this file. Please remove it and upload again.')
  }
}
const removePaymentDoc = (line: PaymentLine, side: PaymentDocSide) => {
  if (paymentLineLocked(line)) return
  if (side === 'pay') line.docsPay = []
  else if (side === 'collect') line.docsCollect = []
  else line.docsInvoice = []
  persistPaymentRequest(true)
}
const uploadPaymentDocs = (index: number, side: PaymentDocSide) => {
  const line = gsdModal.payment.lines[index]
  if (!line || paymentLineLocked(line)) return
  const input = document.createElement('input')
  input.type = 'file'
  input.multiple = false
  input.onchange = async () => {
    const file = input.files?.[0]
    if (!file) return
    try {
      dispatchLoading.value = `Uploading ${file.name}...`
      const uploaded = await uploadAdminAttachment(file)
      const attachment: PaymentDocument = { name: uploaded.name, url: uploaded.url, type: uploaded.type }
      if (side === 'pay') line.docsPay = [attachment]
      else if (side === 'collect') line.docsCollect = [attachment]
      else line.docsInvoice = [attachment]
      persistPaymentRequest()
    } catch (error: any) {
      showToast(String(error?.data?.message || error?.message || 'Could not upload the attachment'))
    } finally {
      dispatchLoading.value = ''
    }
  }
  input.click()
}
const sendPaymentRequest = async () => {
  const selected = gsdModal.payment.lines.filter((line) => line.selected)
  const target = selected.filter((line) => !line.sentAt || line.editing)
  if (!target.length) {
    showToast(selected.length ? 'Selected rows were already sent. Click Edit before sending an update.' : 'Select row(s) first')
    return
  }
  const required: Array<keyof PaymentLine> = ['chargeName', 'payTo', 'payAt', 'curPay', 'totalPay', 'collectFrom', 'collectAt', 'curCollect', 'totalCollect']
  const invalid = new Set<string>()
  target.forEach((line) => {
    required.forEach((key) => {
      if (!String(line[key] || '').trim()) invalid.add(paymentInvalidKey(line, key))
    })
    if (!optionMatch(paymentChargeOptions.value, line.chargeName)) invalid.add(paymentInvalidKey(line, 'chargeName'))
    if (line.payAt && !optionMatch(paymentCountries.value, line.payAt)) invalid.add(paymentInvalidKey(line, 'payAt'))
    if (line.collectAt && !optionMatch(paymentCountries.value, line.collectAt)) invalid.add(paymentInvalidKey(line, 'collectAt'))
    if (!optionMatch(paymentCurrencies.value, line.curPay)) invalid.add(paymentInvalidKey(line, 'curPay'))
    if (!optionMatch(paymentCurrencies.value, line.curCollect)) invalid.add(paymentInvalidKey(line, 'curCollect'))
  })
  paymentInvalidFields.value = invalid
  if (invalid.size) {
    showToast('Fix the highlighted fields')
    nextTick(() => document.querySelector<HTMLInputElement>('.gsd-payment-modal .pcell.invalid')?.focus())
    return
  }
  const ok = await askConfirm('Are you sure to send request?', '', { okText: 'YES', cancelText: 'NO', tone: 'remove' })
  if (!ok) return
  const stamp = paymentStamp()
  const targetIds = new Set(target.map((line) => line.id))
  target.forEach((line) => {
    formatPaymentAmount(line, 'totalPay')
    formatPaymentAmount(line, 'totalCollect')
  })
  gsdModal.payment.lines = gsdModal.payment.lines.map((line) => targetIds.has(line.id)
    ? {
        ...line,
        lastFeedback: [line.status, line.reason].filter((value) => String(value || '').trim()).join(' - ') || line.lastFeedback,
        sentAt: stamp,
        sender: opsDeptUpper(),
        reqDate: stamp,
        approvedAt: '',
        status: '',
        reason: '',
        statusDetails: '',
        requestUnread: true,
        feedbackUnread: false,
        editing: false,
        selected: false,
      }
    : line)
  await nextTick()
  await persistPaymentRequest(true)
}
