const bcFrame = ref<HTMLIFrameElement | null>(null)
const BC_ADD_BTN_MAP: Record<string, string> = { seaVVBody: 'seaVVAdd', airFlBody: 'airFlAdd', seaDimBody: 'seaDimAdd', airDimBody: 'airDimAdd' }
const bcSerialize = () => {
  const d = bcFrame.value?.contentDocument as Document | undefined
  if (!d) return null
  const onTab = d.querySelector('.tab.on')
  const data: any = { tab: onTab ? onTab.getAttribute('data-t') : 'sea', company: (d.getElementById('coSel') as any)?.value ?? '', fields: {}, editable: {}, rows: {} }
  d.querySelectorAll('.sheet input[id],.sheet select[id],.sheet textarea[id]').forEach((el: any) => { data.fields[el.id] = el.value })
  d.querySelectorAll('.sheet [contenteditable][id]').forEach((el: any) => { data.editable[el.id] = el.classList.contains('ph-active') ? '' : el.textContent })
  Object.keys(BC_ADD_BTN_MAP).forEach((bid) => {
    const body = d.getElementById(bid)
    if (!body) return
    data.rows[bid] = Array.from(body.querySelectorAll('tr')).map((tr) => Array.from(tr.querySelectorAll('input,select')).map((inp: any) => inp.value))
  })
  return data
}
const bcDeserialize = (data: any) => {
  if (!data) return
  const d = bcFrame.value?.contentDocument as Document | undefined
  const w = bcFrame.value?.contentWindow as any
  if (!d || !w) return
  if (data.company) {
    const cs = d.getElementById('coSel') as any
    if (cs) { cs.value = data.company; cs.dispatchEvent(new w.Event('change', { bubbles: true })) }
  }
  if (data.tab) {
    const tb = d.querySelector('[data-t="' + data.tab + '"]') as any
    if (tb) tb.click()
  }
  Object.keys(data.rows || {}).forEach((bid) => {
    const body = d.getElementById(bid)
    if (!body) return
    const want = data.rows[bid].length
    const addBtn = d.getElementById(BC_ADD_BTN_MAP[bid]) as any
    while (body.querySelectorAll('tr').length < want && addBtn) addBtn.click()
    while (body.querySelectorAll('tr').length > want) {
      const last = body.querySelector('tr:last-child')
      if (!last) break
      last.parentNode?.removeChild(last)
    }
    const trs = body.querySelectorAll('tr')
    data.rows[bid].forEach((vals: any[], ri: number) => {
      const tr = trs[ri]
      if (!tr) return
      const inps = tr.querySelectorAll('input,select')
      vals.forEach((v, ci) => {
        const inp = inps[ci] as any
        if (inp) { inp.value = v; inp.dispatchEvent(new w.Event('input', { bubbles: true })); inp.dispatchEvent(new w.Event('change', { bubbles: true })) }
      })
    })
  })
  Object.keys(data.fields || {}).forEach((id) => {
    const el = d.getElementById(id) as any
    if (!el) return
    el.value = data.fields[id]
    el.dispatchEvent(new w.Event('input', { bubbles: true }))
    el.dispatchEvent(new w.Event('change', { bubbles: true }))
  })
  Object.keys(data.editable || {}).forEach((id) => {
    const el = d.getElementById(id) as any
    if (!el) return
    if (data.editable[id]) { el.textContent = data.editable[id]; el.classList.remove('ph-active') }
    else { el.textContent = el.getAttribute('data-ph'); el.classList.add('ph-active') }
  })
}
const bcLock = (on: boolean) => {
  bcModal.locked = on
  const d = bcFrame.value?.contentDocument as Document | undefined
  if (!d) return
  d.querySelectorAll('.sheet input,.sheet select,.sheet textarea').forEach((el: any) => { el.disabled = on })
  d.querySelectorAll('.sheet [contenteditable]').forEach((el: any) => { el.contentEditable = on ? 'false' : 'true' })
  const cs = d.getElementById('coSel') as any
  if (cs) cs.disabled = on
  ;['seaVVAdd', 'airFlAdd', 'seaDimAdd', 'airDimAdd', 'seaDimToggle', 'airDimToggle', 'seaDimUse', 'airDimUse', 'seaWhMng', 'airWhMng', 'btnClear'].forEach((id) => {
    const el = d.getElementById(id) as any
    if (el) el.disabled = on
  })
  d.querySelectorAll('.rowdel,.wdel').forEach((el: any) => { el.disabled = on })
  let styleEl = d.getElementById('bcLockStyle') as HTMLStyleElement | null
  if (on) {
    if (!styleEl) {
      styleEl = d.createElement('style')
      styleEl.id = 'bcLockStyle'
      d.head.appendChild(styleEl)
    }
    styleEl.textContent = '.sheet input:disabled,.sheet select:disabled,.sheet textarea:disabled{opacity:.55;cursor:not-allowed;background:#f1f4f2}.sheet [contenteditable="false"]{opacity:.55;cursor:not-allowed}.wh-manage-btn:disabled,.dim-toggle:disabled,.addrow-btn:disabled,.rowdel:disabled,.wdel:disabled{opacity:.4;cursor:not-allowed}'
  } else if (styleEl) styleEl.textContent = ''
}
const onBcFrameLoad = () => {
