const openBookingDetail = (row: number, column: number) => {
  bookingDetailModal.row = row
  bookingDetailModal.column = column
  bookingDetailModal.number = ''
  bookingDetailModal.documentName = ''
  bookingDetailModal.documents = []
  bookingDetailModal.url = ''
  const raw = rows.value[row]?.[column]
  const parsed = parseJsonCell(raw, null as any)
  const booking = parsed && typeof parsed === 'object' && 'booking' in parsed ? (parsed as any).booking || {} : {}
  bookingDetailModal.number = String(booking.number || (raw && !String(raw).startsWith('{') ? raw : '')).trim()
  bookingDetailModal.documents = Array.isArray(booking.documents) ? booking.documents.map((doc: any) => newBookingDocument(String(doc.name || doc), doc.url)) : []
  bookingDetailModal.url = String(booking.url || bookingDetailModal.documents[0]?.url || '')
  bookingDetailModal.documentName = String(booking.fileName || booking.documentName || '')
  if (!bookingDetailModal.documentName && bookingDetailModal.url) bookingDetailModal.documentName = bookingDetailModal.documents[0]?.name || 'Booking document'
  bookingDetailModal.locked = !!bookingDetailModal.number || !!bookingDetailModal.url || bookingDetailModal.documents.some((document) => document.name.trim() || document.url)
  if (!bookingDetailModal.documents.length) bookingDetailModal.documents.push(newBookingDocument())
  bookingDetailModal.open = true
}
const closeBookingDetail = () => { bookingDetailModal.open = false; bookingDetailModal.row = -1; bookingDetailModal.column = -1 }
const clearBookingDetail = () => { bookingDetailModal.number = ''; bookingDetailModal.documentName = ''; bookingDetailModal.documents = [newBookingDocument()]; bookingDetailModal.url = '' }
const addBookingDocument = () => {
  bookingDetailModal.documents.push(newBookingDocument())
}
const uploadBookingDocument = (index: number) => {
  bookingUploadIndex.value = index
  bookingDetailInput.value?.click()
}
const uploadBookingNumber = () => {
  bookingUploadIndex.value = -1
  bookingDetailInput.value?.click()
}
const viewBookingDocument = (index: number) => {
  const url = bookingDetailModal.documents[index]?.url
  if (url) void viewBookingAttachment(url)
}
const removeBookingDocument = (index: number) => {
  if (bookingDetailModal.documents.length === 1) {
    bookingDetailModal.documents[0] = newBookingDocument()
    return
  }
  bookingDetailModal.documents.splice(index, 1)
}
const onBookingDetailFile = async (event: Event) => {
  const input = event.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file) return
  bookingDetailModal.uploading = true
  try {
    const uploaded = await uploadAdminAttachment(file)
    const url = String(uploaded?.url || '').trim()
    if (!url) throw new Error('The server did not return the uploaded file URL')
    const name = String(uploaded?.name || file.name).trim()
    const index = bookingUploadIndex.value
    if (index < 0) {
      bookingDetailModal.url = url
      bookingDetailModal.documentName = name
      return
    }
    while (bookingDetailModal.documents.length <= index) bookingDetailModal.documents.push(newBookingDocument())
    bookingDetailModal.documents[index] = newBookingDocument(name, url)
  } catch (error: any) {
    showToast(String(error?.data?.message || error?.message || 'Could not upload the booking attachment'))
  } finally {
    bookingDetailModal.uploading = false
    input.value = ''
  }
}
const viewBookingAttachment = async (url: string) => {
  const attachmentUrl = String(url || '').trim()
  if (!attachmentUrl) return
  await viewAdminAttachment(attachmentUrl)
}
const viewBookingDetailFile = () => { if (bookingDetailModal.url) void viewBookingAttachment(bookingDetailModal.url) }
const saveBookingDetail = () => {
  const documents = bookingDetailModal.documents.filter((document) => document.name.trim() || document.url)
  if (!bookingDetailModal.number && !documents.length) {
    showToast('Enter Booking No# or attach a document')
    return
  }
  rows.value[bookingDetailModal.row][bookingDetailModal.column] = JSON.stringify({ booking: { number: bookingDetailModal.number, documents, url: bookingDetailModal.url, fileName: bookingDetailModal.documentName } })
  bookingDetailModal.locked = true
  mirrorFclLinkedCell(bookingDetailModal.row, bookingDetailModal.column)
  scheduleSave()
}
const mirroredEcdVolumeValue = async (row: number) => {
  const parsed = opsParts.value
  if (!parsed) return ''
  const type = String(parsed.type || '').toUpperCase()
  const dept = String(parsed.dept || '').toUpperCase()
  const sourceDept = isAirSheet() && isExwFcdSheet()
    ? 'ECD'
    : ['DO', 'DAP', 'DDU', 'DDP'].includes(type) && ['CCD', 'TCD', 'FCD'].includes(dept)
      ? 'ICD'
      : ''
  if (!sourceDept) return ''
  const ecdKey = opsLeafKey(parsed.base, parsed.mode, parsed.type, sourceDept as any)
  try {
    const sheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(ecdKey))}`)
    const extracted = extractWorkbookRows(Array.isArray(sheet.rows) ? sheet.rows.map((item: any[]) => [...item]) : [], sheet)
    const sourceRows = extracted.rows || []
    const sourceHeader = (rows.value[0] || []).map((value) => String(value ?? '').trim())
    const targetHeader = (sourceRows[0] || []).map((value: any) => String(value ?? '').trim())
    const volumeColumn = targetHeader.indexOf('VOLUME')
    if (volumeColumn < 0) return ''
    const identity = rowIdentity(sourceHeader, rows.value[row] || [])
    const matchedIndex = identity
      ? sourceRows.findIndex((item: any[], index: number) => index > 0 && rowIdentity(targetHeader, item) === identity)
      : row
    return matchedIndex > 0 ? sourceRows[matchedIndex]?.[volumeColumn] ?? '' : ''
  } catch {
    return ''
  }
}
const openGsdModal = async (row: number, column: number) => {
