        gsdModal.form.locked = true
        gsdModal.editing = false
      } else if (label === 'CLEARANCE DOCS APPROVAL') {
        gsdModal.formFields = []
        gsdModal.form = clearanceDocsFormFromCell(rawText)
        gsdModal.editing = !gsdModal.form.locked
      } else if (label === 'CLEARANCE DETAIL' || label === 'CLEARANCE DETAILS' || label === 'CUSTOMS CLEARANCE DETAILS') {
        gsdModal.formFields = []
        const linkedClearanceValue = isDupTcdClearanceDetailsModal() ? await linkedTcdClearanceValue(row, rawText) : rawText
        if (linkedClearanceValue !== rawText && String(linkedClearanceValue || '').trim()) rows.value[row][column] = linkedClearanceValue
        gsdModal.form = clearanceDetailsFormFromCell(linkedClearanceValue)
        if (isDupCcdClearanceDetailsModal()) {
          gsdModal.form.linkedContSealValue = await linkedCcdContSealValue(row, rowValueByHeader('CONT/SEAL INFO'))
        }
        if (isSimpleCcdClearanceDetailsModal()) gsdModal.form.openId = ''
        syncClearanceRowsFromSource()
        gsdModal.editing = !isDupTcdClearanceDetailsModal()
      } else {
        const fields = gsdFormFieldsFor(label)
        gsdModal.formFields = fields
        gsdModal.form = { ...emptyGsdForm(fields), ...(parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form : {}) }
        if (label === 'MBL NO#' && rawText && !rawText.trim().startsWith('{')) gsdModal.form.mblNo = rawText.trim()
      }
      // The Excel structure files are authoritative for inbound/locked
      // columns. Keep every corresponding modal in read-only mode even when
      // the stored payload has not been marked as locked yet.
      if (isLockedOpsCell(row, column) || isSentEcdRowLocked(row)) gsdModal.editing = false
    } else {
      gsdModal.text = rawText
    }
  }
  // SENT ECD locks the complete GSD row. Its buttons remain available for
  // viewing, but no modal may switch to edit mode until SENT ECD is unlocked.
  if (isSentEcdRowLocked(row)) gsdModal.editing = false
}
