const noticeServicePair = () => {
  const parsed = opsParts.value
  if (!parsed || gsdModal.row < 1) return null
  const resolvedPair = gsdModal.form?.noticeServicePair
  if (resolvedPair?.originType && resolvedPair?.destinationType) return resolvedPair
  const currentType = upperText(parsed.type)
  const header = (rows.value[0] || []).map((value: any) => upperText(value))
  const plusColumn = header.indexOf(`${currentType}+`)
  const selectedType = plusColumn >= 0 ? upperText(rows.value[gsdModal.row]?.[plusColumn]) : ''
  const originTypes = ['EXW', 'FCA', 'FCF']
  const destinationTypes = ['DO', 'DAP', 'DDU', 'DDP']
  const originType = originTypes.includes(currentType) ? currentType : originTypes.includes(selectedType) ? selectedType : ''
  const destinationType = destinationTypes.includes(currentType) ? currentType : destinationTypes.includes(selectedType) ? selectedType : ''
  return originType && destinationType ? { originType, destinationType } : null
}
const resolveLinkedNoticeServicePair = async (row: number) => {
  const direct = noticeServicePair()
  if (direct) return direct
  const current = opsParts.value
  if (!current || row < 1) return null
  const currentType = upperText(current.type)
  const originTypes = ['EXW', 'FCA', 'FCF']
  const destinationTypes = ['DO', 'DAP', 'DDU', 'DDP']
  const currentHeader = (rows.value[0] || []).map((value: any) => String(value ?? '').trim())
  const shipmentLink = opsShipmentLink(currentHeader, rows.value[row] || [], row, settings.value)
  if (!shipmentLink) return null
  try {
    // CCD/TCD do not carry the service-flow (+) column. Resolve it through the
    // linked GSD row so Notice can expose both origin (O*) and destination (D*).
    const gsdKey = opsLeafKey(current.base, current.mode, current.type, 'GSD')
    const gsdSheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(gsdKey))}`)
    const extracted = extractWorkbookRows(Array.isArray(gsdSheet?.rows) ? gsdSheet.rows.map((item: any[]) => [...item]) : [], gsdSheet)
    const gsdHeader = opsHeaderFor(current.base, current.mode, 'GSD', current.type)
    const gsdRows = alignRowsToHeader(extracted.rows, gsdHeader).rows
    const gsdSettings = extracted.settings || gsdSheet?.settings || {}
    const linkedRow = gsdRows.findIndex((item, index) => index > 0 && opsShipmentLink(gsdHeader, item, index, gsdSettings) === shipmentLink)
    if (linkedRow < 1) return null
    const plusColumn = gsdHeader.indexOf(`${currentType}+`)
    const counterpartType = plusColumn >= 0 ? upperText(gsdRows[linkedRow]?.[plusColumn]) : ''
    const originType = originTypes.includes(currentType) ? currentType : originTypes.includes(counterpartType) ? counterpartType : ''
    const destinationType = destinationTypes.includes(currentType) ? currentType : destinationTypes.includes(counterpartType) ? counterpartType : ''
    return originType && destinationType ? { originType, destinationType } : null
  } catch (error) {
    console.warn('Could not resolve linked Notice service pair', error)
    return null
  }
}
const scopedNoticeDeptTargets = () => {
  const parsed = opsParts.value
  const pair = noticeServicePair()
  if (!parsed || !pair) return []
  const currentType = upperText(parsed.type)
  const currentScope = currentType === pair.originType ? 'O' : currentType === pair.destinationType ? 'D' : ''
  const currentTarget = currentScope ? `${currentScope}${upperText(parsed.dept)}` : ''
  const targets = (type: string, prefix: 'O' | 'D') =>
    opsDeptsFor(opsBaseForType(type as any), type as any)
      .map((dept: any) => upperText(dept))
      .filter((dept: string) => !!dept)
      .map((dept: string) => `${prefix}${dept}`)
  return [...targets(pair.originType, 'O'), ...targets(pair.destinationType, 'D')]
    .filter((target) => target !== currentTarget)
    .filter((target) => target !== 'DGSD')
    .filter((target) => upperText(parsed.dept) !== 'ICD' || !['OGSD', 'DGSD'].includes(target))
}
const noticeDeptTarget = (label: string) => {
  const normalized = upperText(label)
  const pair = noticeServicePair()
  const match = pair ? normalized.match(/^([OD])(.+)$/) : null
  if (!match || !pair) return { label: normalized, dept: normalized, type: upperText(opsParts.value?.type || '') }
  return {
    label: normalized,
    dept: match[2],
    type: match[1] === 'O' ? pair.originType : pair.destinationType,
  }
}
const reminderDeptTargets = () => {
  const active = String(activeDept.value || '').toUpperCase()
  const type = String(activeType.value || '').toUpperCase()
  const scopedTargets = scopedNoticeDeptTargets()
  if (scopedTargets.length) return scopedTargets
  if (isExwFclGsdSheet()) {
    if (type === 'DO') return ['ICD', 'TCD', 'DCD', 'FCD']
    if (type === 'DAP') return ['ICD', 'TCD', 'FCD']
    if (['DDU', 'DDP'].includes(type)) return ['ICD', 'CCD', 'TCD', 'FCD']
    if (['FCA', 'FCF'].includes(type)) return ['ECD', 'TCD', 'DCD', 'FCD']
    return ['ECD', 'TCD', 'CCD', 'DCD', 'FCD']
  }
  if (isFclExwOrFcaEcdSheet()) {
    if (type === 'FCF') return ['GSD', 'DCD', 'FCD']
    return type === 'FCA' ? ['GSD', 'TCD', 'DCD', 'FCD'] : ['GSD', 'TCD', 'CCD', 'DCD', 'FCD']
  }
  if (type === 'DO' && opsParts.value?.mode === 'FCL' && active === 'ICD') return ['GSD', 'FCD']
  if (type === 'DAP' && opsParts.value?.mode === 'FCL' && active === 'ICD') return ['GSD', 'TCD', 'FCD']
  if (type === 'DAP' && opsParts.value?.mode === 'FCL' && active === 'TCD') return ['GSD', 'ICD', 'FCD']
  if (type === 'DAP' && opsParts.value?.mode === 'FCL' && active === 'FCD') return ['GSD', 'ICD', 'TCD']
  if (['DDU', 'DDP'].includes(type) && opsParts.value?.mode === 'FCL' && active === 'ICD') return ['GSD', 'CCD', 'TCD', 'FCD']
  if (['DDU', 'DDP'].includes(type) && opsParts.value?.mode === 'FCL' && active === 'CCD') return ['GSD', 'ICD', 'TCD', 'FCD']
  if (['DDU', 'DDP'].includes(type) && opsParts.value?.mode === 'FCL' && active === 'TCD') return ['GSD', 'ICD', 'CCD', 'FCD']
  if (['DDU', 'DDP'].includes(type) && opsParts.value?.mode === 'FCL' && active === 'FCD') return ['GSD', 'ICD', 'CCD', 'TCD']
  if (type === 'FCF' && opsParts.value?.mode === 'FCL' && active === 'DCD') return ['GSD', 'ECD', 'FCD']
  if (['EXW', 'FCA'].includes(type) && opsParts.value?.mode === 'FCL' && active === 'TCD') {
    return type === 'FCA'
      ? ['GSD', 'ECD', 'DCD', 'FCD']
      : ['GSD', 'ECD', 'CCD', 'DCD', 'FCD']
  }
  if (['EXW', 'FCA', 'FCF'].includes(type) && opsParts.value?.mode === 'FCL' && active === 'CCD') {
    return ['GSD', 'ECD', 'TCD', 'DCD', 'FCD']
  }
  if (['EXW', 'FCA', 'FCF'].includes(type) && opsParts.value?.mode === 'FCL' && active === 'DCD') {
    return ['GSD', 'ECD', 'TCD', 'CCD', 'FCD']
  }
  if (isLclSheet()) {
    const airNoticeTargets: Record<string, Record<string, string[]>> = {
      FCA: {
        GSD: ['ECD', 'TCD', 'DCD', 'FCD'], ECD: ['GSD', 'TCD', 'DCD', 'FCD'], TCD: ['GSD', 'ECD', 'DCD', 'FCD'], DCD: ['GSD', 'ECD', 'TCD', 'FCD'], FCD: ['GSD', 'ECD', 'TCD', 'DCD'],
      },
      FCF: {
        GSD: ['ECD', 'FCD'], ECD: ['GSD', 'DCD', 'FCD'], DCD: ['GSD', 'ECD', 'FCD'], FCD: ['GSD', 'ECD', 'DCD'],
      },
      DO: {
        GSD: ['ICD', 'FCD'], ICD: ['GSD', 'FCD'], FCD: ['GSD', 'ICD'],
      },
      DAP: {
        GSD: ['ICD', 'TCD', 'FCD'], ICD: ['GSD', 'TCD', 'FCD'], TCD: ['GSD', 'ICD', 'FCD'], FCD: ['GSD', 'ICD', 'TCD'],
      },
      DDU: {
        GSD: ['ICD', 'CCD', 'TCD', 'FCD'], ICD: ['GSD', 'TCD', 'CCD', 'FCD'], CCD: ['GSD', 'ICD', 'TCD', 'FCD'], TCD: ['GSD', 'ICD', 'CCD', 'FCD'], FCD: ['GSD', 'ICD', 'CCD', 'TCD'],
      },
      DDP: {
        GSD: ['ICD', 'CCD', 'TCD', 'FCD'], ICD: ['GSD', 'TCD', 'CCD', 'FCD'], CCD: ['GSD', 'ICD', 'TCD', 'FCD'], TCD: ['GSD', 'ICD', 'CCD', 'FCD'], FCD: ['GSD', 'ICD', 'CCD', 'TCD'],
      },
      DUP: {
        GSD: ['ICD', 'CCD', 'TCD', 'FCD'], ICD: ['GSD', 'TCD', 'CCD', 'FCD'], CCD: ['GSD', 'ICD', 'TCD', 'FCD'], TCD: ['GSD', 'ICD', 'CCD', 'FCD'], FCD: ['GSD', 'ICD', 'CCD', 'TCD'],
      },
    }
    const exactTargets = airNoticeTargets[type]?.[active]
    if (exactTargets) return exactTargets
  }
  if (isLclSheet() && String(opsParts.value?.type || '').toUpperCase() === 'EXW') {
    const airExwTargets: Record<string, string[]> = {
      GSD: ['ECD', 'TCD', 'CCD', 'DCD', 'FCD'],
      ECD: ['GSD', 'TCD', 'CCD', 'DCD', 'FCD'],
      TCD: ['GSD', 'ECD', 'CCD', 'DCD', 'FCD'],
      CCD: ['GSD', 'ECD', 'TCD', 'DCD', 'FCD'],
      DCD: ['GSD', 'ECD', 'TCD', 'CCD', 'FCD'],
      FCD: ['GSD', 'ECD', 'TCD', 'CCD', 'DCD'],
    }
    if (airExwTargets[active]) return airExwTargets[active]
  }
  const targetsByDept: Record<string, string[]> = {
    GSD: ['ECD', 'TCD', 'CCD', 'FCD'],
    ECD: ['TCD', 'CCD', 'DCD', 'FCD'],
    DCD: ['ECD', 'FCD'],
    FCD: ['GSD', 'ECD', 'TCD', 'CCD', 'DCD'],
  }
  const preferred =
    (type === 'DO' || type === 'DAP' || type === 'DDU' || type === 'DDP') && active === 'GSD' ? ['ICD', 'FCD'] :
    (type === 'DDU' || type === 'DDP') && active === 'CCD' ? ['ICD', 'TCD', 'FCD'] :
    (type === 'DDU' || type === 'DDP') && active === 'TCD' ? ['ICD', 'CCD', 'FCD'] :
    type === 'DAP' && active === 'TCD' ? ['ICD', 'FCD'] :
    (type === 'DAP' || type === 'DDU' || type === 'DDP') && active === 'FCD' ? ['GSD', 'ICD'] :
    type === 'DO' && active === 'FCD' ? ['GSD', 'ICD'] :
    targetsByDept[active] || ['ECD', 'TCD', 'CCD', 'DCD', 'FCD']
  const availablePreferred = preferred.filter((dept) => deptTabs.value.includes(dept) || !deptTabs.value.length)
  const defaults = availablePreferred.length ? availablePreferred : deptTabs.value
  return defaults.filter((dept) => dept !== active && (active === 'FCD' || dept !== 'GSD')).slice(0, active === 'FCD' ? 5 : 4)
}
const reminderToday = (date = new Date()) => {
  const part = (value: number) => String(value).padStart(2, '0')
  if (isLclSheet() && ['EXW', 'FCA', 'FCF'].includes(String(opsParts.value?.type || '').toUpperCase())) {
    return `${date.getFullYear()}/${part(date.getMonth() + 1)}/${part(date.getDate())}`
  }
  return `${part(date.getDate())}/${part(date.getMonth() + 1)}/${date.getFullYear()}`
}
const noticeInboxDeptLabel = (note: ReminderNote) => {
  const dept = upperText(note.dept)
  if (/^[OD](GSD|ECD|ICD|TCD|CCD|DCD|FCD)$/.test(dept)) return dept
  const pair = noticeServicePair()
  if (!pair) return dept
  const sourceType = upperText(note.sourceType || '')
  if (sourceType === pair.originType) return `O${dept}`
  if (sourceType === pair.destinationType) return `D${dept}`
  // Compatibility for notices created before sourceType/scope was stored:
  // a notice received from the same department name came from the opposite service side.
  const currentType = upperText(opsParts.value?.type || '')
  if (dept === upperText(opsParts.value?.dept || '')) return `${currentType === pair.originType ? 'D' : 'O'}${dept}`
  return dept
}
const reminderDeptCount = (dept: string) => gsdModal.reminderInboxNotes.filter((note) => noticeInboxDeptLabel(note) === dept && note.read !== true).length
const reminderViewNotes = () => gsdModal.reminderInboxNotes.filter((note) => noticeInboxDeptLabel(note) === gsdModal.reminderViewDept)
const syncReminderNoteToDept = async (note: ReminderNote, operation: 'upsert' | 'remove', notifyOnError = true, sourceRowIndex = gsdModal.row) => {
  const parsed = opsParts.value
  const target = noticeDeptTarget(note.dept)
  const targetDept = target.dept
  const sourceDept = String(parsed?.dept || activeDept.value || '').trim().toUpperCase()
  if (!parsed || !targetDept || !reminderDeptTargets().includes(target.label)) {
    if (notifyOnError) showToast('Notice Dept is not allowed')
    return false
  }

  const targetBase = opsBaseForType(target.type as any)
  const targetKey = opsLeafKey(targetBase, parsed.mode, target.type as any, targetDept as any)
  const targetHeader = opsHeaderFor(targetBase, parsed.mode, targetDept as any, target.type as any)
  const sourceHeader = (rows.value[0] || []).map((value) => String(value ?? '').trim())
  const sourceRow = rows.value[sourceRowIndex] || []
  const sourceLink = ensureOpsShipmentLink(sourceHeader, sourceRow, sourceRowIndex, settings.value)
  const sourceIdentity = rowIdentity(sourceHeader, sourceRow)

  const queueKey = sheetStorageKey(targetKey)
  return queueLinkedWrite(queueKey, async () => {
    try {
      let targetSheet: any
      try {
        targetSheet = await props.request(`/workbook/sheets/${encodeURIComponent(queueKey)}`)
      } catch (error: any) {
        if (requestStatus(error) !== 404) throw error
        if (operation === 'remove') return true
        targetSheet = { rows: [targetHeader.slice()], columnWidths: targetHeader.map(() => 100), rowHeights: {}, formatting: {}, merges: [], settings: {} }
        const created = await props.request('/workbook/sheets', {
          method: 'POST',
          body: { key: queueKey, label: targetKey, group: 'Operations', rows: [...targetSheet.rows, [workbookMetaMarker, JSON.stringify({ version: 1, columnWidths: targetSheet.columnWidths, rowHeights: {}, formatting: {}, merges: [], settings: {} })]] },
        })
        targetSheet.updatedAt = responseUpdatedAt(created)
      }
    const extracted = extractWorkbookRows(Array.isArray(targetSheet.rows) ? targetSheet.rows.map((item: any[]) => [...item]) : [], targetSheet)
    const targetRows = alignRowsToHeader(extracted.rows, targetHeader).rows
    const targetSettings = { ...(extracted.settings || targetSheet.settings || {}) }
    const targetLinks = targetSettings.opsRowLinks && typeof targetSettings.opsRowLinks === 'object' ? { ...targetSettings.opsRowLinks } : {}
    let targetRowIndex = sourceLink
      ? targetRows.findIndex((_row, index) => index > 0 && String(targetLinks[String(index)] || '').trim() === sourceLink)
      : -1
    if (targetRowIndex < 1 && sourceLink) {
      targetRowIndex = targetRows.findIndex((targetRow, index) =>
        index > 0 && opsShipmentLink(targetHeader, targetRow, index, targetSettings) === sourceLink)
    }
    if (targetRowIndex < 1 && sourceIdentity) {
      targetRowIndex = targetRows.findIndex((targetRow, index) =>
        index > 0 && rowIdentity(targetHeader, targetRow) === sourceIdentity)
    }
    if (targetRowIndex < 1) {
      const matchLabels = ['JOB NO#', 'REF#', 'HBL NO#', 'MBL NO#']
      targetRowIndex = targetRows.findIndex((targetRow, index) => index > 0 && matchLabels.some((label) => {
        const sourceColumn = sourceHeader.indexOf(label)
        const targetColumn = targetHeader.indexOf(label)
        if (sourceColumn < 0 || targetColumn < 0) return false
        const sourceValue = String(sourceRow[sourceColumn] ?? '').trim()
        const targetValue = String(targetRow[targetColumn] ?? '').trim()
        return !!sourceValue && sourceValue === targetValue
      }))
    }

    const targetColumn = targetHeader.findIndex((label) => ['NOTICE', 'REMINDER'].includes(String(label || '').trim().toUpperCase()))
    if (targetColumn < 0) throw new Error(`${targetDept} does not have a NOTICE column`)
    if (targetRowIndex < 1 && operation === 'remove') return true
    if (targetRowIndex < 1) {
      targetRows.push(targetHeader.map((targetLabel) => {
        const aliases: Record<string, string[]> = {
          'EFA+': ['EFA+', 'FCF+', 'EXW+'],
          'ORIGIN AGENT': ['ORIGIN AGENT', 'ORIGINAL AGENT'],
          'CUT OFF DETAIL': ['CUT OFF DETAIL', 'CUT OFF DETAILS'],
          'BILL DETAIL': ['BILL DETAIL', 'BILL APPROVAL'],
          'ARRIVAL NOTICE DETAIL': ['ARRIVAL NOTICE DETAIL', 'ARRIVAL NOTICE SENDING'],
        }
        const sourceColumn = sourceHeader.findIndex((sourceLabel) => (aliases[targetLabel] || [targetLabel]).includes(sourceLabel))
        return sourceColumn >= 0 ? sourceRow[sourceColumn] ?? '' : ''
      }))
      targetRowIndex = targetRows.length - 1
    }
    targetLinks[String(targetRowIndex)] = sourceLink
    targetSettings.opsRowLinks = targetLinks

    const current = parseJsonCell(targetRows[targetRowIndex]?.[targetColumn], null as any)
    const targetNotes = current && typeof current === 'object' && Array.isArray((current as any).notes) ? (current as any).notes : []
    const targetInbox = current && typeof current === 'object' && Array.isArray((current as any).inbox) ? (current as any).inbox : []
    const existingNotice = targetInbox.find((item: any) => String(item?.id || '') === note.id)
    const withoutCurrent = targetInbox.filter((item: any) => String(item?.id || '') !== note.id)
    const nextInbox = operation === 'remove'
      ? withoutCurrent
      : [...withoutCurrent, { ...note, dept: sourceDept, sourceType: upperText(parsed.type), read: false, changeType: existingNotice ? 'updated' : 'new' }]
    targetRows[targetRowIndex][targetColumn] = JSON.stringify({ notes: targetNotes, inbox: nextInbox })

    await patchLoadedWorkbookSheet(queueKey, targetSheet, { rows: [...targetRows, [workbookMetaMarker, JSON.stringify({
        version: 1,
        columnWidths: extracted.columnWidths || targetSheet.columnWidths || targetHeader.map(() => 100),
        rowHeights: extracted.rowHeights || targetSheet.rowHeights || {},
        formatting: extracted.formatting || targetSheet.formatting || {},
        merges: extracted.merges || targetSheet.merges || [],
        settings: targetSettings,
      })]] })
    return true
    } catch (error: any) {
      console.warn(`Could not sync NOTICE to ${targetDept}`, error)
      if (notifyOnError) showToast(error?.data?.message || error?.message || `Could not send NOTICE to ${targetDept}`)
      return false
    }
  })
}
const persistReminderNotes = async (immediate = false) => {
  if (!rows.value[gsdModal.row]) return false
  rows.value[gsdModal.row][gsdModal.column] = JSON.stringify({ notes: gsdModal.reminderNotes, inbox: gsdModal.reminderInboxNotes })
  if (immediate) return saveSheet()
