const removeReminderNote = async (index: number) => {
  const ok = await askConfirm('Are you sure to remove?', '', { okText: 'YES', cancelText: 'NO', tone: 'remove' })
  if (!ok) return
  const removed = gsdModal.reminderNotes[index]
  dispatchLoading.value = `Removing notice from ${removed?.dept || 'department'}...`
