const markReminderDeptRead = (dept: string) => {
  let changed = false
  const newlyViewedIds = gsdModal.reminderInboxNotes
    .filter((note) => noticeInboxDeptLabel(note) === dept && note.read !== true)
    .map((note) => note.id)
  gsdModal.reminderJustViewedIds = Array.from(new Set([...gsdModal.reminderJustViewedIds, ...newlyViewedIds]))
  gsdModal.reminderInboxNotes = gsdModal.reminderInboxNotes.map((note) => {
    if (noticeInboxDeptLabel(note) !== dept || note.read === true) return note
    changed = true
    return { ...note, read: true }
  })
  if (changed) void persistReminderNotes()
}
const markReminderUnread = (id: string) => {
  let changed = false
  gsdModal.reminderInboxNotes = gsdModal.reminderInboxNotes.map((note) => {
    if (note.id !== id || note.read !== true) return note
    changed = true
    return { ...note, read: false }
  })
  gsdModal.reminderJustViewedIds = gsdModal.reminderJustViewedIds.filter((noteId) => noteId !== id)
  if (changed) void persistReminderNotes()
}
