const todayIso = () => {
  const date = new Date()
  const pad = (part: number) => String(part).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}
const cutoffRecords = () => {
  const list = Array.isArray(gsdModal.form.cutoffs) ? gsdModal.form.cutoffs : []
  return list.slice().sort((a: CutoffRecord, b: CutoffRecord) => Number(b.ts || 0) - Number(a.ts || 0)) as CutoffRecord[]
}
const cutoffHasInput = () => !!(gsdModal.form.siDate || gsdModal.form.siTime || gsdModal.form.cyDate || gsdModal.form.cyTime)
const clearCutoffHint = () => {
  gsdModal.form.hint = ''
}
const formatCutoffDate = (value: string) => {
  if (!value) return ''
  const parsed = new Date(`${value}T00:00:00`)
  if (Number.isNaN(parsed.getTime())) return value.replace(/-/g, '/')
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
  return `${String(parsed.getDate()).padStart(2, '0')}/${months[parsed.getMonth()]}/${parsed.getFullYear()}`
}
const cutoffReminderAt = (siDate: string, siTime: string) => {
  if (!siDate || !siTime) return ''
  const cutoff = new Date(`${siDate}T${siTime}:00`)
  if (Number.isNaN(cutoff.getTime())) return ''
  cutoff.setDate(cutoff.getDate() - 4)
  return cutoff.toISOString()
}
const cutoffRecipientEmails = (row: number) => {
  const header = rows.value[0] || []
  const emails = new Set<string>()
  for (const label of ['SHIPPER', 'CLIENT']) {
    const column = header.findIndex((_: any, index: number) => normalizedHeaderLabel(index) === label)
    if (column < 0) continue
    const client = clientRecordFromCell(rows.value[row]?.[column])
    String(client?.email || '').split(',').map((email) => email.trim()).filter(emailOk).forEach((email) => emails.add(email))
  }
  return [...emails]
}
const cutoffFormFromCell = (value: any) => {
  const parsed = parseJsonCell(value, null as any)
  const form = parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form || {} : {}
  let cutoffs = Array.isArray(form.cutoffs) ? form.cutoffs : []
  if (!cutoffs.length && (form.siDate || form.siTime || form.cyDate || form.cyTime)) {
    cutoffs = [{
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      siDate: String(form.siDate || ''),
      siTime: String(form.siTime || ''),
      cyDate: String(form.cyDate || ''),
      cyTime: String(form.cyTime || ''),
      ts: Number(form.ts || Date.now()),
    }]
  }
  return {
    siDate: '',
    siTime: '',
    cyDate: '',
    cyTime: '',
    hint: '',
    selectedId: '',
    editId: '',
    cutoffs: cutoffs.map((item: any, index: number) => ({
      id: String(item.id || `${Date.now()}-${index}`),
      siDate: String(item.siDate || ''),
      siTime: String(item.siTime || ''),
      cyDate: String(item.cyDate || ''),
      cyTime: String(item.cyTime || ''),
      ts: Number(item.ts || Date.now() - index),
      reminderAt: String(item.reminderAt || cutoffReminderAt(String(item.siDate || ''), String(item.siTime || ''))),
      recipientEmails: Array.isArray(item.recipientEmails) ? item.recipientEmails.map((email: any) => String(email || '').trim()).filter(Boolean) : [],
      reminderStatus: ['SENT', 'CANCELLED'].includes(String(item.reminderStatus || '').toUpperCase()) ? String(item.reminderStatus).toUpperCase() : 'SCHEDULED',
    })),
  }
}
const persistCutoffForm = (immediate = false) => {
  rows.value[gsdModal.row][gsdModal.column] = JSON.stringify({ form: { cutoffs: cutoffRecords() } })
  mirrorFclLinkedCell(gsdModal.row, gsdModal.column)
  scheduleSave()
  if (immediate) void saveSheet()
}
const clearCutoffForm = () => {
  gsdModal.form.siDate = ''
  gsdModal.form.siTime = ''
  gsdModal.form.cyDate = ''
  gsdModal.form.cyTime = ''
  gsdModal.form.hint = ''
  gsdModal.form.selectedId = ''
  gsdModal.form.editId = ''
}
const setCutoffHint = (message: string) => {
  gsdModal.form.hint = message
}
const saveCutoffRecord = () => {
  const siDate = String(gsdModal.form.siDate || '')
  const siTime = String(gsdModal.form.siTime || '')
  const cyDate = String(gsdModal.form.cyDate || '')
  const cyTime = String(gsdModal.form.cyTime || '')
  const today = todayIso()
  if ((siDate && !siTime) || (!siDate && siTime)) return setCutoffHint('Fill both SI date and time')
  if ((cyDate && !cyTime) || (!cyDate && cyTime)) return setCutoffHint('Fill both CY date and time')
  if (!siDate && !cyDate) return setCutoffHint('Enter SI or CY cutoff')
  if (siDate && siDate < today) return setCutoffHint('SI date cannot be in the past')
  if (cyDate && cyDate < today) return setCutoffHint('CY date cannot be in the past')
  const editId = String(gsdModal.form.editId || '')
  const list = cutoffRecords()
  if (editId) {
    const target = list.find((item) => item.id === editId)
    if (target) {
      target.siDate = siDate
      target.siTime = siTime
      target.cyDate = cyDate
      target.cyTime = cyTime
      target.ts = Date.now()
      target.reminderAt = cutoffReminderAt(siDate, siTime)
      target.recipientEmails = cutoffRecipientEmails(gsdModal.row)
      target.reminderStatus = 'SCHEDULED'
    }
    gsdModal.form.cutoffs = list
  } else {
    gsdModal.form.cutoffs = [{
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      siDate, siTime, cyDate, cyTime, ts: Date.now(),
      reminderAt: cutoffReminderAt(siDate, siTime),
      recipientEmails: cutoffRecipientEmails(gsdModal.row),
      reminderStatus: 'SCHEDULED',
    }, ...list]
  }
  persistCutoffForm(true)
  clearCutoffForm()
}
const selectCutoffRecord = (id: string) => {
  gsdModal.form.selectedId = gsdModal.form.selectedId === id ? '' : id
  gsdModal.form.hint = ''
}
const editCutoffRecord = () => {
  const item = cutoffRecords().find((record) => record.id === gsdModal.form.selectedId)
  if (!item) return setCutoffHint('Select a row to edit')
  gsdModal.form.siDate = item.siDate
  gsdModal.form.siTime = item.siTime
  gsdModal.form.cyDate = item.cyDate
  gsdModal.form.cyTime = item.cyTime
  gsdModal.form.editId = item.id
  gsdModal.form.hint = 'Editing selected row - change values then Save'
}
const removeCutoffRecord = async () => {
  const selectedId = String(gsdModal.form.selectedId || '')
  if (!selectedId) return setCutoffHint('Select a row to remove')
  const ok = await askConfirm('Are you sure to remove?', '', { okText: 'YES', cancelText: 'NO', tone: 'remove' })
  if (!ok) return
  gsdModal.form.cutoffs = cutoffRecords().filter((item) => item.id !== selectedId)
