const linkedCcdContSealValue = async (row: number, fallback: any) => {
  const parsed = opsParts.value
  if (!parsed || !isCcdDduDdpFlow()) return fallback
  const sourceHeader = (rows.value[0] || []).map((item) => String(item || '').trim())
  const sourceLink = opsShipmentLink(sourceHeader, rows.value[row] || [], row, settings.value)
  if (!sourceLink) return fallback
  try {
    const sourceKey = opsLeafKey(parsed.base, parsed.mode, parsed.type, 'ICD')
    const sourceSheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(sourceKey))}`)
    const targetHeader = opsHeaderFor(parsed.base, parsed.mode, 'ICD', parsed.type)
    const extracted = extractWorkbookRows(Array.isArray(sourceSheet.rows) ? sourceSheet.rows.map((item: any[]) => [...item]) : [], sourceSheet)
    const sourceRows = alignRowsToHeader(extracted.rows, targetHeader).rows
    const links = extracted.settings?.opsRowLinks || sourceSheet.settings?.opsRowLinks || {}
    const linkedRow = sourceRows.findIndex((_item, index) => index > 0 && String(links[String(index)] || '') === sourceLink)
    const column = targetHeader.findIndex((label) => ['CONT/SEAL INFO', 'TRUCK & CONT/SEAL INFO'].includes(upperText(label)))
    const value = linkedRow > 0 && column >= 0 ? sourceRows[linkedRow]?.[column] : ''
    return String(value ?? '').trim() ? value : fallback
  } catch (error: any) {
    if (requestStatus(error) !== 404) console.warn('Could not load linked CONT/SEAL INFO from ICD', error)
    return fallback
  }
}
