    showToast(kind === 'DEBIT' ? 'Selected lines must share the same Collect from and the same currency.' : 'Selected lines must share the same Pay to and the same currency.')
    return
  }
  openPaymentNoteModal(kind, selected.map((line: any) => ({
    charge: String(line.charge || ''),
    party: String(line[partyKey] || ''),
    currency: String(line[currencyKey] || ''),
    amount: String(line[kind === 'DEBIT' ? 'totalCol' : 'totalPay'] || ''),
  })), String(gsdModal.form.issueFrom || ''), String(gsdModal.form.issueBank || ''))
}
const expenseNumber = (value: any) => Number(String(value || '0').replace(/,/g, '')) || 0
const expenseMoney = (value: number) => value.toFixed(2)
const expenseTotal = (kind: 'pay' | 'collect') => {
  const currencyKey = kind === 'pay' ? 'payCurrency' : 'collectCurrency'
  const lineCurrency = kind === 'pay' ? 'curPay' : 'curCol'
  const lineTotal = kind === 'pay' ? 'totalPay' : 'totalCol'
  const currency = String(gsdModal.form[currencyKey] || 'ALL')
  const total = expenseCollectLines()
    .filter((line: any) => currency === 'ALL' || line[lineCurrency] === currency)
    .reduce((sum: number, line: any) => sum + expenseNumber(line[lineTotal]), 0)
  return expenseMoney(total)
}
const expenseDeductedTotal = () => {
  const currency = String(gsdModal.form.deductCurrency || 'ALL')
  const total = expenseCollectLines()
    .filter((line: any) => currency === 'ALL' || line.curPay === currency || line.curCol === currency)
    .reduce((sum: number, line: any) => sum + expenseNumber(line.totalCol) - expenseNumber(line.totalPay), 0)
  return expenseMoney(total)
}
const expenseStatusClass = (status: any) => ({
  ok: String(status || '').toUpperCase() === 'APPROVED',
  reject: String(status || '').toUpperCase() === 'REJECTED',
  edit: String(status || '').toUpperCase() === 'REQUEST EDIT',
})
const expenseCollectValidStatus = (line: any) => ['APPROVED', 'REJECTED', 'REQUEST EDIT'].includes(upperText(line?.status || ''))
const expenseCollectCanEditSelected = () => expenseCollectSelectedLines().length > 0
const expenseCollectCanSendSelected = () => expenseCollectSelectedLines().some((line: any) => expenseCollectValidStatus(line) && (!line.statusDetails || line.editing))
const expenseStamp = () => {
  const date = new Date()
  const pad = (value: number) => String(value).padStart(2, '0')
  return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`
}
