const routeFromCellValue = (value: any): RouteRecord | null => {
  const parsed = parseJsonCell(value, null as any)
  const rawForm = parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form : parsed
  if (rawForm && typeof rawForm === 'object') {
    const route = 'route' in rawForm && rawForm.routeData ? rawForm.routeData : rawForm
    const clean = normalizeRouteRecord(route)
    if (clean.polCode && clean.podCode) return clean
    const routeText = String(rawForm.route || '').trim()
    const match = routeText.match(/^([A-Z0-9]+)-([A-Z0-9]+)$/i)
    if (match) return normalizeRouteRecord({ polCode: match[1], podCode: match[2] })
  }
  const raw = String(value || '').trim()
  const match = raw.match(/^([A-Z0-9]+)-([A-Z0-9]+)$/i)
  return match ? normalizeRouteRecord({ polCode: match[1], podCode: match[2] }) : null
}
