const selectVessel = () => {
  updateVesselSearch()
  const vessel = findVessel(gsdModal.form.vesselName || '')
  const voyage = upperText(gsdModal.form.voyage || '').trim()
  if (!gsdModal.form.vesselName || !voyage) {
    gsdModal.form.hint = 'Fill vessel and voyage number'
    return
  }
  if (!vessel) {
    gsdModal.form.hint = 'Vessel not found - use Add New'
    showToast('Vessel not found - use Add New')
    return
  }
  const selected = { ...vessel, voyage }
  if (isExwEcdVesselDelayModal()) {
    applyVesselSelection(gsdModal.row, gsdModal.column, selected, voyage)
    let extra = 0
    if (gsdModal.form.applyAll) {
      for (const other of vesselSameRows(selected.name, voyage)) {
        applyVesselSelection(other, gsdModal.column, selected, voyage)
        extra += 1
      }
    }
    scheduleSave()
    void saveSheet()
    showToast(extra ? `Vessel applied to ${extra + 1} shipment(s)` : `Vessel selected - ${selected.name} / ${voyage}`)
    closeGsdModal()
    return
  }
  rows.value[gsdModal.row][gsdModal.column] = JSON.stringify({ form: { vesselData: selected } })
  mirrorFclLinkedCell(gsdModal.row, gsdModal.column)
  scheduleSave()
  void saveSheet()
  showToast(`Vessel selected - ${selected.name} / ${voyage}`)
  closeGsdModal()
}
// ---- AIR/LCL EXW ECD vessel history + delay (mockup `EXW ECD` #ovs) ----
const vesselCellForm = (value: any) => {
  const parsed = parseJsonCell(value, null as any)
  return parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form || {} : {}
}
const vesselCellHistory = (value: any) => {
  const history = vesselCellForm(value).history
  return Array.isArray(history) ? history.map((item: any) => ({ ...item })) : []
}
const vesselRowEtdEta = (row: number) => {
  const etdIndex = headerIndexOf(['ETD'])
  const etaIndex = headerIndexOf(['ETA'])
  return {
    etd: etdIndex >= 0 ? String(rows.value[row]?.[etdIndex] ?? '') : '',
    eta: etaIndex >= 0 ? String(rows.value[row]?.[etaIndex] ?? '') : '',
  }
}
const vesselVoyageKey = (name: any, voyage: any) =>
  `${upperText(name).trim()}::${upperText(voyage).trim()}`
const vesselSameRows = (name: string, voyage: string) => {
  const out: number[] = []
  const column = gsdModal.column
  const targetKey = vesselVoyageKey(name, voyage)
  if (targetKey === '::') return out
  for (let index = 1; index < rows.value.length; index++) {
    if (index === gsdModal.row) continue
    const vessel = vesselFromCellValue(rows.value[index]?.[column])
    if (vessel && vesselVoyageKey(vessel.name, vessel.voyage) === targetKey) out.push(index)
  }
  return out
}
const applyVesselSelection = (row: number, column: number, vessel: any, voyage: string) => {
  const history = vesselCellHistory(rows.value[row]?.[column])
  history.forEach((item: any) => { item.status = 'Expired' })
  const order = history.length ? Math.max(...history.map((item: any) => Number(item.order) || 0)) + 1 : 1
  const { etd, eta } = vesselRowEtdEta(row)
  history.push({ order, time: billTimestamp(), type: 'SELECT', name: vessel.name, imo: vessel.imo, voyage, etd, eta, status: 'Applied', reason: '' })
  rows.value[row][column] = JSON.stringify({ form: { vesselData: { ...vessel, voyage }, history, delayed: false, delayReason: '' } })
}
const rescheduleCutoffForVesselDelay = (row: number, oldEtd: string, newEtd: string) => {
  if (!oldEtd || !newEtd) return
  const oldDate = new Date(`${oldEtd}T00:00:00`)
  const nextDate = new Date(`${newEtd}T00:00:00`)
  if (Number.isNaN(oldDate.getTime()) || Number.isNaN(nextDate.getTime())) return
  const shiftDays = Math.round((nextDate.getTime() - oldDate.getTime()) / 86400000)
  if (!shiftDays) return
  const cutoffColumn = (rows.value[0] || []).findIndex((_: any, index: number) =>
    ['CUTOFF DETAIL', 'CUT OFF DETAIL', 'CUT OFF DETAILS'].includes(normalizedHeaderLabel(index)))
  if (cutoffColumn < 0) return
  const parsed = parseJsonCell(rows.value[row]?.[cutoffColumn], null as any)
  const form = parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form || {} : {}
  const cutoffs = Array.isArray(form.cutoffs) ? form.cutoffs.map((item: any) => ({ ...item })) : []
  if (!cutoffs.length) return
  const applied = cutoffs.slice().sort((a: any, b: any) => Number(b.ts || 0) - Number(a.ts || 0))[0]
  const shiftDate = (value: any) => {
    if (!value) return ''
    const date = new Date(`${String(value)}T00:00:00`)
    if (Number.isNaN(date.getTime())) return String(value)
    date.setDate(date.getDate() + shiftDays)
    return date.toISOString().slice(0, 10)
  }
  applied.siDate = shiftDate(applied.siDate)
  applied.cyDate = shiftDate(applied.cyDate)
  applied.reminderAt = cutoffReminderAt(String(applied.siDate || ''), String(applied.siTime || ''))
  applied.recipientEmails = cutoffRecipientEmails(row)
  applied.reminderStatus = 'SCHEDULED'
  applied.ts = Date.now()
  rows.value[row][cutoffColumn] = JSON.stringify({ form: { cutoffs } })
  mirrorFclLinkedCell(row, cutoffColumn)
}
const applyVesselDelay = (row: number, column: number, newEtd: string, newEta: string, reason: string) => {
  const form = vesselCellForm(rows.value[row]?.[column])
  const vessel = vesselFromCellValue(rows.value[row]?.[column])
  if (!vessel) return
  const history = vesselCellHistory(rows.value[row]?.[column])
  history.forEach((item: any) => { item.status = 'Expired' })
  const order = history.length ? Math.max(...history.map((item: any) => Number(item.order) || 0)) + 1 : 1
  const current = vesselRowEtdEta(row)
  const etd = newEtd || current.etd
  const eta = newEta || current.eta
  history.push({ order, time: billTimestamp(), type: 'DELAY', name: vessel.name, imo: vessel.imo, voyage: vessel.voyage, etd, eta, status: 'Applied', reason })
  const etdIndex = headerIndexOf(['ETD'])
  const etaIndex = headerIndexOf(['ETA'])
  if (newEtd) rescheduleCutoffForVesselDelay(row, current.etd, newEtd)
  if (newEtd && etdIndex >= 0) rows.value[row][etdIndex] = newEtd
  if (newEta && etaIndex >= 0) rows.value[row][etaIndex] = newEta
  rows.value[row][column] = JSON.stringify({ form: { ...form, vesselData: { ...vessel }, history, delayed: true, delayReason: reason } })
}
const vesselDelayCanUpdate = () => !!gsdModal.form.selectedHistoryOrder || !!(gsdModal.form.delayToggle && (gsdModal.form.newEtd || gsdModal.form.newEta) && String(gsdModal.form.delayReason || '').trim())
const selectVesselHistory = (item: any) => {
  gsdModal.form.selectedHistoryOrder = Number(item.order) || 0
  gsdModal.form.vesselName = item.name
  gsdModal.form.imo = findVessel(item.name)?.imo || ''
  gsdModal.form.voyage = item.voyage
  gsdModal.form.delayToggle = item.type === 'DELAY'
  gsdModal.form.newEtd = item.type === 'DELAY' ? item.etd : ''
  gsdModal.form.newEta = item.type === 'DELAY' ? item.eta : ''
  gsdModal.form.delayReason = item.type === 'DELAY' ? item.reason : ''
  gsdModal.form.hint = 'History row selected - press Update to apply changes'
}
const updateVesselDelay = () => {
  const vessel = vesselFromCellValue(rows.value[gsdModal.row]?.[gsdModal.column])
  if (!vessel?.name) {
    gsdModal.form.hint = 'Select a vessel first'
    showToast('Select a vessel first')
    return
  }
  const selectedOrder = Number(gsdModal.form.selectedHistoryOrder) || 0
  if (selectedOrder) {
    const form = vesselCellForm(rows.value[gsdModal.row]?.[gsdModal.column])
    const history = vesselCellHistory(rows.value[gsdModal.row]?.[gsdModal.column])
    const selected = history.find((item: any) => Number(item.order) === selectedOrder)
    if (!selected) {
      gsdModal.form.hint = 'Selected history row was not found'
      return
    }
    const selectedVessel = findVessel(gsdModal.form.vesselName || '') || vessel
    const voyage = upperText(gsdModal.form.voyage || selected.voyage || '').trim()
    history.forEach((item: any) => { item.status = Number(item.order) === selectedOrder ? 'Applied' : 'Expired' })
    selected.name = selectedVessel.name
    selected.imo = selectedVessel.imo
    selected.voyage = voyage
    if (selected.type === 'DELAY') {
      selected.etd = gsdModal.form.newEtd || selected.etd
      selected.eta = gsdModal.form.newEta || selected.eta
      selected.reason = String(gsdModal.form.delayReason || selected.reason || '').trim()
    }
    const etdIndex = headerIndexOf(['ETD'])
    const etaIndex = headerIndexOf(['ETA'])
    if (selected.etd && etdIndex >= 0) rows.value[gsdModal.row][etdIndex] = selected.etd
    if (selected.eta && etaIndex >= 0) rows.value[gsdModal.row][etaIndex] = selected.eta
    rows.value[gsdModal.row][gsdModal.column] = JSON.stringify({ form: {
      ...form,
      vesselData: { ...selectedVessel, voyage },
      history,
      delayed: selected.type === 'DELAY',
      delayReason: selected.type === 'DELAY' ? selected.reason : '',
    } })
    if (gsdModal.form.applyAll && selected.type === 'DELAY') {
      for (const other of vesselSameRows(vessel.name, vessel.voyage)) {
        applyVesselDelay(other, gsdModal.column, selected.etd, selected.eta, selected.reason)
      }
    }
    gsdModal.form.selectedHistoryOrder = 0
    scheduleSave()
    void saveSheet()
    return
  }
  const reason = String(gsdModal.form.delayReason || '').trim()
  if (!gsdModal.form.newEtd && !gsdModal.form.newEta) {
    showToast('Enter New ETD or New ETA')
    return
  }
  if (!reason) {
    showToast('Reason is required')
    return
  }
  applyVesselDelay(gsdModal.row, gsdModal.column, gsdModal.form.newEtd, gsdModal.form.newEta, reason)
  let extra = 0
  if (gsdModal.form.applyAll) {
    for (const other of vesselSameRows(vessel.name, vessel.voyage)) {
      applyVesselDelay(other, gsdModal.column, gsdModal.form.newEtd, gsdModal.form.newEta, reason)
      extra += 1
    }
  }
  gsdModal.form.delayToggle = false
  gsdModal.form.newEtd = ''
  gsdModal.form.newEta = ''
  gsdModal.form.delayReason = ''
  scheduleSave()
  void saveSheet()
}
