const pickupBcFiles = (): Array<{ name: string; url: string }> => {
  const header = rows.value[0] || []
  const column = header.findIndex((_: any, index: number) => normalizedHeaderLabel(index) === 'BC NO#')
  if (column < 0) return []
  const parsed = parseJsonCell(rows.value[gsdModal.row]?.[column], null as any)
  const booking = parsed && typeof parsed === 'object' ? (parsed.booking || parsed) : {}
  const documents = Array.isArray(booking.documents) ? booking.documents : []
  const main = booking.url ? [{ name: String(booking.fileName || booking.documentName || 'Booking document'), url: String(booking.url) }] : []
  const seen = new Set<string>()
  return [...main, ...documents]
    .map((doc: any) => ({ name: String(doc?.name || ''), url: String(doc?.url || '') }))
    .filter((doc: { name: string; url: string }) => doc.url && !seen.has(doc.url) && !!seen.add(doc.url))
}
