const validatePickupDetails = () => {
  const invalid = new Set<string>()
  // Values copied from SHIPPER are authoritative even when that directory
  // record does not contain every optional address/PIC field. Those controls
  // are disabled while Copy is on, so only validate the operational fields
  // that the user can still enter.
  const copiedFromParty = pickupShowsCopy() && !!gsdModal.form.copy
  const required = copiedFromParty
    ? ['pickupDate', 'pickupTime']
    : ['company', 'address', 'city', 'picName', 'picPhone', 'picEmail', 'pickupDate', 'pickupTime']
  if (!copiedFromParty && isExwFcaPickupModal()) required.splice(2, 0, 'ward', 'zip')
  required.forEach((key) => {
    if (!String(gsdModal.form[key] || '').trim()) invalid.add(key)
  })
  const pickupDate = String(gsdModal.form.pickupDate || '')
  if (pickupDate && pickupDate < todayIso()) invalid.add('pickupDate')
  if (!gsdModal.form.noRestriction) invalid.add('noRestriction')
  pickupInvalidFields.value = invalid
  if (pickupDate && pickupDate < todayIso()) {
    showToast(`${isDeliveryDetailsModal() ? 'Delivery' : 'Pickup'} date cannot be in the past`)
    return false
  }
  if (required.some((key) => invalid.has(key))) {
    showToast('Please fill all fields')
    return false
  }
  if (invalid.has('noRestriction')) {
    showToast('Tick "No Vehicle Access Restrictions" to save')
    return false
  }
  return true
}
