    const sendResult = await props.request('/workbook/send-pickup-email', {
      method: 'POST',
      body: {
        sheetKey: sourceStorageKey,
        rowIndex: gsdModal.row,
        columnIndex: gsdModal.column,
        shipmentLink: settings.value?.opsRowLinks?.[String(gsdModal.row)] || '',
        to: gsdModal.form.picEmail,
        shipper: rowValueByHeader('SHIPPER'),
        target,
        jobNo: rowValueByHeader('JOB NO#') || rowValueByHeader('REF#'),
        refNo: rowValueByHeader('REF#'),
        shipmentType: `${opsParts.value?.mode || ''} ${opsParts.value?.type || ''}`.trim(),
        shipment: {
          liner: emailCellDisplayValue('LINER', rowValueByHeader('LINER')),
          bookingNo: emailCellDisplayValue('BC NO#', rowValueByHeader('BC NO#')),
          etd: rowValueByHeader('ETD'),
          eta: rowValueByHeader('ETA'),
          route: emailCellDisplayValue('ROUTE', rowValueByHeader('ROUTE')),
          vesselVoyage: emailCellDisplayValue('VESSEL/VOYAGE', rowValueByHeader('VESSEL/VOYAGE')),
          volume: emailCellDisplayValue('VOLUME', rowValueByHeader('VOLUME')),
        },
        details: {
          company: gsdModal.form.company, address: gsdModal.form.address, ward: gsdModal.form.ward,
          zip: gsdModal.form.zip, city: gsdModal.form.city, picName: gsdModal.form.picName,
          picPhone: gsdModal.form.picPhone, pickupDate: gsdModal.form.pickupDate,
          pickupTime: gsdModal.form.pickupTime, returnPort: gsdModal.form.returnPort,
          remarks: gsdModal.form.remarks,
        },
        bookingFiles: pickupBcFiles(),
      },
    })
    const confirmedSentAt = String(sendResult?.sentAt || sendResult?.data?.sentAt || new Date().toISOString())
    const workbookUpdatedAt = String(sendResult?.workbookUpdatedAt || sendResult?.data?.workbookUpdatedAt || '')
    if (workbookUpdatedAt) rememberSheetUpdatedAt(sourceStorageKey, workbookUpdatedAt)
    gsdModal.form.sent = true
    gsdModal.form.sentAt = confirmedSentAt
    gsdModal.form.saved = true
    gsdModal.editing = false
    persistPickupModal(false)
    if (['EXW', 'FCA', 'DAP', 'DDU', 'DDP'].includes(String(opsParts.value?.type || '').toUpperCase()) && ['FCL', 'LCL'].includes(String(opsParts.value?.mode || '').toUpperCase()) && opsDeptUpper() === 'TCD') {
      const targetLabel = isDeliveryDetailsModal() ? 'DELIVERY DETAIL' : 'PICKUP DETAIL'
      await Promise.all(fclTcdMirrorDepts().map((dept) => mirrorExwFclWorkflowCell(dept, targetLabel, rows.value[gsdModal.row][gsdModal.column])))
    }
    await saveSheet()
    showToast(`${isDeliveryDetailsModal() ? 'Delivery details' : 'Pickup details'} sent to ${target}`)
  } catch (error: any) {
    showToast(error?.data?.message || error?.message || `Could not send to ${target}`)
  } finally {
    dispatchLoading.value = ''
  }
}
const isClearanceDocsModal = () => isGsdFormModalLabel('CLEARANCE DOCS APPROVAL')
