const linkedTcdClearanceValue = async (row: number, fallback: any) => {
  const parsed = opsParts.value
  if (!parsed || parsed.dept !== 'TCD' || !['DDU', 'DDP'].includes(upperText(parsed.type))) return fallback
  const currentHeader = (rows.value[0] || []).map((item) => String(item || '').trim())
  const currentRow = rows.value[row] || []
  const sourceLink = opsShipmentLink(currentHeader, currentRow, row, settings.value)
  try {
    const sourceKey = opsLeafKey(parsed.base, parsed.mode, parsed.type, 'CCD')
    const sourceSheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(sourceKey))}`)
    const sourceTargetHeader = opsHeaderFor(parsed.base, parsed.mode, 'CCD', parsed.type)
    const extracted = extractWorkbookRows(Array.isArray(sourceSheet.rows) ? sourceSheet.rows.map((item: any[]) => [...item]) : [], sourceSheet)
    const sourceRows = alignRowsToHeader(extracted.rows, sourceTargetHeader).rows
    const sourceLinks = extracted.settings?.opsRowLinks || sourceSheet.settings?.opsRowLinks || {}
    let sourceRowIndex = sourceLink
      ? sourceRows.findIndex((_item, index) => index > 0 && String(sourceLinks[String(index)] || '') === sourceLink)
      : -1
    if (sourceRowIndex < 1) {
      const identity = rowIdentity(currentHeader, currentRow)
      if (identity) sourceRowIndex = sourceRows.findIndex((item, index) => index > 0 && rowIdentity(sourceTargetHeader, item) === identity)
    }
    const sourceColumn = sourceTargetHeader.findIndex((label) => ['CLEARANCE DETAIL', 'CLEARANCE DETAILS', 'CUSTOMS CLEARANCE DETAILS'].includes(upperText(label)))
    const value = sourceRowIndex > 0 && sourceColumn >= 0 ? sourceRows[sourceRowIndex]?.[sourceColumn] : ''
    return String(value ?? '').trim() ? value : fallback
  } catch (error: any) {
    if (requestStatus(error) !== 404) console.warn('Could not load linked CLEARANCE DETAIL from CCD', error)
    return fallback
  }
}
