    maxHeight: 'calc(100vh - 32px)',
    boxSizing: 'border-box' as const,
  })

  if (gsdModal.kind === 'reminder') return shell('1134px')
  if (gsdModal.kind === 'client') return shell('560px')
  if (gsdModal.kind === 'extra') return shell('520px')
  if (gsdModal.kind === 'dealt') return shell('1040px')
  if (gsdModal.kind === 'hbl') return shell('382px')
  if (gsdModal.kind !== 'form') return shell('520px')

  if (isPaymentRequestModal()) return shell(usesFullPaymentRequestLayout() ? '1400px' : '1280px', 'min(620px, 86vh)')
  if (isExpenseCollectModal()) return shell('1400px', 'min(620px, 86vh)')
  if (isSiSubmitModal() || isArrivalNoticeModal()) return shell('920px')
  if (isCutoffModal() || isVolumeModal()) return shell('780px')
  if (isFreetimeModal()) return shell('600px')
  if (isRouteModal()) return shell('660px')
  if (isVesselModal()) return shell(isExwEcdVesselDelayModal() || isAirDcdVesselHistoryModal() ? '980px' : '700px')
  if (isPickupModal()) return shell(isDeliveryDetailsModal() ? '890px' : '880px')
  if (isDoContSealModal()) return shell('680px')
  if (isTruckContModal()) return shell('1360px')
  if (isPickupReturnStatusModal()) {
    if (isAirDupTcdTruckingStatusModal() || isAirDupFcdTruckingStatusModal()) return shell('1360px')
    if (isAirDupIcdTruckingStatusModal()) return shell('960px')
    return shell('920px')
  }
  if (isDoReleaseModal()) return shell('660px')
  if (isBillReleaseModal()) return shell('720px')
  if (isBillApprovalModal()) return shell('840px')
  if (isPreAlertConfirmationModal()) {
    if (isAirDoIcdPreAlertConfirmationModal()) return shell('720px')
    if (isAirDupCompactPreAlertConfirmationModal()) return shell('880px')
    return shell('980px')
  }
  if (isPreAlertModal()) return shell('486px')
  if (isClearanceDocsModal()) return shell('700px')
  if (isClearanceDetailsModal()) {
    if (isSimpleCcdClearanceDetailsModal()) return shell('780px')
    if (isDupTcdClearanceDetailsModal()) return shell('760px')
    return shell('1180px')
  }
  return shell('620px')
}
const clearanceDocDefaults = (): ClearanceDocRecord[] => [
  { key: 'ci', label: 'COMMERCIAL INVOICE (CI):', verified: false, file: '', url: '', displayName: '' },
  { key: 'pkl', label: 'PACKING LIST (PKL):', verified: false, file: '', url: '', displayName: '' },
  { key: 'photos', label: 'CARGO PHOTOS:', verified: false, file: '', url: '', displayName: '' },
  { key: 'ot', label: '', verified: false, file: '', url: '', displayName: '', custom: true },
]
const normalizeClearanceDoc = (doc: any, fallback: ClearanceDocRecord): ClearanceDocRecord => ({
  key: String(doc?.key || fallback.key),
  label: String(doc?.label || doc?.name || fallback.label || ''),
  verified: !!(doc?.verified ?? doc?.checked ?? fallback.verified),
  file: String(doc?.file || fallback.file || ''),
  url: String(doc?.url || fallback.url || ''),
  displayName: String(doc?.displayName || doc?.dname || doc?.file || fallback.displayName || fallback.file || ''),
  custom: !!(doc?.custom ?? fallback.custom),
})
const clearanceDocsFormFromCell = (value: any) => {
  const parsed = parseJsonCell(value, null as any)
  const form = parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form || {} : parsed && typeof parsed === 'object' ? parsed : {}
  const stored = Array.isArray(form.docs) ? form.docs : []
  const defaults = clearanceDocDefaults()
  const keyMatchesClearanceDoc = (item: any, key: string) => {
    const storedKey = String(item?.key || '')
    if (storedKey === key) return true
    if (key === 'pkl' && storedKey === 'pl') return true
    return false
  }
  const docs = defaults.map((fallback) => normalizeClearanceDoc(stored.find((item: any) => keyMatchesClearanceDoc(item, fallback.key)), fallback))
  stored.filter((item: any) => item?.custom && !docs.some((doc) => doc.key === item.key)).forEach((item: any, index: number) => {
    docs.push(normalizeClearanceDoc(item, { key: `ot${index + 1}`, label: '', verified: false, file: '', url: '', displayName: '', custom: true }))
  })
  return { docs, locked: !!form.locked }
}
const clearanceDocs = () => (Array.isArray(gsdModal.form.docs) ? gsdModal.form.docs : []) as ClearanceDocRecord[]
const clearanceDocsSaved = (value: any) => {
  const form = clearanceDocsFormFromCell(value)
  return !!form.locked || form.docs.some((doc) => doc.verified || doc.file || doc.label && doc.custom)
}
const clearanceDocUploadLabel = (key: string) => {
  if (key === 'ci') return 'upload CI'
  if (key === 'pkl') return 'upload PKL'
  if (key === 'photos') return 'upload photos'
  return 'upload docs'
}
const clearanceDocsAnyChecked = () => clearanceDocs().some((doc) => doc.verified)
const clearanceDocsCanSave = () => gsdModal.editing && clearanceDocsAnyChecked()
const clearanceDocsValidationMessage = () => {
  const docs = clearanceDocs()
  const ci = docs.find((doc) => doc.key === 'ci')
  const pkl = docs.find((doc) => doc.key === 'pkl')
  if (!ci?.verified || !ci.file || !pkl?.verified || !pkl.file) return 'Please verify and upload all required documents.'
  const tickedWithoutFile = docs.find((doc) => doc.verified && !doc.file)
  if (tickedWithoutFile) return 'Every ticked document must have an uploaded file.'
  const badOther = docs.find((doc) => doc.custom && doc.verified && !doc.label.trim())
  if (badOther) return 'Please enter a name for every ticked OTHERS document.'
  return ''
}
const addClearanceOtherDoc = () => {
