  const records = volumeFormFromCell(volumeValue).records
  return records[records.length - 1]
}
const clearanceRowsFromSource = (): ClearanceRow[] => {
  if (isDupTcdSheet()) {
    return doContSealVolumeRows().map((record) => ({
      key: record.key,
      type: record.type,
      purpose: record.purpose,
      containerNo: '',
      sealNo: '',
    }))
  }
  if (isDupCcdSheet()) {
    const contSealValue = gsdModal.form.linkedContSealValue || rowValueByHeader('CONT/SEAL INFO')
    const contSealRecords = doContSealFormFromCell(contSealValue).records
    return contSealRecords.map((record, index) => ({
      key: String(record.key || `dup-ccd-${index}`),
      type: String(record.type || ''),
      purpose: String(record.purpose || ''),
      containerNo: String(record.container || ''),
      sealNo: String(record.seal || ''),
    }))
  }
  const volumes = volumeFormFromCell(rowValueByHeader('VOLUME')).records
  const truckValue = rowValueByHeader('TRUCK & CONT/SEAL INFO') || rowValueByHeader('TRUCKING INFO') || rowValueByHeader('CONT/SEAL INFO')
  const trucks = truckContFormFromCell(truckValue).records.filter((truck) =>
    truck.container || truck.seal || truck.truck || truck.driver,
  )
  const savedRows = Array.isArray(gsdModal.form.rows) ? gsdModal.form.rows as ClearanceRow[] : []
  const usedSaved = new Set<number>()
  const usedTrucks = new Set<number>()
  const sameVolumeKind = (left: any, right: any) =>
    upperText(left?.type || left?.contType) === upperText(right?.type || right?.contType) &&
    upperText(left?.purpose) === upperText(right?.purpose)
  const volumeRows = volumes.map((volume, volumeIndex) => {
    const savedIndex = savedRows.findIndex((item, index) => !usedSaved.has(index) && sameVolumeKind(item, volume))
    if (savedIndex >= 0) usedSaved.add(savedIndex)
    const saved = savedIndex >= 0 ? savedRows[savedIndex] : null
    let truckIndex = trucks.findIndex((truck, index) => !usedTrucks.has(index) && sameVolumeKind(truck, volume) && !!(truck.container || truck.seal))
    if (truckIndex < 0 && volumes.length === 1) truckIndex = trucks.findIndex((truck, index) => !usedTrucks.has(index) && !!(truck.container || truck.seal))
    if (truckIndex >= 0) usedTrucks.add(truckIndex)
    const truck = truckIndex >= 0 ? trucks[truckIndex] : null
    return {
      key: String(saved?.key || `vol-${volume.id || volumeIndex}`),
      type: String(volume.type || ''),
      purpose: String(volume.purpose || ''),
      containerNo: String(truck?.container || saved?.containerNo || ''),
      sealNo: String(truck?.seal || saved?.sealNo || ''),
    }
  })
  const extraTruckRows = trucks.flatMap((truck, index) => {
    if (usedTrucks.has(index) || !(truck.container || truck.seal)) return []
    const savedIndex = savedRows.findIndex((item, savedIndex) => !usedSaved.has(savedIndex) &&
      (item.containerNo === truck.container || item.sealNo === truck.seal))
    if (savedIndex >= 0) usedSaved.add(savedIndex)
    const saved = savedIndex >= 0 ? savedRows[savedIndex] : null
    return [{
      key: String(saved?.key || truck.id || `${truck.container || 'CONT'}-${truck.seal || index}`),
      type: String((truck as any).contType || (truck as any).type || saved?.type || ''),
      purpose: String((truck as any).purpose || saved?.purpose || ''),
      containerNo: String(truck.container || saved?.containerNo || ''),
      sealNo: String(truck.seal || saved?.sealNo || ''),
    }]
  })
  return [...volumeRows, ...extraTruckRows]
}
