const normalizeTruckContRecord = (item: any): TruckContRecord => ({
  id: String(item?.id || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`),
  selected: !!item?.selected,
  truck: String(item?.truck || item?.truckComp || item?.company || ''),
  container: String(item?.container || item?.containerNo || ''),
  contType: String(item?.contType || item?.containerType || ''),
  seal: String(item?.seal || item?.sealNo || ''),
  driver: String(item?.driver || item?.driverName || ''),
  drvId: String(item?.drvId || item?.driverId || ''),
  drvPhone: String(item?.drvPhone || item?.driverPhone || ''),
  eta1: String(item?.eta1 || item?.pickupDate || item?.date || ''),
  eta2: String(item?.eta2 || item?.pickupTime || item?.time || ''),
  gdate: String(item?.gdate || item?.returnDate || item?.ret || item?.gateinDate || ''),
  gtime: String(item?.gtime || item?.gateinTime || ''),
  epodSign: String(item?.epodSign || item?.epod || ''),
  epodUrl: String(item?.epodUrl || ''),
  epodReceiver: String(item?.epodReceiver || ''),
})
const truckContFormFromCell = (value: any) => {
  const parsed = parseJsonCell(value, null as any)
  const locked = !!(parsed && typeof parsed === 'object' && 'form' in parsed && (parsed as any).form?.locked)
  const sentAt = String(parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form?.sentAt || '' : '')
  let source: any[] = []
  if (Array.isArray(parsed)) source = parsed
  else if (parsed && typeof parsed === 'object' && Array.isArray((parsed as any).records)) source = (parsed as any).records
  else if (parsed && typeof parsed === 'object' && 'form' in parsed && Array.isArray((parsed as any).form?.records)) source = (parsed as any).form.records
  else if (parsed && typeof parsed === 'object' && 'form' in parsed) source = [(parsed as any).form]
  else if (parsed && typeof parsed === 'object') source = [parsed]
  const records = source.map(normalizeTruckContRecord).filter((item) =>
    item.truck || item.container || item.contType || item.seal || item.driver || item.eta1 || item.eta2 || item.gdate || item.gtime || item.epodSign,
  )
  return { records: records.length ? records : [emptyTruckContRecord()], locked, sentAt }
}
const seedTruckContFromVolume = (form: any) => {
  const volume = volumeFormFromCell(rowValueByHeader('VOLUME'))
  const expected: string[] = (volume.records || []).map((record: any) => {
    const type = String(record.type || '').replace(/\s+/g, '').toUpperCase()
    const purpose = String(record.purpose || '').replace(/\s+/g, '').toUpperCase()
    return purpose && !type.endsWith(purpose) ? `${type}${purpose}` : type
  })
  if (!expected.length) return form
  const current = Array.isArray(form.records) ? form.records : []
  form.records = expected.map((contType, index) => ({ ...emptyTruckContRecord(), ...(current[index] || {}), contType }))
  return form
}
