    driverDetail.rows = clientDetailRows(target).map((item) => [item.label, item.value] as [string, string])
    driverDetail.open = true
  } catch (error) {
    console.error('Could not load Truck Company detail', error)
    showToast('Could not load Truck Company detail')
  }
}
const openEpodSignDetail = (record: TruckContRecord) => {
  if (!record.epodSign) return
  if (record.epodUrl) {
    window.open(record.epodUrl, '_blank', 'noopener,noreferrer')
    return
  }
  epodSignDetail.container = record.container || ''
  epodSignDetail.seal = record.seal || ''
  epodSignDetail.signedAt = record.epodSign
  epodSignDetail.open = true
}
const refreshTruckEpodStatuses = async () => {
  if (!gsdModal.open || !isTruckContModal()) return
  let changed = false
  await Promise.all(truckContRecords().map(async (record) => {
    if (!record.epodUrl || record.epodSign) return
    const token = String(record.epodUrl).split('/epod/')[1]?.split(/[?#]/)[0]
    if (!token) return
    try {
      const result = await props.request(`/public/epod/${encodeURIComponent(token)}`)
      const data = result?.data || result
      if (data?.status === 'SIGNED' && data?.signedAt) {
        record.epodSign = String(data.signedAt)
        record.epodReceiver = String(data.receiverName || '')
        changed = true
      }
    } catch (error) {
      console.warn('Could not refresh ePOD status', error)
    }
  }))
  if (changed) {
    gsdModal.form.initialRecords = truckContSnapshot(truckContRecords())
    persistTruckContCell(false)
  }
}
const openCcdEmail = () => {
  ccdEmail.value = ''
  ccdEmail.hint = ''
  ccdEmail.open = true
}
const sendCcdEmail = () => {
  const raw = ccdEmail.value.trim()
  if (!raw) { ccdEmail.hint = 'Please enter at least one email address.'; return }
  const list = raw.split(',').map((item) => item.trim()).filter(Boolean)
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  const bad = list.filter((item) => !re.test(item))
  if (bad.length) { ccdEmail.hint = `Invalid email: ${bad.join(', ')}`; return }
  ccdEmail.open = false
  showToast(`Cleared docs sent to ${list.length} recipient(s)`)
}
const pickupReturnRecords = () => (Array.isArray(gsdModal.form.records) ? gsdModal.form.records : []) as PickupReturnRecord[]
