const siSubmitContainers = () => Array.isArray(gsdModal.form.containers) ? gsdModal.form.containers : []
const rawSiSourceValue = (label: string) => {
  const target = upperText(label).trim()
  const column = (rows.value[0] || []).findIndex((_: any, index: number) => normalizedHeaderLabel(index) === target)
  return column >= 0 ? rows.value[gsdModal.row]?.[column] : ''
}
const siClientTextFromSource = (value: any) => {
  const parsed = typeof value === 'object' && value !== null ? value : parseJsonCell(value, null as any)
  const source = parsed && typeof parsed === 'object' && ('client' in parsed || 'CLIENT' in parsed)
    ? (parsed as any).client || (parsed as any).CLIENT
    : parsed
  if (!source || typeof source !== 'object') return ''
  const field = (...names: string[]) => names.map((name) => source?.[name]).find((item) => item != null)
  const lines = [
    ['COMPANY NAME', field('companyName', 'COMPANYNAME', 'company', 'COMPANY')],
    ['TAX ID', field('taxId', 'TAXID', 'taxID', 'TAX ID', 'taxCode', 'TAXCODE')],
    ['ADDRESS', field('address', 'ADDRESS')],
    ['CITY / PROVINCE', field('city', 'CITY', 'cityProvince', 'CITYPROVINCE')],
    ['COUNTRY', field('country', 'COUNTRY')],
    ['PIC NAME', field('picName', 'PICNAME', 'pic', 'PIC')],
    ['EMAIL', field('email', 'EMAIL')],
    ['PHONE', field('phone', 'PHONE')],
  ].map(([label, item]) => `${label}: ${String(item || '').trim() || '-'}`)
  return lines.join('\n')
}
const toggleSiPartyCopy = (party: 'SHIPPER' | 'CNEE') => {
  const isShipper = party === 'SHIPPER'
  const copyKey = isShipper ? 'copyShipper' : 'copyConsignee'
  const valueKey = isShipper ? 'shipper' : 'consignee'
  const backupKey = isShipper ? 'shipper' : 'consignee'
  if (gsdModal.form[copyKey]) {
    siPartyCopyBackup[backupKey] = String(gsdModal.form[valueKey] || '')
    const detail = siClientTextFromSource(rawSiSourceValue(party))
    if (!detail) {
      gsdModal.form[copyKey] = false
      showToast(`No linked ${isShipper ? 'Shipper' : 'Consignee'} Full Detail found`)
      return
    }
    gsdModal.form[valueKey] = detail
  } else {
    gsdModal.form[valueKey] = siPartyCopyBackup[backupKey]
  }
}
const siRouteDisplay = (value: any, side: 'pol' | 'pod') => {
  const route = routeFromCellValue(value)
  if (!route) return ''
  const known = routeDirectory.value.find((item) => upperText(item.polCode) === upperText(route.polCode) && upperText(item.podCode) === upperText(route.podCode)) || route
  const place = side === 'pol' ? known.pol : known.pod
  const country = side === 'pol' ? known.polC : known.podC
  // SI must show the readable location (Shanghai, China), never the port code.
  if (!place) return ''
  const displayCase = (entry: any) => {
    const text = String(entry || '').trim()
    if (!text || /^[A-Z]{2,3}$/.test(text)) return text
    return text.toLocaleLowerCase().replace(/\b\p{L}/gu, (letter) => letter.toLocaleUpperCase())
  }
  return [displayCase(place), displayCase(country)].filter(Boolean).join(', ')
}
const siDateFromSource = (value: any) => {
  const raw = String(value || '').trim()
  if (!raw) return ''
  const iso = raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/)
  if (iso) return `${iso[1]}-${String(iso[2]).padStart(2, '0')}-${String(iso[3]).padStart(2, '0')}`
  const dmy = raw.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/)
  return dmy ? `${dmy[3]}-${String(dmy[2]).padStart(2, '0')}-${String(dmy[1]).padStart(2, '0')}` : raw
}
const syncSiSubmitFromSources = () => {
  // `locked` only controls whether the submitted SI can be edited. Linked
  // shipment fields must still refresh whenever the modal is opened; otherwise
  // an older saved SI keeps blank/stale ETD and route values forever.
  if (!isLinkedFclDcdSiModal()) return
  const shipper = siClientTextFromSource(rawSiSourceValue('SHIPPER'))
  const consignee = siClientTextFromSource(rawSiSourceValue('CNEE'))
  if (gsdModal.form.copyShipper && shipper) gsdModal.form.shipper = shipper
  if (gsdModal.form.copyConsignee && consignee) gsdModal.form.consignee = consignee
  const booking = bookingDetailValue(rawSiSourceValue('BC NO#'))
  if (booking) gsdModal.form.bookingNo = booking
  const vessel = vesselFromCellValue(rawSiSourceValue('VESSEL/VOYAGE'))
  if (vessel) gsdModal.form.vessel = [vessel.name, vessel.voyage].filter(Boolean).join(' / ')
  const etd = siDateFromSource(rawSiSourceValue('ETD'))
  if (etd) gsdModal.form.depDate = etd
  const routeValue = rawSiSourceValue('ROUTE')
  const pol = siRouteDisplay(routeValue, 'pol')
  const pod = siRouteDisplay(routeValue, 'pod')
  if (pol) gsdModal.form.pol = pol
  if (pod) gsdModal.form.pod = pod
  const truckValue = rawSiSourceValue('TRUCK & CONT/SEAL INFO') || rawSiSourceValue('TRUCKING INFO')
  const linked = truckContFormFromCell(truckValue).records.filter((item) => item.container || item.seal || item.contType)
  if (linked.length) {
    const saved = siSubmitContainers()
    gsdModal.form.containers = linked.map((item, index) => ({
      ...newSiSubmitContainer(),
      ...(saved[index] || {}),
      contNo: item.container || '',
      contType: item.contType || '',
      sealNo: item.seal || '',
    }))
  }
}
const siSubmitTotal = (field: 'qty' | 'gw' | 'mea') => {
  const total = siSubmitContainers().reduce((sum: number, container: any) => sum + (Number.parseFloat(String(container?.[field] || '0')) || 0), 0)
  const precision = field === 'mea' ? 3 : 2
  return String(Number(total.toFixed(precision)))
}
const addSiSubmitContainer = () => {
  if (!gsdModal.editing) return
  if (!Array.isArray(gsdModal.form.containers)) gsdModal.form.containers = []
