const siExportingPdf = ref(false)
const exportSiSubmitPdf = async () => {
  if (!gsdModal.form.locked || siExportingPdf.value) return
  const sheet = document.querySelector<HTMLElement>('.gsd-si-modal .si-sheet')
  if (!sheet) return
  siExportingPdf.value = true
  try {
    await nextTick()
    const [{ default: html2canvas }, { jsPDF }] = await Promise.all([
      import('html2canvas'),
      import('jspdf'),
    ])
    const canvas = await html2canvas(sheet, {
      scale: 2,
      useCORS: true,
      backgroundColor: '#ffffff',
      logging: false,
      width: sheet.scrollWidth,
      height: sheet.scrollHeight,
      windowWidth: Math.max(document.documentElement.clientWidth, sheet.scrollWidth),
      windowHeight: Math.max(document.documentElement.clientHeight, sheet.scrollHeight),
      onclone: (clonedDocument) => {
        const clonedSheet = clonedDocument.querySelector<HTMLElement>('.gsd-si-modal .si-sheet')
        if (!clonedSheet) return
        clonedSheet.style.width = `${sheet.scrollWidth}px`
        clonedSheet.style.maxWidth = 'none'
        clonedSheet.style.margin = '0'
        const sourceControls = Array.from(sheet.querySelectorAll<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>('input,textarea,select'))
        const clonedControls = Array.from(clonedSheet.querySelectorAll<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>('input,textarea,select'))
        clonedControls.forEach((control, index) => {
          const source = sourceControls[index]
          if (!source) return
          if (source instanceof HTMLInputElement && ['radio', 'checkbox'].includes(source.type)) {
            control.toggleAttribute('checked', source.checked)
            return
          }
          const value = source instanceof HTMLSelectElement
            ? source.selectedOptions[0]?.textContent || source.value
            : source.value
          const display = clonedDocument.createElement('div')
          const style = window.getComputedStyle(source)
          display.textContent = value || ''
          display.className = `${control.className || ''} si-pdf-field-value`
          display.style.boxSizing = 'border-box'
          display.style.width = '100%'
          display.style.minHeight = `${Math.max(source.offsetHeight, 30)}px`
          display.style.height = 'auto'
          display.style.border = style.border
          display.style.borderRadius = style.borderRadius
          display.style.background = style.backgroundColor
          display.style.padding = style.padding
          display.style.color = style.color
          display.style.font = style.font
          display.style.lineHeight = style.lineHeight === 'normal' ? '1.35' : style.lineHeight
          display.style.textAlign = style.textAlign
          display.style.whiteSpace = source instanceof HTMLTextAreaElement ? 'pre-wrap' : 'normal'
          display.style.overflowWrap = 'anywhere'
          display.style.wordBreak = 'break-word'
          if (source instanceof HTMLTextAreaElement) {
            display.style.paddingTop = '6px'
            display.style.paddingBottom = '6px'
          } else {
            display.style.display = 'flex'
            display.style.alignItems = 'center'
            display.style.paddingTop = '0'
            display.style.paddingBottom = '0'
          }
          if (control.closest('.si-table')) {
            display.style.justifyContent = 'center'
          }
          control.replaceWith(display)
        })
        clonedSheet.querySelectorAll<HTMLElement>('.si-party-head label,.si-attachment,.si-add-container,input[type="file"]').forEach((control) => control.remove())
      },
    })
    if (!canvas.width || !canvas.height) throw new Error('The SI PDF page could not be rendered')
    const pdf = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait', compress: true })
    const margin = 10
    const pageWidth = 210 - margin * 2
    const pageHeight = 297 - margin * 2
    const pagePixelHeight = Math.floor((canvas.width * pageHeight) / pageWidth)
    let sourceY = 0
    let pageIndex = 0
    while (sourceY < canvas.height) {
      const sliceHeight = Math.min(pagePixelHeight, canvas.height - sourceY)
      const pageCanvas = document.createElement('canvas')
      pageCanvas.width = canvas.width
      pageCanvas.height = sliceHeight
      const context = pageCanvas.getContext('2d')
      if (!context) throw new Error('The SI PDF page could not be prepared')
      context.fillStyle = '#ffffff'
      context.fillRect(0, 0, pageCanvas.width, pageCanvas.height)
      context.drawImage(canvas, 0, sourceY, canvas.width, sliceHeight, 0, 0, canvas.width, sliceHeight)
      if (pageIndex > 0) pdf.addPage('a4', 'portrait')
      const imageHeight = (sliceHeight * pageWidth) / canvas.width
      pdf.addImage(pageCanvas.toDataURL('image/jpeg', 0.98), 'JPEG', margin, margin, pageWidth, imageHeight, undefined, 'FAST')
      sourceY += sliceHeight
      pageIndex += 1
    }
    const reference = String(gsdModal.form.bookingNo || rowValueByHeader('JOB NO#') || 'DOCUMENT').trim().replace(/[^a-zA-Z0-9_-]+/g, '_')
    pdf.save(`SI_${reference}.pdf`)
  } catch (error) {
    console.error('Unable to export SI PDF', error)
    showToast('Unable to export SI PDF. Please try again.')
  } finally {
    siExportingPdf.value = false
  }
}

