const rowValueByHeader = (label: string) => {
  const target = upperText(label).trim()
  let column = -1
  for (let index = 0; index < columnCount.value; index += 1) {
    if (normalizedHeaderLabel(index) === target) {
      column = index
      break
    }
  }
  if (column < 0) return ''
  const raw = rows.value[gsdModal.row]?.[column]
  return clientCellText(raw) || String(raw || '').trim()
}
const preAlertFileName = (file: any) => typeof file === 'string' ? file : String(file?.name || '')
const normalizePreAlertDoc = (doc: any, fallback: PreAlertDoc): PreAlertDoc => ({
  key: String(doc?.key || fallback.key),
  label: String(doc?.label || fallback.label),
  checked: !!doc?.checked,
  name: String(doc?.name || fallback.name || ''),
  custom: !!(doc?.custom || fallback.custom),
})
const preAlertFormFromCell = (value: any) => {
  const parsed = parseJsonCell(value, null as any)
  const form = parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form || {} : parsed && typeof parsed === 'object' ? parsed : {}
  const files = Object.entries(form.files || {}).reduce((acc, [key, file]) => {
    const name = preAlertFileName(file)
    const url = typeof file === 'object' && file ? String((file as any).url || '') : ''
    if (name) acc[key] = url ? { name, url } : { name }
    return acc
  }, {} as Record<string, PreAlertFile>)
  const savedDocs = Array.isArray(form.docs) ? form.docs : []
  const defaultDocs = defaultPreAlertDocs()
  const docs = defaultDocs.map((fallback) => {
    const match = savedDocs.find((doc: any) => String(doc?.key || '') === fallback.key)
    return normalizePreAlertDoc(match || { checked: !!form.docChk?.[fallback.key], name: fallback.key === 'ot' ? form.otherName || '' : '' }, fallback)
  })
  savedDocs.forEach((doc: any) => {
    const key = String(doc?.key || '')
    if (key && !docs.some((item) => item.key === key)) docs.push(normalizePreAlertDoc(doc, { key, label: 'OTHER', checked: false, name: '', custom: true }))
  })
  const efa = preAlertForwardingOption()
  return {
    destAgent: rowValueByHeader('DESTINATION AGENT') || rowValueByHeader('DEST. AGENT') || '....',
    chk: {
      mc: !!form.chk?.mc,
      hc: !!form.chk?.hc,
      mr: !!form.chk?.mr,
      hr: !!form.chk?.hr,
    },
    at: {
      mc: String(form.at?.mc || ''),
      hc: String(form.at?.hc || ''),
      mr: String(form.at?.mr || ''),
      hr: String(form.at?.hr || ''),
    },
    files,
    docs,
    remarks: String(form.remarks || ''),
    sent: !!form.sent,
    sentAt: String(form.sentAt || ''),
    targetService: String(form.targetService || ''),
    locked: !!form.locked,
    // FCL uses the separate Attach Dest. Clearance Docs dialog instead of this inline block.
    showDocs: opsParts.value?.mode !== 'FCL' && (efa === 'DDU' || efa === 'DDP') && !(isExwEcdSheet() && opsParts.value?.mode !== 'FCL'),
  }
}
const loadPreAlertDestinationAgent = async () => {
  // Workbooks use both labels. Read the already-linked trader from either
  // column instead of treating DEST. AGENT as a missing manual input.
  const raw = rowValueByHeader('DESTINATION AGENT') || rowValueByHeader('DEST. AGENT')
  const parsed = parseJsonCell(raw, null as any)
  const embedded = parsed && typeof parsed === 'object' ? ((parsed as any).client || (parsed as any).CLIENT || parsed) : null
  const embeddedName = String(embedded?.fullName || embedded?.FULLNAME || embedded?.companyName || embedded?.COMPANYNAME || '').trim()
  if (embeddedName) {
    gsdModal.form.destAgent = embeddedName
    return
  }
  const code = clientCellText(raw)
  if (!code) return
  try {
    const res = await props.request(`/entities/clients?field=namecode&search=${encodeURIComponent(code)}&role=DESTINATION%20AGENT&limit=8`)
    const match = (Array.isArray(res?.items) ? res.items : []).map(normalizeClientRecord).find((item: GsdClientRecord) => upperText(item.namecode) === upperText(code))
    gsdModal.form.destAgent = match?.companyName || (match as any)?.fullName || code
  } catch {
    gsdModal.form.destAgent = code
  }
}
