  const sourceLink = ensureOpsShipmentLink(currentHeader, currentRow, row, settings.value)
  const identity = rowIdentity(currentHeader, currentRow)
  const values = new Map<string, any>()
  currentHeader.forEach((label, index) => {
    if (String(currentRow[index] ?? '').trim()) values.set(label, currentRow[index])
  })
  for (const dept of orderedOpsDepts(parsed.base, parsed.type, parsed.mode)) {
    if (dept === parsed.dept) continue
    const key = opsLeafKey(parsed.base, parsed.mode, parsed.type, dept as any)
    try {
      const sheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(key))}`)
      const header = opsHeaderFor(parsed.base, parsed.mode, dept as any, parsed.type)
      const extracted = extractWorkbookRows(Array.isArray(sheet.rows) ? sheet.rows.map((item: any[]) => [...item]) : [], sheet)
      const aligned = alignRowsToHeader(extracted.rows, header).rows
      const links = extracted.settings?.opsRowLinks || sheet.settings?.opsRowLinks || {}
      const match = aligned.find((item, index) => index > 0 && (
        (sourceLink && String(links[String(index)] || '').trim() === sourceLink)
        || (identity && rowIdentity(header, item) === identity)
      ))
      if (!match) continue
      header.forEach((label, index) => {
        if (String(match[index] ?? '').trim()) values.set(label, match[index])
      })
    } catch (error: any) {
      if (requestStatus(error) !== 404) console.warn(`Could not collect ${dept} data for destination record`, error)
    }
  }
  const sending = preAlertFormFromCell(values.get('PRE-ALERT SENDING'))
  const freetime = freetimeFormFromCell(values.get('FREETIME CONFIRMATION'))
  const latestFreetime = [...(freetime.records || [])].sort((left: any, right: any) => Number(right.ts || 0) - Number(left.ts || 0))[0]
  if (values.has('PRE-ALERT SENDING') || latestFreetime) {
    values.set('PRE-ALERT CONFIRMATION', JSON.stringify({ form: {
      mblConfirmed: !!sending.chk?.mc,
      mblConfirmedAt: String(sending.at?.mc || ''),
      hblConfirmed: !!sending.chk?.hc,
      hblConfirmedAt: String(sending.at?.hc || ''),
      dem: latestFreetime ? String(latestFreetime.dem ?? '') : '',
      det: latestFreetime ? String(latestFreetime.det ?? '') : '',
      history: latestFreetime ? [{ id: `linked-${latestFreetime.id}`, dem: String(latestFreetime.dem ?? 0), det: String(latestFreetime.det ?? 0), status: 'Applied' }] : [],
      linkedFromOrigin: true,
    } }))
  }
  const header = [...values.keys()]
  return { header, row: header.map((label) => values.get(label) ?? '') }
}
const sendPreAlert = async () => {
  if (!gsdModal.form.locked) {
    showToast('Save before sending')
    return
  }
  const targetService = preAlertTargetService()
  if (!['DO', 'DAP', 'DDU', 'DDP'].includes(targetService)) {
    showToast(`Select the destination service in ${upperText(opsParts.value?.type || 'SERVICE')}+ before sending`)
    return
  }
  const destinationCell = preAlertSourceCell('DESTINATION AGENT', 'DEST. AGENT')
  const destinationEmail = linkedEntityEmail(destinationCell)
  if (!destinationEmail) {
    showToast('Destination Agent does not have an email in Traders & Suppliers')
    return
  }
  const ok = await askConfirm('Send pre-alert to destination agent?', '', { okText: 'YES', cancelText: 'NO', tone: 'remove' })
  if (!ok) return
  dispatchLoading.value = `Creating ${targetService} record and sending pre-alert...`
  try {
    const source = opsParts.value
    if (!source) throw new Error('The current Operations sheet is invalid')
    const sentAt = formatLocalDateTime()
    const collectedSource = await crossServiceSourceSnapshot(gsdModal.row)
    const sourceHeader = collectedSource.header
    const sourceRow = collectedSource.row
    // Overseas pre-alert enters the import workflow directly at ICD. It is
    // already a real shipment, so creating an intermediate GSD record would
    // duplicate the job and does not match the requested operation flow.
    const linked = await transferRowToNextDept(gsdModal.row, 'ICD', sentAt, false, {
      key: opsLeafKey(source.base, source.mode, targetService as any, 'GSD'),
      country: loadedCountryId.value,
      header: sourceHeader,
      row: sourceRow,
      settings: {
        ...settings.value,
        crossServiceInboundDirect: true,
        crossServiceOriginType: upperText(source.type),
      },
    })
    if (!linked) throw new Error(`Could not create the linked ${targetService} record`)
    const result = await props.request('/workbook/send-pre-alert-email', {
      method: 'POST',
      body: {
        to: destinationEmail,
        destinationAgent: gsdModal.form.destAgent || clientCellText(destinationCell),
        jobNo: rowValueByHeader('JOB NO#') || rowValueByHeader('REF#'),
        shipmentType: `${source.mode} ${source.type}`,
        service: targetService,
        details: {
          client: emailCellDisplayValue('CLIENT', rowValueByHeader('CLIENT')),
          shipper: emailCellDisplayValue('SHIPPER', rowValueByHeader('SHIPPER')),
          cnee: emailCellDisplayValue('CNEE', rowValueByHeader('CNEE')),
          originAgent: emailCellDisplayValue('ORIGIN AGENT', rowValueByHeader('ORIGINAL AGENT') || rowValueByHeader('ORIGIN AGENT')),
          carrier: emailCellDisplayValue('LINER', rowValueByHeader('LINER') || rowValueByHeader('AIRLINE')),
          bookingNo: emailCellDisplayValue('BC NO#', rowValueByHeader('BC NO#')),
          refNo: rowValueByHeader('REF#'), hblNo: emailCellDisplayValue('HBL NO#', rowValueByHeader('HBL NO#')) || rowValueByHeader('HAWB NO#'),
          mblNo: rowValueByHeader('MBL NO#') || rowValueByHeader('MAWB NO#'), etd: rowValueByHeader('ETD'),
          eta: rowValueByHeader('ETA'), route: emailCellDisplayValue('ROUTE', rowValueByHeader('ROUTE')),
          vessel: emailCellDisplayValue('VESSEL/VOYAGE', rowValueByHeader('VESSEL/VOYAGE')) || rowValueByHeader('FLIGHT NO#'),
          volume: emailCellDisplayValue('VOLUME', rowValueByHeader('VOLUME')), remarks: gsdModal.form.remarks,
        },
        documents: [
          ...Object.values(gsdModal.form.files || {}).map((file: any) => preAlertFileName(file)),
          ...[preDocsData().ci, preDocsData().pl, ...(preDocsData().others || [])].flatMap((item: any) => (item.files || []).map((file: any) => file.name)),
        ].filter(Boolean),
      },
    })
    gsdModal.form.sent = true
    gsdModal.form.sentAt = String(result?.data?.sentAt || new Date().toISOString())
    gsdModal.form.targetService = targetService
    gsdModal.form.locked = true
    gsdModal.editing = false
    persistPreAlert(false)
    await saveSheet()
  } catch (error: any) {
    showToast(error?.data?.message || error?.message || 'Could not send pre-alert')
  } finally {
    dispatchLoading.value = ''
  }
}
const volumeRecords = () => (Array.isArray(gsdModal.form.records) ? gsdModal.form.records : []) as VolumeRecord[]
const volumeSummaryLines = (value: any) => {
  const records = volumeFormFromCell(value).records || []
  return records.map((record: any) => {
    const quantity = String(record.volume ?? '').trim()
    const size = String(record.type ?? '').trim().replace(/\s+/g, '').toUpperCase()
    const purpose = String(record.purpose ?? '').trim().replace(/\s+/g, '').toUpperCase()
    if (!quantity || !size) return ''
    const suffix = purpose && !size.endsWith(purpose) ? `${size}${purpose}` : size
    return `${quantity}X${suffix}`
  }).filter(Boolean)
}
const volumeSummaryText = (value: any) => volumeSummaryLines(value).join('\n')
const freetimeRecords = () => {
  const list = Array.isArray(gsdModal.form.records) ? gsdModal.form.records : []
