}
const volumeFormFromCell = (value: any) => {
  const parsed = parseJsonCell(value, null as any)
  const form = parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form || {} : {}
  const storedTypeOptions = Array.isArray(form.typeOptions) ? form.typeOptions.map((option: any) => String(option)) : []
  const legacyContainerDefaults = storedTypeOptions.length === 3 && ['20', '40', '45'].every((option) => storedTypeOptions.includes(option))
  const typeOptions = isAirSheet() && (!storedTypeOptions.length || legacyContainerDefaults)
    ? ['PLTS', 'CTNS', 'PCES']
    : storedTypeOptions.length ? storedTypeOptions : ['20', '40', '45']
  let records = Array.isArray(form.records) ? form.records : []
  if (!records.length && (form.volume || form.type || form.purpose)) {
    records = [{ id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, volume: Number(form.volume || 0), type: String(form.type || ''), purpose: String(form.purpose || '') }]
  }
  return {
    volume: '',
    type: '',
    purpose: '',
    gw: '',
    gwUnit: 'KGS',
    mea: '',
    hint: '',
    selectedId: '',
    editId: '',
    addOption: '',
    newOption: '',
    typeOptions,
    purposeOptions: Array.isArray(form.purposeOptions) && form.purposeOptions.length ? form.purposeOptions : ['GP', 'HQ', 'OT', 'FR', 'RF', 'TK'],
    records: records.map((item: any, index: number) => ({
      id: String(item.id || `${Date.now()}-${index}`),
      volume: Number(item.volume || 0),
      type: String(item.type || ''),
      purpose: String(item.purpose || ''),
      gw: String(item.gw ?? ''),
      gwUnit: String(item.gwUnit || ''),
      mea: String(item.mea ?? ''),
    })),
  }
}
const freetimeFormFromCell = (value: any) => {
  const parsed = parseJsonCell(value, null as any)
  const form = parsed && typeof parsed === 'object' && 'form' in parsed ? (parsed as any).form || {} : {}
  let records = Array.isArray(form.records) ? form.records : []
  if (!records.length && (form.dem !== undefined || form.det !== undefined) && (form.dem !== '' || form.det !== '')) {
    records = [{ id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, dem: Number(form.dem || 0), det: Number(form.det || 0), ts: Number(form.ts || Date.now()) }]
  }
  return {
    dem: '',
    det: '',
    hint: '',
    selectedId: '',
    editId: '',
    records: records.map((item: any, index: number) => ({
      id: String(item.id || `${Date.now()}-${index}`),
      dem: Number(item.dem || 0),
      det: Number(item.det || 0),
      ts: Number(item.ts || Date.now() - index),
    })),
  }
}
const freetimeSummaryText = (value: any) => {
  const records = freetimeFormFromCell(value).records || []
  const record: any = records[records.length - 1]
  if (!record || (record.dem === 0 && record.det === 0)) return ''
  return `${record.dem || 0}/${record.det || 0}`
}
