const saveVolumeRecord = () => {
  if (isReadonlyTcdVolumeModal()) return
  const raw = String(gsdModal.form.volume || '').trim()
  const volume = Number(raw)
  const type = String(gsdModal.form.type || '')
  const purpose = String(gsdModal.form.purpose || '')
  if (!raw || !Number.isInteger(volume) || volume < 1) {
    gsdModal.form.hint = 'Volume must be a positive integer'
    return
  }
  if (!type) {
    gsdModal.form.hint = isLclSheet() ? 'Select a UNIT' : 'Select a TYPE'
    return
  }
  if (!purpose && !isLclSheet()) {
    gsdModal.form.hint = 'Select a PURPOSE'
    return
  }
  const gw = String(gsdModal.form.gw ?? '').trim()
  const gwUnit = String(gsdModal.form.gwUnit || 'KGS')
  const mea = String(gsdModal.form.mea ?? '').trim()
  const editId = String(gsdModal.form.editId || '')
  const list = volumeRecords().slice()
  if (editId) {
    const target = list.find((item) => item.id === editId)
    if (target) {
      target.volume = volume
      target.type = type
      target.purpose = purpose
      ;(target as any).gw = gw
      ;(target as any).gwUnit = gwUnit
      ;(target as any).mea = mea
    }
  } else {
    list.push({ id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, volume, type, purpose, gw, gwUnit, mea } as any)
  }
  gsdModal.form.records = list
  persistVolumeForm(true)
  clearVolumeForm()
}
const editVolumeRecord = () => {
  if (isReadonlyTcdVolumeModal()) return
  const item = volumeRecords().find((record) => record.id === gsdModal.form.selectedId)
  if (!item) {
