const addDealtFiles = async (event: Event) => {
  if (!gsdModal.editing) return
  const input = event.target as HTMLInputElement
  const files = Array.from(input.files || [])
  if (!files.length) return
  dispatchLoading.value = files.length > 1 ? `Uploading ${files.length} DEALT INFO files...` : `Uploading ${files[0].name}...`
  try {
    for (const file of files) {
      const uploaded = await uploadAdminAttachment(file)
      const url = String(uploaded?.url || '').trim()
      if (!url) throw new Error(`The server did not return a URL for ${file.name}`)
      gsdModal.dealt.files.push({
        name: String(uploaded?.name || file.name).trim(),
        url,
        mimeType: String(uploaded?.mimeType || file.type || ''),
        size: Number(uploaded?.size || file.size || 0),
      })
    }
  } catch (error: any) {
    showToast(String(error?.data?.message || error?.message || 'Could not upload the DEALT INFO attachment'))
  } finally {
    dispatchLoading.value = ''
    input.value = ''
  }
}
const viewDealtFile = (file: { name: string; url?: string }) => {
