const persistLinkedClient = async (client: GsdClientRecord) => {
  if (gsdModal.kind !== 'client' || !rows.value[gsdModal.row]) return
  const clean = normalizeClientRecord(client)
  dispatchLoading.value = `Linking ${gsdModal.clientRole || 'record'}...`
  try {
  const value = JSON.stringify({ client: clean })
  const sourceKey = activeKey.value
  const sourceCountry = loadedCountryId.value
  const sourceHeader = (rows.value[0] || []).map((item) => String(item ?? '').trim())
  const sourceRow = rows.value[gsdModal.row] || []
  const sourceIdentity = rowIdentity(sourceHeader, sourceRow)
  const sourceLink = opsShipmentLink(sourceHeader, sourceRow, gsdModal.row, settings.value)
  const columnLabel = normalizedHeaderLabel(gsdModal.column)
  let targetRow = gsdModal.row
  rows.value[targetRow][gsdModal.column] = value
  const saved = await saveSheet()
  if (!saved && isVisibleSheet(sourceKey, sourceCountry)) {
    const refreshedHeader = (rows.value[0] || []).map((item) => String(item ?? '').trim())
    const refreshedColumn = refreshedHeader.findIndex((item) => upperText(item) === columnLabel)
    const refreshedLinks = settings.value?.opsRowLinks || {}
    const matchedRow = rows.value.findIndex((item, index) => index > 0 && (
      (sourceLink && String(refreshedLinks[String(index)] || '').trim() === sourceLink)
      || (sourceIdentity && rowIdentity(refreshedHeader, item) === sourceIdentity)
    ))
    if (matchedRow > 0 && refreshedColumn >= 0) {
      targetRow = matchedRow
      rows.value[targetRow][refreshedColumn] = value
      gsdModal.row = targetRow
      gsdModal.column = refreshedColumn
      if (!await saveSheet()) {
        showToast(`Could not link ${clean.namecode || clean.id || clean.companyName}. Please try again`)
        return
      }
    } else {
      showToast('The worksheet row changed. Please open the record and try again')
      return
    }
  }
  // Selecting an existing party is also a real source-cell change. Propagate
  // it exactly like the create/edit path so every already-linked department
  // receives the new Shipper/CNEE/Agent/Liner record.
  await mirrorFclLinkedCell(targetRow, gsdModal.column)
  closeGsdModal()
  } finally {
    dispatchLoading.value = ''
  }
}
const findExistingClient = async (data: ReturnType<typeof emptyClientForm>, role: string) => {
  // Company names are not unique: different branches/roles may legitimately
  // use the same legal or abbreviated company name. Only NAMECODE identifies
  // a duplicate client for the selected role (the API enforces the same rule).
  const probes = [['namecode', data.namecode]] as const
  for (const [field, value] of probes) {
    const term = upperText(value)
    if (!term) continue
    const records = await props.request(`/records?country=${encodeURIComponent(countryViewId())}&page=traders_traders&search=${encodeURIComponent(term)}&limit=1000`)
    const recordMatch = (Array.isArray(records?.items) ? records.items : []).find((record: any) => {
      const row = record?.data || {}
      const candidate = field === 'namecode' ? row.namecode : row.company
      const roles = Array.isArray(row.roles) ? row.roles : String(row.role || '').split(',')
      return upperText(candidate) === term && roles.map(upperText).includes(upperText(role))
    })
    if (recordMatch) {
      const row = recordMatch.data || {}
      return normalizeClientRecord({
        id: row.id,
        namecode: row.namecode,
        companyName: row.company,
        address: row.address,
        city: row.city,
        country: row.country,
        picName: row.pic,
        email: row.email,
        phone: row.phone,
        status: row.status,
        roles: row.roles || [row.role],
      })
    }
    const res = await props.request(`/entities/clients?field=${encodeURIComponent(field)}&search=${encodeURIComponent(term)}&role=${encodeURIComponent(role)}&limit=50`)
    const found = (Array.isArray(res?.items) ? res.items : []).map(normalizeClientRecord).find((item: GsdClientRecord) => {
