      return upperText(candidate) === term
    })
    if (found) return found
  }
  return null
}
const linkClientToTraders = async (client: GsdClientRecord) => {
  if (client.roles?.map(upperText).includes('CLIENT') !== true) return
  const country = countryViewId()
  const page = 'traders_traders'
  const search = upperText(client.namecode || client.id || client.companyName)
  const existingResponse = await props.request(`/records?country=${encodeURIComponent(country)}&page=${encodeURIComponent(page)}&search=${encodeURIComponent(search)}&limit=1000`)
  const existing = (Array.isArray(existingResponse?.items) ? existingResponse.items : []).find((record: any) => {
    const data = record?.data || {}
    return upperText(data.namecode) === upperText(client.namecode) || upperText(data.id) === upperText(client.id)
  })
  if (existing) return
  await props.request('/records', {
    method: 'POST',
    body: {
      country,
      page,
      kind: 'traders-suppliers',
      sortOrder: 0,
      data: {
        recdate: new Date().toISOString().slice(0, 10),
        id: client.id,
        namecode: client.namecode,
        role: 'CLIENT',
        roles: ['CLIENT'],
        gsd: currentTraderCreator(),
        company: client.companyName,
        taxid: '',
        address: client.address,
        city: client.city,
        country: client.country,
        pic: client.picName,
        email: client.email,
        phone: client.phone,
        status: upperText(client.status) === 'INACTIVE' ? 'Inactive' : 'Active',
        notes: '',
        tab: 'traders',
        table: 'Traders',
      },
    },
  })
}
const useSelectedGsdClient = async () => {
  if (!gsdModal.selectedClient) return
  await persistLinkedClient(gsdModal.selectedClient)
}
const preparedClientForm = () => {
  const data = clientFormFromRecord(gsdModal.clientForm)
  // City/Country lists are suggestions only. Preserve manually entered values
  // so linking a new Shipper/Cnee does not fail when the value is not seeded.
  data.city = optionMatch(cityOptions.value, data.city) || upperText(data.city)
  data.country = optionMatch(countryOptions.value, data.country) || upperText(data.country)
  return data
}
const validateClientForm = (data: ReturnType<typeof emptyClientForm>) => {
  const missing = requiredClientFields.filter((field) => !String((data as any)[field] || '').trim())
  if (missing.length) {
    showToast(`Fill all fields: ${missing.join(', ').toUpperCase()}`)
    return false
  }
  if (!emailOk(data.email)) {
    showToast('Invalid email format')
    return false
  }
  return true
}
const saveGsdModal = async () => {
