        }
        const existingRoles = savingEditClient && Array.isArray(gsdModal.selectedClient?.roles) ? gsdModal.selectedClient.roles : []
        const roles = Array.from(new Set([...existingRoles.map(upperText), traderRole].filter(Boolean)))
        const editingTrader = savingEditClient && !!gsdModal.selectedClient?.sourcePage
