                country: gsdModal.selectedClient?.sourceCountry || countryViewId(),
                page: gsdModal.selectedClient?.sourcePage,
                kind: gsdModal.selectedClient?.sourceKind || 'traders-suppliers',
                sortOrder: gsdModal.selectedClient?.sourceSortOrder || 0,
                data: {
                  ...(gsdModal.selectedClient?.sourceData || {}),
                  id: gsdModal.selectedClient?.id,
                  namecode: payload.namecode,
                  company: payload.companyName,
                  address: payload.address,
                  city: payload.city,
                  country: payload.country,
                  pic: payload.picName,
                  phone: payload.phone,
                  email: payload.email,
                  status: payload.status || 'ACTIVE',
                  role: roles.join(','),
                  roles,
                },
              },
            })
          : await props.request(editingId ? `/entities/clients/${editingId}` : '/entities/clients', {
              method: editingId ? 'PATCH' : 'POST',
              body: { ...payload, roles },
            })
        const clean = editingTrader
          ? normalizeClientRecord({ ...(saved?.data?.data || saved?.data || {}), entityId: editingId })
          : normalizeClientRecord(saved)
        dispatchLoading.value = `Linking ${gsdModal.clientRole || 'client'} to worksheet...`
        if (!savingEditClient && role === 'CLIENT') await linkClientToTraders(clean)
        else if (!savingEditClient) await linkPaymentPartyToTraders(clean, role)
        rows.value[gsdModal.row][gsdModal.column] = JSON.stringify({ client: clean })
        await mirrorFclLinkedCell(gsdModal.row, gsdModal.column)
        gsdModal.selectedClient = clean
        gsdModal.clientForm = clientFormFromRecord(clean)
        gsdModal.clientView = 'detail'
