    }
    if (required === 'YES') {
      const hblNo = upperText(String(gsdModal.form.hblNo || '')).trim()
      if (!hblNo) {
        gsdModal.form.hint = 'Enter the HBL number'
        return
      }
      rows.value[gsdModal.row][gsdModal.column] = hblNo
    } else {
      rows.value[gsdModal.row][gsdModal.column] = 'N/A'
