    void mirrorExwFclDocumentNumber('HBL NO#', rows.value[gsdModal.row][gsdModal.column])
    mirrorFclLinkedCell(gsdModal.row, gsdModal.column)
    gsdModal.editing = false
    scheduleSave()
    void saveSheet()
    closeGsdModal()
