  } else if (gsdModal.kind === 'form') {
    if (isPaymentRequestModal()) {
      persistPaymentRequest(true)
      return
    }
    if (isPickupModal()) {
      savePickupDetails()
      return
    }
    if (isTruckContModal()) {
      saveTruckContDetails()
      return
    }
    if (isSiSubmitModal()) {
      saveSiSubmit()
      return
