// GSD must always be able to update ACTION, even after SENT ECD locks the
// remaining cells in that row. Other departments keep the existing lock rule.
const isActionSelectLocked = (row: number) => opsDeptUpper() !== 'GSD' && isSentEcdRowLocked(row)
