      if (emailResult?.status === 'failed') showToast(emailResult.error || 'Booking data was linked, but the email could not be sent')
      else if (emailResult?.status === 'no-recipients') showToast('Booking data was linked, but Client/Shipper email was not found')
      else if (emailResult?.status === 'not-configured') showToast('Booking data was linked, but SMTP email is not configured')
      if (sourceStillVisible()) {
        rows.value[row][column] = sourceRow[column]
        settings.value = normalizeWorkbookCell(sourceState.settings)
        const jobColumn = sourceHeader.indexOf('JOB NO#')
        if (jobColumn >= 0) rows.value[row][jobColumn] = sourceRow[jobColumn]
        input.checked = true
        saveState.value = `Saved ${new Date().toLocaleTimeString('en-GB')}`
      }
    } catch (error: any) {
      if (requestStatus(error) === 409 && sourceStillVisible()) {
        await loadSheet()
