    const sourceStillVisible = () => isVisibleSheet(sourceKey, sourceCountry) && rows.value === sourceRowsIdentity
    dispatchLoading.value = 'Submitting manifest and creating linked department records...'
    try {
      const flushed = await flushPendingSave()
      if (!flushed || !sourceStillVisible()) return

      const sourceState = snapshotSheetState()
      const sourceHeader = (sourceState.rows[0] || []).map((item) => String(item || '').trim())
      const sourceRow = sourceState.rows[row]
      const sourceParts = parseOpsKey(sourceKey)
      if (!sourceRow || !sourceParts) throw new Error('Could not identify the ICD shipment')

      const submittedAt = formatLocalDateTime()
