        },
      }))
      rememberSheetUpdatedAt(sourceStorageKey, responseUpdatedAt(dispatched))

      if (sourceStillVisible()) {
        rows.value[row][column] = sourceRow[column]
        settings.value = normalizeWorkbookCell(sourceState.settings)
        input.checked = true
        saveState.value = `Saved ${new Date().toLocaleTimeString('en-GB')}`
      }
    } catch (error: any) {
      if (requestStatus(error) === 409 && sourceStillVisible()) {
        await loadSheet()
        return
      }
      if (sourceStillVisible()) input.checked = isChecked(rows.value[row]?.[column])
      showToast(error?.data?.message || error?.message || 'Could not submit manifest')
    } finally {
      dispatchLoading.value = ''
    }
  } else {
    rows.value[row][column] = input.checked ? 'TRUE' : ''
  }
