  if (!parsed) return ''
  const depts = orderedOpsDepts(parsed.base, parsed.type, parsed.mode)
  const index = depts.indexOf(parsed.dept)
  const nextDept = index >= 0 ? depts[index + 1] : null
  return nextDept ? opsLeafKey(parsed.base, parsed.mode, parsed.type, nextDept) : ''
}
const rowIdentity = (header: string[], row: any[]) => {
  for (const label of ['JOB NO#', 'REF#', 'HBL NO#', 'MBL NO#', 'CLIENT']) {
    const index = header.indexOf(label)
    const value = index >= 0 ? String(row[index] ?? '').trim() : ''
    if (value) return `${label}:${value}`
  }
  return ''
}
const ensureOpsShipmentLink = (header: string[], row: any[], rowIndex: number, sheetSettings: Record<string, any> = settings.value) => {
  const links = sheetSettings?.opsRowLinks && typeof sheetSettings.opsRowLinks === 'object' ? sheetSettings.opsRowLinks : {}
  const existing = String(links[String(rowIndex)] || '').trim()
  const jobColumn = header.indexOf('JOB NO#')
  const jobNo = jobColumn >= 0 ? String(row[jobColumn] || '').trim() : ''
  const link = existing || jobNo || newOpsShipmentLink()
  if (jobColumn >= 0 && !jobNo) row[jobColumn] = link
  const nextLinks = { ...links, [String(rowIndex)]: link }
  if (sheetSettings === settings.value) settings.value = { ...settings.value, opsRowLinks: nextLinks }
  else sheetSettings.opsRowLinks = nextLinks
  return link
}
const mirrorExwFclDocumentNumber = async (label: 'HBL NO#' | 'MBL NO#', value: any, sourceRowIndex = gsdModal.row) => {
