    const matchLabels = ['REF#', 'CLIENT', 'HBL NO#', 'MBL NO#']
    const linkedRow = targetRows.findIndex((_targetRow, targetIndex) => targetIndex > 0 && String(targetLinks[String(targetIndex)] || '').trim() === sourceLink)
    const matchingRow = linkedRow > 0 ? linkedRow : targetRows.findIndex((targetRow, targetIndex) => targetIndex > 0 && matchLabels.filter((key) => key !== 'CLIENT').some((key) => {
      if (key === label) return false
      const sourceColumn = sourceHeader.indexOf(key)
      const targetColumn = targetHeader.indexOf(key)
      const sourceValue = sourceColumn >= 0 ? clientCellText(sourceRow[sourceColumn]) || String(sourceRow[sourceColumn] || '').trim() : ''
      const targetValue = targetColumn >= 0 ? clientCellText(targetRow[targetColumn]) || String(targetRow[targetColumn] || '').trim() : ''
      return !!sourceValue && sourceValue === targetValue
    }))
    const targetColumn = targetHeader.indexOf(label)
    if (matchingRow < 1 || targetColumn < 0) return
    targetLinks[String(matchingRow)] = sourceLink
    targetSettings.opsRowLinks = targetLinks
    targetRows[matchingRow][targetColumn] = value
    await patchLoadedWorkbookSheet(targetStorageKey, targetSheet, { rows: [...targetRows, [workbookMetaMarker, JSON.stringify({
        version: 1,
        columnWidths: targetSheet.columnWidths || targetHeader.map(() => 100),
