const syncCrossServiceGsdRow = async (row: number, column: number, createdAt = formatLocalDateTime()) => {
  const parsed = opsParts.value
  if (!parsed || !isCrossServiceRecordSourceColumn(column)) return false
  const sourceKey = activeKey.value
  const sourceCountry = loadedCountryId.value
  const sourceRowsIdentity = rows.value
  const sourceStillVisible = () => isVisibleSheet(sourceKey, sourceCountry) && rows.value === sourceRowsIdentity
  const counterpartType = String(rows.value[row]?.[column] || '').trim().toUpperCase()
  if (!OPS_TERMS.includes(counterpartType as any) || counterpartType === String(parsed.type || '').toUpperCase()) return false
  const counterpartBase = opsBaseForType(counterpartType as any)
  const targetKey = opsLeafKey(counterpartBase, parsed.mode, counterpartType as any, 'GSD')
  const targetHeader = opsHeaderFor(counterpartBase, parsed.mode, 'GSD', counterpartType as any)
  const sourceHeader = (rows.value[0] || []).map((item) => String(item || '').trim())
  const sourceRow = rows.value[row] || []
  const linkId = crossServiceLinkId(row)
  const targetStorageKey = sheetStorageKey(targetKey, sourceCountry)
  try {
    let targetSheet: any
    try {
      targetSheet = await props.request(`/workbook/sheets/${encodeURIComponent(targetStorageKey)}`)
    } catch (error: any) {
      if (requestStatus(error) !== 404) throw error
      targetSheet = { rows: [targetHeader.slice()], columnWidths: targetHeader.map(() => 100), rowHeights: {}, formatting: {}, merges: [], settings: {} }
      const created = await props.request('/workbook/sheets', {
        method: 'POST',
        body: { key: targetStorageKey, label: targetKey, group: 'Operations', rows: [...targetSheet.rows, [workbookMetaMarker, JSON.stringify({ version: 1, columnWidths: targetSheet.columnWidths, rowHeights: {}, formatting: {}, merges: [], settings: {} })]] },
      })
      targetSheet.updatedAt = responseUpdatedAt(created)
    }
    const extracted = extractWorkbookRows(Array.isArray(targetSheet.rows) ? targetSheet.rows.map((item: any[]) => [...item]) : [], targetSheet)
    const targetRows = alignRowsToHeader(extracted.rows, targetHeader).rows
    const targetSettings = { ...(extracted.settings || targetSheet.settings || {}) }
    const targetLinks = { ...crossServiceLinks(targetSettings) }
    let targetRowIndex = targetRows.findIndex((_item, index) => index > 0 && targetLinks[String(index)]?.id === linkId)
    const sourceValue = (label: string) => {
      const index = sourceHeader.indexOf(label)
      return index >= 0 ? sourceRow[index] ?? '' : ''
    }
    if (targetRowIndex < 1) {
      const time = createdAt
      const targetRow = targetHeader.map((label) => {
        if (label === 'TIME') return time
        if (label === 'JOB NO#') return nextGeneratedJobNo(time, targetRows)
        if (label === `${counterpartType}+`) return String(parsed.type || '').toUpperCase()
        if (label === 'ACTION') return 'ACTIVE'
        if (['CLIENT', 'DEALT INFO'].includes(label)) return sourceValue(label)
        return ''
      })
      targetRows.push(targetRow)
      targetRowIndex = targetRows.length - 1
    } else {
      const targetRow = targetRows[targetRowIndex]
      for (const label of ['CLIENT', 'DEALT INFO']) {
        const targetColumn = targetHeader.indexOf(label)
        if (targetColumn >= 0 && sourceValue(label) !== '') targetRow[targetColumn] = sourceValue(label)
      }
      const reciprocalColumn = targetHeader.indexOf(`${counterpartType}+`)
      if (reciprocalColumn >= 0) targetRow[reciprocalColumn] = String(parsed.type || '').toUpperCase()
    }
    if (!sourceStillVisible()) return false
    targetLinks[String(targetRowIndex)] = { id: linkId, counterpartKey: sourceKey, counterpartType: String(parsed.type || '').toUpperCase() }
    targetSettings.crossServiceLinks = targetLinks
    await patchLoadedWorkbookSheet(targetStorageKey, targetSheet, { rows: [...targetRows, [workbookMetaMarker, JSON.stringify({
        version: 1,
        columnWidths: extracted.columnWidths || targetSheet.columnWidths || targetHeader.map(() => 100),
        rowHeights: extracted.rowHeights || targetSheet.rowHeights || {},
        formatting: extracted.formatting || targetSheet.formatting || {},
        merges: extracted.merges || targetSheet.merges || [],
        settings: targetSettings,
      })]] })
    if (sourceStillVisible()) {
      settings.value = {
        ...settings.value,
        crossServiceLinks: {
          ...crossServiceLinks(),
          [String(row)]: { id: linkId, counterpartKey: targetKey, counterpartType },
        },
      }
      scheduleSave()
    }
    showToast(`Linked ${String(parsed.type || '').toUpperCase()} with ${counterpartType}`)
    return true
  } catch (error: any) {
    showToast(error?.data?.message || error?.message || `Could not link to ${counterpartType}`)
    return false
  }
}
