type LinkedMirrorSource = {
  parsed: NonNullable<ReturnType<typeof parseOpsKey>>
  header: string[]
  row: any[]
  settings: Record<string, any>
  country: string
}
const linkedDateLabels = new Set(['ATD', 'ATA'])
const markLinkedDateChange = (targetSettings: Record<string, any>, row: number, label: any, previousValue: any, nextValue: any) => {
  const normalizedLabel = upperText(label)
  const previous = String(previousValue ?? '').trim()
  const next = String(nextValue ?? '').trim()
  if (!linkedDateLabels.has(normalizedLabel) || !previous || !next || previous === next) return
  const changes = targetSettings.linkedDateChanges && typeof targetSettings.linkedDateChanges === 'object'
    ? { ...targetSettings.linkedDateChanges }
    : {}
  changes[String(row)] = {
    ...(changes[String(row)] || {}),
    [normalizedLabel]: { from: previous, to: next, changedAt: formatLocalDateTime() },
  }
  targetSettings.linkedDateChanges = changes
}
const linkedDateChanged = (row: number, column: number) =>
  row > 0 && linkedDateLabels.has(normalizedHeaderLabel(column)) &&
  Boolean(settings.value.linkedDateChanges?.[String(row)]?.[normalizedHeaderLabel(column)])
const runMirrorExwFclWorkflowCell = async (
  targetDept: FclStructureDept,
  label: string,
  value: any,
  sourceRowIndex = gsdModal.row,
  source?: LinkedMirrorSource,
) => {
  const parsed = source?.parsed || opsParts.value
  if (!parsed) return
  const type = String(parsed.type || '').toUpperCase()
  const mode = String(parsed.mode || '').toUpperCase()
  const sourceDept = String(parsed.dept || '').toUpperCase()
  const supported = ['FCL', 'LCL', 'AIR'].includes(mode) && ['EXW', 'FCA', 'FCF', 'DO', 'DAP', 'DDU', 'DDP'].includes(type)
  if (!supported) return
  const targetKey = opsLeafKey(parsed.base, parsed.mode, parsed.type, targetDept as any)
  const sourceHeader = source?.header || (rows.value[0] || []).map((item) => String(item || '').trim())
  const sourceRow = source?.row || rows.value[sourceRowIndex] || []
  const sourceLink = opsShipmentLink(sourceHeader, sourceRow, sourceRowIndex, source?.settings || settings.value)
  const targetStorageKey = sheetStorageKey(targetKey, source?.country || countryViewId())
  try {
    const targetSheet = await props.request(`/workbook/sheets/${encodeURIComponent(targetStorageKey)}`)
    const targetHeader = opsHeaderFor(parsed.base, parsed.mode, targetDept as any, parsed.type)
    const extracted = extractWorkbookRows(Array.isArray(targetSheet.rows) ? targetSheet.rows.map((item: any[]) => [...item]) : [], targetSheet)
    const targetRows = alignRowsToHeader(extracted.rows, targetHeader).rows
    const targetSettings = extracted.settings || targetSheet.settings || {}
    const targetLinks = targetSettings.opsRowLinks && typeof targetSettings.opsRowLinks === 'object' ? targetSettings.opsRowLinks : {}
    const linkedRow = sourceLink ? targetRows.findIndex((_targetRow, targetIndex) => targetIndex > 0 && String(targetLinks[String(targetIndex)] || '') === sourceLink) : -1
    let matchingRow = linkedRow > 0 ? linkedRow : targetRows.findIndex((targetRow, targetIndex) => targetIndex > 0 && ['REF#', 'JOB NO#', 'HBL NO#', 'MBL NO#'].some((key) => {
      const sourceColumn = sourceHeader.indexOf(key)
      const targetColumn = targetHeader.indexOf(key)
      const sourceValue = sourceColumn >= 0 ? clientCellText(sourceRow[sourceColumn]) || String(sourceRow[sourceColumn] || '').trim() : ''
      const targetValue = targetColumn >= 0 ? clientCellText(targetRow[targetColumn]) || String(targetRow[targetColumn] || '').trim() : ''
      return !!sourceValue && sourceValue === targetValue
    }))
    const effectiveLabel = label === 'PAYMENT REQUEST' && targetDept === 'FCD'
      ? 'EXPENSE/COLLECT LIST'
      : label
    const mirrorLabelAliases: Record<string, string[]> = {
      'ORIGIN AGENT': ['ORIGIN AGENT', 'ORIGINAL AGENT'],
      'ORIGINAL AGENT': ['ORIGINAL AGENT', 'ORIGIN AGENT'],
      'DEST. AGENT': ['DEST. AGENT', 'DESTINATION AGENT'],
      'DESTINATION AGENT': ['DESTINATION AGENT', 'DEST. AGENT'],
      'CNEE': ['CNEE', 'CONSIGNEE'],
      'CONSIGNEE': ['CONSIGNEE', 'CNEE'],
      'CLEARANCE DETAIL': ['CLEARANCE DETAIL', 'CLEARANCE DETAILS', 'CUSTOMS CLEARANCE DETAILS'],
      'CLEARANCE DETAILS': ['CLEARANCE DETAILS', 'CLEARANCE DETAIL', 'CUSTOMS CLEARANCE DETAILS'],
    }
    const targetLabels = mirrorLabelAliases[effectiveLabel] || [effectiveLabel]
    let targetColumn = targetLabels.map((candidate) => targetHeader.indexOf(candidate)).find((index) => index >= 0) ?? -1
    if (targetColumn < 0 && label === 'TRUCKING INFO') targetColumn = targetHeader.indexOf('TRUCK & CONT/SEAL INFO')
    if (targetColumn < 0 && label === 'TRUCK & CONT/SEAL INFO') targetColumn = targetHeader.indexOf('TRUCKING INFO')
    if (targetColumn < 0) return
    // Older GSD -> ECD transfers may have created the target row without
    // copying JOB NO#/TIME. In that case the row position is the only stable
    // link left; repair its identity while mirroring the changed field.
    if (matchingRow < 1 && sourceDept === 'GSD' && targetDept === 'ECD' && sourceRowIndex > 0 && sourceRowIndex < targetRows.length) {
      matchingRow = sourceRowIndex
      for (const identityLabel of ['TIME', 'JOB NO#']) {
        const sourceColumn = sourceHeader.indexOf(identityLabel)
        const targetIdentityColumn = targetHeader.indexOf(identityLabel)
        if (sourceColumn >= 0 && targetIdentityColumn >= 0 && !String(targetRows[matchingRow][targetIdentityColumn] ?? '').trim()) {
          targetRows[matchingRow][targetIdentityColumn] = sourceRow[sourceColumn] ?? ''
        }
      }
    }
    // Older TCD/ECD rows do not always share JOB NO# and may have lost their
    // opsRowLinks metadata. Their row position is the remaining stable link.
    if (matchingRow < 1 && sourceDept === 'TCD' && targetDept === 'ECD' && sourceRowIndex > 0 && sourceRowIndex < targetRows.length) {
      matchingRow = sourceRowIndex
    }
    if (matchingRow < 1) return
    const wasAlreadyLinked = !!sourceLink && String(targetLinks[String(matchingRow)] || '') === sourceLink
    if (sourceLink) {
