    }
    // The first value received while BC SENT/Manifest creates the relationship
    // is the baseline, not a schedule change. Highlight only later updates to
    // the same already-linked shipment.
    if (wasAlreadyLinked) {
      markLinkedDateChange(targetSettings, matchingRow, targetHeader[targetColumn], targetRows[matchingRow][targetColumn], value)
    }
    targetRows[matchingRow][targetColumn] = value
    await patchLoadedWorkbookSheet(targetStorageKey, targetSheet, { rows: [...targetRows, [workbookMetaMarker, JSON.stringify({
        version: 1,
        columnWidths: targetSheet.columnWidths || targetHeader.map(() => 100),
        rowHeights: targetSheet.rowHeights || {},
        formatting: targetSheet.formatting || {},
        merges: targetSheet.merges || [],
        settings: targetSettings,
      })]] })
  } catch (error: any) {
    if (requestStatus(error) !== 404) console.warn(`Could not mirror ${label} to ${targetDept}`, error)
  }
}
const mirrorExwFclWorkflowCell = (
  targetDept: FclStructureDept,
  label: string,
  value: any,
  sourceRowIndex = gsdModal.row,
) => {
  const parsed = opsParts.value
  if (!parsed) return Promise.resolve()
  const sourceHeader = (rows.value[0] || []).map((item) => String(item || '').trim())
  ensureOpsShipmentLink(sourceHeader, rows.value[sourceRowIndex] || [], sourceRowIndex, settings.value)
  const source: LinkedMirrorSource = {
    parsed: { ...parsed },
    header: sourceHeader,
    row: [...(rows.value[sourceRowIndex] || [])],
    settings: { ...(settings.value || {}) },
    country: countryViewId(),
  }
  const queueKey = sheetStorageKey(opsLeafKey(parsed.base, parsed.mode, parsed.type, targetDept as any), source.country)
  const previous = linkedWriteChains.get(queueKey) || Promise.resolve()
  const write = previous.catch(() => undefined).then(() => runMirrorExwFclWorkflowCell(targetDept, label, value, sourceRowIndex, source))
  linkedWriteChains.set(queueKey, write)
  void write.finally(() => {
    if (linkedWriteChains.get(queueKey) === write) linkedWriteChains.delete(queueKey)
  })
  return trackLinkedWrite(write)
