  const isConfirmedDapTcdLink = parsed.mode === 'FCL' && parsed.type === 'DAP' && parsed.dept === 'TCD'
  if (isConfirmedDapTcdLink) {
    const recipients = label === 'PAYMENT REQUEST'
      ? ['ICD']
      : label === 'TRUCK & CONT/SEAL INFO' ? ['FCD'] : []
    for (const dept of recipients) void mirrorExwFclWorkflowCell(dept as FclStructureDept, label, rows.value[row]?.[column], row)
    return
  }
  const isConfirmedDapFcdLink = parsed.mode === 'FCL' && parsed.type === 'DAP' && parsed.dept === 'FCD'
  if (isConfirmedDapFcdLink) return
  const isConfirmedDduGsdLink = parsed.mode === 'FCL' && parsed.type === 'DDU' && parsed.dept === 'GSD'
  if (isConfirmedDduGsdLink) {
    const recipients = ['ICD OPS', 'CLIENT', 'DEALT INFO', 'DDU+'].includes(label) ? ['ICD'] : []
    for (const dept of recipients) void mirrorExwFclWorkflowCell(dept as FclStructureDept, label, rows.value[row]?.[column], row)
    return
  }
  const isConfirmedDduIcdLink = parsed.mode === 'FCL' && ['DDU', 'DDP'].includes(parsed.type) && parsed.dept === 'ICD'
  if (isConfirmedDduIcdLink) {
    const icdToCcd = [
      'SHIPPER', 'CNEE', 'LINER', 'REF#', 'HBL NO#', 'MBL NO#', 'VOLUME', 'ROUTE',
      'VESSEL/VOYAGE', 'ATD', 'ETA', 'CONT/SEAL INFO', 'ATA', 'DO VALIDITY',
    ]
    const icdToTcd = [
      'SHIPPER', 'CNEE', 'LINER', 'REF#', 'HBL NO#', 'MBL NO#', 'VOLUME', 'ROUTE',
      'VESSEL/VOYAGE', 'ATD', 'ATA', 'DO VALIDITY',
    ]
    const icdToFcd = [
      'SHIPPER', 'CNEE', 'ORIGIN AGENT', 'ORIGINAL AGENT', 'DESTINATION AGENT', 'DEST. AGENT',
      'LINER', 'REF#', 'HBL NO#', 'MBL NO#', 'ATD', 'ATA', 'VOLUME', 'ROUTE', 'VESSEL/VOYAGE',
    ]
    const recipients = label === 'EXTRA SERVICE'
      ? ['GSD']
      : label === 'PAYMENT REQUEST' ? ['CCD', 'TCD']
        : label === 'PRE-ALERT CONFIRMATION' ? ['CCD']
          : label === 'CONT/SEAL INFO' ? ['CCD', 'TCD']
            : icdToCcd.includes(label) ? ['CCD']
              : icdToTcd.includes(label) ? ['TCD']
                : icdToFcd.includes(label) ? ['FCD'] : []
    for (const dept of recipients) {
      const targetLabel = label === 'CONT/SEAL INFO' && dept === 'TCD' ? 'TRUCK & CONT/SEAL INFO' : label
      void mirrorExwFclWorkflowCell(dept as FclStructureDept, targetLabel, rows.value[row]?.[column], row)
    }
    return
  }
  const isConfirmedDduCcdLink = parsed.mode === 'FCL' && ['DDU', 'DDP'].includes(parsed.type) && parsed.dept === 'CCD'
  if (isConfirmedDduCcdLink) {
    const recipients = label === 'PAYMENT REQUEST'
      ? ['ICD', 'TCD']
      : label === 'PRE-ALERT CONFIRMATION' ? ['ICD']
        : label === 'CLEARANCE DETAIL' ? ['TCD'] : []
    for (const dept of recipients) void mirrorExwFclWorkflowCell(dept as FclStructureDept, label, rows.value[row]?.[column], row)
    return
  }
  const isConfirmedDduTcdLink = parsed.mode === 'FCL' && ['DDU', 'DDP'].includes(parsed.type) && parsed.dept === 'TCD'
  if (isConfirmedDduTcdLink) {
    const recipients = label === 'PAYMENT REQUEST'
      ? ['ICD', 'CCD']
      : label === 'TRUCK & CONT/SEAL INFO' ? ['ICD', 'FCD'] : []
    for (const dept of recipients) {
      const targetLabel = label === 'TRUCK & CONT/SEAL INFO' && dept === 'ICD' ? 'CONT/SEAL INFO' : label
      void mirrorExwFclWorkflowCell(dept as FclStructureDept, targetLabel, rows.value[row]?.[column], row)
    }
    return
  }
  const isConfirmedDduFcdLink = parsed.mode === 'FCL' && ['DDU', 'DDP'].includes(parsed.type) && parsed.dept === 'FCD'
  if (isConfirmedDduFcdLink) return
  const isConfirmedDdpGsdLink = parsed.mode === 'FCL' && parsed.type === 'DDP' && parsed.dept === 'GSD'
  if (isConfirmedDdpGsdLink) {
    const recipients = ['ICD OPS', 'CLIENT', 'DEALT INFO', 'DDP+'].includes(label) ? ['ICD'] : []
    for (const dept of recipients) void mirrorExwFclWorkflowCell(dept as FclStructureDept, label, rows.value[row]?.[column], row)
    return
  }
  const ordered = orderedOpsDepts(parsed.base, parsed.type, parsed.mode)
  const currentIndex = ordered.indexOf(parsed.dept)
  const downstream = currentIndex < 0 ? [] : ordered.slice(currentIndex + 1).filter((dept) => {
    const targetHeader = opsHeaderFor(parsed.base, parsed.mode, dept as any, parsed.type)
    return targetHeader.includes(label)
  })
  // Keep the explicit cross-department relationships and also update every
  // already-linked downstream sheet containing the same owned field. This is
  // required when a user returns to an earlier tab and changes source data.
  const recipients = Array.from(new Set([...fclLinkedRecipients(), ...downstream])) as FclStructureDept[]
  for (const dept of recipients) {
    const targetLabel = label === 'ARRIVAL NOTICE SENDING' && ['CCD', 'TCD'].includes(dept)
      ? 'ARRIVAL NOTICE DETAIL'
      : label === 'CONT/SEAL INFO' && dept === 'TCD'
        ? 'TRUCK & CONT/SEAL INFO'
        : label === 'TRUCK & CONT/SEAL INFO' && dept === 'ICD' ? 'CONT/SEAL INFO' : label
    void mirrorExwFclWorkflowCell(dept, targetLabel, value, row)
  }
}
const hasDownstreamOpsActivity = async (rowIndex: number) => {
  const targetKey = nextOpsLeafKey()
  const parsed = targetKey ? parseOpsKey(targetKey) : null
  if (!targetKey || !parsed) return false
  const sourceHeader = (rows.value[0] || []).map((value) => String(value ?? '').trim())
  const sourceRow = rows.value[rowIndex] || []
  const identity = rowIdentity(sourceHeader, sourceRow)
  if (!identity) return false
  try {
    const targetSheet = await props.request(`/workbook/sheets/${encodeURIComponent(sheetStorageKey(targetKey))}`)
    const extracted = extractWorkbookRows(Array.isArray(targetSheet.rows) ? targetSheet.rows.map((row: any[]) => [...row]) : [], targetSheet)
    const targetHeader = opsHeaderFor(parsed.base, parsed.mode, parsed.dept, parsed.type)
    const aligned = alignRowsToHeader(extracted.rows, targetHeader).rows
    const targetRow = aligned.find((row, index) => index > 0 && rowIdentity(targetHeader, row) === identity)
    if (!targetRow) return false
    return targetHeader.some((label, targetIndex) => {
      if (label === 'TIME') return false
      const sourceIndex = sourceHeader.indexOf(label)
      const original = sourceIndex >= 0 ? String(sourceRow[sourceIndex] ?? '').trim() : ''
      const current = String(targetRow[targetIndex] ?? '').trim()
      return current !== original
    })
  } catch (error: any) {
    if (requestStatus(error) === 404) return false
    throw error
  }
}
type OpsTransferSource = { key: string; country: string; header: string[]; row: any[]; settings: Record<string, any> }
const transferRowToNextDept = async (rowIndex: number, targetDept?: string, transferTime = '', notify = true, snapshot?: OpsTransferSource): Promise<boolean> => {
  const source = parseOpsKey(snapshot?.key || activeKey.value)
  const targetKey = targetDept && source
    ? opsLeafKey(source.base, source.mode, source.type, targetDept as any)
    : nextOpsLeafKey()
  const parsed = targetKey ? parseOpsKey(targetKey) : null
  if (!targetKey || !parsed) {
    if (notify) showToast('No next department')
    return false
  }
  const sourceHeader = snapshot?.header || (rows.value[0] || []).map((value) => String(value ?? '').trim())
  const sourceRow = snapshot?.row || rows.value[rowIndex] || []
  const sourceSettings = snapshot?.settings || settings.value
  const sourceCarry = sourceSettings?.crossServiceCarryByRow?.[String(rowIndex)] || {}
  const sourceLink = ensureOpsShipmentLink(sourceHeader, sourceRow, rowIndex, sourceSettings)
  const targetHeader = opsHeaderFor(parsed.base, parsed.mode, parsed.dept, parsed.type)
  const sourceIndexForTarget = (label: string) => {
    const aliases: Record<string, string[]> = {
      'EFA+': ['EFA+', 'FCF+', 'EXW+'],
      'ORIGIN AGENT': ['ORIGIN AGENT', 'ORIGINAL AGENT'],
      'CUT OFF DETAIL': ['CUT OFF DETAIL', 'CUT OFF DETAILS'],
      'BILL DETAIL': ['BILL DETAIL', 'BILL APPROVAL'],
      'ARRIVAL NOTICE DETAIL': ['ARRIVAL NOTICE DETAIL', 'ARRIVAL NOTICE SENDING'],
      'CONT/SEAL INFO': ['CONT/SEAL INFO', 'TRUCK & CONT/SEAL INFO', 'TRUCKING INFO'],
      'TRUCK & CONT/SEAL INFO': ['TRUCK & CONT/SEAL INFO', 'CONT/SEAL INFO', 'TRUCKING INFO'],
      'PRE-ALERT CONFIRMATION': ['PRE-ALERT CONFIRMATION', 'PRE-ALERT SENDING'],
    }
    return sourceHeader.findIndex((sourceLabel) => (aliases[label] || [label]).includes(sourceLabel))
  }
  const sendingFromGsdToIcdFlow = source?.dept === 'GSD' && ['DO', 'DAP', 'DDU', 'DDP'].includes(String(parsed.type || '').toUpperCase()) && parsed.dept === 'ICD'
  const crossServiceInbound = sendingFromGsdToIcdFlow
    && (!!sourceSettings?.crossServiceInboundDirect || !sourceHeader.some((label) => upperText(label) === `${upperText(source.type)}+`))
        const sendingDoGsdToIcd = sendingFromGsdToIcdFlow && ['FCL', 'LCL'].includes(parsed.mode) && parsed.type === 'DO'
  const sendingToInitialOpsDept = sendingFromGsdToIcdFlow || (
    ['EXW', 'FCA', 'FCF'].includes(String(parsed.type || '').toUpperCase()) && parsed.dept === 'ECD'
  )
  const nextRow = targetHeader.map((label) => {
    if (label === 'MODE') return 'AUTO'
    if (label === 'TIME') {
      // TIME is the shipment's creation timestamp and must travel with the
      // linked row. Previously downstream transfers used an empty fallback,
      // so a refresh could leave the target row with a blank TIME value.
      const sourceTimeColumn = sourceHeader.findIndex((sourceLabel) => sourceLabel === 'TIME')
      const sourceTime = sourceTimeColumn >= 0 ? String(sourceRow[sourceTimeColumn] ?? '').trim() : ''
      return sendingFromGsdToIcdFlow ? transferTime || formatLocalDateTime() : transferTime || sourceTime || (sendingToInitialOpsDept ? formatLocalDateTime() : '')
    }
    if (sendingToInitialOpsDept && label === 'BU') return generatedJobCountryCode()
    if (sendingToInitialOpsDept && label === 'SALES') return String(sourceSettings?.opsRowCreators?.[String(rowIndex)] || props.currentUser?.displayName || props.currentUser?.username || '').trim()
    if (crossServiceInbound && label === `${upperText(parsed.type)}+`) return upperText(sourceSettings?.crossServiceOriginType || '')
    if (label === 'REF#') {
      const sourceRef = sourceIndexForTarget('REF#')
      const sourceJob = sourceIndexForTarget('JOB NO#')
      return String((sourceRef >= 0 ? sourceRow[sourceRef] : '') || (sourceJob >= 0 ? sourceRow[sourceJob] : '') || '').trim()
    }
    if (sendingToInitialOpsDept && label === 'NOTICE') return ''
    if (sendingToInitialOpsDept && label === 'ACTION') return 'ACTIVE'
    if (['CLEARANCE DETAIL', 'CLEARANCE DETAILS'].includes(label) && sourceCarry.clearanceDetail) return sourceCarry.clearanceDetail
    const sourceIndex = sourceIndexForTarget(label)
    return sourceIndex >= 0 ? sourceRow[sourceIndex] ?? '' : ''
  })
  const identity = rowIdentity(sourceHeader, sourceRow)
  const queueKey = sheetStorageKey(targetKey, snapshot?.country || loadedCountryId.value)
  return queueLinkedWrite(queueKey, async () => {
    try {
      let targetSheet: any
      try {
        targetSheet = await props.request(`/workbook/sheets/${encodeURIComponent(queueKey)}`)
      } catch (error: any) {
        if (requestStatus(error) !== 404) throw error
        targetSheet = { rows: [targetHeader.slice()], columnWidths: targetHeader.map(() => 100), rowHeights: {}, formatting: {}, merges: [], settings: {} }
        const created = await props.request('/workbook/sheets', {
          method: 'POST',
          body: { key: queueKey, label: targetKey, group: 'Operations', rows: [...targetSheet.rows, [workbookMetaMarker, JSON.stringify({ version: 1, columnWidths: targetSheet.columnWidths, rowHeights: {}, formatting: {}, merges: [], settings: {} })]] },
        })
        targetSheet.updatedAt = responseUpdatedAt(created)
      }
    const targetExtracted = extractWorkbookRows(Array.isArray(targetSheet.rows) && targetSheet.rows.length ? targetSheet.rows.map((row: any[]) => [...row]) : [targetHeader.slice()], targetSheet)
    targetSheet = { ...targetSheet, ...targetExtracted, rows: targetExtracted.rows }
    const targetRows = targetSheet.rows.length ? targetSheet.rows : [targetHeader.slice()]
    const aligned = alignRowsToHeader(targetRows, targetHeader)
    const finalRows = aligned.rows
    const targetOpsColumn = targetHeader.findIndex((label) => String(label || '').trim().toUpperCase() === `${String(parsed.dept || '').toUpperCase()} OPS`)
    // GSD explicitly selects the first ECD/ICD owner. Any later department
    // receives its own assignee automatically, balanced by active workload.
    if (targetOpsColumn >= 0 && !String(nextRow[targetOpsColumn] || '').trim()) {
      nextRow[targetOpsColumn] = leastLoadedDepartmentStaff(parsed.dept, targetHeader, finalRows)
    }
    const targetSettings = { ...(targetSheet.settings || {}) }
    const targetLinks = targetSettings.opsRowLinks && typeof targetSettings.opsRowLinks === 'object' ? { ...targetSettings.opsRowLinks } : {}
    const linkedIndex = sourceLink ? finalRows.findIndex((_row, index) => index > 0 && String(targetLinks[String(index)] || '') === sourceLink) : -1
    const targetIdentityIndex = linkedIndex > 0 ? linkedIndex : identity
      ? finalRows.findIndex((row, index) => index > 0 && rowIdentity(targetHeader, row) === identity)
      : -1
    if (targetIdentityIndex > 0) {
      const previousLinkedDates = Object.fromEntries(['ATD', 'ATA'].map((label) => {
        const column = targetHeader.indexOf(label)
        return [label, column >= 0 ? finalRows[targetIdentityIndex][column] : '']
      }))
      finalRows[targetIdentityIndex] = finalRows[targetIdentityIndex].map((current, column) => {
        const label = targetHeader[column]
        if (label === 'REF#') return current || nextRow[column]
        const sourceColumn = sourceIndexForTarget(label)
        const isGsdToExportEcd = source?.dept === 'GSD' && parsed.dept === 'ECD' && ['FCL', 'LCL', 'AIR'].includes(parsed.mode) && ['EXW', 'FCA', 'FCF'].includes(parsed.type)
        const sendingDapGsdToIcd = sendingFromGsdToIcdFlow && ['FCL', 'LCL'].includes(parsed.mode) && parsed.type === 'DAP'
        const sendingDduGsdToIcd = sendingFromGsdToIcdFlow && ['FCL', 'LCL', 'AIR'].includes(parsed.mode) && parsed.type === 'DDU'
        const sendingDdpGsdToIcd = sendingFromGsdToIcdFlow && ['FCL', 'LCL', 'AIR'].includes(parsed.mode) && parsed.type === 'DDP'
        const isInbound = crossServiceInbound
          ? sourceColumn >= 0 || ['TIME', 'BU', 'SALES'].includes(label)
          : isGsdToExportEcd
          ? ['TIME', 'EXTRA SERVICE', 'JOB NO#', 'ECD OPS', 'CLIENT', 'DEALT INFO', 'EXW+', 'FCA+', 'FCF+', 'BU', 'SALES'].includes(label)
          : sendingDoGsdToIcd
            ? ['TIME', 'EXTRA SERVICE', 'JOB NO#', 'ICD OPS', 'CLIENT', 'DEALT INFO', 'DO+', 'BU', 'SALES'].includes(label)
            : sendingDapGsdToIcd
              ? ['TIME', 'EXTRA SERVICE', 'JOB NO#', 'ICD OPS', 'CLIENT', 'DEALT INFO', 'DAP+', 'BU', 'SALES'].includes(label)
              : sendingDduGsdToIcd
                ? ['TIME', 'EXTRA SERVICE', 'JOB NO#', 'ICD OPS', 'CLIENT', 'DEALT INFO', 'DDU+', 'BU', 'SALES'].includes(label)
                : sendingDdpGsdToIcd
                  ? ['TIME', 'EXTRA SERVICE', 'JOB NO#', 'ICD OPS', 'CLIENT', 'DEALT INFO', 'DDP+', 'BU', 'SALES'].includes(label)
                  : sourceColumn >= 0 || ['TIME', 'BU', 'SALES'].includes(label)
        return isInbound ? nextRow[column] : current
      })
      if (targetOpsColumn >= 0 && !String(finalRows[targetIdentityIndex][targetOpsColumn] || '').trim()) {
        finalRows[targetIdentityIndex][targetOpsColumn] = nextRow[targetOpsColumn]
      }
      for (const label of linkedDateLabels) {
        const column = targetHeader.indexOf(label)
        if (column >= 0) markLinkedDateChange(targetSettings, targetIdentityIndex, label, previousLinkedDates[label], finalRows[targetIdentityIndex][column])
      }
    }
    else finalRows.push(nextRow)
    const finalRowIndex = targetIdentityIndex > 0 ? targetIdentityIndex : finalRows.length - 1
    if (sourceLink) targetLinks[String(finalRowIndex)] = sourceLink
    targetSettings.opsRowLinks = targetLinks
    if (crossServiceInbound) {
      targetSettings.crossServiceInboundRows = { ...(targetSettings.crossServiceInboundRows || {}), [String(finalRowIndex)]: true }
    }
    const sourceClearanceColumn = sourceHeader.findIndex((label) => ['CLEARANCE DETAIL', 'CLEARANCE DETAILS'].includes(upperText(label)))
    const clearanceDetail = sourceClearanceColumn >= 0 ? sourceRow[sourceClearanceColumn] : sourceCarry.clearanceDetail
    if (clearanceDetail) {
      targetSettings.crossServiceCarryByRow = {
        ...(targetSettings.crossServiceCarryByRow || {}),
        [String(finalRowIndex)]: { ...sourceCarry, clearanceDetail },
      }
    }
    await patchLoadedWorkbookSheet(queueKey, targetSheet, {
        rows: [...finalRows, [workbookMetaMarker, JSON.stringify({
          version: 1,
          columnWidths: Array.isArray(targetSheet.columnWidths) ? targetSheet.columnWidths : targetHeader.map(() => 100),
          rowHeights: targetSheet.rowHeights || {},
          formatting: targetSheet.formatting || {},
          merges: Array.isArray(targetSheet.merges) ? targetSheet.merges : [],
          settings: targetSettings,
        })]],
    })
    if (notify) showToast(`Sent to ${parsed.dept}`)
    return true
    } catch (error: any) {
      if (notify) showToast(error?.data?.message || error?.message || 'Could not send to next department')
      return false
    }
  })
}
const setDropdownValue = (row: number, column: number, event: Event) => {
