const positionPopupNear = (target: HTMLElement, width = 180) => {
  const rect = target.getBoundingClientRect()
  return {
    left: Math.max(8, Math.min(rect.left, window.innerWidth - width - 8)),
    top: Math.min(rect.bottom + 4, window.innerHeight - 280),
    width: Math.max(width, Math.round(rect.width)),
  }
}
const setDropdownOptions = (column: number, options: string[]) => {
  const clean = uniqueDropdownOptions(options).filter(Boolean)
  settings.value = {
    ...settings.value,
    dropdownOptions: {
      ...(settings.value.dropdownOptions || {}),
      [opsColumnOptionKey(column)]: clean,
    },
  }
  scheduleSave()
}
const openDropdownPopup = (row: number, column: number, event?: MouseEvent, target?: HTMLElement) => {
  if (isLockedOpsCell(row, column)) {
