  }
  const el = target || (event?.currentTarget as HTMLElement)?.closest('td') as HTMLElement || sheetBody.value?.querySelector<HTMLElement>(`td[data-r="${row}"][data-c="${column}"]`)
  if (!el) return
  const pos = positionPopupNear(el, 160)
  Object.assign(dropdownPopup, { open: true, row, column, left: pos.left, top: pos.top, width: pos.width, filter: '', mode: 'pick', newItem: '', error: '' })
