const addDropdownPopupOption = () => {
  const value = dropdownPopup.newItem.trim()
  if (!value) return
  const options = dropdownOptions(dropdownPopup.column)
  if (options.some((option) => option.toLowerCase() === value.toLowerCase())) {
    dropdownPopup.error = 'Already exists.'
    return
  }
  setDropdownOptions(dropdownPopup.column, [...options, value])
  dropdownPopup.newItem = ''
  dropdownPopup.error = ''
}
const removeDropdownPopupOption = (option: string) => {
