const applyCutoffTime = () => { if (cutoffTimePopup.field) gsdModal.form[cutoffTimePopup.field] = `${cutoffTimePopup.hour}:${cutoffTimePopup.minute}`; clearCutoffHint(); closeCutoffTimePopup() }
const applyNativeOrCutoffTime = () => {
