  const column = datePopup.column
  rows.value[row][column] = ''
  closeDatePopup()
  void persistDatePopupValue(row, column)
}
const parseRecordList = <T extends Record<string, any>>(value: any): T[] => {
  try {
    const parsed = JSON.parse(String(value || '[]'))
    return Array.isArray(parsed) ? parsed.filter((item) => item && typeof item === 'object') as T[] : []
  } catch {
    return []
  }
}
