const updateOpsTimeCell = (row: number, column: number, event: Event) => {
  if (isLockedOpsCell(row, column) || isSentEcdRowLocked(row)) return
  const value = (event.target as HTMLInputElement).value
  const next = value ? value.replace('T', ' ') : ''
  if (String(rows.value[row]?.[column] ?? '') === next) return
  rows.value[row][column] = next
  mirrorFclLinkedCell(row, column)
  scheduleSave()
}
const finishOpsCellEdit = (row: number, column: number, event: Event) => {
  if (!isEditingCell(row, column) && !isOpsEditingRow(row)) return
  if (isEditingCell(row, column)) editingCell.value = null
  if (isLockedOpsCell(row, column) || isSentEcdRowLocked(row)) return
  const rawNext = ((event.target as HTMLElement).innerText || '').trim()
  const next = isOpsMoneyColumn(column) && rawNext ? formatMoneyValue(rawNext) : rawNext
  const current = String(rows.value[row]?.[column] ?? '')
  if (next === current) return
  rows.value[row][column] = next
  mirrorFclLinkedCell(row, column)
  if (isExwFclFreeTextMblColumn(column) && ['ECD', 'DCD'].includes(opsDeptUpper())) {
    void mirrorExwFclDocumentNumber('MBL NO#', next, row)
  }
  if (isOpsEditingRow(row)) return
  scheduleSave()
}
const cellStyle = (row: number, column: number) => {
  const format = cellFormatOf(row, column)
  return {
    textAlign: format.align || defaultCellAlign(),
    color: format.color || '',
    backgroundColor: format.background || '',
    height: rowHeights.value[String(row)] ? `${rowHeights.value[String(row)]}px` : '',
  }
}
const rowStyle = (row: number) => {
  if (row === 0) return {} // let CSS (.hdr) control the height automatically
  return { height: `${Math.max(26, Number(rowHeights.value[String(row)]) || 26)}px` }
}
const formatAdminDateDisplay = (value: any) => {
  if (value == null || value === '') return value
  const raw = String(value).trim()
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})(?:(?:T|\s)(\d{2}):(\d{2})(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})?)?$/)
  if (!match) return value
  const date = `${match[3]}/${match[2]}/${match[1]}`
  return match[4] ? `${date} ${match[4]}:${match[5]}` : date
}
const displayCell = (value: any, row: number, column: number) => {
  const format = cellFormatOf(row, column)
  if (row > 0 && normalizedHeaderLabel(column) === 'ACTION' && (value == null || value === '')) return 'ACTIVE'
  if (row > 0 && normalizedHeaderLabel(column) === 'MODE' && upperText(value) === 'MANUAL') return 'MANU'
  // Linked Client cells can arrive through a generic renderer (for example
  // after a cross-department copy). Always show the client code/name rather
  // than leaking the serialized CLIENT object into the grid.
  if (row > 0 && (isClientLinkColumn(column) || normalizedHeaderLabel(column) === 'CLIENT')) {
    const clientText = clientCellText(value)
    if (clientText && !clientText.trim().startsWith('{')) return clientText
  }
  if (row > 0 && typeof value === 'string' && value.trim().startsWith('{')) {
    const jsonLabel = normalizedHeaderLabel(column)
    if (jsonLabel === 'ROUTE') {
      const route = routeFromCellValue(value)
      if (route?.polCode && route?.podCode) return `${route.polCode}-${route.podCode}`
    }
    if (jsonLabel === 'VESSEL/VOYAGE' || jsonLabel === 'VESSEL NAME') {
      const vessel = vesselFromCellValue(value)
      if (vessel?.name) return vessel.voyage ? `${vessel.name} / ${vessel.voyage}` : vessel.name
    }
    if (jsonLabel === 'BC NO#') {
      const booking = bookingDetailValue(value)
      if (booking) return booking
    }
    if (jsonLabel === 'HBL NO#') {
      const parsedHbl = parseJsonCell(value, null as any)
      const form = parsedHbl && typeof parsedHbl === 'object' && 'form' in parsedHbl ? (parsedHbl as any).form || {} : {}
      if (String(form.required || '').toUpperCase() === 'NO') return 'N/A'
      if (form.hblNo) return String(form.hblNo)
    }
  }
  if (value == null || value === '') return ''
  if (isCheckboxCell(row, column)) return ''
  if (format.type === 'number') {
    const number = Number(String(value).replace(/,/g, ''))
    return Number.isNaN(number) ? value : number.toLocaleString('en-US')
  }
  if (format.type === 'time') {
    const raw = String(value)
    const match = raw.match(/\b(\d{1,2}):(\d{2})\b/)
    if (match) return `${match[1].padStart(2, '0')}:${match[2]}`
    return value
  }
  if (format.type === 'date') {
    return formatAdminDateDisplay(value)
  }
  return formatAdminDateDisplay(value)
}

const columnLetter = (index: number) => {
  let value = ''
  let current = index + 1
  while (current > 0) {
    current--
    value = String.fromCharCode(65 + (current % 26)) + value
    current = Math.floor(current / 26)
  }
  return value
}
const columnWidth = (index: number) => {
  const stored = Number(columnWidths.value[index])
  return Math.max(56, stored === 132 || !stored ? 100 : stored)
}
const csvCell = (value: any) => `"${String(value ?? '').replace(/"/g, '""')}"`
const downloadRowsCsv = (exportRows: any[][], suffix = '') => {
  if (!exportRows.length) {
    showToast('Nothing to export')
    return
  }
  const csv = `\uFEFF${exportRows.map((row) => row.map(csvCell).join(',')).join('\r\n')}`
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }))
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = `SHOPTRANS_${activeKey.value}${suffix}.csv`
  anchor.click()
  URL.revokeObjectURL(url)
}
const exportCsv = () => downloadRowsCsv(rows.value)
const toggleOpsExportMenu = () => {
