const exportOpsScope = (scope: 'selected' | 'filtered' | 'all') => {
  const header = rows.value[0] || []
  let bodyIndexes: number[] = []
  if (scope === 'selected') bodyIndexes = [...opsSelectedRows.value].filter((row) => row > 0).sort((a, b) => a - b)
  else if (scope === 'filtered') bodyIndexes = opsBodyRows.value.slice()
  else bodyIndexes = rows.value.map((_, index) => index).filter((index) => index > 0)
  const exportRows = [header, ...bodyIndexes.map((index) => rows.value[index]).filter(Boolean)]
  opsExportOpen.value = false
  downloadRowsCsv(exportRows, `_${scope}`)
}
