const highlightDOM = () => {
  if (!sheetBody.value || !columnBar.value || !rowBar.value) return
  const ss = sheetBody.value
  const cb = columnBar.value
  const rbw = rowBar.value

  // clear old classes
  ss.querySelectorAll('.sel-rng').forEach(td => td.classList.remove('sel-rng'))
  ss.querySelectorAll('.colsel').forEach(td => td.classList.remove('colsel'))
  ss.querySelectorAll('.rowsel').forEach(tr => tr.classList.remove('rowsel'))
  cb.querySelectorAll('.sel').forEach(th => th.classList.remove('sel'))
  rbw.querySelectorAll('.sel').forEach(rn => rn.classList.remove('sel'))

  const rect = selectedRect.value
  if (!rect) return

  const isCol = selectionKind.value === 'col'
  const isRow = selectionKind.value === 'row'

  // highlight body cells
  ss.querySelectorAll('td.cell').forEach(td => {
    const r = Number(td.getAttribute('data-r'))
    const c = Number(td.getAttribute('data-c'))
    if (r >= rect.r1 && r <= rect.r2 && c >= rect.c1 && c <= rect.c2) {
      td.classList.add('sel-rng')
    }
    if (isCol && c >= rect.c1 && c <= rect.c2) td.classList.add('colsel')
  })

  // highlight body rows
  if (isRow) {
    ss.querySelectorAll('tbody tr').forEach(tr => {
      const firstTd = tr.querySelector('td.cell')
      if (firstTd) {
        const r = Number(firstTd.getAttribute('data-r'))
        if (!isNaN(r) && r >= rect.r1 && r <= rect.r2) tr.classList.add('rowsel')
      }
    })
  }

  // highlight column headers
  cb.querySelectorAll('th[data-col]').forEach(th => {
    const c = Number(th.getAttribute('data-col'))
    if (c >= rect.c1 && c <= rect.c2) th.classList.add('sel')
  })

  // highlight row headers
  rbw.querySelectorAll('th.row-number[data-row]').forEach(rn => {
    const r = Number(rn.getAttribute('data-row'))
    if (r >= rect.r1 && r <= rect.r2) rn.classList.add('sel')
  })
}

const scrollLeftSheet = () => {
