const scrollToStartSheet = () => {
  if (sheetBody.value) {
    sheetBody.value.scrollLeft = 0
  }
}
const scrollUpSheet = () => {
  if (sheetBody.value) {
    sheetBody.value.scrollTop -= 60
  }
}
const scrollDownSheet = () => {
  if (sheetBody.value) {
    sheetBody.value.scrollTop += 60
  }
}

watch(() => props.sheetKey, (key) => {
  if (key !== activeKey.value) flushPendingSave()
  activeKey.value = key
})
watch(() => props.currentCountry?.id, async (country, previousCountry) => {
  if (!country || country === previousCountry) return
  await flushPendingSave()
  await loadSheet()
})
watch(activeKey, loadSheet, { immediate: true })
watch(activeKey, () => {
  opsSelectedRows.value = new Set()
  opsFilterField.value = 'all'
  opsEditingRow.value = null
  opsExportOpen.value = false
  opsFilterOpen.value = false
  opsAdvancedFilters.value = []
  opsAppliedFilters.value = []
})
watch(rows, recalibrateStatusCounts, { deep: true })
watch([activeStatus, sortBy], () => {
  visibleRowsLimit.value = 250
})
watch([visibleRowIndexes, sheetWidth, sheetTable], () => {
  sheetResizeObserver?.disconnect()
  if (sheetTable.value) {
    sheetResizeObserver = new ResizeObserver(syncRenderedRowHeights)
    sheetResizeObserver.observe(sheetTable.value)
  }
  syncRenderedRowHeights()
}, { flush: 'post' })

watch([selectedRect, selectionKind, visibleRowIndexes], () => {
  nextTick(highlightDOM)
}, { flush: 'post' })

onMounted(() => {
  window.addEventListener('mousemove', onGlobalMouseMove)
  window.addEventListener('mouseup', onGlobalMouseUp)
  window.addEventListener('mousedown', onGlobalMouseDown, true)
  window.addEventListener('click', preventNativeOperationsPicker, true)
  window.addEventListener('keydown', onGlobalKeyDown)
  window.addEventListener('paste', onGlobalPaste)
  window.addEventListener('scroll', onGlobalScrollClose, true)
  epodStatusTimer = window.setInterval(() => { void refreshTruckEpodStatuses() }, 8000)
})
onUpdated(syncRenderedRowHeights)
onBeforeUnmount(() => {
  window.removeEventListener('mousemove', onGlobalMouseMove)
  window.removeEventListener('mouseup', onGlobalMouseUp)
  window.removeEventListener('mousedown', onGlobalMouseDown, true)
  window.removeEventListener('click', preventNativeOperationsPicker, true)
  window.removeEventListener('keydown', onGlobalKeyDown)
  window.removeEventListener('paste', onGlobalPaste)
  window.removeEventListener('scroll', onGlobalScrollClose, true)
  sheetResizeObserver?.disconnect()
  if (epodStatusTimer) window.clearInterval(epodStatusTimer)
  if (saveTimer) void flushPendingSave()
})
</script>

