.toast{position:fixed;bottom:30px;left:50%;transform:translate(-50%,20px);background:#008f4c;color:#fff;font-size:13px;font-weight:600;padding:12px 20px;border-radius:10px;display:flex;align-items:center;gap:10px;box-shadow:0 10px 20px rgba(0,143,76,.3);opacity:0;visibility:hidden;transition:.3s cubic-bezier(.175,.885,.32,1.275);z-index:9999}
.toast.on{opacity:1;visibility:visible;transform:translate(-50%,0)}
.toast svg{width:18px;height:18px}
@media(max-width:1100px){
  .workbook,.ops-ms-page{width:100%;max-width:100%;min-width:0}
  .ops-ms-toolbar{flex-wrap:wrap;overflow:visible;padding:10px 14px;gap:7px}
  .ops-spacer{display:none}
  .ops-search-group{flex:1 1 320px;min-width:220px}
  .ops-search{width:auto;min-width:80px;flex:1 1 auto}
  .ops-tablewrap{margin:0 14px 14px;max-width:calc(100% - 28px);overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
  .ops-adv-filter{margin:0 14px 10px}
}
@media(max-width:700px){
  .workbook,.ops-ms-page{height:100dvh;min-height:0;overflow:hidden}
  .ops-ms-head{display:grid;grid-template-columns:minmax(0,1fr) auto;min-width:0;padding-right:8px}
  .ops-ms-head .ops-ms-terms{min-width:0}
  .ops-ms-country{margin-left:0;padding-left:8px;background:#f5faf6}
  .ops-ms-page .country-btn{max-width:132px}
  .ops-ms-page .country-btn span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .ops-ms-tabs{max-width:100%;margin-bottom:6px;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch}
  .ops-ms-tab{min-height:38px;padding:9px 12px;font-size:12px}
  .ops-ms-toolbar{align-items:center;padding:8px;margin-bottom:8px}
  .ops-ms-toolbar>.ops-btn,.ops-export-wrap>.ops-btn{min-height:36px}
  .ops-search-group{order:20;flex:1 1 100%;width:100%;min-width:0;height:36px}
  .ops-filter-select,.ops-search{height:28px}
  .ops-search-group>.ops-btn{min-height:28px}
  .ops-status-lbl{order:23;margin-left:auto}
  .ops-status-select{order:24;height:32px;width:96px}
  .ops-adv-filter{margin:0 8px 8px;padding:8px}
  .ops-adv-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;width:100%}
  .ops-adv-row input{grid-column:1 / -1;width:100%}
  .ops-adv-actions{flex-wrap:wrap}
  .ops-tablewrap{margin:0 8px 8px;max-width:calc(100% - 16px);border-radius:7px;padding-bottom:24px}
  .ops-ms-table tbody td{height:38px}
}
@media(max-width:900px){.workbook:not(.ops-workbook){height:auto}.head-line{flex-wrap:wrap}.save-state{margin-left:0}.sheet-shell{height:65vh}.wb-search{min-width:160px;flex:1 1 160px}}
/* AIR EXW DCD — VESSEL / VOYAGE history-only modal (mockup #ovs) */
.gsd-vhist-modal{width:min(980px,96vw);max-height:90vh;padding:34px 24px 24px;border-radius:10px;overflow:auto;font:12px/1.35 var(--sans,'Geist',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif)}
.gsd-vhist-head{text-align:center;font-size:13px;font-weight:900;color:#0e1512;text-transform:uppercase;margin:0 0 14px}
.gsd-vhist-wrap{overflow-x:auto}
.gsd-vhist-table{width:100%;min-width:898px;border-collapse:collapse;table-layout:fixed;font-size:11.5px;color:#33413b}
.gsd-vhist-table col:nth-child(1){width:52px}
.gsd-vhist-table th,.gsd-vhist-table td{border:1px solid #cfd8d2;text-align:center;padding:6px 8px;height:32px}
.gsd-vhist-table th{background:#eef3ee;color:#66736c;font-family:var(--mono,'Geist Mono',ui-monospace,monospace);font-size:10.5px;font-weight:800;letter-spacing:.02em}
.gsd-vhist-table td{background:#f8fbfa}
.gsd-vhist-table td.applied{color:#0a6b3b;font-weight:800}
.gsd-vhist-table td.expired{color:#8a94a0;font-weight:700}
.gsd-vhist-table td.empty{height:44px;background:#fff;color:#8a94a0;font-weight:600}
.gsd-vty{display:inline-flex;align-items:center;justify-content:center;min-width:56px;height:20px;border-radius:999px;font-size:10px;font-weight:800;letter-spacing:.03em}
.gsd-vty.sel{background:#e8f6ee;color:#0a6b3b}
.gsd-vty.dly{background:#fff4e5;color:#b45f04}
.ops-nbadge{display:inline-grid;place-items:center;min-width:14px;height:14px;margin-left:5px;padding:0 3px;border-radius:999px;background:#d63a3a;color:#fff;font-size:9px;font-weight:800;line-height:1}
/* AIR/LCL — vessel delay panel + history on EXW ECD (mockup #ovs) */
.gsd-modal.gsd-vessel-ecd-modal{width:min(980px,96vw);max-height:92vh;overflow:auto}
.gsd-vdelay{margin:12px 0 4px}
.gsd-vdtog,.gsd-vapall{display:inline-flex;align-items:center;gap:7px;font-size:12.5px;font-weight:700;color:#33414d;cursor:pointer}
.gsd-vdtog.disabled,.gsd-vapall.disabled{color:#9aa4a0;cursor:not-allowed}.gsd-vdtog.disabled input,.gsd-vapall.disabled input{cursor:not-allowed;opacity:.55}
.gsd-vapall{display:flex;margin:10px 0 2px}
.gsd-vdelay input[type=checkbox]{width:15px;height:15px;accent-color:#008f4c}
.gsd-vdbox{margin-top:8px;border:1px solid #e6c9a8;background:#fdf6ee;border-radius:8px;padding:10px 12px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}
.gsd-vdbox label{display:grid;gap:5px;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.03em;color:#7a847d}
.gsd-vdbox input{height:32px;border:1px solid #d3dacf;border-radius:7px;padding:5px 9px;font:inherit;font-size:12.5px;outline:none}
.gsd-vdbox input:focus{box-shadow:inset 0 0 0 2px #00c566}
.gsd-vhist-wrap.ecd{margin-top:16px;border-top:1px solid #e4e9e2;padding-top:12px}
.gsd-vhist-wrap.ecd tbody tr{cursor:pointer}.gsd-vhist-wrap.ecd tbody tr:hover td{background:#fff8ed}.gsd-vhist-wrap.ecd tbody tr.selected td{background:#ffefd6;box-shadow:inset 0 1px 0 #f3b562,inset 0 -1px 0 #f3b562}.gsd-vhist-wrap.ecd tbody tr.delay td.vessel-date{color:#e67e22;font-weight:800}
/* Keep every compact + glyph optically centred instead of relying on the font baseline. */
.gsd-plusmini,.gsd-truck-plus,.clr-plus,.pay-hplus,.with-plus>button,.cl-tab.dept-add,.pdc-up{position:relative;font-size:0!important;line-height:0!important;text-align:center;--plus-bar-length:8px;--plus-bar-thickness:2px}
.gsd-payment-modal .pay-head-label{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:100%;vertical-align:middle;white-space:nowrap}.gsd-payment-modal .pay-head-label .pay-hplus{display:inline-grid;place-items:center;flex:0 0 16px;margin:0;vertical-align:middle}
.gsd-plusmini::before,.gsd-plusmini::after,.gsd-truck-plus::before,.gsd-truck-plus::after,.clr-plus::before,.clr-plus::after,.pay-hplus::before,.pay-hplus::after,.with-plus>button::before,.with-plus>button::after,.cl-tab.dept-add::before,.cl-tab.dept-add::after,.pdc-up::before,.pdc-up::after{content:'';position:absolute;left:50%;top:50%;display:block;border-radius:999px;background:currentColor;transform:translate(-50%,-50%);pointer-events:none}
.gsd-plusmini::before,.gsd-truck-plus::before,.clr-plus::before,.pay-hplus::before,.with-plus>button::before,.cl-tab.dept-add::before,.pdc-up::before{width:var(--plus-bar-length);height:var(--plus-bar-thickness)}
.gsd-plusmini::after,.gsd-truck-plus::after,.clr-plus::after,.pay-hplus::after,.with-plus>button::after,.cl-tab.dept-add::after,.pdc-up::after{width:var(--plus-bar-thickness);height:var(--plus-bar-length)}
.clr-plus{--plus-bar-length:10px}.pay-hplus{--plus-bar-length:7px;--plus-bar-thickness:1.5px}
/* AIR/LCL — delayed vessel highlight on ETD/ETA cells */
.ops-ms-table td.vdly,.ops-ms-table td.vdly .ops-textcell{color:#e67e22;font-weight:700}
.ops-ms-table td.linked-date-changed,.sheet-body td.linked-date-changed{background:#fff1dc!important;color:#c2410c!important;font-weight:800}.ops-ms-table td.linked-date-changed .ops-textcell{color:#c2410c!important;font-weight:800}
.do-info-overlay{z-index:470!important;background:rgba(10,30,18,.46)!important}.do-info-modal{position:relative;width:700px;max-width:94vw;border:1px solid #cbd5d0;border-radius:12px;background:#fff;padding:62px 54px 24px;box-shadow:0 18px 50px rgba(0,0,0,.28);box-sizing:border-box}.do-info-x{position:absolute;right:12px;top:12px;display:grid;place-items:center;width:24px;height:24px;border:0;border-radius:50%;background:#c0392b;color:#fff;font:800 15px/1 Arial,sans-serif;cursor:pointer}.do-info-row{display:grid;grid-template-columns:96px minmax(0,1fr) 150px 30px 30px;align-items:center;gap:10px;margin:0 0 16px}.do-info-row label{font-size:12.5px;font-weight:700;line-height:1.25;color:#33413b}.do-info-row input{width:100%;height:38px;box-sizing:border-box;border:1px solid #c9d3cf;border-radius:8px;background:#f7faf9;padding:8px 10px;font:inherit;font-size:12.5px;color:#33413b;outline:none}.do-info-row input:focus{border-color:#00c566;box-shadow:0 0 0 2px rgba(0,197,102,.12)}.do-info-row input:disabled{background:#eef2f0;color:#64746d}.do-info-upload,.do-info-view{width:30px!important;height:30px!important;padding:2px!important}.do-info-upload{color:#1680bd!important}.do-info-upload svg,.do-info-view svg{width:19px!important;height:19px!important;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.do-info-upload.has{color:#1b7a43!important}.do-info-view{color:#0f4c81!important}.do-info-upload:disabled{opacity:.35;cursor:not-allowed}.do-info-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.do-info-actions button{height:34px;border:0;border-radius:8px;padding:0 14px;font:inherit;font-size:12.5px;font-weight:800;cursor:pointer}.do-info-actions .save{background:#008f4c;color:#fff}.do-info-actions .edit{background:#e67e22;color:#fff}.do-info-actions .close{background:#64748b;color:#fff}.do-info-actions button:disabled{opacity:.45;cursor:not-allowed}@media(max-width:650px){.do-info-modal{padding:58px 20px 20px}.do-info-row{grid-template-columns:80px minmax(0,1fr) 30px 30px}.do-info-row input[type=date]{grid-column:2}.do-info-row .do-info-upload{grid-column:3;grid-row:1/3}.do-info-row .do-info-view{grid-column:4;grid-row:1/3}}
